INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('TencentBlueKing/bk-weweb/bk-weweb', 'community', 'TencentBlueKing', 'bk-weweb', 'TencentBlueKing/bk-weweb', 'bk-weweb', 0, 0, 33, '2026-03-08T01:57:15.441Z', '2026-03-08T02:07:44.955Z', '4640e7c8971bbe9d452ac974c1871846df1e6d8c239783ce1b38aad0be1565ce', '{"id":"TencentBlueKing/bk-weweb/bk-weweb","name":"bk-weweb","description":{"en":"bk-weweb is a micro-frontend framework that supports micro-applications and micro-modules, benefiting developers who need to build complex web applications. It provides a lightweight solution for loading remote applications and modules.","zh":"BK-WeWeb 是一个基于 Web Components 技术的微前端框架，支持微应用和微模块两种模式。它提供了快速开始和易于使用的 API","ja":"BK-WeWeb は Web Components 技術をベースにしたマイクロフロントエンドフレームワークで、マイクロアプリとマイクロモジュールの 2 つのモードをサポートします。簡単に開始して、使いやすい API が提供されます","ko":"BK-WeWeb는 Web Components 기술을 기반으로 한 마이크로 프론트엔드 프레임워크로, 마이크로 애플리케이션과 마イク로 모듈의 2가지 모드를 지원합니다. 쉽게 시작하고, 사용하기 쉬운 API를 제공합니다","es":"bk-weweb es un framework de microfrontends ligero y basado en Web Components, que admite dos modos de ejecución: microaplicaciones y micromódulos","fr":"bk-weweb est un framework de microfrontends léger et basé sur les Web Components, qui prend en charge deux modes d''exécution : microapplications et micromodules","de":"bk-weweb ist ein leichtes Microfrontend-Framework basierend auf Web Components, das zwei Ausführungsmodi unterstützt: Microanwendungen und Micromodule","pt":"O bk-weweb é um framework de micro frontend leve baseado em Web Components, que suporta dois modos de execução: microaplicativos e micromódulos","ru":"bk-weweb - легкий микрофронтенд-фреймворк на основе Web Components, поддерживающий два режима выполнения: микроприложения и микромодули","ar":"bk-weweb هو إطار عمل ميكرو فرونت إند خفيف مبني على ويب كومبوننتس، يدعم وضعين للتشغيل: تطبيقات صغيرة ووحدات صغيرة"},"seo":{"title":{"en":"bk-weweb: Micro-Frontend Framework Setup Guide | AI Agent...","zh":"BK-WeWeb 微前端框架 Setup Guide","ja":"BK-WeWeb マイクロフロントエンド フレームワークのセットアップガイド","ko":"BK-WeWeb 마이크로 프론트엔드 프레임워크 설정 가이드","es":"Guía de configuración de bk-weweb para microfrontends","fr":"Guide de démarrage rapide pour bk-weweb et les microfront...","de":"Einrichtungsleitfaden für bk-weweb Microfrontend Framework","pt":"Guia de Configuração do bk-weweb: Micro Frontend com Web ...","ru":"Настройка bk-weweb: Микрофронтенд с Web Components","ar":"دليل إعداد bk-weweb: ميكرو فرونت إند مع ويب كومبوننتس"},"description":{"en":"Discover how to install and use bk-weweb, a lightweight micro-frontend framework based on Web Components technology, and explore its features and benefits","zh":"BK-WeWeb 是腾讯蓝鲸团队开源的轻量级微前端框架，基于 Web Components 技术，支持微应用和微模块两种模式。快速开始使用 BK-WeWeb","ja":"BK-WeWeb はテンセント藍鯨チームによってオープンソースされた軽量級マイクロフロントエンドフレームワークです。Web Components 技術をベースに、マイクロアプリとマイクロモジュールの 2 つのモードをサポートします。BK-WeWeb を使ってみましょう","ko":"BK-WeWeb는騰訊藍鯨팀이 오픈소스한 경량급 마이크로 프론트엔드 프레임워크입니다. Web Components 기술을 기반으로 마이크로 애플리케이션과 마이크로 모듈의 2가지 모드를 지원합니다. BK-WeWeb를 시작해 보세요","es":"Aprende a utilizar bk-weweb, un framework de microfrontends ligero y basado en Web Components, para mejorar la escalabilidad y flexibilidad de tus aplicacion...","fr":"Découvrez comment utiliser bk-weweb, un framework de microfrontends léger et basé sur les Web Components, pour améliorer la scalabilité et la flexibilité de ...","de":"Erfahren Sie, wie Sie bk-weweb, ein leichtes Microfrontend-Framework basierend auf Web Components, verwenden können, um die Skalierbarkeit und Flexibilität I...","pt":"Aprenda a configurar o bk-weweb, um framework de micro frontend leve baseado em Web Components, para criar aplicações modulares","ru":"Узнайте, как настроить bk-weweb, легкий микрофронтенд-фреймворк на основе Web Components, для создания модульных приложений","ar":"تعلم كيفية إعداد bk-weweb، إطار عمل ميكرو فرونت إند خفيف مبني على ويب كومبوننتس، لإنشاء تطبيقات قابلة للتحديث"},"definition":{"en":"bk-weweb is a micro-frontend framework based on Web Components technology, supporting two modes: micro-application and micro-module","zh":"BK-WeWeb 是一个开源的微前端框架，基于 Web Components 技术","ja":"BK-WeWeb はオープンソースのマイクロフロントエンドフレームワークで、Web Components 技術をベースにします","ko":"BK-WeWeb는 오픈소스 마이크로 프론트엔드 프레임워크로, Web Components 기술을 기반으로 합니다","es":"bk-weweb es un framework de microfrontends que utiliza Web Components para permitir la creación de aplicaciones web escalables y flexibles","fr":"bk-weweb est un framework de microfrontends qui utilise les Web Components pour permettre la création d''applications web scalables et flexibles","de":"bk-weweb ist ein Microfrontend-Framework, das Web Components verwendet, um die Erstellung von skalierbaren und flexiblen Webanwendungen zu ermöglichen","pt":"O bk-weweb é um framework de micro frontend que permite criar aplicações modulares usando Web Components","ru":"bk-weweb - фреймворк микрофронтенда, позволяющий создавать модульные приложения с использованием Web Components","ar":"bk-weweb هو إطار عمل ميكرو فرونت إند يسمح بإنشاء تطبيقات قابلة للتحديث باستخدام ويب كومبوننتس"},"features":{"en":["Supports micro-application and micro-module modes","Based on Web Components technology","Installs via npm using `npm install @blueking/bk-weweb`","Allows importing in main application using `import ''@blueking/bk-weweb'';`","Provides two entry types: HTML for micro-applications and JS for micro-modules","Enables loading of remote applications and modules"],"zh":["基于 Web Components 技术","支持微应用和微模块两种模式","提供快速开始和易于使用的 API","支持 npm 安装","支持 TypeScript"],"ja":["Web Components 技術をベースに","マイクロアプリとマイクロモジュールの 2 つのモードをサポート","簡単に開始して、使いやすい API が提供","npm インストールをサポート","TypeScript をサポート"],"ko":["Web Components 기술을 기반으로","마이크로 애플리케이션과 마이크로 모듈의 2가지 모드를 지원","쉽게 시작하고, 사용하기 쉬운 API를 제공","npm 설치를 지원","TypeScript를 지원"],"es":["Soporte para microaplicaciones y micromódulos","Basado en Web Components","Instalación mediante npm","Dos modos de ejecución: microaplicaciones y micromódulos","Compatibilidad con HTML y JS","Integración con aplicaciones web existentes"],"fr":["Prise en charge des microapplications et des micromodules","Basé sur les Web Components","Installation via npm","Deux modes d''exécution : microapplications et micromodules","Compatibilité avec HTML et JS","Intégration avec des applications web existantes"],"de":["Unterstützung für Microanwendungen und Micromodule","Basierend auf Web Components","Installation über npm","Zwei Ausführungsmodi: Microanwendungen und Micromodule","Kompatibilität mit HTML und JS","Integration mit bestehenden Webanwendungen"],"pt":["Suporte a dois modos de execução: microaplicativos e micromódulos","Baseado em Web Components","Instalação via npm com @blueking/bk-weweb","Integração com aplicações principais via importação de módulos","Suporte a carga de aplicativos e módulos remotos"],"ru":["Поддержка двух режимов выполнения: микроприложения и микромодули","Основан на Web Components","Установка через npm с @blueking/bk-weweb","Интеграция с основными приложениями через импорт модулей","Поддержка загрузки удаленных приложений и модулей"],"ar":["دعم وضعين للتشغيل: تطبيقات صغيرة ووحدات صغيرة","مبني على ويب كومبوننتس","التثبيت عبر npm مع @blueking/bk-weweb","التكامل مع التطبيقات الرئيسية عبر استيراد الوحدات","دعم تحميل التطبيقات والوحدات البعيدة"]},"keywords":{"en":["how to use bk-weweb","bk-weweb micro-frontend framework","bk-weweb vs single-spa","bk-weweb install guide","what is bk-weweb","bk-weweb alternative","bk-weweb setup tutorial","bk-weweb web components","bk-weweb micro-application mode","bk-weweb micro-module mode"],"zh":["BK-WeWeb","微前端框架","Web Components","微应用","微模块","npm 安装","TypeScript"],"ja":["BK-WeWeb","マイクロフロントエンド フレームワーク","Web Components","マイクロアプリ","マイクロモジュール","npm インストール","TypeScript"],"ko":["BK-WeWeb","마이크로 프론트엔드 프레임워크","Web Components","마이크로 애플리케이션","마이크로 모듈","npm 설치","TypeScript"],"es":["bk-weweb","microfrontends","Web Components","npm","instalación de bk-weweb","configuración de bk-weweb","microaplicaciones","micromódulos","desarrollo web","framework de microfrontends"],"fr":["bk-weweb","microfrontends","Web Components","npm","installation de bk-weweb","configuration de bk-weweb","microapplications","micromodules","développement web","framework de microfrontends"],"de":["bk-weweb","Microfrontends","Web Components","npm","Installation von bk-weweb","Konfiguration von bk-weweb","Microanwendungen","Micromodule","Webentwicklung","Microfrontend-Framework"],"pt":["bk-weweb","micro frontend","Web Components","framework de micro frontend","desenvolvimento de aplicações modulares","integração de aplicações","npm @blueking/bk-weweb","microaplicativos","micromódulos"],"ru":["bk-weweb","микрофронтенд","Web Components","фреймворк микрофронтенда","разработка модульных приложений","интеграция приложений","npm @blueking/bk-weweb","микроприложения","микромодули"],"ar":["bk-weweb","ميكرو فرونت إند","ويب كومبوننتس","إطار عمل ميكرو فرونت إند","تطوير تطبيقات قابلة للتحديث","تكامل التطبيقات","npm @blueking/bk-weweb","تطبيقات صغيرة","وحدات صغيرة"]}},"owner":"TencentBlueKing","repo":"bk-weweb","repoPath":"TencentBlueKing/bk-weweb","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.441Z","topics":[],"category":"community","skillMd":{"name":"bk-weweb","description":"蓝鲸 BK-WeWeb 微前端框架使用指南。帮助用户使用 bk-weweb 实现微应用和微模块的加载、隔离和通信。当用户询问微前端、bk-weweb、子应用加载、JS沙箱、CSS隔离、预加载或需要创建微前端应用时使用此 skill。","bodyPreview":"# BK-WeWeb 微前端框架\n\nBK-WeWeb 是腾讯蓝鲸团队开源的轻量级微前端框架，基于 Web Components 技术，支持微应用和微模块两种模式。\n\n## 快速开始\n\n### 安装\n\n```bash\nnpm install @blueking/bk-weweb\n```\n\n### 在主应用中引入\n\n```typescript\n// main.ts\nimport ''@blueking/bk-weweb'';\n```\n\n## 两种运行模式\n\n| 模式             | 说明             | 入口类型 | 适用场景           |\n| ---------------- | ---------------- | -------- | ------------------ |\n| **微应用 (app)** | 加载完整远程应用 | HTML     | 独立部署的完整应用 |\n| **微模块 (js)**  | 加载远程 JS 模块 | JS       | 远程组件、插件系统 |\n\n## 基础用法\n\n### Web Component 标签方式\n\n`","body":"# BK-WeWeb 微前端框架\n\nBK-WeWeb 是腾讯蓝鲸团队开源的轻量级微前端框架，基于 Web Components 技术，支持微应用和微模块两种模式。\n\n## 快速开始\n\n### 安装\n\n```bash\nnpm install @blueking/bk-weweb\n```\n\n### 在主应用中引入\n\n```typescript\n// main.ts\nimport ''@blueking/bk-weweb'';\n```\n\n## 两种运行模式\n\n| 模式             | 说明             | 入口类型 | 适用场景           |\n| ---------------- | ---------------- | -------- | ------------------ |\n| **微应用 (app)** | 加载完整远程应用 | HTML     | 独立部署的完整应用 |\n| **微模块 (js)**  | 加载远程 JS 模块 | JS       | 远程组件、插件系统 |\n\n## 基础用法\n\n### Web Component 标签方式\n\n```vue\n<template>\n  <!-- 微应用 -->\n  <bk-weweb\n    id=\"child-app\"\n    url=\"http://localhost:8001/\"\n    :scope-js=\"true\"\n    :scope-css=\"true\"\n  />\n\n  <!-- 微模块 -->\n  <bk-weweb\n    id=\"chart-module\"\n    mode=\"js\"\n    url=\"http://localhost:8002/widget.js\"\n  />\n</template>\n```\n\n### Hooks API 方式\n\n```typescript\nimport { loadApp, mount, unmount } from ''@blueking/bk-weweb'';\n\n// 加载并挂载微应用\nawait loadApp({\n  url: ''http://localhost:8001/'',\n  id: ''my-app'',\n  scopeJs: true,\n  scopeCss: true,\n  data: { userId: ''123'', token: ''xxx'' },\n});\nmount(''my-app'', document.getElementById(''container''));\n\n// 卸载\nunmount(''my-app'');\n```\n\n## 核心 API\n\n### 生命周期 Hooks\n\n| API                                       | 说明                                           |\n| ----------------------------------------- | ---------------------------------------------- |\n| `loadApp(props)`                          | 加载微应用，返回 `Promise<MicroAppModel>`      |\n| `loadInstance(props)`                     | 加载微模块，返回 `Promise<MicroInstanceModel>` |\n| `mount(appKey, container?, callback?)`    | 挂载到容器                                     |\n| `unmount(appKey)`                         | 卸载应用/模块                                  |\n| `activated(appKey, container, callback?)` | 激活（用于 keepAlive 模式）                    |\n| `deactivated(appKey)`                     | 停用（用于 keepAlive 模式）                    |\n| `unload(url)`                             | 删除缓存                                       |\n\n### 预加载 Hooks\n\n| API                         | 说明           |\n| --------------------------- | -------------- |\n| `preLoadApp(options)`       | 预加载微应用   |\n| `preLoadInstance(options)`  | 预加载微模块   |\n| `preLoadSource(sourceList)` | 预加载资源文件 |\n\n### 启动配置\n\n```typescript\nimport weWeb from ''@blueking/bk-weweb'';\n\nweWeb.start({\n  collectBaseSource: true, // 收集主应用资源供子应用共享\n  webComponentTag: ''my-micro-app'', // 自定义标签名\n  fetchSource: async (url, options) => {\n    // 自定义资源获取（如添加认证头）\n    const response = await fetch(url, {\n      ...options,\n      headers: { Authorization: `Bearer ${token}` },\n    });\n    return response.text();\n  },\n});\n```\n\n## 配置属性速查\n\n### 微应用属性 (mode=\"app\" 或默认)\n\n| 属性             | 类型            | 默认值  | 说明                   |\n| ---------------- | --------------- | ------- | ---------------------- |\n| `url`            | `string`        | -       | **必填**，应用入口 URL |\n| `id`             | `string`        | -       | 应用唯一标识符         |\n| `scopeJs`        | `boolean`       | `true`  | JS 沙箱隔离            |\n| `scopeCss`       | `boolean`       | `true`  | CSS 样式隔离           |\n| `scopeLocation`  | `boolean`       | `false` | 路由隔离               |\n| `setShadowDom`   | `boolean`       | `false` | 使用 Shadow DOM        |\n| `keepAlive`      | `boolean`       | `false` | 缓存模式               |\n| `showSourceCode` | `boolean`       | `false` | 显示源码               |\n| `data`           | `object/string` | -       | 传递数据               |\n| `initSource`     | `string[]`      | -       | 初始化资源             |\n\n### 微模块属性 (mode=\"js\")\n\n| 属性             | 类型            | 默认值  | 说明                   |\n| ---------------- | --------------- | ------- | ---------------------- |\n| `url`            | `string`        | -       | **必填**，JS 模块 URL  |\n| `id`             | `string`        | -       | **必填**，模块唯一标识 |\n| `mode`           | `''js''`          | -       | **必填**，设为 `''js''`  |\n| `scopeJs`        | `boolean`       | `false` | JS 沙箱隔离            |\n| `scopeCss`       | `boolean`       | `true`  | CSS 样式隔离           |\n| `keepAlive`      | `boolean`       | `false` | 缓存模式               |\n| `showSourceCode` | `boolean`       | `true`  | 显示源码               |\n| `data`           | `object/string` | -       | 传递数据               |\n\n## 子应用开发\n\n### 全局变量\n\n子应用中可通过以下全局变量获取运行时信息：\n\n```typescript\nif (window.__POWERED_BY_BK_WEWEB__) {\n  const appKey = window.__BK_WEWEB_APP_KEY__; // 应用标识\n  const data = window.__BK_WEWEB_DATA__; // 主应用传递的数据\n  const realWindow = window.rawWindow; // 原始 window\n  const realDocument = window.rawDocument; // 原始 document\n}\n```\n\n### 微模块 render 规范\n\n微模块需导出包含 `render` 方法的对象：\n\n```typescript\n// widget.js\nexport default {\n  render(container: HTMLElement, data: Record<string, unknown>) {\n    container.innerHTML = `<div>Hello ${data.name}</div>`;\n\n    // 返回销毁函数\n    return () => {\n      container.innerHTML = '''';\n    };\n  },\n\n  // 可选：其他方法供主应用调用\n  update(newData) {\n    /* ... */\n  },\n  getState() {\n    return {\n      /* ... */\n    };\n  },\n};\n```\n\n## 框架集成示例\n\n### Vue 3\n\n```vue\n<script setup lang=\"ts\">\n  import { ref, onMounted, onBeforeUnmount } from ''vue'';\n  import { loadApp, mount, unmount } from ''@blueking/bk-weweb'';\n\n  const containerRef = ref<HTMLElement>();\n  const appId = ''child-app'';\n\n  onMounted(async () => {\n    await loadApp({\n      url: ''http://localhost:8001/'',\n      id: appId,\n      scopeJs: true,\n      scopeCss: true,\n      data: { userId: ''123'' },\n    });\n    mount(appId, containerRef.value!);\n  });\n\n  onBeforeUnmount(() => unmount(appId));\n</script>\n\n<template>\n  <div\n    ref=\"containerRef\"\n    class=\"app-container\"\n  ></div>\n</template>\n```\n\n### React\n\n```tsx\nimport { useRef, useEffect } from ''react'';\nimport { loadApp, mount, unmount } from ''@blueking/bk-weweb'';\n\nconst MicroApp: React.FC = () => {\n  const containerRef = useRef<HTMLDivElement>(null);\n  const appId = ''child-app'';\n\n  useEffect(() => {\n    const load = async () => {\n      await loadApp({\n        url: ''http://localhost:8001/'',\n        id: appId,\n        scopeJs: true,\n        scopeCss: true,\n      });\n      if (containerRef.current) {\n        mount(appId, containerRef.current);\n      }\n    };\n    load();\n    return () => unmount(appId);\n  }, []);\n\n  return (\n    <div\n      ref={containerRef}\n      style={{ height: ''600px'' }}\n    />\n  );\n};\n```\n\n## 预加载策略\n\n```typescript\nimport { preLoadApp, mount } from ''@blueking/bk-weweb'';\n\n// 页面加载完成后预加载\nwindow.addEventListener(''load'', () => {\n  setTimeout(() => {\n    preLoadApp({\n      url: ''http://localhost:8001/'',\n      id: ''dashboard'',\n      scopeJs: true,\n    });\n  }, 2000); // 延迟避免影响首屏\n});\n\n// 需要时直接挂载（无需等待加载）\nfunction showDashboard() {\n  mount(''dashboard'', document.getElementById(''container''));\n}\n```\n\n## 常见问题\n\n### 1. 子应用加载失败\n\n- 检查 CORS 配置，确保允许跨域\n- 检查 URL 是否正确\n- 查看控制台错误信息\n\n### 2. 样式冲突\n\n- 确认 `scopeCss` 已开启\n- 考虑使用 `setShadowDom` 获得更彻底隔离\n- 检查是否使用了 `!important`\n\n### 3. 子应用路由不工作\n\n- 开启 `scopeLocation` 实现路由隔离\n- 确认路由模式（hash/history）\n\n### 4. 访问主应用全局变量\n\n```typescript\n// 子应用中访问真实 window\nconst realWindow = window.rawWindow || window;\nconst mainConfig = realWindow.__MAIN_APP_CONFIG__;\n```\n\n## 详细参考文档\n\n- [Hooks API 详解](references/hooks-api.md)\n- [微应用配置](references/micro-app.md)\n- [微模块配置](references/micro-module.md)\n\n## 类型定义\n\n```typescript\nimport {\n  loadApp,\n  loadInstance,\n  mount,\n  unmount,\n  activated,\n  deactivated,\n  unload,\n  preLoadApp,\n  preLoadInstance,\n  preLoadSource,\n  WewebMode,\n  type IAppModelProps,\n  type IJsModelProps,\n  type BaseModel,\n} from ''@blueking/bk-weweb'';\n```\n"},"lastSynced":"2026-03-08T02:07:44.955Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing to build complex web applications with micro-frontend architecture.","zh":"非常适合需要构建复杂Web应用程序的前端代理，使用微前端架构。","ja":"マイクロフロントエンドアーキテクチャを使用して複雑なWebアプリケーションを構築する必要があるフロントエンドエージェントに最適です。","ko":"마이크로 프론트엔드 아키텍처를 사용하여 복잡한 웹 애플리케이션을 구축해야 하는 프론트엔드 에이전트에게 적합합니다.","es":"Perfecto para agentes Frontend que necesitan crear aplicaciones web complejas con arquitectura de micro-frontend.","fr":"Parfait pour les agents Frontend qui ont besoin de créer des applications web complexes avec une architecture de micro-frontend.","de":"Perfekt für Frontend-Agenten, die komplexe Webanwendungen mit Micro-Frontend-Architektur erstellen müssen.","pt":"Perfeito para Agentes Frontend que precisam criar aplicações web complexas com arquitetura de micro-frontend.","ru":"Идеально подходит для фронтенд-агентов, которым необходимо создавать сложные веб-приложения с микрофронтенд архитектурой.","ar":"مثالي للوكلاء الأماميين الذين يحتاجون إلى بناء تطبيقات ويب معقدة مع هندسة ميكرو-أمامية."},"recommendation":{"en":"Empowers agents to load remote applications and modules using Web Components technology, supporting both micro-applications and micro-modules, and provides a lightweight solution for complex web development using HTML and JavaScript.","zh":"赋予代理加载远程应用程序和模块的能力，使用Web Components技术，支持微应用程序和微模块，并为使用HTML和JavaScript的复杂Web开发提供了轻量级解决方案。","ja":"Web Componentsテクノロジーを使用して、リモートアプリケーションとモジュールをロードする機能をエージェントに与え、マイクロアプリケーションとマイクロモジュールの両方をサポートし、HTMLとJavaScriptを使用した複雑なWeb開発のために軽量なソリューションを提供します。","ko":"Web Components 기술을 사용하여远程 애플리케이션과 모듈을 로드할 수 있는 기능을 에이전트에게 부여하며, 마이크로 애플리케이션과 마이크로 모듈을 모두 지원하며, HTML과 JavaScript를 사용한 복잡한 웹 개발을 위한 경량 솔루션을 제공합니다.","es":"Habilita a los agentes a cargar aplicaciones y módulos remotos utilizando la tecnología de Web Components, que admite tanto microaplicaciones como módulos micro, y proporciona una solución ligera para el desarrollo web complejo utilizando HTML y JavaScript.","fr":"Permet aux agents de charger des applications et des modules distants en utilisant la technologie de Web Components, qui prend en charge à la fois les microapplications et les micromodules, et fournit une solution légère pour le développement web complexe en utilisant HTML et JavaScript.","de":"Ermöglich es den Agenten, Remoteanwendungen und -module mithilfe der Web-Components-Technologie zu laden, die sowohl Mikroanwendungen als auch Mikromodule unterstützt und eine leichte Lösung für die komplexe Webentwicklung mit HTML und JavaScript bietet.","pt":"Habilita os agentes a carregar aplicações e módulos remotos usando a tecnologia de Web Components, suportando tanto microaplicações quanto micro-módulos, e fornece uma solução leve para o desenvolvimento web complexo usando HTML e JavaScript.","ru":"Наделяет агентов возможностью загружать удаленные приложения и модули с помощью технологии Web Components, поддерживая как микроприложения, так и микромодули, и обеспечивает легковесное решение для сложного веб-разработки с использованием HTML и JavaScript.","ar":"يمنح الوكلاء القدرة على تحميل التطبيقات والمكونات البعيدة باستخدام تقنية مكونات الويب، مع دعم التطبيقات والمكونات الدقيقة، ويقدم حلًا خفيفًا للتنمية الويب المعقدة باستخدام HTML وJavaScript."},"useCases":{"en":["Building micro-frontend applications with remote loading capabilities","Developing independent micro-applications with HTML entry points","Creating modular web components using JavaScript entry points"],"zh":["使用远程加载功能构建微前端应用程序","使用HTML入口点开发独立的微应用程序","使用JavaScript入口点创建模块化的Web组件"],"ja":["リモートロード機能を使用してマイクロフロントエンドアプリケーションを構築する","HTMLエントリポイントを使用して独立したマイクロアプリケーションを開発する","JavaScriptエントリポイントを使用してモジュール化されたWebコンポーネントを作成する"],"ko":["원격 로드 기능을 사용하여 마이크로 프론트엔드 애플리케이션을 구축하는 것","HTML 入口점을 사용하여 독립적인 마이크로 애플리케이션을 개발하는 것","JavaScript 入口점을 사용하여 모듈화된 웹 컴포넌트를 생성하는 것"],"es":["Creación de aplicaciones de micro-frontend con capacidades de carga remota","Desarrollo de microaplicaciones independientes con puntos de entrada HTML","Creación de componentes web modulares utilizando puntos de entrada JavaScript"],"fr":["Création d''applications de micro-frontend avec des capacités de chargement distant","Développement de microapplications indépendantes avec des points d''entrée HTML","Création de composants web modulaires en utilisant des points d''entrée JavaScript"],"de":["Erstellung von Micro-Frontend-Anwendungen mit Remote-Ladefunktionen","Entwicklung unabhängiger Mikroanwendungen mit HTML-Einstiegspunkten","Erstellung modulare Webkomponenten mit JavaScript-Einstiegspunkten"],"pt":["Construção de aplicações de micro-frontend com capacidades de carregamento remoto","Desenvolvimento de microaplicações independentes com pontos de entrada HTML","Criação de componentes web modulares usando pontos de entrada JavaScript"],"ru":["Создание микрофронтенд-приложений с возможностью удаленной загрузки","Разработка независимых микроприложений с точками входа HTML","Создание модульных веб-компонентов с помощью точек входа JavaScript"],"ar":["بناء تطبيقات ميكرو-أمامية مع قدرات التحميل البعيدة","تنمية تطبيقات دقيقة مستقلة مع نقاط دخول HTML","إنشاء مكونات ويب متوافقة باستخدام نقاط دخول JavaScript"]},"limitations":{"en":["Requires npm installation of @blueking/bk-weweb","Limited to web applications using Web Components technology"],"zh":["需要安装@blueking/bk-weweb的npm","仅限于使用Web Components技术的Web应用程序"],"ja":["@blueking/bk-wewebのnpmをインストールする必要がある","Web Componentsテクノロジーを使用したWebアプリケーションに限定される"],"ko":["@blueking/bk-weweb의 npm을 설치해야 함","Web Components 기술을 사용하는 웹 애플리케이션에만 제한됨"],"es":["Requiere la instalación de npm de @blueking/bk-weweb","Limitado a aplicaciones web que utilizan la tecnología de Web Components"],"fr":["Nécessite l''installation de npm de @blueking/bk-weweb","Limité aux applications web qui utilisent la technologie de Web Components"],"de":["Erfordert die npm-Installation von @blueking/bk-weweb","Begrenzt auf Webanwendungen, die die Web-Components-Technologie verwenden"],"pt":["Requer instalação do npm do @blueking/bk-weweb","Limitado a aplicações web que usam a tecnologia de Web Components"],"ru":["Требует установки npm @blueking/bk-weweb","Ограничен для веб-приложений, использующих технологию Web Components"],"ar":["يتطلب تثبيت npm @blueking/bk-weweb","محدود للتطبيقات الويب التي تستخدم تقنية مكونات الويب"]},"version":4},"contentHash":"4640e7c8971bbe9d452ac974c1871846df1e6d8c239783ce1b38aad0be1565ce","qualityScore":33}');
