INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('TencentBlueKing/bk-weweb/bk-weweb', 'bk-weweb', 'TencentBlueKing', 'bk-weweb', 'community', 'bk-weweb TencentBlueKing bk-weweb community bk-weweb is a micro-frontend framework that supports micro-applications and micro-modules, benefiting developers who need to build complex web applications. It provides a lightweight solution for loading remote applications and modules. BK-WeWeb 是一个基于 Web Components 技术的微前端框架，支持微应用和微模块两种模式。它提供了快速开始和易于使用的 API BK-WeWeb は Web Components 技術をベースにしたマイクロフロントエンドフレームワークで、マイクロアプリとマイクロモジュールの 2 つのモードをサポートします。簡単に開始して、使いやすい API が提供されます BK-WeWeb는 Web Components 기술을 기반으로 한 마이크로 프론트엔드 프레임워크로, 마이크로 애플리케이션과 마イク로 모듈의 2가지 모드를 지원합니다. 쉽게 시작하고, 사용하기 쉬운 API를 제공합니다 bk-weweb es un framework de microfrontends ligero y basado en Web Components, que admite dos modos de ejecución: microaplicaciones y micromódulos bk-weweb est un framework de microfrontends léger et basé sur les Web Components, qui prend en charge deux modes d''exécution : microapplications et micromodules bk-weweb ist ein leichtes Microfrontend-Framework basierend auf Web Components, das zwei Ausführungsmodi unterstützt: Microanwendungen und Micromodule O bk-weweb é um framework de micro frontend leve baseado em Web Components, que suporta dois modos de execução: microaplicativos e micromódulos bk-weweb - легкий микрофронтенд-фреймворк на основе Web Components, поддерживающий два режима выполнения: микроприложения и микромодули bk-weweb هو إطار عمل ميكرو فرونت إند خفيف مبني على ويب كومبوننتس، يدعم وضعين للتشغيل: تطبيقات صغيرة ووحدات صغيرة how to use bk-weweb bk-weweb micro-frontend framework bk-weweb vs single-spa bk-weweb install guide what is bk-weweb bk-weweb alternative bk-weweb setup tutorial bk-weweb web components bk-weweb micro-application mode bk-weweb micro-module mode BK-WeWeb 微前端框架 Web Components 微应用 微模块 npm 安装 TypeScript Supports micro-application and micro-module modes Based on Web Components technology Installs via npm using `npm install @blueking/bk-weweb` Allows importing in main application using `import ''@blueking/bk-weweb'';` Provides two entry types: HTML for micro-applications and JS for micro-modules Enables loading of remote applications and modules bk-weweb is a micro-frontend framework based on Web Components technology, supporting two modes: micro-application and micro-module');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mento-protocol/frontend-monorepo/ask-questions-if-underspecified', 'community', 'mento-protocol', 'frontend-monorepo', 'mento-protocol/frontend-monorepo', 'ask-questions-if-underspecified', 0, 0, 33, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:42.667Z', '78298cb6125789a79e2ac28332c96905278f4de0560bb8ed0b09ffae70f3e08b', '{"id":"mento-protocol/frontend-monorepo/ask-questions-if-underspecified","name":"ask-questions-if-underspecified","description":{"en":"The ask-questions-if-underspecified skill helps AI agents identify underspecified requests and ask clarifying questions to ensure accurate implementation. This skill benefits developers by reducing errors and improving workflow efficiency.","zh":"ask-questions-if-underspecified技巧可以帮助AIエージェント避免不必要的工作，通过提出最小的澄清问题来确保工作的准确性","ja":"ask-questions-if-underspecifiedは、AIエージェントが最小の質問を通じて作業の明確性を保つことを支援する","ko":"ask-questions-if-underspecified는 AI 에이전트가 최소한의 질문을 통해 작업의 명확성을 유지하도록 지원하는 기술입니다","es":"El skill ''ask-questions-if-underspecified'' permite a los desarrolladores identificar y solicitar clarificaciones para especificaciones incompletas, mejorando la precisión y eficiencia en el desarrollo de software","fr":"Le skill ''ask-questions-if-underspecified'' permet aux développeurs d''identifier et de demander des clarifications pour les spécifications incomplètes, améliorant la précision et l''efficacité dans le développement de logiciels","de":"Der Skill ''ask-questions-if-underspecified'' ermöglicht es Entwicklern, unvollständige Spezifikationen zu identifizieren und Klarstellungen anzufordern, wodurch die Genauigkeit und Effizienz in der Softwareentwicklung verbessert werden","pt":"A habilidade de perguntar em casos subespecificados ajuda a evitar trabalhos errados, definindo objetivos claros e necessários","ru":"Навык запроса разъяснений при неоднозначных задачах помогает избежать ошибок, определяя четкие цели и необходимые задачи","ar":"مهارة طرح الأسئلة في الحالات الغير محددة تساعد على تجنب الأخطاء عن طريق تعريف الأهداف الواضحة والمطلوبة"},"seo":{"title":{"en":"ask-questions-if-underspecified: Clarification Setup Guid...","zh":"AIエージェント问答技巧：ask-questions-if-underspecified Setup Guide","ja":"AIエージェントの質問を効率化する：ask-questions-if-underspecified ベストプラクティス","ko":"AI 에이전트를 위한 효율적인 질문技巧: ask-questions-if-underspecified 가이드","es":"Guía de Configuración de Preguntas para Especificaciones ...","fr":"Configurer les Questions pour les Spécifications Incomplè...","de":"Einrichtungsleitfaden für Fragen zu unvollständigen Spezi...","pt":"Guia de Configuração para Perguntas em Casos Subespecific...","ru":"ИИ Агенты: Руководство по Запросу Разъяснений при Неодноз...","ar":"دليل إعداد الأسئلة في الحالات الغير محددة"},"description":{"en":"Discover how to implement ask-questions-if-underspecified and avoid wrong work by asking the right questions - get started with our setup guide today!","zh":"了解ask-questions-if-underspecified技巧，优化AIエージェント的工作流程，减少不必要的工作","ja":"ask-questions-if-underspecifiedを使用して、AIエージェントの質問を最適化し、作業の効率を向上させる","ko":"ask-questions-if-underspecified를 사용하여 AI 에이전트의 질문을 최적화하고 작업 효율을 향상시키는 방법","es":"Aprende a implementar preguntas para especificaciones incompletas en tus proyectos de desarrollo con herramientas de inteligencia artificial","fr":"Découvrez comment configurer les questions pour les spécifications incomplètes dans vos projets de développement avec les outils d''intelligence artificielle","de":"Erfahren Sie, wie Sie Fragen zu unvollständigen Spezifikationen in Ihren Entwicklungsprojekten mit KI-Tools umsetzen","pt":"Aprenda a implementar a habilidade de perguntar em casos subespecificados para evitar trabalhos errados e melhorar a eficiência","ru":"Узнайте, как реализовать навык запроса разъяснений при неоднозначных задачах для повышения эффективности и избежания ошибок","ar":"تعرف على كيفية تنفيذ مهارة طرح الأسئلة في الحالات الغير محددة لتحسين الكفاءة وتجنب الأخطاء"},"definition":{"en":"ask-questions-if-underspecified is a skill that enables AI agents to determine when a request is unclear and prompts them to ask necessary questions to clarify objectives and requirements.","zh":"ask-questions-if-underspecified是一种AIエージェント技巧，用于在工作开始前提出必要的澄清问题","ja":"ask-questions-if-underspecifiedは、AIエージェントが作業開始前に必要な質問を出すための手法","ko":"ask-questions-if-underspecified는 작업 시작 전에 필요한 질문을 하는 AI 에이전트 기술입니다","es":"Una técnica de desarrollo que implica hacer preguntas para aclarar especificaciones incompletas y evitar errores","fr":"Une technique de développement qui consiste à poser des questions pour clarifier les spécifications incomplètes et éviter les erreurs","de":"Eine Entwicklungstechnik, bei der Fragen gestellt werden, um unvollständige Spezifikationen zu klären und Fehler zu vermeiden","pt":"O que é perguntar em casos subespecificados? É a capacidade de identificar e solicitar informações adicionais para evitar ambiguidades","ru":"Что такое запрос разъяснений при неоднозначных задачах? Это способность определять и запрашивать дополнительную информацию для избежания неоднозначностей","ar":"ما هي مهارة طرح الأسئلة في الحالات الغير محددة؟ هي القدرة على تحديد وطلب المعلومات الإضافية لتجنب الغموض"},"features":{"en":["Identifies underspecified requests by exploring work requirements","Asks minimum set of clarifying questions to avoid wrong work","Delays implementation until must-have questions are answered or user approves stated assumptions","Treats requests as underspecified if objectives or requirements are unclear","Prompts AI agents to ask questions to define the objective and identify what should change or stay the same"],"zh":["根据工作目标和范围提出澄清问题","避免不必要的工作和误解","确保工作的准确性和效率","支持多种工作流程和场景","与Mento UIs集成"],"ja":["作業の目的と範囲に基づく質問の提出","不要な作業と誤解の回避","作業の正確性と効率の確保","多様なワークフローとシナリオのサポート","Mento UIsとの連携"],"ko":["작업 목표와 범위에 따라 질문을 제안","불필요한 작업과 오해를 피함","작업의 정확성과 효율성을 보장","다양한 워크플ロー와 시나리오 지원","Mento UIs와의 통합"],"es":["Identificación de especificaciones incompletas","Solicitud de clarificaciones para evitar errores","Mejora de la precisión y eficiencia en el desarrollo de software","Integración con herramientas de inteligencia artificial","Compatibilidad con flujos de trabajo de desarrollo ágiles"],"fr":["Identification des spécifications incomplètes","Demande de clarifications pour éviter les erreurs","Amélioration de la précision et de l''efficacité dans le développement de logiciels","Intégration avec les outils d''intelligence artificielle","Compatibilité avec les flux de travail de développement agiles"],"de":["Identifizierung unvollständiger Spezifikationen","Anforderung von Klarstellungen zur Fehlervermeidung","Verbesserung der Genauigkeit und Effizienz in der Softwareentwicklung","Integration mit KI-Tools","Kompatibilität mit agilen Entwicklungswerkzeugen"],"pt":["Definição de objetivos claros","Identificação de necessidades de informações adicionais","Solicitação de esclarecimentos para evitar ambiguidades","Melhoria da eficiência e redução de erros","Integração com tecnologias de UI, como Mento UIs"],"ru":["Определение четких целей","Определение необходимости дополнительной информации","Запрос разъяснений для избежания неоднозначностей","Повышение эффективности и снижение ошибок","Интеграция с технологиями интерфейса пользователя, такими как Mento UIs"],"ar":["تحديد الأهداف الواضحة","تحديد حاجة المعلومات الإضافية","طلب التوضيحات لتجنب الغموض","تحسين الكفاءة وخفض الأخطاء","التكامل مع تكنولوجيا واجهة المستخدم، مثل Mento UIs"]},"keywords":{"en":["how to use ask-questions-if-underspecified","what is ask-questions-if-underspecified","ask-questions-if-underspecified alternative","ask-questions-if-underspecified vs clarification skills","ask-questions-if-underspecified install","ask-questions-if-underspecified setup guide","clarification techniques for AI agents","avoiding wrong work in AI implementation"],"zh":["AIエージェント","ask-questions-if-underspecified","工作流程优化","澄清问题","Mento UIs","AI工具","工作效率","作业准确性"],"ja":["AIエージェント","ask-questions-if-underspecified","ワークフロー最適化","質問の提出","Mento UIs","AIツール","作業効率","作業の正確性"],"ko":["AI 에이전트","ask-questions-if-underspecified","작업 흐름 최적화","질문 제안","Mento UIs","AI 도구","작업 효율","작업 정확성"],"es":["herramientas de inteligencia artificial","desarrollo de software","especificaciones incompletas","preguntas para aclarar","mejora de la precisión","eficiencia en el desarrollo","integración con AI","desarrollo ágil"],"fr":["outils d''intelligence artificielle","développement de logiciels","spécifications incomplètes","questions pour clarifier","amélioration de la précision","efficacité dans le développement","intégration avec l''IA","développement agile"],"de":["KI-Tools","Softwareentwicklung","unvollständige Spezifikationen","Fragen zur Klarstellung","Verbesserung der Genauigkeit","Effizienz in der Entwicklung","Integration mit KI","agiles Entwicklungswerkzeug"],"pt":["perguntar em casos subespecificados","guias de configuração","melhoria da eficiência","redução de erros","tecnologias de UI","Mento UIs","desenvolvimento de software","engenharia de software"],"ru":["запрос разъяснений при неоднозначных задачах","руководство по настройке","повышение эффективности","снижение ошибок","технологии интерфейса пользователя","Mento UIs","разработка программного обеспечения","инженерия программного обеспечения"],"ar":["طرح الأسئلة في الحالات الغير محددة","دليل الإعداد","تحسين الكفاءة","تقليل الأخطاء","تكنولوجيا واجهة المستخدم","Mento UIs","تطوير البرمجيات","هندسة البرمجيات"]}},"owner":"mento-protocol","repo":"frontend-monorepo","repoPath":"mento-protocol/frontend-monorepo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"ask-questions-if-underspecified","description":"Clarify requirements before implementing. Do not use automatically, only when invoked explicitly.","bodyPreview":"# Ask Questions If Underspecified\n\n## Goal\n\nAsk the minimum set of clarifying questions needed to avoid wrong work; do not start implementing until the must-have questions are answered (or the user explicitly approves proceeding with stated assumptions).\n\n## Workflow\n\n### 1) Decide whether the request is underspecified\n\nTreat a request as underspecified if after exploring how to perform the work, some or all of the following are not clear:\n\n- Define the objective (what should change vs stay the","body":"# Ask Questions If Underspecified\n\n## Goal\n\nAsk the minimum set of clarifying questions needed to avoid wrong work; do not start implementing until the must-have questions are answered (or the user explicitly approves proceeding with stated assumptions).\n\n## Workflow\n\n### 1) Decide whether the request is underspecified\n\nTreat a request as underspecified if after exploring how to perform the work, some or all of the following are not clear:\n\n- Define the objective (what should change vs stay the same)\n- Define \"done\" (acceptance criteria, examples, edge cases)\n- Define scope (which files/components/users are in/out)\n- Define constraints (compatibility, performance, style, deps, time)\n- Identify environment (language/runtime versions, OS, build/test runner)\n- Clarify safety/reversibility (data migration, rollout/rollback, risk)\n\nIf multiple plausible interpretations exist, assume it is underspecified.\n\n### 2) Ask must-have questions first (keep it small)\n\nAsk 1-5 questions in the first pass. Prefer questions that eliminate whole branches of work.\n\nMake questions easy to answer:\n\n- Optimize for scannability (short, numbered questions; avoid paragraphs)\n- Offer multiple-choice options when possible\n- Suggest reasonable defaults when appropriate (mark them clearly as the default/recommended choice; bold the recommended choice in the list, or if you present options in a code block, put a bold \"Recommended\" line immediately above the block and also tag defaults inside the block)\n- Include a fast-path response (e.g., reply `defaults` to accept all recommended/default choices)\n- Include a low-friction \"not sure\" option when helpful (e.g., \"Not sure - use default\")\n- Separate \"Need to know\" from \"Nice to know\" if that reduces friction\n- Structure options so the user can respond with compact decisions (e.g., `1b 2a 3c`); restate the chosen options in plain language to confirm\n\n### 3) Pause before acting\n\nUntil must-have answers arrive:\n\n- Do not run commands, edit files, or produce a detailed plan that depends on unknowns\n- Do perform a clearly labeled, low-risk discovery step only if it does not commit you to a direction (e.g., inspect repo structure, read relevant config files)\n\nIf the user explicitly asks you to proceed without answers:\n\n- State your assumptions as a short numbered list\n- Ask for confirmation; proceed only after they confirm or correct them\n\n### 4) Confirm interpretation, then proceed\n\nOnce you have answers, restate the requirements in 1-3 sentences (including key constraints and what success looks like), then start work.\n\n## Question templates\n\n- \"Before I start, I need: (1) ..., (2) ..., (3) .... If you don''t care about (2), I will assume ....\"\n- \"Which of these should it be? A) ... B) ... C) ... (pick one)\"\n- \"What would you consider ''done''? For example: ...\"\n- \"Any constraints I must follow (versions, performance, style, deps)? If none, I will target the existing project defaults.\"\n- Use numbered questions with lettered options and a clear reply format\n\n```text\n1) Scope?\na) Minimal change (default)\nb) Refactor while touching the area\nc) Not sure - use default\n2) Compatibility target?\na) Current project defaults (default)\nb) Also support older versions: <specify>\nc) Not sure - use default\n\nReply with: defaults (or 1a 2a)\n```\n\n## Anti-patterns\n\n- Don''t ask questions you can answer with a quick, low-risk discovery read (e.g., configs, existing patterns, docs).\n- Don''t ask open-ended questions if a tight multiple-choice or yes/no would eliminate ambiguity faster.\n"},"lastSynced":"2026-03-08T02:08:42.667Z","agentAnalysis":{"suitability":{"en":"Ideal for Conversational AI Agents like Claude or AutoGPT needing to clarify user requests and avoid misinterpretation.","zh":"适合于需要澄清用户请求并避免误解的对话式 AI 代理，如 Claude 或 AutoGPT。","ja":"Claude または AutoGPT のような、ユーザーのリクエストを明確化し、誤解を避ける必要がある会話型 AI エージェントに最適です。","ko":"클라르크 또는 오토지피티 같은 대화형 AI 에이전트가 사용자 요청을 명확히 하고 오해를 피하는 데 적합합니다.","es":"Ideal para Agentes de IA Conversacional como Claude o AutoGPT que necesitan aclarar solicitudes de usuario y evitar malas interpretaciones.","fr":"Idéal pour les agents d''IA conversationnels comme Claude ou AutoGPT qui doivent clarifier les demandes des utilisateurs et éviter les mauvaises interprétations.","de":"Ideal für Conversational AI-Agents wie Claude oder AutoGPT, die Benutzeranfragen klären und Fehlinterpretationen vermeiden müssen.","pt":"Ideal para Agentes de IA Conversacional como Claude ou AutoGPT que precisam esclarecer solicitações de usuários e evitar interpretações erradas.","ru":"Идеально подходит для разговорных агентов ИИ, таких как Claude или AutoGPT, которым необходимо уточнять запросы пользователей и избегать неправильного толкования.","ar":"مثالي لعميل الذكاء الاصطناعي المحادث مثل Claude أو AutoGPT الذين يحتاجون إلى توضيح طلبات المستخدم وتجنب سوء الفهم."},"recommendation":{"en":"Empowers agents to identify underspecified requests and ask targeted clarifying questions, ensuring accurate implementation and reducing errors by leveraging objective definition and workflow efficiency protocols.","zh":"赋予代理识别不明确请求的能力，并提出有针对性的澄清问题，确保准确实施并通过利用客观定义和工作流效率协议减少错误。","ja":"エージェントが不明確なリクエストを特定し、ターゲットを絞ったクエリを提出できるようにし、正確な実装を保証し、客観的な定義とワークフロー効率プロトコルを利用してエラーを削減します。","ko":"에이전트가 요청을 명확히 하지 않는 것을 식별하고 목표를 명확히 하는 질문을 제기하여 정확한 구현을 보장하고 객관적인 정의 및 워크플로우 효율성 프로토콜을 활용하여 오류를 줄입니다.","es":"Permite a los agentes identificar solicitudes poco especificadas y hacer preguntas de aclaración dirigidas, garantizando una implementación precisa y reduciendo los errores mediante la utilización de protocolos de definición objetiva y eficiencia de flujo de trabajo.","fr":"Permet aux agents d''identifier les demandes peu spécifiées et de poser des questions de clarification ciblées, assurant une mise en œuvre précise et réduisant les erreurs en exploitant les protocoles de définition objective et d''efficacité de workflow.","de":"Ermöglicht es den Agenten, wenig spezifizierte Anfragen zu identifizieren und gezielte Klärungsfragen zu stellen, wodurch eine genaue Umsetzung sichergestellt und Fehler durch die Nutzung von Protokollen für objektive Definition und Workflow-Effizienz reduziert werden.","pt":"Habilita os agentes a identificar solicitações subespecificadas e fazer perguntas esclarecedoras direcionadas, garantindo implementação precisa e reduzindo erros por meio de protocolos de definição objetiva e eficiência de fluxo de trabalho.","ru":"Наделяет агентов возможностью выявлять неоднозначные запросы и задавать целевые уточняющие вопросы, обеспечивая точную реализацию и снижая количество ошибок за счет использования объективных определений и протоколов эффективности рабочего процесса.","ar":"تمكّن الوكيل من تحديد الطلبات غير المحددة جيدًا وطرح أسئلة توضيحية مستهدفة، مما يضمن التنفيذ الدقيق وتقليل الأخطاء من خلال بروتوكولات التعريف الموضوعي وكفاءة سير العمل."},"useCases":{"en":["Automating request clarification for complex tasks","Generating targeted questions for user confirmation","Debugging underspecified objectives to ensure correct outcomes"],"zh":["复杂任务的请求澄清自动化","生成针对用户确认的有针对性的问题","调试不明确的目标以确保正确的结果"],"ja":["複雑なタスクのリクエストの明確化の自動化","ユーザー確認のためのターゲットを絞った質問の生成","不明確な目的のデバッグによる正確な結果の確保"],"ko":["복잡한 작업의 요청 명확화 자동화","사용자 확인을 위한 목표를 명확히 하는 질문 생성","명확하지 않은 목표의 디버깅을 통한 올바른 결과 보장"],"es":["Automatización de la aclaración de solicitudes para tareas complejas","Generación de preguntas dirigidas para la confirmación del usuario","Depuración de objetivos poco especificados para garantizar resultados correctos"],"fr":["Automatisation de la clarification des demandes pour les tâches complexes","Génération de questions ciblées pour la confirmation de l''utilisateur","Débogage d''objectifs peu spécifiés pour assurer des résultats corrects"],"de":["Automatisierung der Anfrageklärung für komplexe Aufgaben","Generierung gezielter Fragen für die Benutzerbestätigung","Fehlerbehebung ungenauer Ziele, um korrekte Ergebnisse sicherzustellen"],"pt":["Automatizar a clarificação de solicitações para tarefas complexas","Gerar perguntas direcionadas para confirmação do usuário","Depurar objetivos não especificados para garantir resultados corretos"],"ru":["Автоматизация уточнения запросов для сложных задач","Генерация целевых вопросов для подтверждения пользователя","Отладка неоднозначных целей для обеспечения правильных результатов"],"ar":["تأتمتة توضيح الطلبات للمهام المعقدة","توليد أسئلة مستهدفة لتأكيد المستخدم","تصحيح الأهداف غير المحددة جيدًا لضمان النتائج الصحيحة"]},"limitations":{"en":["Requires clear user interaction protocols","Dependent on agent''s ability to understand request context"],"zh":["需要清晰的用户交互协议","依赖于代理理解请求上下文的能力"],"ja":["明確なユーザーインタラクションプロトコルが必要","エージェントのリクエストコンテキストを理解する能力に依存"],"ko":["명확한 사용자 상호작용 프로토콜이 필요","에이전트가 요청 콘텍스트를 이해하는 능력에 의존"],"es":["Requiere protocolos de interacción de usuario claros","Dependiente de la capacidad del agente para comprender el contexto de la solicitud"],"fr":["Nécessite des protocoles d''interaction utilisateur clairs","Dépend de la capacité de l''agent à comprendre le contexte de la demande"],"de":["Benötigt klare Benutzerinteraktionsprotokolle","Hängt von der Fähigkeit des Agents ab, den Kontext der Anfrage zu verstehen"],"pt":["Exige protocolos de interação do usuário claros","Depende da capacidade do agente de entender o contexto da solicitação"],"ru":["Требует четких протоколов взаимодействия с пользователем","Зависит от способности агента понимать контекст запроса"],"ar":["يتطلب بروتوكولات تفاعل المستخدم واضحة","يعتمد على قدرة الوكيل على فهم سياق الطلب"]},"version":4},"contentHash":"78298cb6125789a79e2ac28332c96905278f4de0560bb8ed0b09ffae70f3e08b","qualityScore":33}');
