INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mento-protocol/frontend-monorepo/ask-questions-if-underspecified', 'ask-questions-if-underspecified', 'mento-protocol', 'frontend-monorepo', 'community', 'ask-questions-if-underspecified mento-protocol frontend-monorepo community The ask-questions-if-underspecified skill helps AI agents identify underspecified requests and ask clarifying questions to ensure accurate implementation. This skill benefits developers by reducing errors and improving workflow efficiency. ask-questions-if-underspecified技巧可以帮助AIエージェント避免不必要的工作，通过提出最小的澄清问题来确保工作的准确性 ask-questions-if-underspecifiedは、AIエージェントが最小の質問を通じて作業の明確性を保つことを支援する ask-questions-if-underspecified는 AI 에이전트가 최소한의 질문을 통해 작업의 명확성을 유지하도록 지원하는 기술입니다 El skill ''ask-questions-if-underspecified'' permite a los desarrolladores identificar y solicitar clarificaciones para especificaciones incompletas, mejorando la precisión y eficiencia en el desarrollo de software Le skill ''ask-questions-if-underspecified'' permet aux développeurs d''identifier et de demander des clarifications pour les spécifications incomplètes, améliorant la précision et l''efficacité dans le développement de logiciels Der Skill ''ask-questions-if-underspecified'' ermöglicht es Entwicklern, unvollständige Spezifikationen zu identifizieren und Klarstellungen anzufordern, wodurch die Genauigkeit und Effizienz in der Softwareentwicklung verbessert werden A habilidade de perguntar em casos subespecificados ajuda a evitar trabalhos errados, definindo objetivos claros e necessários Навык запроса разъяснений при неоднозначных задачах помогает избежать ошибок, определяя четкие цели и необходимые задачи مهارة طرح الأسئلة في الحالات الغير محددة تساعد على تجنب الأخطاء عن طريق تعريف الأهداف الواضحة والمطلوبة how to use ask-questions-if-underspecified what is ask-questions-if-underspecified ask-questions-if-underspecified alternative ask-questions-if-underspecified vs clarification skills ask-questions-if-underspecified install ask-questions-if-underspecified setup guide clarification techniques for AI agents avoiding wrong work in AI implementation AIエージェント ask-questions-if-underspecified 工作流程优化 澄清问题 Mento UIs AI工具 工作效率 作业准确性 Identifies underspecified requests by exploring work requirements Asks minimum set of clarifying questions to avoid wrong work Delays implementation until must-have questions are answered or user approves stated assumptions Treats requests as underspecified if objectives or requirements are unclear Prompts AI agents to ask questions to define the objective and identify what should change or stay the same ask-questions-if-underspecified is a skill that enables AI agents to determine when a request is unclear and prompts them to ask necessary questions to clarify objectives and requirements.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ewei068/pokestar/add-move', 'community', 'ewei068', 'pokestar', 'ewei068/pokestar', 'add-move', 0, 0, 33, '2026-03-08T01:57:15.443Z', '2026-03-08T02:08:46.178Z', '0cd839f77949beb8765ee0e3d5f2475bd52a267af073821b7d0e6ef5f604f935', '{"id":"ewei068/pokestar/add-move","name":"add-move","description":{"en":"The add-move skill enables developers to add new moves to the Pokemon Gacha Discord Bot by modifying specific files. This skill benefits bot developers and enthusiasts.","zh":"本指南介绍如何向Pokestar添加移动，包括修改相关文件和实现移动结构","ja":"Pokestarにムーブを追加する方法を紹介します。関連ファイルの修正とムーブ構造の実装を含みます","ko":"이 가이드는 Pokestar에 이동을 추가하는 방법을介绍합니다. 관련 파일 수정 및 이동 구조 구현 포함","es":"El skill add-move permite agregar movimientos a Pokestar en el bot de Discord Pokémon Gacha. Requiere la modificación de archivos como battleEnums.js y moves.js","fr":"Le skill add-move permet d''ajouter des mouvements à Pokestar sur le bot Discord Pokémon Gacha. Il nécessite la modification de fichiers tels que battleEnums.js et moves.js","de":"Das Skill add-move ermöglicht das Hinzufügen von Bewegungen zu Pokestar im Discord-Bot Pokémon Gacha. Es erfordert die Bearbeitung von Dateien wie battleEnums.js und moves.js","pt":"O add-move é uma habilidade que permite adicionar movimentos ao Pokestar. Aprenda como configurá-lo.","ru":"ИИ Агенты для Покемон Гача Бота: добавление движений с помощью add-move.","ar":"إضافة add-move هي سمة تمكنك من إضافة الحركات إلى بوكستار. تعلم كيفية تكوينها."},"seo":{"title":{"en":"add-move: Setup Guide for Pokemon Gacha Discord Bot | AI ...","zh":"添加移动Setup Guide - Pokémon Gacha Discord Bot","ja":"ムーブ追加セットアップガイド - Pokémon Gacha Discord Bot","ko":"이동 추가 설정 가이드 - Pokémon Gacha Discord Bot","es":"Guía de configuración para add-move en Pokémon Gacha Disc...","fr":"Guide d''installation pour add-move sur Pokémon Gacha Disc...","de":"Einrichtungsanleitung für add-move in Pokémon Gacha Disco...","pt":"Guia de Configuração add-move: Adicionando Movimentos ao ...","ru":"ИИ Агенты: Настройка add-move для Покемон Гача Бота","ar":"إضافة الحركات إلى بوكستار باستخدام إضافة add-move"},"description":{"en":"Discover how to add moves to Pokestar with our step-by-step guide. Learn to modify battleEnums.js and moves.js files for a seamless experience.","zh":"学习如何向Pokestar添加移动，包括修改src/enums/battleEnums.js和src/battle/data/moves.js文件","ja":"Pokestarにムーブを追加する方法を学ぶ，src/enums/battleEnums.jsとsrc/battle/data/moves.jsファイルの修正を含む","ko":"Pokestar에 이동을 추가하는 방법을 배우세요. src/enums/battleEnums.js 및 src/battle/data/moves.js 파일 수정 포함","es":"Aprende a agregar movimientos a Pokestar con nuestro bot de Discord. Descubre cómo modificar archivos para implementar nuevos movimientos","fr":"Découvrez comment ajouter des mouvements à Pokestar avec notre bot Discord. Apprenez à modifier les fichiers pour implémenter de nouveaux mouvements","de":"Erfahren Sie, wie Sie Bewegungen zu Pokestar hinzufügen, mit unserem Discord-Bot. Entdecken Sie, wie Sie Dateien bearbeiten, um neue Bewegungen zu implementi...","pt":"Aprenda a adicionar movimentos ao Pokestar com o bot de gacha do Discord. Guia passo a passo para desenvolvedores.","ru":"ИИ Агенты для Покемон Гача Бота. Узнайте, как добавить движения с помощью add-move.","ar":"تعلم كيفية إضافة الحركات إلى بوكستار باستخدام إضافة add-move. دليل شامل للمطورين."},"definition":{"en":"add-move is a technical skill for modifying the Pokemon Gacha Discord Bot, allowing developers to add new moves by updating the battleEnums.js and moves.js files.","zh":"添加移动是指向Pokestar添加新移动的过程，涉及修改枚举和移动数据文件","ja":"ムーブ追加は、Pokestarに新しいムーブを追加するプロセスであり、列挙型とムーブデータファイルの修正を含む","ko":"이동 추가는 Pokestar에 새로운 이동을 추가하는 과정으로, 열거형 및 이동 데이터 파일 수정을 포함","es":"add-move es un skill que permite agregar nuevos movimientos a Pokestar en un bot de Discord","fr":"add-move est un skill qui permet d''ajouter de nouveaux mouvements à Pokestar sur un bot Discord","de":"add-move ist ein Skill, der das Hinzufügen neuer Bewegungen zu Pokestar in einem Discord-Bot ermöglicht","pt":"O add-move é uma habilidade que adiciona movimentos ao Pokestar, permitindo personalização do jogo.","ru":"ИИ Агенты: add-move - это способность, добавляющая движения в Покемон Гача Бот.","ar":"إضافة add-move هي سمة تتيح إضافة الحركات إلى بوكستار، مما يسمح بالتخصيص اللعبة."},"features":{"en":["Modifies src/enums/battleEnums.js to add new moveIdEnum entries","Updates src/battle/data/moves.js to implement new move structures","Utilizes the Move class with properties like id, name, type, and power","Supports addition of custom moves with specific types, such as FIRE, WATER, or GRASS","Requires careful modification of specific files without altering other moves or battleConfig.js"],"zh":["修改src/enums/battleEnums.js文件添加移动枚举","实现移动结构，包括移动ID、名称、类型和威力","添加移动实现到src/battle/data/moves.js文件","支持多种移动类型，例如火、水、草等","使用JavaScript语言实现移动添加"],"ja":["src/enums/battleEnums.jsファイルを修正してムーブ列挙型を追加","ムーブ構造を実装，ムーブID、名称、タイプ、威力を含む","ムーブ実装をsrc/battle/data/moves.jsファイルに追加","複数のムーブタイプをサポート，例えば火、水、草など","JavaScript言語を使用してムーブ追加を実現"],"ko":["src/enums/battleEnums.js 파일 수정하여 이동 열거형 추가","이동 구조 구현, 이동 ID, 이름, 유형 및 위력을 포함","이동 구현을 src/battle/data/moves.js 파일에 추가","여러 가지 이동 유형 지원, 예를 들어 불, 물, 초록 등","JavaScript 언어 사용하여 이동 추가 구현"],"es":["Modificación de archivos como battleEnums.js y moves.js","Implementación de nuevos movimientos con la estructura de Move","Uso de enums para identificar movimientos únicos","Configuración de tipo y poder de los movimientos","Integración con el bot de Discord Pokémon Gacha"],"fr":["Modification de fichiers tels que battleEnums.js et moves.js","Implémentation de nouveaux mouvements avec la structure de Move","Utilisation d''enums pour identifier des mouvements uniques","Configuration du type et de la puissance des mouvements","Intégration avec le bot Discord Pokémon Gacha"],"de":["Bearbeitung von Dateien wie battleEnums.js und moves.js","Implementierung neuer Bewegungen mit der Struktur von Move","Verwendung von Enums zur Identifizierung eindeutiger Bewegungen","Konfiguration von Typ und Kraft der Bewegungen","Integration mit dem Discord-Bot Pokémon Gacha"],"pt":["Adiciona movimentos ao Pokestar","Modifica o arquivo src/enums/battleEnums.js","Cria implementação de movimento em src/battle/data/moves.js","Suporta tipos de Pokémon como FOGO, ÁGUA e GRAMA","Permite personalização do poder do movimento"],"ru":["Добавляет движения в Покемон Гача Бот","Изменяет файл src/enums/battleEnums.js","Создает реализацию движения в src/battle/data/moves.js","Поддерживает типы покемонов, такие как ОГОНЬ, ВОДА и ТРАВА","Позволяет настраивать силу движения"],"ar":["تتيح إضافة الحركات إلى بوكستار","يتطلب تعديل ملف src/enums/battleEnums.js","يخلق تنفيذ الحركة في src/battle/data/moves.js","يدعم أنواع البوكيمون مثل النار والماء وال草","يسمح بالتخصيص لقوة الحركة"]},"keywords":{"en":["how to use add-move","add-move setup guide","pokemon gacha discord bot moves","add-move alternative","add-move vs other discord bots","add-move install","what is add-move","add-move documentation","modifying battleEnums.js","adding custom moves to pokemon gacha"],"zh":["添加移动","Pokestar","Discord Bot","JavaScript","移动枚举","移动结构","AIエージェント"," Pokémon Gacha"],"ja":["ムーブ追加","Pokestar","Discord Bot","JavaScript","ムーブ列挙型","ムーブ構造","AIエージェント","Pokémon Gacha"],"ko":["이동 추가","Pokestar","Discord Bot","JavaScript","이동 열거형","이동 구조","AI 에이전트","Pokémon Gacha"],"es":["add-move","Pokémon Gacha Discord Bot","agregar movimientos","modificar archivos","implementar nuevos movimientos","enums en JavaScript","bot de Discord para Pokémon"],"fr":["add-move","Pokémon Gacha Discord Bot","ajouter des mouvements","modifier des fichiers","implémenter de nouveaux mouvements","enums en JavaScript","bot Discord pour Pokémon"],"de":["add-move","Pokémon Gacha Discord Bot","Bewegungen hinzufügen","Dateien bearbeiten","neue Bewegungen implementieren","Enums in JavaScript","Discord-Bot für Pokémon"],"pt":["add-move","Pokestar","Pokémon Gacha Discord Bot","adicionar movimentos","personalização de jogo","desenvolvimento de jogos","JavaScript","Discord Bot"],"ru":["ИИ Агенты","add-move","Покемон Гача Бот","добавление движений","настройка игры","разработка игр","JavaScript","Discord Бот"],"ar":["إضافة add-move","بوكستار","بوكيمون غاتش ديسكورد بوت","إضافة الحركات","تخصيص اللعبة","تطوير الألعاب","جافا سكريبت","ديسكورد بوت"]}},"owner":"ewei068","repo":"pokestar","repoPath":"ewei068/pokestar","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.443Z","topics":[],"category":"community","skillMd":{"name":"add-move","description":"Add new moves to the battle system. Use when implementing attack, status, or support moves for Pokemon.","bodyPreview":"# Adding Moves to Pokestar\n\n## Quick Reference\n\n**Files to modify:**\n\n1. `src/enums/battleEnums.js` - Add `moveIdEnum.YOUR_MOVE` entry (ONLY if not exists)\n2. `src/battle/data/moves.js` - Add the move implementation\n\n**DO NOT** modify other moves or `battleConfig.js` unless explicitly asked.\n\n## Move Structure\n\n```javascript\n[moveIdEnum.MOVE_NAME]: new Move({\n  id: moveIdEnum.MOVE_NAME,\n  name: \"Move Name\",\n  type: pokemonTypes.TYPE,           // FIRE, WATER, GRASS, etc.\n  power: 80,","body":"# Adding Moves to Pokestar\n\n## Quick Reference\n\n**Files to modify:**\n\n1. `src/enums/battleEnums.js` - Add `moveIdEnum.YOUR_MOVE` entry (ONLY if not exists)\n2. `src/battle/data/moves.js` - Add the move implementation\n\n**DO NOT** modify other moves or `battleConfig.js` unless explicitly asked.\n\n## Move Structure\n\n```javascript\n[moveIdEnum.MOVE_NAME]: new Move({\n  id: moveIdEnum.MOVE_NAME,\n  name: \"Move Name\",\n  type: pokemonTypes.TYPE,           // FIRE, WATER, GRASS, etc.\n  power: 80,                         // Base damage (null for non-damaging)\n  accuracy: 100,                     // Hit chance % (null = always hits)\n  cooldown: 3,                       // Turns before reusable\n  targetType: targetTypes.ENEMY,     // ENEMY, ALLY, ANY\n  targetPosition: targetPositions.FRONT, // FRONT, BACK, ANY, SELF, NON_SELF\n  targetPattern: targetPatterns.SINGLE,  // See references/target-patterns.md\n  tier: moveTiers.POWER,             // BASIC, POWER, ULTIMATE\n  damageType: damageTypes.PHYSICAL,  // PHYSICAL, SPECIAL, OTHER\n  description: \"Move description\",\n  execute() { /* implementation */ },\n}),\n```\n\n## Execute Context\n\n**NOTE:** The `execute` function binds `this` to the `MoveInstance.js` `MoveInstance` class, with properties such as:\n\n**Example Properties:**\n\n- `this.source` - User of the move\n- `this.primaryTarget` - Main target selected\n- `this.allTargets` - All affected targets (based on pattern)\n- `this.missedTargets` - Targets that were missed\n- `this.battle` - Battle instance\n- `this.power`, `this.type`, `this.id` - Move properties\n\n## Example Generic Methods\n\nAll generic methods are available in `MoveInstance.js`. These are some common examples:\n\n```javascript\n// Deal damage to all targets\nthis.genericDealAllDamage();\n// Returns { damageInstances: {targetId: damage}, totalDamageDealt: number }\n\n// Custom damage calculation\nthis.genericDealAllDamage({\n  calculateDamageFunction: (args) =>\n    this.source.calculateMoveDamage(args) * 1.5,\n  offTargetDamageMultiplier: 0.5,\n  backTargetDamageMultiplier: 0.7,\n  attackOverride: this.source.getStat(\"def\"),\n});\n\n// Apply status (BURN, PARALYSIS, FROZEN, SLEEP, POISON)\nthis.genericApplyAllStatus({\n  statusId: statusConditions.BURN,\n  probability: 0.3,\n});\n\n// Apply effect (see references/effects.md)\nthis.genericApplyAllEffects({\n  effectId: \"atkUp\",\n  duration: 3,\n  probability: 0.5,\n});\n\n// Single target effect\nthis.genericApplySingleEffect({\n  target: this.primaryTarget,\n  effectId: \"shield\",\n  duration: 3,\n  initialArgs: { shield: 100 },\n});\n\n// Combat readiness\nthis.genericChangeAllCombatReadiness({ amount: 25, action: \"boost\" }); // or \"reduce\"\n\n// Healing\nthis.genericHealAllTargets({ healPercent: 25 });\nthis.genericHealSingleTarget({ target, healAmount: 100 });\n```\n\n## Move Tags\n\nOptional `tags` array for ability interactions:\n\n- `\"punch\"` - Boosted by Iron Fist ability\n- `\"slice\"` - Boosted by Sharpness ability\n- `\"charge\"` - Two-turn move\n\n## Dynamic Move Properties\n\nUse `overrideFields` to change properties based on context:\n\n```javascript\noverrideFields: (options) => {\n  if (options.source?.speciesId === pokemonIdEnum.SPECIAL_FORM) {\n    return { power: 120, description: \"Enhanced version\" };\n  }\n},\n```\n\n## Useful BattlePokemon Methods\n\n- `pokemon.getStat(\"atk\")` - Get effective stat\n- `pokemon.hasType(pokemonTypes.FIRE)` - Check type\n- `pokemon.applyEffect(id, duration, source, initialArgs)`\n- `pokemon.dispellEffect(effectId)` - Remove effect\n- `pokemon.removeStatus()` - Clear status condition\n- `pokemon.dealDamage(amount, target, info)` - Deal damage\n- `pokemon.giveHeal(amount, target, info)` - Heal\n- `pokemon.boostCombatReadiness(source, amount)`\n- `pokemon.getPartyPokemon()` - Get ally array\n- `pokemon.isFainted` - Check if fainted\n\n## References\n\n- `references/target-patterns.md` - Visual guide to target patterns\n- `references/effects.md` - List of all buff/debuff effect IDs\n- `references/pattern-*.md` - Code examples for common move types\n"},"lastSynced":"2026-03-08T02:08:46.178Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents specializing in Discord bot development and Pokemon game mechanics modification.","zh":"非常适合专注于 Discord 机器人开发和 Pokemon 游戏机制修改的 AI Agent。","ja":"Discordボット開発とPokemonゲームのメカニック修正に特化したAIエージェントに理想的です。","ko":"Discord 봇 개발과 Pokemon 게임 메커니즘 수정에 특화된 AI 에이전트에 이상적입니다.","es":"Ideal para Agentes de IA que se especializan en el desarrollo de bots de Discord y la modificación de mecánicas de juego de Pokémon.","fr":"Idéal pour les agents IA spécialisés dans le développement de bots Discord et la modification des mécaniques de jeu de Pokémon.","de":"Ideal für KI-Agents, die auf die Entwicklung von Discord-Bots und die Modifizierung von Pokémon-Spielmechaniken spezialisiert sind.","pt":"Ideal para Agentes de IA especializados em desenvolvimento de bots para Discord e modificação de mecânicas de jogos de Pokemon.","ru":"Идеально подходит для ИИ-агентов, специализирующихся на разработке ботов для Discord и модификации механик игр Pokemon.","ar":"مثالي لوكلاء الذكاء الاصطناعي المتخصصين في تطوير بوتات Discord وتعديل ميكانيكيات ألعاب Pokemon."},"recommendation":{"en":"Enables direct modification of Pokemon battle mechanics by adding new move implementations to the battle system. Provides structured access to modify moveIdEnum in battleEnums.js and implement complete move objects in moves.js with type, power, and effect specifications.","zh":"通过向战斗系统添加新的招式实现，能够直接修改 Pokemon 战斗机制。提供结构化访问以修改 battleEnums.js 中的 moveIdEnum，并在 moves.js 中实现包含类型、威力和效果规范的完整招式对象。","ja":"バトルシステムに新しいわざの実装を追加することで、Pokemonのバトルメカニックを直接修正できます。battleEnums.js内のmoveIdEnumを修正し、moves.jsにタイプ、威力、効果の仕様を含む完全なわざオブジェクトを実装するための構造化されたアクセスを提供します。","ko":"배틀 시스템에 새로운 기술 구현을 추가하여 Pokemon 배틀 메커니즘을 직접 수정할 수 있게 합니다. battleEnums.js의 moveIdEnum을 수정하고, 타입, 위력, 효과 사양을 포함한 완전한 기술 객체를 moves.js에 구현하기 위한 구조화된 접근을 제공합니다.","es":"Permite la modificación directa de las mecánicas de batalla de Pokémon agregando nuevas implementaciones de movimientos al sistema de batalla. Proporciona acceso estructurado para modificar moveIdEnum en battleEnums.js e implementar objetos de movimiento completos en moves.js con especificaciones de tipo, potencia y efecto.","fr":"Permet la modification directe des mécaniques de bataille de Pokémon en ajoutant de nouvelles implémentations de mouvements au système de bataille. Fournit un accès structuré pour modifier moveIdEnum dans battleEnums.js et implémenter des objets de mouvement complets dans moves.js avec des spécifications de type, de puissance et d''effet.","de":"Ermöglicht die direkte Modifizierung der Pokémon-Kampfmechaniken durch Hinzufügen neuer Bewegungsumsetzungen zum Kampfsystem. Bietet strukturierten Zugriff zum Modifizieren von moveIdEnum in battleEnums.js und zum Implementieren vollständiger Bewegungsobjekte in moves.js mit Typ-, Kraft- und Effektspezifikationen.","pt":"Permite a modificação direta das mecânicas de batalha de Pokemon, adicionando novas implementações de movimentos ao sistema de batalha. Fornece acesso estruturado para modificar o moveIdEnum no battleEnums.js e implementar objetos de movimento completos no moves.js com especificações de tipo, poder e efeito.","ru":"Позволяет напрямую изменять механику боя Pokemon путем добавления новых реализаций приемов в боевую систему. Предоставляет структурированный доступ для изменения moveIdEnum в battleEnums.js и реализации полных объектов приемов в moves.js с указанием типа, силы и эффекта.","ar":"يتيح التعديل المباشر على ميكانيكيات معارك Pokemon من خلال إضافة تنفيذات حركات جديدة إلى نظام المعركة. يوفر وصولاً منظمًا لتعديل moveIdEnum في battleEnums.js وتنفيذ كائنات الحركة الكاملة في moves.js مع تحديد النوع والقوة والتأثير."},"useCases":{"en":["Extending battle system capabilities with custom moves","Modifying Pokemon Gacha bot gameplay mechanics","Adding new combat options to Discord bot battles"],"zh":["使用自定义招式扩展战斗系统功能","修改 Pokemon Gacha 机器人游戏机制","为 Discord 机器人战斗添加新的战斗选项"],"ja":["カスタムわざでバトルシステムの機能を拡張","Pokemon Gachaボットのゲームプレイメカニックを修正","Discordボットのバトルに新しい戦闘オプションを追加"],"ko":["커스텀 기술로 배틀 시스템 기능 확장","Pokemon Gacha 봇의 게임플레이 메커니즘 수정","Discord 봇 배틀에 새로운 전투 옵션 추가"],"es":["Ampliar las capacidades del sistema de batalla con movimientos personalizados","Modificar las mecánicas de juego de bot de Gacha de Pokémon","Agregar nuevas opciones de combate a las batallas de bots de Discord"],"fr":["Étendre les capacités du système de bataille avec des mouvements personnalisés","Modifier les mécaniques de jeu du bot Gacha de Pokémon","Ajouter de nouvelles options de combat aux batailles de bots Discord"],"de":["Erweitern der Kampfsystemfähigkeiten mit benutzerdefinierten Bewegungen","Modifizieren der Spielmechaniken des Pokémon-Gacha-Bots","Hinzufügen neuer Kampfoptionen zu Discord-Bot-Kämpfen"],"pt":["Extensão das capacidades do sistema de batalha com movimentos personalizados","Modificação das mecânicas de jogabilidade do bot Pokemon Gacha","Adição de novas opções de combate às batalhas de bot do Discord"],"ru":["Расширение возможностей боевой системы с пользовательскими приемами","Изменение игровой механики бота Pokemon Gacha","Добавление новых вариантов боя в битвы бота Discord"],"ar":["توسيع قدرات نظام المعركة باستخدام حركات مخصصة","تعديل ميكانيكيات اللعب لبوت Pokemon Gacha","إضافة خيارات قتال جديدة إلى معارك بوت Discord"]},"limitations":{"en":["Requires filesystem access to modify src/enums/battleEnums.js and src/battle/data/moves.js","Limited to Pokemon Gacha Discord Bot architecture","Cannot modify battleConfig.js without explicit permission"],"zh":["需要文件系统访问权限来修改 src/enums/battleEnums.js 和 src/battle/data/moves.js","仅限于 Pokemon Gacha Discord Bot 架构","未经明确许可无法修改 battleConfig.js"],"ja":["src/enums/battleEnums.js と src/battle/data/moves.js を修正するためのファイルシステムアクセスが必要","Pokemon Gacha Discord Bot アーキテクチャに限定","明示的な許可なしでは battleConfig.js を修正できない"],"ko":["src/enums/battleEnums.js 및 src/battle/data/moves.js 수정을 위한 파일 시스템 접근 권한 필요","Pokemon Gacha Discord Bot 아키텍처로 제한됨","명시적 허가 없이는 battleConfig.js 수정 불가"],"es":["Requiere acceso al sistema de archivos para modificar src/enums/battleEnums.js y src/battle/data/moves.js","Limitado a la arquitectura del bot de Gacha de Discord de Pokémon","No puede modificar battleConfig.js sin permiso explícito"],"fr":["Nécessite un accès au système de fichiers pour modifier src/enums/battleEnums.js et src/battle/data/moves.js","Limité à l''architecture du bot Gacha de Discord de Pokémon","Ne peut pas modifier battleConfig.js sans autorisation explicite"],"de":["Benötigt Dateizugriff, um src/enums/battleEnums.js und src/battle/data/moves.js zu modifizieren","Begrenzt auf die Architektur des Pokémon-Gacha-Discord-Bots","Kann battleConfig.js nicht ohne explizite Genehmigung modifizieren"],"pt":["Requer acesso ao sistema de arquivos para modificar src/enums/battleEnums.js e src/battle/data/moves.js","Limitado à arquitetura do Pokemon Gacha Discord Bot","Não pode modificar o battleConfig.js sem permissão explícita"],"ru":["Требуется доступ к файловой системе для изменения src/enums/battleEnums.js и src/battle/data/moves.js","Ограничено архитектурой бота Pokemon Gacha Discord","Не может изменять battleConfig.js без явного разрешения"],"ar":["يتطلب الوصول إلى نظام الملفات لتعديل src/enums/battleEnums.js و src/battle/data/moves.js","مقتصر على بنية بوت Pokemon Gacha Discord","لا يمكن تعديل battleConfig.js بدون إذن صريح"]},"version":4},"contentHash":"0cd839f77949beb8765ee0e3d5f2475bd52a267af073821b7d0e6ef5f604f935","qualityScore":33}');
