INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ewei068/pokestar/add-move', 'add-move', 'ewei068', 'pokestar', 'community', 'add-move ewei068 pokestar community The add-move skill enables developers to add new moves to the Pokemon Gacha Discord Bot by modifying specific files. This skill benefits bot developers and enthusiasts. 本指南介绍如何向Pokestar添加移动，包括修改相关文件和实现移动结构 Pokestarにムーブを追加する方法を紹介します。関連ファイルの修正とムーブ構造の実装を含みます 이 가이드는 Pokestar에 이동을 추가하는 방법을介绍합니다. 관련 파일 수정 및 이동 구조 구현 포함 El skill add-move permite agregar movimientos a Pokestar en el bot de Discord Pokémon Gacha. Requiere la modificación de archivos como battleEnums.js y moves.js Le skill add-move permet d''ajouter des mouvements à Pokestar sur le bot Discord Pokémon Gacha. Il nécessite la modification de fichiers tels que battleEnums.js et moves.js Das Skill add-move ermöglicht das Hinzufügen von Bewegungen zu Pokestar im Discord-Bot Pokémon Gacha. Es erfordert die Bearbeitung von Dateien wie battleEnums.js und moves.js O add-move é uma habilidade que permite adicionar movimentos ao Pokestar. Aprenda como configurá-lo. ИИ Агенты для Покемон Гача Бота: добавление движений с помощью add-move. إضافة add-move هي سمة تمكنك من إضافة الحركات إلى بوكستار. تعلم كيفية تكوينها. how to use add-move add-move setup guide pokemon gacha discord bot moves add-move alternative add-move vs other discord bots add-move install what is add-move add-move documentation modifying battleEnums.js adding custom moves to pokemon gacha 添加移动 Pokestar Discord Bot JavaScript 移动枚举 移动结构 AIエージェント Pokémon Gacha Modifies src/enums/battleEnums.js to add new moveIdEnum entries Updates src/battle/data/moves.js to implement new move structures Utilizes the Move class with properties like id, name, type, and power Supports addition of custom moves with specific types, such as FIRE, WATER, or GRASS Requires careful modification of specific files without altering other moves or battleConfig.js add-move is a technical skill for modifying the Pokemon Gacha Discord Bot, allowing developers to add new moves by updating the battleEnums.js and moves.js files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jchaselubitz/drill-app/expo-router', 'community', 'jchaselubitz', 'drill-app', 'jchaselubitz/drill-app', 'expo-router', 0, 0, 33, '2026-03-08T01:57:15.446Z', '2026-03-08T02:08:54.414Z', '202b315c374ae6e07427c443e1c698459ede0a79ca2596d5551ee7d21854d0fe', '{"id":"jchaselubitz/drill-app/expo-router","name":"expo-router","description":{"en":"The expo-router skill enables developers to configure stack navigator settings for their Expo applications, allowing for automatic route discovery from file structures.","zh":"Expo Router是一个强大的导航工具，支持Stack Navigator和屏幕选项的配置","ja":"Expo Routerは強力なナビゲーションツールで、Stack Navigatorとスクリーンオプションの設定をサポート","ko":"Expo Router는 강력한 네비게이션 도구로, Stack Navigator와 화면 옵션의 구성 설정을 지원","es":"Expo-router es una herramienta para la configuración de rutas en aplicaciones Expo. Permite a los desarrolladores configurar rutas de manera eficiente.","fr":"Expo-router est un outil de configuration de routes pour les applications Expo. Il permet aux développeurs de configurer des routes de manière efficace.","de":"Expo-router ist ein Tool für die Konfiguration von Routen in Expo-Anwendungen. Es ermöglicht Entwicklern, Routen effizient zu konfigurieren.","pt":"O Expo Router é uma ferramenta para gerenciar rotas em aplicações Expo. Ele permite configurar opções de tela e layout para cada tela.","ru":"Expo Router — это инструмент для управления маршрутами в приложениях Expo. Он позволяет настраивать опции экрана и макета для каждой экрана.","ar":"إكسبو روتر هو أداة لإدارة المسارات في التطبيقات إكسبو. يسمح بضبط خيارات الشاشة و التصميم لتطبيق كل شاشة"},"seo":{"title":{"en":"expo-router: Stack Navigator Setup Guide | AI Agent Skill","zh":"Expo Router Setup Guide - AIエージェント导航配置","ja":"Expo Router ベストプラクティス - AIエージェントを活用したナビゲーション","ko":"Expo Router 설정 가이드 - AI 에이전트를 이용한 네비게이션 구성","es":"Guía de configuración de expo-router para desarrolladores","fr":"Configurer expo-router : Meilleures pratiques pour les dé...","de":"Expo-Router-Setup-Anleitung für Entwickler","pt":"Guia de Configuração do Expo Router","ru":"Настройка Expo Router: Лучшие Практики","ar":"دليل إعداد إكسبو روتر لل.AI الإداة"},"description":{"en":"Discover how to configure expo-router for seamless navigation. Learn how to set up root layout and per-screen options with our expert guide.","zh":"了解Expo Router的配置方法，包括Stack Navigator和屏幕选项的设置，实现AIエージェント导航","ja":"Expo Routerの設定方法を学び、AIエージェントを活用したナビゲーションのベストプラクティスをマスター","ko":"Expo Router 설정 방법을 알아보고, AI 에이전트를 이용한 네비게이션 구성을 최적화하세요","es":"Aprende a configurar expo-router para tus proyectos de desarrollo con nuestra guía paso a paso. Descubre las mejores prácticas para una implementación exitosa.","fr":"Découvrez comment configurer expo-router pour vos projets de développement avec notre guide étape par étape. Apprenez les meilleures pratiques pour une mise ...","de":"Erfahren Sie, wie Sie expo-router für Ihre Entwicklungsprojekte konfigurieren können. Unsere Schritt-für-Schritt-Anleitung hilft Ihnen bei einer erfolgreiche...","pt":"Aprenda a configurar o Expo Router com nossos tutoriais e dicas de especialistas. Descubra como otimizar suas rotas com o Expo Router.","ru":"Узнайте, как настроить Expo Router с помощью наших уроков и советов экспертов. Откройте для себя, как оптимизировать маршруты с Expo Router.","ar":"تعلم كيفية إعداد إكسبو روتر من خلال دروسنا و نصائح خبرائنا. اكتشف كيفية تحسين مساراتك مع إكسبو روتر"},"definition":{"en":"expo-router is a navigation tool that allows developers to set up stack navigator configurations and customize screen options for their Expo applications.","zh":"Expo Router是React Native应用的导航工具，提供Stack Navigator和屏幕选项的配置","ja":"Expo RouterはReact Nativeアプリのナビゲーションツールで、Stack Navigatorとスクリーンオプションの設定を提供","ko":"Expo Router는 React Native 애플리케이션의 네비게이션 도구로, Stack Navigator와 화면 옵션의 구성 설정을 제공","es":"Expo-router es una herramienta de configuración de rutas para aplicaciones Expo que utiliza la configuración de pantalla y el descubrimiento automático de rutas.","fr":"Expo-router est un outil de configuration de routes pour les applications Expo qui utilise la configuration d''écran et la découverte automatique de routes.","de":"Expo-router ist ein Tool für die Konfiguration von Routen in Expo-Anwendungen, das die Bildschirmkonfiguration und die automatische Routenentdeckung verwendet.","pt":"O que é Expo Router? É uma ferramenta de gerenciamento de rotas para aplicações Expo.","ru":"Что такое Expo Router? Это инструмент управления маршрутами для приложений Expo.","ar":"ما هو إكسبو روتر؟ إنه أداة لإدارة المسارات لتطبيقات إكسبو"},"features":{"en":["Configures stack navigator settings using the Stack component","Sets default screen options using the screenOptions property","Enables automatic route discovery from file structures","Allows per-screen configuration of options","Supports customization of header settings using the headerShown property"],"zh":["支持Stack Navigator","屏幕选项的配置","自动发现路由","个性化屏幕配置"],"ja":["Stack Navigatorのサポート","スクリーンオプションの設定","ルートの自動発見","個別のスクリーン設定"],"ko":["Stack Navigator 지원","화면 옵션의 구성 설정","자동으로 라우트 обнаруж","개별 화면 구성 설정"],"es":["Configuración de pantalla con screenOptions","Descubrimiento automático de rutas desde la estructura de archivos","Configuración individual de opciones para cada pantalla","Compatibilidad con Stack Navigator","Uso de componentes de Expo para la configuración de rutas"],"fr":["Configuration d''écran avec screenOptions","Découverte automatique de routes à partir de la structure de fichiers","Configuration individuelle des options pour chaque écran","Compatibilité avec Stack Navigator","Utilisation de composants Expo pour la configuration de routes"],"de":["Bildschirmkonfiguration mit screenOptions","Automatische Routenentdeckung aus der Dateistruktur","Individuelle Konfiguration von Optionen für jeden Bildschirm","Kompatibilität mit Stack Navigator","Verwendung von Expo-Komponenten für die Routenkonfiguration"],"pt":["Configuração de opções de tela com screenOptions","Layout personalizado com Root Layout Setup","Descoberta automática de rotas a partir da estrutura de arquivos","Configuração individual de opções de tela para cada tela","Integração com o componente Stack do Expo Router"],"ru":["Настройка опций экрана с помощью screenOptions","Пользовательский макет с помощью Root Layout Setup","Автоматическое обнаружение маршрутов из структуры файлов","Индивидуальная настройка опций экрана для каждой экрана","Интеграция с компонентом Stack Expo Router"],"ar":["ضبط خيارات الشاشة مع screenOptions","تصميم مخصص مع إعداد التصميم الجذري","اكتشاف تلقائي للمسارات من هيكل الملفات","ضبط خيارات الشاشة الفردية لكل شاشة","التكامل مع مكون Stack من إكسبو روتر"]},"keywords":{"en":["how to use expo-router","expo-router setup guide","expo-router vs react-navigation","expo-router install","what is expo-router","expo-router stack navigator configuration","expo-router screen options","expo-router automatic route discovery"],"zh":["Expo Router","React Native","Stack Navigator","AIエージェント","导航配置","屏幕选项"],"ja":["Expo Router","React Native","Stack Navigator","AIエージェント","ナビゲーション設定","スクリーンオプション"],"ko":["Expo Router","React Native","Stack Navigator","AI 에이전트","네비게이션 구성","화면 옵션"],"es":["expo-router","configuración de rutas","desarrollo de aplicaciones Expo","Stack Navigator","screenOptions","descubrimiento automático de rutas","configuración de pantalla","herramientas de desarrollo","expo-router tutorial"],"fr":["expo-router","configuration de routes","développement d''applications Expo","Stack Navigator","screenOptions","découverte automatique de routes","configuration d''écran","outils de développement","tutoriel expo-router"],"de":["expo-router","Konfiguration von Routen","Entwicklung von Expo-Anwendungen","Stack Navigator","screenOptions","automatische Routenentdeckung","Bildschirmkonfiguration","Entwicklungstools","expo-router-Anleitung"],"pt":["expo router","configuração de rotas","gerenciamento de rotas","screenOptions","Root Layout Setup","descoberta automática de rotas","configuração individual de telas","expo router tutorial"],"ru":["expo router","настройка маршрутов","управление маршрутами","screenOptions","Root Layout Setup","автоматическое обнаружение маршрутов","индивидуальная настройка экранов","expo router уроки"],"ar":["إكسبو روتر","إعداد المسارات","إدارة المسارات","screenOptions","إعداد التصميم الجذري","اكتشاف تلقائي للمسارات","ضبط خيارات الشاشة الفردية","دروس إكسبو روتر"]}},"owner":"jchaselubitz","repo":"drill-app","repoPath":"jchaselubitz/drill-app","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.446Z","topics":[],"category":"community","skillMd":{"name":"expo-router","description":"Patterns for Expo Router including Stack configuration, native tabs, and file-based routing best practices. Apply when working with navigation, routing, or screen configuration.","bodyPreview":"# Expo Router Patterns\n\n## Stack Navigator Configuration\n\n### Root Layout Setup\nUse `screenOptions` on the Stack component to set defaults for all screens. Do NOT explicitly list every screen - routes are auto-discovered from the file structure.\n\n```tsx\n// app/_layout.tsx\nimport { Stack } from ''expo-router'';\n\nexport default function RootLayout() {\n  return (\n    <Stack screenOptions={{ headerShown: false }} />\n  );\n}\n```\n\n### Per-Screen Configuration\nIndividual screens configure their own option","body":"# Expo Router Patterns\n\n## Stack Navigator Configuration\n\n### Root Layout Setup\nUse `screenOptions` on the Stack component to set defaults for all screens. Do NOT explicitly list every screen - routes are auto-discovered from the file structure.\n\n```tsx\n// app/_layout.tsx\nimport { Stack } from ''expo-router'';\n\nexport default function RootLayout() {\n  return (\n    <Stack screenOptions={{ headerShown: false }} />\n  );\n}\n```\n\n### Per-Screen Configuration\nIndividual screens configure their own options using `<Stack.Screen>` within the component file:\n\n```tsx\n// app/lesson/[id].tsx\nimport { Stack } from ''expo-router'';\n\nexport default function LessonScreen() {\n  return (\n    <View>\n      <Stack.Screen\n        options={{\n          title: ''Lesson'',\n          headerShown: true,\n          headerBackTitle: ''Back'',\n        }}\n      />\n      {/* Screen content */}\n    </View>\n  );\n}\n```\n\n### Dynamic Header Configuration\nUse `useNavigation` with `setOptions` for dynamic header content like buttons:\n\n```tsx\nimport { useNavigation } from ''expo-router'';\nimport { useLayoutEffect } from ''react'';\n\nexport default function Screen() {\n  const navigation = useNavigation();\n\n  useLayoutEffect(() => {\n    navigation.setOptions({\n      headerRight: () => (\n        <Pressable onPress={handlePress}>\n          <Ionicons name=\"add\" size={28} />\n        </Pressable>\n      ),\n    });\n  }, [navigation]);\n\n  return <View>{/* content */}</View>;\n}\n```\n\n## Native Tabs (`expo-router/unstable-native-tabs`)\n\nNative tabs provide platform-native tab bar with SF Symbols on iOS:\n\n```tsx\n// app/(tabs)/_layout.tsx\nimport { Icon, Label, NativeTabs } from ''expo-router/unstable-native-tabs'';\n\nexport default function TabLayout() {\n  return (\n    <NativeTabs>\n      <NativeTabs.Trigger name=\"index\" options={{ title: ''Home'' }}>\n        <Icon sf=\"house.fill\" drawable=\"custom_android_drawable\" />\n        <Label>Home</Label>\n      </NativeTabs.Trigger>\n    </NativeTabs>\n  );\n}\n```\n\n## Key Principles\n\n1. **File-based routing**: Routes are auto-discovered from the `app/` directory structure\n2. **Minimal configuration**: Only configure what you need to override\n3. **Screen-level options**: Screens configure their own headers/options using `<Stack.Screen>` within the component\n4. **Layout files**: `_layout.tsx` files define navigation structure for their directory\n5. **Route groups**: Parentheses like `(tabs)` create route groups without affecting the URL path\n\n## Common Mistakes to Avoid\n\n- Don''t list every screen explicitly in Stack - they''re auto-discovered\n- Don''t use `screenOptions` for route-specific settings - use `<Stack.Screen>` in the route file\n- Don''t nest navigators deeply - use file-based routing for cleaner structure\n"},"lastSynced":"2026-03-08T02:08:54.414Z","agentAnalysis":{"suitability":{"en":"Ideal for Mobile App Agents requiring streamlined navigation configuration in Expo applications","zh":"非常适合需要简化导航配置的移动应用代理在Expo应用程序中使用","ja":"Expoアプリケーションで合理化されたナビゲーション設定を必要とするモバイルアプリエージェントに最適","ko":"Expo 애플리케이션에서 간소화된 네비게이션 구성을 요구하는 모바일 앱 에이전트에 이상적","es":"Ideal para agentes de aplicaciones móviles que requieren una configuración de navegación optimizada en aplicaciones Expo","fr":"Idéal pour les agents d''applications mobiles nécessitant une configuration de navigation simplifiée dans les applications Expo","de":"Ideal für Mobile App-Agents, die eine optimierte Navigationskonfiguration in Expo-Anwendungen benötigen","pt":"Ideal para Agentes de Aplicativos Móveis que exigem configuração de navegação simplificada em aplicativos Expo","ru":"Идеально для агентов мобильных приложений, требующих упрощенной настройки навигации в приложениях Expo","ar":"مثالي للعملاء تطبيقات الجوال التي تتطلب تكوين الملاحة المُبسطة في تطبيقات Expo"},"recommendation":{"en":"Empowers agents to automatically discover routes from file structures and configure stack navigator settings using Expo Router, enabling seamless navigation experiences with features like automatic route discovery and customizable screen options via ''screenOptions'' on the Stack component","zh":"使代理能够自动从文件结构发现路由并使用Expo Router配置堆栈导航器设置，通过自动路由发现和通过Stack组件上的''screenOptions''自定义屏幕选项等功能实现无缝导航体验","ja":"ファイル構造からルートを自動的に発見し、Expo Routerを使用してスタックナビゲーター設定を構成する機能をエージェントに付与し、自動ルート発見やStackコンポーネントの''screenOptions''によるカスタマイズ可能な画面オプションなどの機能でシームレスなナビゲーション体験を実現","ko":"에이전트가 파일 구조에서 자동으로 경로를 발견하고 Expo Router를 사용하여 스택 네비게이터 설정을 구성할 수 있도록 하여 자동 경로 발견 및 Stack 컴포넌트의 ''screenOptions''를 통한 사용자 정의 가능한 화면 옵션과 같은 기능으로 원활한 네비게이션 경험을 가능하게 함","es":"Habilita a los agentes a descubrir automáticamente rutas desde estructuras de archivos y configurar la configuración del navegador de pila utilizando Expo Router, lo que permite experiencias de navegación sin problemas con características como el descubrimiento automático de rutas y opciones de pantalla personalizables a través de ''screenOptions'' en el componente Stack","fr":"Permet aux agents de découvrir automatiquement les routes à partir de structures de fichiers et de configurer les paramètres du navigateur de pile à l''aide d''Expo Router, ce qui permet des expériences de navigation sans interruption avec des fonctionnalités comme la découverte automatique de routes et des options d''écran personnalisables via ''screenOptions'' sur le composant Stack","de":"Ermöglicht es Agenten, automatisch Routen aus Dateistrukturen zu entdecken und die Konfiguration des Stack-Navigators mithilfe von Expo Router zu konfigurieren, wodurch nahtlose Navigationserlebnisse mit Funktionen wie automatischer Routenentdeckung und anpassbaren Bildschirmoptionen über ''screenOptions'' im Stack-Component ermöglicht werden","pt":"Habilita os agentes a descobrir automaticamente rotas a partir de estruturas de arquivos e configurar configurações do navegador de pilha usando o Expo Router, permitindo experiências de navegação sem interrupções com recursos como descoberta automática de rotas e opções de tela personalizáveis via ''screenOptions'' no componente Stack","ru":"Позволяет агентам автоматически обнаруживать маршруты из структуры файлов и настраивать параметры навигатора стека с помощью Expo Router, обеспечивая бесшовные навигационные trải nghiệm с функциями, такими как автоматическое обнаружение маршрутов и настраиваемые параметры экрана через ''screenOptions'' в компоненте Stack","ar":"يُمكّن العملاء من اكتشاف الطرق تلقائيًا من هيكل الملفات وتكوين إعدادات الملاحة في المكدس باستخدام Expo Router، وتمكين تجارب الملاحة دون انقطاع مع الميزات مثل اكتشاف الطريق التلقائي وخيارات الشاشة القابلة للتعديل عبر ''screenOptions'' على مكون المكدس"},"useCases":{"en":["Configuring stack navigator settings for Expo apps","Automating route discovery from file structures","Customizing screen options for individual screens"],"zh":["为Expo应用程序配置堆栈导航器设置","从文件结构自动化路由发现","为单个屏幕自定义屏幕选项"],"ja":["Expoアプリのスタックナビゲーター設定の構成","ファイル構造からのルート自動発見","個々の画面の画面オプションのカスタマイズ"],"ko":["Expo 앱용 스택 네비게이터 설정 구성","파일 구조에서 자동 경로 발견","개별 화면에 대한 화면 옵션 사용자 정의"],"es":["Configuración de la configuración del navegador de pila para aplicaciones Expo","Automatización del descubrimiento de rutas desde estructuras de archivos","Personalización de opciones de pantalla para pantallas individuales"],"fr":["Configuration des paramètres du navigateur de pile pour les applications Expo","Automatisation de la découverte de routes à partir de structures de fichiers","Personnalisation des options d''écran pour les écrans individuels"],"de":["Konfiguration der Stack-Navigator-Einstellungen für Expo-Apps","Automatisierung der Routenentdeckung aus Dateistrukturen","Anpassung von Bildschirmoptionen für einzelne Bildschirme"],"pt":["Configurando configurações do navegador de pilha para aplicativos Expo","Automatizando a descoberta de rotas a partir de estruturas de arquivos","Personalizando opções de tela para telas individuais"],"ru":["Настройка параметров навигатора стека для приложений Expo","Автоматизация обнаружения маршрутов из структуры файлов","Настройка параметров экрана для отдельных экранов"],"ar":["تكوين إعدادات ملاحة المكدس لتطبيقات Expo","تأتمتة اكتشاف الطرق من هيكل الملفات","تخصيص خيارات الشاشة لأجهزة العرض الفردية"]},"limitations":{"en":["Requires Expo application setup","Limited to stack navigator configuration"],"zh":["需要Expo应用程序设置","仅限于堆栈导航器配置"],"ja":["Expoアプリケーションのセットアップが必要","スタックナビゲーター構成に限定"],"ko":["Expo 애플리케이션 설정 필요","스택 네비게이터 구성으로 제한됨"],"es":["Requiere configuración de la aplicación Expo","Limitado a la configuración del navegador de pila"],"fr":["Nécessite une configuration d''application Expo","Limité à la configuration du navigateur de pile"],"de":["Benötigt Expo-Anwendungskonfiguration","Begrenzt auf die Konfiguration des Stack-Navigators"],"pt":["Exige configuração de aplicativo Expo","Limitado à configuração do navegador de pilha"],"ru":["Требует настройки приложения Expo","Ограничен настройкой навигатора стека"],"ar":["يتطلب إعداد تطبيق Expo","محدود لتكوين ملاحة المكدس"]},"version":4},"contentHash":"202b315c374ae6e07427c443e1c698459ede0a79ca2596d5551ee7d21854d0fe","qualityScore":33}');
