INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jchaselubitz/drill-app/expo-router', 'expo-router', 'jchaselubitz', 'drill-app', 'community', 'expo-router jchaselubitz drill-app community The expo-router skill enables developers to configure stack navigator settings for their Expo applications, allowing for automatic route discovery from file structures. Expo Router是一个强大的导航工具，支持Stack Navigator和屏幕选项的配置 Expo Routerは強力なナビゲーションツールで、Stack Navigatorとスクリーンオプションの設定をサポート Expo Router는 강력한 네비게이션 도구로, Stack Navigator와 화면 옵션의 구성 설정을 지원 Expo-router es una herramienta para la configuración de rutas en aplicaciones Expo. Permite a los desarrolladores configurar rutas de manera eficiente. Expo-router est un outil de configuration de routes pour les applications Expo. Il permet aux développeurs de configurer des routes de manière efficace. Expo-router ist ein Tool für die Konfiguration von Routen in Expo-Anwendungen. Es ermöglicht Entwicklern, Routen effizient zu konfigurieren. O Expo Router é uma ferramenta para gerenciar rotas em aplicações Expo. Ele permite configurar opções de tela e layout para cada tela. Expo Router — это инструмент для управления маршрутами в приложениях Expo. Он позволяет настраивать опции экрана и макета для каждой экрана. إكسبو روتر هو أداة لإدارة المسارات في التطبيقات إكسبو. يسمح بضبط خيارات الشاشة و التصميم لتطبيق كل شاشة how to use expo-router expo-router setup guide expo-router vs react-navigation expo-router install what is expo-router expo-router stack navigator configuration expo-router screen options expo-router automatic route discovery Expo Router React Native Stack Navigator AIエージェント 导航配置 屏幕选项 Configures stack navigator settings using the Stack component Sets default screen options using the screenOptions property Enables automatic route discovery from file structures Allows per-screen configuration of options Supports customization of header settings using the headerShown property expo-router is a navigation tool that allows developers to set up stack navigator configurations and customize screen options for their Expo applications.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ai-service-incubator/celebrities-shorts-video/generate-video', 'community', 'ai-service-incubator', 'celebrities-shorts-video', 'ai-service-incubator/celebrities-shorts-video', 'generate-video', 0, 0, 33, '2026-03-08T01:57:15.447Z', '2026-03-08T02:08:56.693Z', '8f8825aee533d89dceb33c83771ee62b9c9d796f52e426a8cf7ea19cc4bdce1b', '{"id":"ai-service-incubator/celebrities-shorts-video/generate-video","name":"generate-video","description":{"en":"The generate-video skill generates short-form videos for celebrity cosmetics using AI. It benefits developers and marketers by automating video creation with Python and MoviePy.","zh":"generate-video AI技能是一种自动创建短视频的工具，使用Python和moviepy库","ja":"generate-video AIスキルは、Pythonとmoviepyライブラリを使用して短編ビデオを自動生成するツール","ko":"generate-video 스킬은 Python과 moviepy 패키지를 사용하여 자동으로 숏폼 영상을 생성하는 스킬입니다","es":"El generador de vídeo de cosméticos de celebridades es una habilidad de agente de IA que utiliza Python y MoviePy para crear vídeos cortos","fr":"Le générateur de vidéo de cosmétiques de célébrités est une compétence d''agent IA qui utilise Python et MoviePy pour créer des vidéos courtes","de":"Der Kosmetik-Video-Generator von Celebrities ist eine Fähigkeit des KI-Agents, die Python und MoviePy verwendet, um kurze Videos zu erstellen","pt":"Skill de agente de IA que automatiza a geração de vídeos curtos para cosméticos celebrites. Utiliza Python, MoviePy, Pillow e requer uma estrutura específica de pastas com scripts Markdown, assets de imagem/áudio e fontes.","ru":"Навык ИИ Агента для автоматизации создания коротких видео о косметике знаменитостей. Работает на Python с MoviePy, требует определенной структуры папок со скриптами, медиафайлами и шрифтами.","ar":"أداة ذكاء اصطناعي تقوم بأتمتة توليد فيديوهات قصيرة للتجميل بناءً على نصوص. تعتمد على Python وMoviePy وتتطلب هيكل مجلدات محدد يحتوي على نصوص Markdown وملفات الوسائط والخطوط."},"seo":{"title":{"en":"generate-video: Celebrity Cosmetics Video Generator Setup...","zh":"AIエージェント生成视频设置指南","ja":"AIエージェントによるビデオ生成ベストプラクティス","ko":"generate-video 스킬 설정 가이드","es":"Generador de Vídeo de Cosméticos de Celebridades: Guía de...","fr":"Générateur de Vidéo de Cosmétiques de Célébrités: Meilleu...","de":"Celebrities Kosmetik-Video-Generator: Einrichtungsanleitung","pt":"Gerador de Vídeos com IA: Setup Técnico para Vídeos de Co...","ru":"Генератор коротких видео с ИИ Агентами: техническое руков...","ar":"دليل إعداد أداة الذكاء الاصطناعي لتوليد فيديوهات قصيرة لل..."},"description":{"en":"Discover how to generate short-form videos with celebrity cosmetics using AI. Learn to install and use generate-video with Python and MoviePy.","zh":"使用generate-video AI技能，利用Python和moviepy库自动创建短视频","ja":"AIエージェントを使用して、Pythonとmoviepyライブラリで短編ビデオを自動生成","ko":"generate-video 스킬을 활용하여 Python과 moviepy 패키지를 사용한 자동 숏폼 영상 생성","es":"Aprenda a generar vídeos de cosméticos de celebridades con nuestra guía de configuración para desarrolladores","fr":"Découvrez comment générer des vidéos de cosmétiques de célébrités avec notre guide de configuration pour développeurs","de":"Erfahren Sie, wie Sie mit unserer Einrichtungsanleitung für Entwickler Videos über Kosmetik von Celebrities erstellen","pt":"Guia técnico para configurar o skill generate-video com Python, MoviePy e Pillow. Automatize a criação de vídeos promocionais com scripts, imagens e áudio.","ru":"Техническое руководство по настройке ИИ Агента generate-video на Python с MoviePy. Автоматизируйте создание промо-видео с помощью скриптов и медиафайлов.","ar":"دليل تقني لإعداد أداة الذكاء الاصطناعي generate-video باستخدام Python وMoviePy. أتمتة إنشاء فيديوهات قصيرة من نصوص وصور باستخدام هيكل مجلدات محدد."},"definition":{"en":"generate-video is a Python-based AI agent skill that automatically generates short-form videos for celebrity cosmetics using scripts and predefined assets.","zh":"generate-video AI技能是一种自动创建短视频的工具","ja":"generate-video AIスキルは、短編ビデオを自動生成するツール","ko":"generate-video 스킬은 자동으로 숏폼 영상을 생성하는 스킬","es":"Un generador de vídeo de cosméticos de celebridades es una herramienta de agente de IA que crea vídeos cortos con scripts y activos","fr":"Un générateur de vidéo de cosmétiques de célébrités est un outil d''agent IA qui crée des vidéos courtes avec des scripts et des ressources","de":"Ein Kosmetik-Video-Generator von Celebrities ist ein Tool des KI-Agents, das kurze Videos mit Skripten und Assets erstellt","pt":"Generate-video é um skill de agente de IA que produz automaticamente vídeos promocionais curtos para cosméticos. Ele processa scripts Markdown, combina imagens de celebridades/produtos, BGM e aplica textos com fontes personalizadas usando bibliotecas Python como MoviePy.","ru":"Generate-video — это навык ИИ Агента для автоматического создания коротких промо-видео о косметике. Он обрабатывает скрипты Markdown, объединяет изображения, аудио и применяет текст с кастомными шрифтами через библиотеки Python.","ar":"Generate-video هي أداة ذكاء اصطناعي تقوم بإنشاء فيديوهات قصيرة ترويجية للتجميل تلقائياً. تعالج نصوص Markdown وتدمج صور المشاهير والمنتجات مع الموسيقى وتطبق نصوصاً بخطوط مخصصة باستخدام مكتبات Python."},"features":{"en":["Generates short-form videos using MoviePy and Python","Supports custom scripts via Markdown files","Utilizes Pillow for image processing and numpy for numerical computations","Requires a specific folder structure for assets and output","Allows for customization with fonts and audio files","Enables automated video generation with a single command: /generate-video [project_name]"],"zh":["支持Python脚本","利用moviepy库自动创建短视频","支持多种媒体格式，包括图片、音频和字体","自定义输出文件夹结构","使用pip安装必要的包，包括moviepy、pillow和numpy"],"ja":["Pythonスクリプトをサポート","moviepyライブラリを使用して短編ビデオを自動生成","複数のメディア形式をサポート，画像、オーディオ、フォントを含む","出力ファイルフォルダ構造をカスタマイズ","pipを使用して必要なパッケージをインストール，moviepy、pillow、numpyを含む"],"ko":["Python 스크립트 지원","moviepy 패키지를 사용하여 자동으로 숏폼 영상을 생성","여러 가지 미디어 형식을 지원，이미지、오디오、폰트를 포함","출력 파일 폴더 구조를 커스터마이징","pip를 사용하여 필요한 패키지를 설치，moviepy、pillow、numpy를 포함"],"es":["Utiliza Python y MoviePy para generar vídeos","Requiere la instalación de paquetes como moviepy, pillow y numpy","Soporta la creación de vídeos con imágenes, audio y fuentes personalizadas","Permite la especificación de scripts y activos para personalizar el vídeo","Genera vídeos en una estructura de carpeta organizada"],"fr":["Utilise Python et MoviePy pour générer des vidéos","Exige l''installation de paquets tels que moviepy, pillow et numpy","Prend en charge la création de vidéos avec des images, de l''audio et des polices personnalisées","Permet la spécification de scripts et de ressources pour personnaliser la vidéo","Génère des vidéos dans une structure de dossier organisée"],"de":["Verwendet Python und MoviePy, um Videos zu erstellen","Erfordert die Installation von Paketen wie moviepy, pillow und numpy","Unterstützt die Erstellung von Videos mit Bildern, Audio und benutzerdefinierten Schriftarten","Ermöglicht die Spezifikation von Skripten und Assets, um das Video zu personalisieren","Erstellt Videos in einer organisierten Verzeichnisstruktur"],"pt":["Processamento de scripts Markdown para narração de vídeo","Integração de imagens de celebridades e produtos (JPEG)","Suporte a arquivos de áudio BGM (MP3) para trilha sonora","Renderização de texto com fontes personalizadas (ex: Pretendard-Bold)","Geração automatizada via comando CLI /generate-video [projeto]","Dependências Python: moviepy, pillow, numpy para edição de vídeo"],"ru":["Обработка скриптов Markdown для narration видео","Интеграция изображений знаменитостей и продуктов (JPEG)","Поддержка аудиофайлов BGM (MP3) для фоновой музыки","Рендеринг текста с кастомными шрифтами (например, Pretendard-Bold)","Автоматическая генерация через команду CLI /generate-video [проект]","Зависимости Python: moviepy, pillow, numpy для монтажа видео"],"ar":["معالجة نصوص Markdown لرواية الفيديو","دمج صور المشاهير والمنتجات (صيغة JPEG)","دعم ملفات الصوت BGM (صيغة MP3) للموسيقى التصويرية","عرض نصوص بخطوط مخصصة (مثل Pretendard-Bold)","توليد تلقائي عبر أمر CLI /generate-video [اسم المشروع]","اعتمادات Python: moviepy, pillow, numpy لتحرير الفيديو"]},"keywords":{"en":["how to use generate-video","generate-video alternative","generate-video setup guide","generate-video install","celebrity cosmetics video generator","AI video generation with Python","MoviePy video generation","generate-video vs other video generators"],"zh":["AIエージェント","generate-video","Python","moviepy","自动创建短视频","短视频生成","AI工具","视频生成库"],"ja":["AIエージェント","generate-video","Python","moviepy","短編ビデオ自動生成","ビデオ生成","AIツール","ビデオ生成ライブラリ"],"ko":["AI 에이전트","generate-video","Python","moviepy","자동 숏폼 영상 생성","숏폼 영상 생성","AI 도구","영상 생성 라이브러리"],"es":["generador de vídeo de cosméticos de celebridades","agente de IA para vídeo","Python para vídeo","MoviePy para vídeo","creación de vídeos cortos","herramientas de agente de IA para desarrolladores"],"fr":["générateur de vidéo de cosmétiques de célébrités","agent IA pour vidéo","Python pour vidéo","MoviePy pour vidéo","création de vidéos courtes","outils d''agent IA pour développeurs"],"de":["Kosmetik-Video-Generator von Celebrities","KI-Agent für Video","Python für Video","MoviePy für Video","Erstellung von kurzen Videos","KI-Agent-Tools für Entwickler"],"pt":["python generate video script","automacao video marketing cosmeticos","moviepy pillow tutorial","IA agentes gerar video","estrutura pastas projeto video","cli comando gerar video","short-form video python","custom fonts moviepy"],"ru":["python скрипт генерации видео","автоматизация видео косметика","moviepy pillow руководство","ИИ Агенты создать видео","структура папок видео проект","cli команда generate-video","короткие видео python","кастомные шрифты moviepy"],"ar":["بايثون توليد فيديو تلقائي","أتمتة فيديوهات التجميل","برنامج moviepy pillow","أدوات الذكاء الاصطناعي لإنشاء الفيديو","هيكل مجلدات مشروع الفيديو","أمر CLI لإنشاء الفيديو","فيديو قصير بايثون","خطوط مخصصة moviepy"]}},"owner":"ai-service-incubator","repo":"celebrities-shorts-video","repoPath":"ai-service-incubator/celebrities-shorts-video","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.447Z","topics":[],"category":"community","skillMd":{"name":"generate-video","description":"Python moviepy를 활용한 숏폼 영상 자동 생성. 스크립트를 기반으로 자막, 이미지, BGM이 포함된 영상을 생성합니다.","bodyPreview":"# Generate Video Skill\n\n스크립트 기반 숏폼 영상을 자동 생성하는 스킬입니다.\n\n## 사용법\n\n```\n/generate-video [프로젝트명]\n```\n\n## 필수 요구사항\n\n### Python 패키지\n```bash\npip install moviepy pillow numpy\n```\n\n### 폴더 구조\n```\nproject/\n├── scripts/\n│   └── [프로젝트명].md      # 스크립트 파일\n├── assets/\n│   ├── images/              # 연예인/제품 이미지\n│   │   ├── celebrity.jpg\n│   │   └── product_1.jpg\n│   ├── audio/               # BGM 파일\n│   │   └── bgm.mp3\n│   └── fonts/               # 폰트 파일\n│       └── Pretendard-Bold.ttf\n└── output/","body":"# Generate Video Skill\n\n스크립트 기반 숏폼 영상을 자동 생성하는 스킬입니다.\n\n## 사용법\n\n```\n/generate-video [프로젝트명]\n```\n\n## 필수 요구사항\n\n### Python 패키지\n```bash\npip install moviepy pillow numpy\n```\n\n### 폴더 구조\n```\nproject/\n├── scripts/\n│   └── [프로젝트명].md      # 스크립트 파일\n├── assets/\n│   ├── images/              # 연예인/제품 이미지\n│   │   ├── celebrity.jpg\n│   │   └── product_1.jpg\n│   ├── audio/               # BGM 파일\n│   │   └── bgm.mp3\n│   └── fonts/               # 폰트 파일\n│       └── Pretendard-Bold.ttf\n└── output/                  # 출력 폴더\n```\n\n## 실행 프로세스\n\n### Step 1: 스크립트 파싱\n1. `scripts/[프로젝트명].md` 파일 읽기\n2. 섹션별 타임코드 추출\n3. 자막 텍스트 추출\n\n### Step 2: 에셋 준비 확인\n- 이미지 파일 존재 확인\n- BGM 파일 확인\n- 폰트 파일 확인\n\n### Step 3: 영상 생성\n```bash\npython .claude/skills/generate-video/scripts/video_generator.py \\\n  --script \"scripts/[프로젝트명].md\" \\\n  --assets \"assets/\" \\\n  --output \"output/[프로젝트명].mp4\" \\\n  --resolution 1080x1920 \\\n  --fps 30\n```\n\n### Step 4: 검수\n- 영상 길이 확인 (60초 이내)\n- 자막 가독성 확인\n- 오디오 싱크 확인\n\n## Python 스크립트 사용법\n\n```bash\n# 기본 실행\npython video_generator.py --script script.md --output output.mp4\n\n# 옵션\n--script      스크립트 파일 경로 (필수)\n--assets      에셋 폴더 경로 (기본: assets/)\n--output      출력 파일 경로 (기본: output/video.mp4)\n--resolution  해상도 (기본: 1080x1920)\n--fps         프레임레이트 (기본: 30)\n--preview     미리보기 모드 (저해상도)\n```\n\n## 영상 스펙\n\n| 항목 | 값 |\n|------|-----|\n| 해상도 | 1080 x 1920 (9:16) |\n| 프레임레이트 | 30 fps |\n| 코덱 | H.264 |\n| 최대 길이 | 60초 |\n| 파일 형식 | MP4 |\n\n## 자막 스타일 설정\n\n```python\nsubtitle_style = {\n    \"font\": \"Pretendard-Bold\",\n    \"fontsize\": 48,\n    \"color\": \"white\",\n    \"stroke_color\": \"black\",\n    \"stroke_width\": 2,\n    \"position\": (\"center\", 0.85)  # 하단 15% 위치\n}\n```\n\n## 트러블슈팅\n\n### 일반적인 오류\n1. **ImageMagick 필요**: `brew install imagemagick`\n2. **폰트 오류**: 폰트 경로 확인 또는 시스템 폰트 사용\n3. **메모리 부족**: `--preview` 모드로 먼저 테스트\n\n### 대체 방법\nmoviepy가 어려운 경우:\n1. FFmpeg 직접 사용\n2. 편집 지시서만 생성 후 수동 편집\n\n## 출력 파일\n\n```\noutput/\n├── [프로젝트명].mp4           # 최종 영상\n├── [프로젝트명]_preview.mp4   # 미리보기 (저해상도)\n└── [프로젝트명]_log.txt       # 생성 로그\n```\n\n## 다음 단계\n\n영상 생성 완료 후:\n1. `/optimize-posting` - 포스팅 최적화\n2. 수동 검수 및 최종 수정\n"},"lastSynced":"2026-03-08T02:08:56.693Z","agentAnalysis":{"suitability":{"en":"Perfect for Marketing Automation Agents specializing in AI-powered cosmetics video content creation.","zh":"非常适合专注于AI驱动的化妆品视频内容创作的营销自动化Agent。","ja":"AIを活用した化粧品ビデオコンテンツ作成を専門とするマーケティングオートメーションAgentに最適です。","ko":"AI 기반 화장품 영상 콘텐츠 제작을 전문으로 하는 마케팅 자동화 에이전트에 완벽합니다.","es":"Perfecto para agentes de automatización de marketing especializados en la creación de contenido de video de cosméticos con tecnología de inteligencia artificial.","fr":"Parfait pour les agents d''automatisation du marketing spécialisés dans la création de contenu vidéo de cosmétiques alimenté par l''intelligence artificielle.","de":"Perfekt für Marketing-Automatisierungsagenten, die auf die Erstellung von AI-gesteuertem Kosmetik-Video-Inhalt spezialisiert sind.","pt":"Perfeito para Agentes de Automação de Marketing especializados na criação de conteúdo de vídeo para cosméticos com tecnologia de IA.","ru":"Идеально подходит для агентов маркетинговой автоматизации, специализирующихся на создании видео-контента для косметики на базе искусственного интеллекта.","ar":"مثالي لوكلاء أتمتة التسويق المتخصصين في إنشاء محتوى فيديو للماكياج مدعوم بالذكاء الاصطناعي."},"recommendation":{"en":"Automates short-form video production for celebrity cosmetics campaigns using Python, MoviePy, and Pillow. Generates branded videos complete with BGM audio tracks, celebrity/product images, and custom fonts directly from markdown scripts.","zh":"使用Python、MoviePy和Pillow自动化名人化妆品活动的短视频制作。可直接从markdown脚本生成包含BGM音轨、名人/产品图片和自定义字体的品牌视频。","ja":"Python、MoviePy、およびPillowを使用して、セレブリティ化粧品キャンペーン向けのショートフォーム動画制作を自動化します。markdownスクリプトから直接、BGMオーディオトラック、セレブリティ/製品画像、カスタムフォントを備えたブランド動画を生成します。","ko":"Python, MoviePy 및 Pillow를 사용하여 유명인 화장품 캠페인을 위한 숏폼 비디오 제작을 자동화합니다. markdown 스크립트에서 직접 BGM 오디오 트랙, 유명인/제품 이미지 및 사용자 정의 글꼴이 포함된 브랜드 비디오를 생성합니다.","es":"Automatiza la producción de videos de forma corta para campañas de cosméticos de celebridades utilizando Python, MoviePy y Pillow. Genera videos de marca completos con pistas de audio BGM, imágenes de celebridades/productos y fuentes personalizadas directamente desde scripts de markdown.","fr":"Automatise la production de vidéos courtes pour les campagnes de cosmétiques de célébrités à l''aide de Python, MoviePy et Pillow. Génère des vidéos de marque complètes avec des pistes audio BGM, des images de célébrités/produits et des polices personnalisées directement à partir de scripts markdown.","de":"Automatisiert die Produktion von Kurzvideos für Celebrity-Kosmetik-Kampagnen unter Verwendung von Python, MoviePy und Pillow. Erzeugt markenbehaftete Videos komplett mit BGM-Audiostrecken, Celebrity-Produkt-Bildern und benutzerdefinierten Schriftarten direkt aus Markdown-Skripten.","pt":"Automatiza a produção de vídeos de curta duração para campanhas de cosméticos de celebridades usando Python, MoviePy e Pillow. Gera vídeos com marca, completos com trilhas sonoras BGM, imagens de celebridades/produtos e fontes personalizadas diretamente a partir de scripts em markdown.","ru":"Автоматизирует производство коротких видео для кампаний по косметике знаменитостей с использованием Python, MoviePy и Pillow. Генерирует брендированные видео, включая аудиодорожки BGM, изображения знаменитостей/продуктов и пользовательские шрифты непосредственно из markdown-сценариев.","ar":"يؤتمت إنتاج الفيديو القصير لحملات مكياج المشاهير باستخدام Python وMoviePy وPillow. يولد مقاطع فيديو تحمل العلامة التجارية كاملة مع مسارات صوتية BGM، وصور للمشاهير/المنتجات، وخطوط مخصصة مباشرةً من نصوص markdown."},"useCases":{"en":["Generating promotional cosmetics videos from script files","Automating celebrity endorsement video production","Creating branded short-form content with BGM integration"],"zh":["从脚本文件生成促销化妆品视频","自动化名人代言视频制作","创建带有BGM集成的品牌短视频内容"],"ja":["スクリプトファイルからのプロモーション用化粧品ビデオの生成","セレブリティエンドースメント動画制作の自動化","BGM統合を備えたブランドのショートフォームコンテンツの作成"],"ko":["스크립트 파일에서 프로모션용 화장품 비디오 생성","유명인 보증 비디오 제작 자동화","BGM 통합이 포함된 브랜드 숏폼 콘텐츠 제작"],"es":["Generar videos promocionales de cosméticos a partir de archivos de script","Automatizar la producción de videos de patrocinio de celebridades","Crear contenido de marca de forma corta con integración de BGM"],"fr":["Générer des vidéos promotionnelles de cosmétiques à partir de fichiers de script","Automatiser la production de vidéos de parrainage de célébrités","Créer du contenu de marque court avec intégration de BGM"],"de":["Erzeugen von Werbevideos für Kosmetik aus Skriptdateien","Automatisieren der Produktion von Celebrity-Unterstützungs-Videos","Erstellen von markenbehaftetem Kurzinhalt mit BGM-Integration"],"pt":["Geração de vídeos promocionais de cosméticos a partir de arquivos de script","Automação da produção de vídeos de endosso de celebridades","Criação de conteúdo de curta duração com marca e integração de BGM"],"ru":["Генерация рекламных видео для косметики из файлов сценариев","Автоматизация производства видео с одобрением знаменитостей","Создание брендированного короткого контента с интеграцией BGM"],"ar":["إنشاء فيديوهات ترويجية للماكياج من ملفات النصوص","أتمتة إنتاج فيديوهات endorsement للمشاهير","إنشاء محتوى قصير يحمل علامة تجارية مع دمج BGM"]},"limitations":{"en":["Requires local file system access for scripts/assets","Depends on MoviePy and Pillow Python packages","Needs pre-configured assets folder structure"],"zh":["需要本地文件系统访问权限以获取脚本/资源","依赖于MoviePy和Pillow Python软件包","需要预先配置的资源文件夹结构"],"ja":["スクリプト/アセットへのローカルファイルシステムアクセスが必要","MoviePyおよびPillow Pythonパッケージに依存","事前に設定されたアセットフォルダ構造が必要"],"ko":["스크립트/에셋에 대한 로컬 파일 시스템 액세스 필요","MoviePy 및 Pillow Python 패키지에 종속됨","사전 구성된 에셋 폴더 구조 필요"],"es":["Requiere acceso al sistema de archivos local para scripts/activos","Depende de los paquetes Python MoviePy y Pillow","Necesita una estructura de carpetas de activos preconfigurada"],"fr":["Nécessite un accès au système de fichiers local pour les scripts/ressources","Dépend des packages Python MoviePy et Pillow","Nécessite une structure de dossiers de ressources préconfigurée"],"de":["Benötigt Zugriff auf das lokale Dateisystem für Skripte/Assets","Hängt von den Python-Paketen MoviePy und Pillow ab","Benötigt eine vorkonfigurierte Asset-Ordnerstruktur"],"pt":["Requer acesso ao sistema de arquivos local para scripts/recursos","Depende dos pacotes Python MoviePy e Pillow","Necessita de uma estrutura de pasta de recursos pré-configurada"],"ru":["Требует доступ к локальной файловой системе для сценариев/активов","Зависит от пакетов Python MoviePy и Pillow","Требует предварительно настроенной структуры папок для активов"],"ar":["يتطلب الوصول إلى نظام الملفات المحلي للنصوص/المواد","يعتمد على حزم Python MoviePy وPillow","يحتاج إلى هيكل مجلد للمواد مُهيأ مسبقًا"]},"version":4},"contentHash":"8f8825aee533d89dceb33c83771ee62b9c9d796f52e426a8cf7ea19cc4bdce1b","qualityScore":33}');
