INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bogajoss/native_threads/gluestack-ui-v4:variants', 'gluestack-ui-v4:variants', 'bogajoss', 'native_threads', 'community', 'gluestack-ui-v4:variants bogajoss native_threads community The gluestack-ui-v4:variants skill allows developers to create custom variants for existing gluestack-ui v4 components, enabling project-specific styling patterns while maintaining consistency and type safety. Gluestack UI v4 变体创建允许您扩展设计系统，保持一致性和类型安全。创建自定义变体以实现项目特定的样式模式。 Gluestack UI v4 variants 作成は、デザインシステムを拡張し、一貫性とタイプセーフティを維持することを可能にします。プロジェクト固有のスタイルパターンを実現するために、カスタム変体を作成します。 Gluestack UI v4 변형 생성을 통해 디자인 시스템을 확장하고 일관성 및 유형 안전성을 유지할 수 있습니다. 프로젝트 특정 스타일 패턴을 구현하기 위한 사용자 정의 변형을 생성합니다. gluestack-ui-v4:variants permite crear variantes personalizadas para componentes existentes, manteniendo la consistencia y la seguridad de tipos gluestack-ui-v4:variants permet de créer des variantes personnalisées pour les composants existants, en maintenant la cohérence et la sécurité des types gluestack-ui-v4:variants ermöglicht die Erstellung benutzerdefinierter Varianten für bestehende Komponenten, wodurch die Konsistenz und die Typsicherheit gewährleistet werden O Gluestack UI v4: Variants permite criar variantes personalizadas para componentes existentes, mantendo a consistência e a segurança de tipos Gluestack UI v4: Варианты позволяет создавать пользовательские варианты для существующих компонентов, сохраняя последовательность и безопасность типов Gluestack UI v4: متغيرات يسمح بإنشاء متغيرات مخصصة لمكونات موجودة، مع الحفاظ على الاتساق وأمان النوع how to use gluestack-ui-v4:variants gluestack-ui-v4:variants setup guide gluestack-ui-v4:variants alternative gluestack-ui-v4:variants vs competitors creating custom variants for gluestack-ui v4 components extending design systems with project-specific styling patterns Gluestack UI v4 变体创建 设计系统 一致性 类型安全 AIエージェント 前端开发 UI 组件 Creates custom variants for existing gluestack-ui v4 components Extends the design system with project-specific styling patterns Maintains consistency and type safety Supports repeating the same style combination across multiple places Enables project-specific design patterns, such as brand-specific button styles gluestack-ui-v4:variants is a sub-skill for creating custom variants of gluestack-ui v4 components, extending the design system with project-specific styling patterns.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('NuclearPlayer/nuclear-xrd/creating-components', 'community', 'NuclearPlayer', 'nuclear-xrd', 'NuclearPlayer/nuclear-xrd', 'creating-components', 0, 0, 33, '2026-03-08T01:57:15.461Z', '2026-03-08T02:09:13.966Z', 'aa9642e9e323b99ad271a983701e4985769a9c4e10121450a4056162bd1707dd', '{"id":"NuclearPlayer/nuclear-xrd/creating-components","name":"creating-components","description":{"en":"The creating-components skill enables developers to build and export UI components using React and class-variance-authority. It benefits developers by providing a structured approach to component creation.","zh":"创建组件涉及定义组件结构和实现模式，使用React和class-variance-authority等技术。了解如何创建高质量的UI组件","ja":"コンポーネントを作成するには、コンポーネントの構造と実装パターンを定義し、Reactとclass-variance-authorityなどのテクノロジーを使用する必要があります","ko":"컴포넌트를 생성하는 것은 컴포넌트 구조와 구현 패턴을 정의하고 React 및 class-variance-authority 같은 기술을 사용하는 것을 포함합니다","es":"Creación de componentes UI con React y class-variance-authority. Estructura y exportación de componentes.","fr":"Création de composants UI avec React et class-variance-authority. Structure et exportation de composants.","de":"Erstellung von UI-Komponenten mit React und class-variance-authority. Struktur und Export von Komponenten.","pt":"Criar componentes UI personalizados com React e class-variance-authority. Aprenda a estruturar e implementar componentes reutilizáveis.","ru":"Создание пользовательских компонентов UI с помощью React и class-variance-authority. Узнайте, как структурировать и реализовывать многократно используемые компоненты.","ar":"إنشاء مكونات واجهة المستخدم المخصصة باستخدام React و class-variance-authority. تعلم كيفية بناء وتطبيق مكونات قابلة لإعادة الاستخدام."},"seo":{"title":{"en":"Creating-Components: Setup Guide for AI Agents | AI Agent...","zh":"创建组件设置指南 - AI工具","ja":"コンポーネント作成ベストプラクティス - AIエージェント","ko":"컴포넌트 생성 가이드 - AI에이전트","es":"Crear Componentes UI: Guía de Configuración con React","fr":"Créer des Composants UI: Meilleures Pratiques avec React","de":"UI-Komponenten Erstellen: Einrichtungsanleitung mit React","pt":"Criando Componentes UI: Guia de Configuração","ru":"Создание Компонентов UI: Руководство по Настройке","ar":"إنشاء مكونات واجهة المستخدم: دليل الإعداد"},"description":{"en":"Discover how to create UI components with class-variance-authority and React. Learn to implement and export components with our expert guide and start buildi...","zh":"了解如何创建高质量的UI组件，包括组件结构和实现模式，使用React和class-variance-authority等技术","ja":"コンポーネントの構造と実装パターンを学び、Reactとclass-variance-authorityなどのテクノロジーを使用して高品質のUIコンポーネントを作成する","ko":"UI 컴포넌트 구조와 구현 패턴에 대해 알아보고 React 및 class-variance-authority 같은 기술을 사용하여 고품질의 UI 컴포넌트를 생성하는 방법","es":"Aprende a crear componentes UI con React y class-variance-authority. Descubre cómo estructurar y exportar tus componentes de manera efectiva.","fr":"Découvrez comment créer des composants UI avec React et class-variance-authority. Apprenez à structurer et exporter vos composants de manière efficace.","de":"Erfahren Sie, wie Sie UI-Komponenten mit React und class-variance-authority erstellen. Lernen Sie, wie Sie Ihre Komponenten effektiv strukturieren und export...","pt":"Aprenda a criar componentes UI personalizados com React e class-variance-authority. Descubra como estruturar e implementar componentes reutilizáveis.","ru":"Узнайте, как создавать пользовательские компоненты UI с помощью React и class-variance-authority. Ознакомьтесь с тем, как структурировать и реализовывать мно...","ar":"تعلم كيفية إنشاء مكونات واجهة المستخدم المخصصة باستخدام React و class-variance-authority. اكتشف كيفية بناء وتطبيق مكونات قابلة لإعادة الاستخدام."},"definition":{"en":"Creating-components is a skill that allows developers to create and manage UI components using a standardized structure and implementation pattern.","zh":"创建组件是指定义和实现UI组件的结构和行为","ja":"コンポーネント作成とは、UIコンポーネントの構造と動作を定義および実装すること","ko":"컴포넌트 생성은 UI 컴포넌트의 구조와 동작을 정의 및 구현하는 것을 의미합니다","es":"Crear componentes es el proceso de diseñar y desarrollar elementos UI reutilizables con React.","fr":"Créer des composants est le processus de conception et de développement d''éléments UI réutilisables avec React.","de":"Die Erstellung von Komponenten ist der Prozess der Gestaltung und Entwicklung von wiederverwendbaren UI-Elementen mit React.","pt":"Criar componentes UI é o processo de desenvolver elementos reutilizáveis de interface do usuário com React e class-variance-authority.","ru":"Создание компонентов UI - это процесс разработки многократно используемых элементов пользовательского интерфейса с помощью React и class-variance-authority.","ar":"إنشاء مكونات واجهة المستخدم هو عملية تطوير عناصر واجهة المستخدم القابلة لإعادة الاستخدام باستخدام React و class-variance-authority."},"features":{"en":["Generates component structure with MyComponent.tsx, MyComponent.test.tsx, and index.ts files","Supports testing with Vitest snapshots","Utilizes class-variance-authority for styling and layout management","Compatible with React and ComponentProps","Exports components from packages/ui/src/components/index.ts","Follows a standardized implementation pattern with tsx files"],"zh":["使用React创建UI组件","定义组件结构和实现模式","使用class-variance-authority管理样式","支持Vitest测试和快照","导出组件以供重用"],"ja":["Reactを使用してUIコンポーネントを作成する","コンポーネントの構造と実装パターンを定義する","class-variance-authorityを使用してスタイルを管理する","Vitestテストとスナップショットをサポートする","コンポーネントをエクスポートして再利用する"],"ko":["React를 사용하여 UI 컴포넌트를 생성하는 기능","컴포넌트 구조와 구현 패턴을 정의하는 기능","class-variance-authority를 사용하여 스타일을 관리하는 기능","Vitest 테스트 및 스냅샷을 지원하는 기능","컴포넌트를 내보내기하여 재사용하는 기능"],"es":["Estructura de componentes con MyComponent.tsx y MyComponent.test.tsx","Uso de class-variance-authority para la creación de componentes","Exportación de componentes desde packages/ui/src/components/index.ts","Compatibilidad con Vitest para pruebas automatizadas","Uso de React para la creación de componentes UI"],"fr":["Structure de composants avec MyComponent.tsx et MyComponent.test.tsx","Utilisation de class-variance-authority pour la création de composants","Exportation de composants depuis packages/ui/src/components/index.ts","Compatibilité avec Vitest pour les tests automatisés","Utilisation de React pour la création de composants UI"],"de":["Komponentenstruktur mit MyComponent.tsx und MyComponent.test.tsx","Verwendung von class-variance-authority für die Erstellung von Komponenten","Export von Komponenten aus packages/ui/src/components/index.ts","Kompatibilität mit Vitest für automatisierte Tests","Verwendung von React für die Erstellung von UI-Komponenten"],"pt":["Estrutura de componente com React","Uso de class-variance-authority para estilização","Criação de componentes reutilizáveis","Testes unitários com Vitest","Exportação de componentes com index.ts","Suporte a snapshots com Vitest"],"ru":["Структура компонента с помощью React","Использование class-variance-authority для стилизации","Создание многократно используемых компонентов","Юнит-тестирование с Vitest","Экспорт компонентов с помощью index.ts","Поддержка снимков с Vitest"],"ar":["هيكل المكون باستخدام React","استخدام class-variance-authority للتنسيق","إنشاء مكونات قابلة لإعادة الاستخدام","اختبارات الوحدة مع Vitest","تصدير المكونات باستخدام index.ts","دعم الصور الثابتة مع Vitest"]},"keywords":{"en":["how to use creating-components","creating-components setup guide","class-variance-authority tutorial","React component creation","creating-components alternative","creating-components vs Storybook","what is creating-components","creating-components install","UI component development"],"zh":["创建组件","UI组件","React","class-variance-authority","Vitest","组件结构","实现模式","AI工具","前端开发"],"ja":["コンポーネント作成","UIコンポーネント","React","class-variance-authority","Vitest","コンポーネント構造","実装パターン","AIエージェント","フロントエンド開発"],"ko":["컴포넌트 생성","UI 컴포넌트","React","class-variance-authority","Vitest","컴포넌트 구조","구현 패턴","AI에이전트","프론트엔드 개발"],"es":["crear componentes ui","react para principiantes","class-variance-authority","vitest para react","componentes ui reutilizables","desarrollo de componentes ui","react y class-variance-authority"],"fr":["créer des composants ui","react pour débutants","class-variance-authority","vitest pour react","composants ui réutilisables","développement de composants ui","react et class-variance-authority"],"de":["ui-komponenten erstellen","react für anfänger","class-variance-authority","vitest für react","ui-komponenten wiederverwendbar","entwicklung von ui-komponenten","react und class-variance-authority"],"pt":["criar componentes ui","react components","class-variance-authority","vitest","componentes reutilizáveis","desenvolvimento de interface do usuário","criação de componentes ui personalizados","guias de configuração de componentes ui"],"ru":["создать компоненты ui","react компоненты","class-variance-authority","vitest","многократно используемые компоненты","разработка пользовательского интерфейса","создание пользовательских компонентов ui","руководства по настройке компонентов ui"],"ar":["إنشاء مكونات واجهة المستخدم","مكونات رياكت","class-variance-authority","vitest","مكونات قابلة لإعادة الاستخدام","تطوير واجهة المستخدم","إنشاء مكونات واجهة المستخدم المخصصة","دلائل إعداد مكونات واجهة المستخدم"]}},"owner":"NuclearPlayer","repo":"nuclear-xrd","repoPath":"NuclearPlayer/nuclear-xrd","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.461Z","topics":[],"category":"community","skillMd":{"name":"creating-components","description":"Use when creating new UI components in packages/ui. Covers component structure, tests, stories, and what to avoid.","bodyPreview":"# Creating UI Components\n\n## Component Structure\n\n```\npackages/ui/src/components/MyComponent/\n├── MyComponent.tsx      # Implementation\n├── MyComponent.test.tsx # Tests\n├── index.ts             # Re-exports\n└── __snapshots__/       # Vitest snapshots (auto-generated)\n```\n\nAfter creating, export from `packages/ui/src/components/index.ts`.\n\n## Implementation Pattern\n\n```tsx\nimport { cva, VariantProps } from ''class-variance-authority'';\nimport { ComponentProps, FC } from ''react'';\nimport { cn } from","body":"# Creating UI Components\n\n## Component Structure\n\n```\npackages/ui/src/components/MyComponent/\n├── MyComponent.tsx      # Implementation\n├── MyComponent.test.tsx # Tests\n├── index.ts             # Re-exports\n└── __snapshots__/       # Vitest snapshots (auto-generated)\n```\n\nAfter creating, export from `packages/ui/src/components/index.ts`.\n\n## Implementation Pattern\n\n```tsx\nimport { cva, VariantProps } from ''class-variance-authority'';\nimport { ComponentProps, FC } from ''react'';\nimport { cn } from ''../../utils'';\n\nconst variants = cva(''base-classes'', {\n  variants: { /* ... */ },\n  defaultVariants: { /* ... */ },\n});\n\ntype MyComponentProps = ComponentProps<''div''> & VariantProps<typeof variants>;\n\nexport const MyComponent: FC<MyComponentProps> = ({\n  className,\n  variant,\n  ...props\n}) => (\n  <div className={cn(variants({ variant, className }))} {...props} />\n);\n```\n\n## Tests\n\n**What to test:**\n- Snapshots (1-2 covering key variants)\n- User interactions\n- Behavior (callbacks called with correct args)\n\n**What NOT to test:**\n- CSS classes, attributes (use snapshots instead)\n- Internal state\n- Things TypeScript already enforces\n\n**Consolidate tests.** One test can cover multiple related assertions. An exception to that is snapshot tests - one snapshot per variant/state.\n\n## Stories\n\nCreate `packages/storybook/src/MyComponent.stories.tsx`.\n\n**One story can show multiple related variants.** For example, it''s wasteful to create a story for each variant of a button. Put them all together in one place. Don''t create separate stories for each variant:\n\n```tsx\nimport { Meta, StoryObj } from ''@storybook/react-vite'';\nimport { useState } from ''react'';\nimport { MyComponent } from ''@nuclearplayer/ui'';\n\nconst meta = {\n  title: ''Components/MyComponent'',\n  component: MyComponent,\n  tags: [''autodocs''],\n} satisfies Meta<typeof MyComponent>;\n\nexport default meta;\ntype Story = StoryObj<typeof MyComponent>;\n\nexport const AllVariants: Story = {\n  render: () => {\n    const [state, setState] = useState(initialState);\n    return (\n      <div className=\"flex flex-col gap-4\">\n        {/* Show all variants, states, interactions */}\n      </div>\n    );\n  },\n};\n```\n\nThis isn''t an iron rule, sometimes it will make more sense to have separate stories.\n\nDon''t run storybook build checks.\n\n## Avoiding Duplication\n\nBefore creating a new component, check if an existing one can be extended.\n\n**Pattern: Discriminated unions for mode variants**\n\nExample: Instead of creating `SingleSelect` and `MultiSelect` components:\n\n```tsx\ntype Props = \n  | { multiple?: false; selected: string; onChange: (id: string) => void }\n  | { multiple: true; selected: string[]; onChange: (ids: string[]) => void };\n```\n\nTypeScript enforces correct types based on the `multiple` prop.\n\n## Classes for customization\n\nWhere it''s likely that a component will need custom styling, expose a `className` prop.\n\nIf there are many parts that may need styling, consider exposing a `classes` prop with specific class names for each part. Define a type for the `classes` prop. Refer to `packages/ui/src/components/TrackTable/types.ts` for an example.\n\n## Strings\n\nAll user-facing strings go through i18n - no hardcoded UI text.\nIf a new component in the ui package needs labels and other kinds of localized text, it should accept a `labels` prop with the relevant strings. The prop should have its own type defined. Refer to `packages/ui/src/components/QueueItem/types.ts` for an example.\n\n## Accessibility\n\nWe don''t care about that. If there''s an opportunity to handle that easily, do it, but don''t go out of your way.\n\n## Checklist\n\n- [ ] Component in `packages/ui/src/components/MyComponent/`\n- [ ] Exported from `packages/ui/src/components/index.ts`\n- [ ] Tests cover behavior, not implementation\n- [ ] Tests consolidated (not one per variant)\n- [ ] One story showing all variants\n- [ ] No CSS class assertions in tests\n- [ ] No duplicate component when extending existing one works\n"},"lastSynced":"2026-03-08T02:09:13.966Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing structured React component creation with class-variance-authority.","zh":"非常适合需要利用 class-variance-authority 进行结构化 React 组件创建的前端智能体。","ja":"class-variance-authority を使用した構造化された React コンポーネント作成を必要とするフロントエンドエージェントに最適です。","ko":"class-variance-authority를 사용하여 구조화된 React 컴포넌트 생성이 필요한 프론트엔드 에이전트에게 완벽합니다.","es":"Perfecto para agentes Frontend que necesitan la creación de componentes de React estructurados con class-variance-authority.","fr":"Parfait pour les agents Frontend qui ont besoin de la création de composants React structurés avec class-variance-authority.","de":"Perfekt für Frontend-Agents, die strukturierte React-Komponenten-Erstellung mit class-variance-authority benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de criação estruturada de componentes React com class-variance-authority.","ru":"Идеально подходит для Frontend-агентов, которым требуется структурированное создание компонентов React с использованием class-variance-authority.","ar":"مثالي لوكلاء الواجهة الأمامية الذين يحتاجون إلى إنشاء مكونات React منظمة باستخدام class-variance-authority."},"recommendation":{"en":"Empowers agents to build and export reusable UI components using React and class-variance-authority, providing a standardized approach to component development with Vitest snapshots and TypeScript.","zh":"使智能体能够使用 React 和 class-variance-authority 构建并导出可复用的 UI 组件，通过 Vitest 快照和 TypeScript 为组件开发提供标准化方法。","ja":"React と class-variance-authority を使用して再利用可能な UI コンポーネントを構築およびエクスポートする機能をエージェントに提供し、Vitest スナップショットと TypeScript によるコンポーネント開発の標準化されたアプローチを実現します。","ko":"React와 class-variance-authority를 사용하여 재사용 가능한 UI 컴포넌트를 구축하고 내보내는 기능을 에이전트에게 부여하며, Vitest 스냅샷과 TypeScript를 통한 컴포넌트 개발의 표준화된 접근 방식을 제공합니다.","es":"Habilita a los agentes a construir y exportar componentes de UI reutilizables utilizando React y class-variance-authority, proporcionando un enfoque estandarizado para el desarrollo de componentes con instantáneas de Vitest y TypeScript.","fr":"Permet aux agents de créer et d''exporter des composants d''interface utilisateur réutilisables en utilisant React et class-variance-authority, fournissant une approche standardisée pour le développement de composants avec des instantanés Vitest et TypeScript.","de":"Ermächtigt Agents, wiederverwendbare UI-Komponenten mit React und class-variance-authority zu erstellen und zu exportieren, und bietet einen standardisierten Ansatz für die Komponentenentwicklung mit Vitest-Snapshots und TypeScript.","pt":"Capacita os agentes a construir e exportar componentes de UI reutilizáveis usando React e class-variance-authority, fornecendo uma abordagem padronizada para o desenvolvimento de componentes com snapshots do Vitest e TypeScript.","ru":"Позволяет агентам создавать и экспортировать повторно используемые UI-компоненты с использованием React и class-variance-authority, обеспечивая стандартизированный подход к разработке компонентов со снимками Vitest и TypeScript.","ar":"يمكّن الوكلاء من بناء وتصدير مكونات واجهة مستخدم قابلة لإعادة الاستخدام باستخدام React و class-variance-authority، مما يوفر نهجًا معياريًا لتطوير المكونات مع لقطات Vitest و TypeScript."},"useCases":{"en":["Building reusable UI components","Exporting components for cross-project usage","Implementing consistent component testing with Vitest"],"zh":["构建可复用的 UI 组件","导出组件以供跨项目使用","使用 Vitest 实施一致的组件测试"],"ja":["再利用可能な UI コンポーネントの構築","クロスプロジェクトでの使用のためのコンポーネントのエクスポート","Vitest を使用した一貫したコンポーネントテストの実装"],"ko":["재사용 가능한 UI 컴포넌트 구축","프로젝트 간 사용을 위한 컴포넌트 내보내기","Vitest를 사용한 일관된 컴포넌트 테스트 구현"],"es":["Creación de componentes de UI reutilizables","Exportación de componentes para uso entre proyectos","Implementación de pruebas de componentes consistentes con Vitest"],"fr":["Création de composants d''interface utilisateur réutilisables","Exportation de composants pour une utilisation entre projets","Mise en œuvre de tests de composants cohérents avec Vitest"],"de":["Erstellung wiederverwendbarer UI-Komponenten","Exportieren von Komponenten für den Einsatz zwischen Projekten","Implementierung konsistenter Komponententests mit Vitest"],"pt":["Construção de componentes de UI reutilizáveis","Exportação de componentes para uso entre projetos","Implementação de testes de componentes consistentes com Vitest"],"ru":["Создание повторно используемых UI-компонентов","Экспорт компонентов для использования в различных проектах","Реализация согласованного тестирования компонентов с Vitest"],"ar":["بناء مكونات واجهة مستخدم قابلة لإعادة الاستخدام","تصدير المكونات للاستخدام عبر المشاريع","تنفيذ اختبار مكونات متسق باستخدام Vitest"]},"limitations":{"en":["Requires React and class-variance-authority setup","TypeScript configuration necessary"],"zh":["需要 React 和 class-variance-authority 设置","需要 TypeScript 配置"],"ja":["React と class-variance-authority のセットアップが必要","TypeScript の設定が必要"],"ko":["React 및 class-variance-authority 설정 필요","TypeScript 구성 필요"],"es":["Requiere configuración de React y class-variance-authority","Configuración de TypeScript necesaria"],"fr":["Nécessite une configuration de React et class-variance-authority","Configuration de TypeScript nécessaire"],"de":["Benötigt React- und class-variance-authority-Setup","TypeScript-Konfiguration erforderlich"],"pt":["Requer configuração do React e class-variance-authority","Configuração do TypeScript necessária"],"ru":["Требует настройки React и class-variance-authority","Необходима конфигурация TypeScript"],"ar":["يتطلب إعداد React و class-variance-authority","تكوين TypeScript ضروري"]},"version":4},"contentHash":"aa9642e9e323b99ad271a983701e4985769a9c4e10121450a4056162bd1707dd","qualityScore":33}');
