INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('NuclearPlayer/nuclear-xrd/creating-components', 'creating-components', 'NuclearPlayer', 'nuclear-xrd', 'community', 'creating-components NuclearPlayer nuclear-xrd community The creating-components skill enables developers to build and export UI components using React and class-variance-authority. It benefits developers by providing a structured approach to component creation. 创建组件涉及定义组件结构和实现模式，使用React和class-variance-authority等技术。了解如何创建高质量的UI组件 コンポーネントを作成するには、コンポーネントの構造と実装パターンを定義し、Reactとclass-variance-authorityなどのテクノロジーを使用する必要があります 컴포넌트를 생성하는 것은 컴포넌트 구조와 구현 패턴을 정의하고 React 및 class-variance-authority 같은 기술을 사용하는 것을 포함합니다 Creación de componentes UI con React y class-variance-authority. Estructura y exportación de componentes. Création de composants UI avec React et class-variance-authority. Structure et exportation de composants. Erstellung von UI-Komponenten mit React und class-variance-authority. Struktur und Export von Komponenten. Criar componentes UI personalizados com React e class-variance-authority. Aprenda a estruturar e implementar componentes reutilizáveis. Создание пользовательских компонентов UI с помощью React и class-variance-authority. Узнайте, как структурировать и реализовывать многократно используемые компоненты. إنشاء مكونات واجهة المستخدم المخصصة باستخدام React و class-variance-authority. تعلم كيفية بناء وتطبيق مكونات قابلة لإعادة الاستخدام. how to use creating-components creating-components setup guide class-variance-authority tutorial React component creation creating-components alternative creating-components vs Storybook what is creating-components creating-components install UI component development 创建组件 UI组件 React class-variance-authority Vitest 组件结构 实现模式 AI工具 前端开发 Generates component structure with MyComponent.tsx, MyComponent.test.tsx, and index.ts files Supports testing with Vitest snapshots Utilizes class-variance-authority for styling and layout management Compatible with React and ComponentProps Exports components from packages/ui/src/components/index.ts Follows a standardized implementation pattern with tsx files Creating-components is a skill that allows developers to create and manage UI components using a standardized structure and implementation pattern.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('eduardojvieira/ZPLC/zustand-state', 'community', 'eduardojvieira', 'ZPLC', 'eduardojvieira/ZPLC', 'zustand-state', 0, 0, 33, '2026-03-08T01:57:15.462Z', '2026-03-08T02:09:16.850Z', '82e215e941ba790c120e7710629f5b655edb0ff65bbc8c88a658506316d0b9af', '{"id":"eduardojvieira/ZPLC/zustand-state","name":"zustand-state","description":{"en":"zustand-state provides minimal state management for developers, allowing them to create and manage state stores with minimal boilerplate. It benefits developers who need a lightweight state management solution.","zh":"Zustand State Management 是一种 Minimal state management 方案，无需 providers 和 minimal boilerplate","ja":"Zustand State Management は、React を使用した開発でMinimal state management を実現するライブラリです","ko":"Zustand State Management 는 Portable PLC Runtime 을 구현하는 데 사용되는 Minimal state management 라이브러리입니다","es":"Zustand State es una biblioteca de gestión de estado minimalista que permite la creación de almacenamientos de estado personalizados sin providers ni boilerplate adicional","fr":"Zustand State est une bibliothèque de gestion d''état minimaliste qui permet la création de magasins d''état personnalisés sans providers ni boilerplate supplémentaire","de":"Zustand State ist eine minimalistische Bibliothek für die Zustandsverwaltung, die die Erstellung von benutzerdefinierten Zustandsspeichern ohne Providers oder zusätzlichen Boilerplate ermöglicht","pt":"O Zustand State é uma biblioteca de gerenciamento de estado mínimo para React, sem provedores e com pouca codificação","ru":"Zustand State - это библиотека минимального управления состоянием для React, без провайдеров и с минимальным кодом","ar":"Zustand State هو مكتبة لإدارة الحالة الأدنى ل React، بدون مزودين وبالترميز الأدنى"},"seo":{"title":{"en":"zustand-state: Minimal State Management Setup Guide | AI ...","zh":"Zustand State Management Setup Guide -Minimal Boilerplate","ja":"Zustand State Management ベストプラクティス - AIエージェント","ko":"Zustand State Management 구현 방법 - Portable PLC Runtime","es":"Guía de configuración de Zustand State para gestión de es...","fr":"Guide de mise en route de Zustand State pour une gestion ...","de":"Einrichtungsanleitung für Zustand State zur minimalen Zus...","pt":"Guia de Configuração do Zustand State","ru":"Настройка Zustand State: Руководство","ar":"إعداد Zustand State: دليل المستخدم"},"description":{"en":"Discover how to implement minimal state management with zustand-state. Learn how to create and use portable state stores with ease. Get started now!","zh":"了解 Zustand State Management 的优势和特点，实现 Minimal state management 和 portable PLC Runtime","ja":"Zustand State Management の特徴と使い方を紹介します。AIエージェントと React を使用した開発","ko":"Zustand State Management 의 기능과 장점을 살펴보고Portable PLC Runtime 을 구현하는 방법","es":"Aprende a utilizar Zustand State para una gestión de estado eficiente en tus aplicaciones con esta guía paso a paso","fr":"Découvrez comment utiliser Zustand State pour une gestion d''état efficace dans vos applications avec ce guide étape par étape","de":"Erfahren Sie, wie Sie Zustand State für eine effiziente Zustandsverwaltung in Ihren Anwendungen verwenden können, mit diesem Schritt-für-Schritt-Leitfaden","pt":"Aprenda a configurar o Zustand State para gerenciamento de estado mínimo em seus projetos React","ru":"Узнайте, как настроить Zustand State для минимального управления состоянием в ваших проектах React","ar":"تعرف على كيفية إعداد Zustand State لتدبير الحالة الأدنى في مشاريع React"},"definition":{"en":"zustand-state is a minimal state management library that provides a simple way to create and manage state stores without the need for providers or excessive boilerplate code.","zh":"Zustand State Management 是一种轻量级的状态管理库","ja":"Zustand State Management は、状態管理を実現するためのライブラリです","ko":"Zustand State Management 는 상태 관리를 위한 라이브러리입니다","es":"Zustand State es una biblioteca JavaScript para la gestión de estado que permite la creación de almacenamientos de estado personalizados","fr":"Zustand State est une bibliothèque JavaScript pour la gestion d''état qui permet la création de magasins d''état personnalisés","de":"Zustand State ist eine JavaScript-Bibliothek für die Zustandsverwaltung, die die Erstellung von benutzerdefinierten Zustandsspeichern ermöglicht","pt":"O que é Zustand State? É uma biblioteca de gerenciamento de estado mínimo para React","ru":"Что такое Zustand State? Это библиотека минимального управления состоянием для React","ar":"ما هو Zustand State؟ هو مكتبة لإدارة الحالة الأدنى ل React"},"features":{"en":["Creates state stores using the `create` function from ''zustand''","Supports minimal boilerplate code for easy state management","Allows for selective state retrieval using the `useBearStore` hook","Enables state updates using the `set` function","Provides a simple interface for defining state shapes, such as the `BearState` interface","Supports type-safe state management using TypeScript"],"zh":["Minimal state management","无需 providers","Minimal boilerplate","支持 TypeScript","可用于 React 开发","实现 portable PLC Runtime"],"ja":["Minimal state management","プロバイダー不要","Minimal boilerplate","TypeScript サポート","React 開発での使用","Portable PLC Runtime 実現"],"ko":["Minimal state management","프로바이더 없음","Minimal boilerplate","TypeScript 지원","React 개발에서 사용","Portable PLC Runtime 구현"],"es":["Gestión de estado minimalista sin providers","Creación de almacenamientos de estado personalizados","Interfaz de programación de aplicaciones (API) de TypeScript","Compatibilidad con la creación de componentes personalizados","Gestión de estado reactiva con actualizaciones en tiempo real"],"fr":["Gestion d''état minimaliste sans providers","Création de magasins d''état personnalisés","Interface de programmation d''applications (API) de TypeScript","Compatibilité avec la création de composants personnalisés","Gestion d''état réactive avec des mises à jour en temps réel"],"de":["Minimalistische Zustandsverwaltung ohne Providers","Erstellung von benutzerdefinierten Zustandsspeichern","Programmierschnittstelle (API) von TypeScript","Kompatibilität mit der Erstellung von benutzerdefinierten Komponenten","Reaktive Zustandsverwaltung mit Echtzeit-Aktualisierungen"],"pt":["Gerenciamento de estado mínimo sem provedores","Código mínimo e fácil de manter","Integração com React para gerenciamento de estado","Suporte a tipos personalizados com TypeScript","Atualização de estado com set e get"],"ru":["Минимальное управление состоянием без провайдеров","Минимальный код и легкость обслуживания","Интеграция с React для управления состоянием","Поддержка пользовательских типов с помощью TypeScript","Обновление состояния с помощью set и get"],"ar":["إدارة الحالة الأدنى بدون مزودين","رمز أدنى وسهل الصيانة","التكامل مع React لإدارة الحالة","دعم أنواع مخصصة مع TypeScript","تحديث الحالة باستخدام set و get"]},"keywords":{"en":["how to use zustand-state","zustand-state alternative","zustand-state vs mobx","zustand-state install","zustand-state setup guide","what is zustand-state","zustand-state tutorial","zustand-state example","zustand-state state management"],"zh":["Zustand State Management","Minimal state management","React 开发","TypeScript","Portable PLC Runtime","状态管理","AIエージェント","前端开发"],"ja":["Zustand State Management","Minimal state management","React 開発","TypeScript","Portable PLC Runtime","状態管理","AIエージェント","フロントエンド開発"],"ko":["Zustand State Management","Minimal state management","React 개발","TypeScript","Portable PLC Runtime","상태 관리","AI 에이전트","프론트엔드 개발"],"es":["Zustand State","gestión de estado","biblioteca JavaScript","almacenamiento de estado personalizado","TypeScript","reactividad","componentes personalizados","Herramientas de desarrollo de software","Estado de la aplicación","Gestión de estado en tiempo real"],"fr":["Zustand State","gestion d''état","bibliothèque JavaScript","magasin d''état personnalisé","TypeScript","réactivité","composants personnalisés","Outils de développement de logiciels","État de l''application","Gestion d''état en temps réel"],"de":["Zustand State","Zustandsverwaltung","JavaScript-Bibliothek","benutzerdefinierter Zustandsspeicher","TypeScript","Reaktivität","benutzerdefinierte Komponenten","Software-Entwicklungstools","Anwendungsstatus","Zustandsverwaltung in Echtzeit"],"pt":["zustand state","gerenciamento de estado react","biblioteca de gerenciamento de estado","react zustand","typescript zustand","zustand state setup","configuração zustand state"],"ru":["zustand state","управление состоянием react","библиотека управления состоянием","react zustand","typescript zustand","настройка zustand state","зустанд стейт руководство"],"ar":["zustand state","إدارة الحالة react","مكتبة إدارة الحالة","react zustand","typescript zustand","إعداد zustand state","دليل zustand state"]}},"owner":"eduardojvieira","repo":"ZPLC","repoPath":"eduardojvieira/ZPLC","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.462Z","topics":[],"category":"community","skillMd":{"name":"zustand-state","description":"Zustand state management for React and vanilla JavaScript. Use when creating stores, using selectors, persisting state to localStorage, integrating devtools, or managing global state without Redux complexity. Triggers on zustand, create(), createStore, useStore, persist, devtools, immer middleware.","bodyPreview":"# Zustand State Management\n\nMinimal state management - no providers, minimal boilerplate.\n\n## Quick Reference\n\n```typescript\nimport { create } from ''zustand''\n\ninterface BearState {\n  bears: number\n  increase: (by: number) => void\n}\n\nconst useBearStore = create<BearState>()((set) => ({\n  bears: 0,\n  increase: (by) => set((state) => ({ bears: state.bears + by })),\n}))\n\n// In component - select only what you need\nconst bears = useBearStore((state) => state.bears)\nconst increase = useBearStore((stat","body":"# Zustand State Management\n\nMinimal state management - no providers, minimal boilerplate.\n\n## Quick Reference\n\n```typescript\nimport { create } from ''zustand''\n\ninterface BearState {\n  bears: number\n  increase: (by: number) => void\n}\n\nconst useBearStore = create<BearState>()((set) => ({\n  bears: 0,\n  increase: (by) => set((state) => ({ bears: state.bears + by })),\n}))\n\n// In component - select only what you need\nconst bears = useBearStore((state) => state.bears)\nconst increase = useBearStore((state) => state.increase)\n```\n\n## State Updates\n\n```typescript\n// Flat updates (auto-merged at one level)\nset({ bears: 5 })\nset((state) => ({ bears: state.bears + 1 }))\n\n// Nested objects (manual spread required)\nset((state) => ({\n  nested: { ...state.nested, count: state.nested.count + 1 }\n}))\n\n// Replace entire state (no merge)\nset({ bears: 0 }, true)\n```\n\n## Selectors & Performance\n\n```typescript\n// Good - subscribes only to bears\nconst bears = useBearStore((state) => state.bears)\n\n// Bad - rerenders on any change\nconst state = useBearStore()\n\n// Multiple values with useShallow (prevents rerenders with shallow comparison)\nimport { useShallow } from ''zustand/react/shallow''\n\nconst { bears, fish } = useBearStore(\n  useShallow((state) => ({ bears: state.bears, fish: state.fish }))\n)\n\n// Array destructuring also works\nconst [bears, fish] = useBearStore(\n  useShallow((state) => [state.bears, state.fish])\n)\n```\n\n## Access Outside Components\n\n```typescript\n// Get current state (non-reactive)\nconst state = useBearStore.getState()\n\n// Update state\nuseBearStore.setState({ bears: 5 })\n\n// Subscribe to changes\nconst unsub = useBearStore.subscribe((state) => console.log(state))\nunsub() // unsubscribe\n```\n\n## Vanilla Store (No React)\n\n```typescript\nimport { createStore } from ''zustand/vanilla''\n\nconst store = createStore((set) => ({\n  bears: 0,\n  increase: (by) => set((state) => ({ bears: state.bears + by })),\n}))\n\nstore.getState().bears\nstore.setState({ bears: 10 })\nstore.subscribe((state) => console.log(state))\n```\n\n## Additional Documentation\n\n- **Middleware**: See [references/middleware.md](references/middleware.md) for persist, devtools, immer\n- **Patterns**: See [references/patterns.md](references/patterns.md) for slices, testing, best practices\n- **TypeScript**: See [references/typescript.md](references/typescript.md) for advanced typing patterns\n\n## Key Patterns\n\n| Pattern | When to Use |\n|---------|-------------|\n| Single selector | One piece of state needed |\n| `useShallow` | Multiple values, avoid rerenders |\n| `getState()` | Outside React, event handlers |\n| `subscribe()` | External systems, logging |\n| Vanilla store | Non-React environments |\n"},"lastSynced":"2026-03-08T02:09:16.850Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Development Agents needing lightweight React state management without boilerplate.","zh":"非常适合需要轻量级React状态管理且无需样板代码的前端开发代理。","ja":"フロントエンド開発エージェントがボイラープレートなしで軽量のReact状態管理を必要とする場合に最適です。","ko":"보일러 플레이트가 없는 경량 React 상태 관리가 필요한 프론트엔드 개발 에이전트에 적합합니다.","es":"Perfecto para agentes de desarrollo Frontend que necesitan una gestión ligera del estado en React sin código repetitivo.","fr":"Parfait pour les agents de développement Frontend ayant besoin d''une gestion d''état légère pour React sans code passe-partout.","de":"Perfekt für Frontend Development Agents, die eine schlanke Zustandsverwaltung für React ohne Boilerplate benötigen.","pt":"Perfeito para agentes de desenvolvimento Frontend que necessitam de gerenciamento de estado React leve sem boilerplate.","ru":"Идеально подходит для агентов разработки Frontend, которым нужен легкий менеджер состояния React без boilerplate.","ar":"مثالي لعمليات تطوير الواجهة الأمامية التي تحتاج إلى إدارة حالة React خفيفة بدون كود مسبق."},"recommendation":{"en":"Enables agents to create and manage Zustand stores with minimal setup, providing state persistence and selective component re-rendering through direct state selection. Eliminates provider wrapper complexity while maintaining TypeScript compatibility.","zh":"使得代理能够创建和管理Zustand存储，并提供最小的设置，实现状态持久性和通过直接状态选择进行选择性组件重新渲染。消除了提供者包装器的复杂性，同时保持TypeScript兼容性。","ja":"エージェントがZustandストアを作成および管理できるようにし、最小限の設定で状態の永続性と直接状態選択による選択的なコンポーネントの再描画を提供します。プロバイダラッパーの複雑さを排除しながらTypeScriptの互換性を維持します。","ko":"에이전트가 Zustand 저장소를 생성하고 관리할 수 있도록 하며, 최소한의 설정으로 상태 지속성 및 직접 상태 선택을 통해 선택적 컴포넌트 재 렌더링을 제공합니다. 제공자 래퍼의 복잡성을 제거하면서 TypeScript 호환성을 유지합니다.","es":"Permite a los agentes crear y gestionar stores de Zustand con una configuración mínima, proporcionando persistencia del estado y rerenderizado selectivo de componentes mediante la selección directa del estado. Elimina la complejidad de los wrapper de providers manteniendo la compatibilidad con TypeScript.","fr":"Permet aux agents de créer et gérer des stores Zustand avec une configuration minimale, fournissant une persistance d''état et un rerendu sélectif des composants via une sélection directe de l''état. Élimine la complexité des wrappers de fournisseurs tout en conservant la compatibilité TypeScript.","de":"Ermöglicht es Agents, Zustand-Stores mit minimalem Setup zu erstellen und zu verwalten, bietet Zustandspersistenz und selektives Neu-Rendering von Komponenten durch direkte Zustandsauswahl. Beseitigt die Komplexität von Provider-Wrappern bei gleichzeitiger Beibehaltung der TypeScript-Kompatibilität.","pt":"Permite que os agentes criem e gerenciem lojas Zustand com configuração mínima, fornecendo persistência de estado e re-renderização seletiva de componentes por meio da seleção direta de estado. Elimina a complexidade do wrapper do provedor ao manter a compatibilidade com TypeScript.","ru":"Позволяет агентам создавать и управлять хранилищами Zustand с минимальной настройкой, обеспечивая сохранность состояния и выборочную перерисовку компонентов посредством прямого выбора состояния. Удаляет сложность обертки провайдера, сохраняя при этом совместимость с TypeScript.","ar":"يسمح للوكلاء بإنشاء وتحكم مخازن Zustand بإعدادات.minimum ، مما يوفر استمرارية الحالة وإعادة تشغيل مكونات محددة من خلال اختيار الحالة المباشر. يقضي على تعقيد غلاف المزود مع الحفاظ على التوافق مع TypeScript."},"useCases":{"en":["Creating minimal state stores for React components","Managing global state without provider nesting","Optimizing performance with selective state selection"],"zh":["为React组件创建最小的状态存储","管理全局状态而不需要提供者嵌套","通过选择性的状态选择优化性能"],"ja":["Reactコンポーネントのための最小限の状態ストアを作成する","プロバイダのネストなしでグローバル状態を管理する","選択的な状態の選択によるパフォーマンスの最適化"],"ko":["React 컴포넌트를 위한 최소한의 상태 저장소를 생성하는 것","제공者の 중첩 없이 전역 상태를 관리하는 것","선택적인 상태 선택을 통한 성능 최적화"],"es":["Creación de stores de estado mínimos para componentes React","Gestión del estado global sin anidamiento de providers","Optimización del rendimiento con selección selectiva del estado"],"fr":["Création de stores d''état minimaux pour les composants React","Gestion d''état global sans imbrication de fournisseurs","Optimisation des performances avec une sélection sélective de l''état"],"de":["Erstellen minimaler Zustands-Stores für React-Komponenten","Verwalten des globalen Zustands ohne Provider-Verschachtelung","Optimieren der Leistung durch selektive Zustandsauswahl"],"pt":["Criação de lojas de estado mínimas para componentes React","Gerenciamento de estado global sem aninhamento de provedor","Otimização do desempenho com seleção de estado seletiva"],"ru":["Создание минимальных хранилищ состояния для компонентов React","Управление глобальным состоянием без вложения провайдера","Оптимизация производительности с помощью выборочной выборки состояния"],"ar":["إنشاء مخازن حالة tối thiểu لمكونات React","إدارة الحالة العالمية دون تضمين المزود","تحسين الأداء باستخدام اختيار الحالة التحديدية"]},"limitations":{"en":["React ecosystem dependency","Requires Zustand library installation","TypeScript interface definition needed"],"zh":["React生态系统依赖","需要Zustand库安装","需要TypeScript接口定义"],"ja":["Reactエコシステムへの依存","Zustandライブラリのインストールが必要","TypeScriptインターフェース定義が必要"],"ko":["React 생태계 의존성","Zustand 라이브러리 설치 필요","TypeScript 인터페이스 정의 필요"],"es":["Dependencia del ecosistema React","Requiere la instalación de la librería Zustand","Necesaria la definición de la interfaz de TypeScript"],"fr":["Dépendance à l''écosystème React","Requiert l''installation de la bibliothèque Zustand","Définition de l''interface TypeScript nécessaire"],"de":["Abhängigkeit vom React-Ökosystem","Erfordert die Installation der Zustand-Bibliothek","TypeScript Interface-Definition erforderlich"],"pt":["Dependência do ecossistema React","Requer instalação da biblioteca Zustand","Necessidade de definição de interface TypeScript"],"ru":["Зависимость от экосистемы React","Требуется установка библиотеки Zustand","Необходимо определение интерфейса TypeScript"],"ar":["اعتماد نظام بيئة React","يتطلب تثبيت مكتبة Zustand","الحاجة إلى تعريف واجهة TypeScript"]},"version":4},"contentHash":"82e215e941ba790c120e7710629f5b655edb0ff65bbc8c88a658506316d0b9af","qualityScore":33}');
