INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arkanwolfshade/MythosMUD/mythosmud-logging-standards', 'mythosmud-logging-standards', 'arkanwolfshade', 'MythosMUD', 'community', 'mythosmud-logging-standards arkanwolfshade MythosMUD community MythosMUD logging standards provide a text-based, browser-accessible Multi-User Dungeon inspired by the Cthulhu Mythos, benefiting developers with structured logging capabilities. MythosMUD Logging Standards 提供了一种结构化的日志记录方式，使用关键字参数和项目日志器 MythosMUD ロギング標準は、構造化ログレコードを実現するためのキーワード引数とプロジェクトロガーを使用します MythosMUD 로깅 표준은 키워드 매개 변수와 프로젝트 로거를 사용하여 구조화된 로그 기록을 제공합니다 MythosMUD Logging Standards es un conjunto de reglas para la gestión de registros en proyectos de MUD. Utiliza Python y estructuras de registro estructuradas. MythosMUD Logging Standards est un ensemble de règles pour la gestion des journaux dans les projets de MUD. Il utilise Python et des structures de journalisation structurées. MythosMUD-Logging-Standards ist ein Satz von Regeln für die Protokollierung in MUD-Projekten. Es verwendet Python und strukturierte Protokollstrukturen. O MythosMUD Logging Standards é um conjunto de diretrizes para registro de logs em jogos de MUD, inspirado no Cthulhu Mythos. MythosMUD Logging Standards - это набор руководств для регистрации логов в МУД-играх, вдохновлённый Ктулху Мифосом и использующий ИИ Агенты معايير تسجيل MythosMUD هي مجموعة من الإرشادات لتسجيل السجلات في ألعاب المногلاتر، مستوحاة من ميثوس كثولو how to use mythosmud-logging-standards mythosmud-logging-standards setup guide structured logging in MythosMUD mythosmud-logging-standards alternative mythosmud-logging-standards vs logging.getLogger mythosmud-logging-standards install MythosMUD Logging Standards 结构化日志记录 关键字参数 项目日志器 Python 日志记录 AIエージェント 日志记录最佳实践 Uses the project logger from server.logging.enhanced_logging_config Supports structured logging with keyword arguments Passes data as key-value pairs for logging Avoids use of f-strings and deprecated context parameter Imports logger using get_logger from enhanced_logging_config mythosmud-logging-standards is a set of guidelines for implementing structured logging in MythosMUD using keyword arguments and the project logger.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wyc7758775/aglie-person-manage/product-requirements-guide', 'community', 'wyc7758775', 'aglie-person-manage', 'wyc7758775/aglie-person-manage', 'product-requirements-guide', 0, 0, 33, '2026-03-08T01:57:15.475Z', '2026-03-08T02:09:45.092Z', '69d20c5b8fa97c3f5aa4a58b4a0ffe140b8a525327cc1ae5a483e0a18b376c99', '{"id":"wyc7758775/aglie-person-manage/product-requirements-guide","name":"product-requirements-guide","description":{"en":"The product-requirements-guide skill assists developers in producing detailed product design documents through structured Q&A sessions, saving them in a `product-designs/` folder.","zh":"产品需求文档指导是用于生成详细、可执行的产品需求文档的工具，包括结构化问答和文件夹规范","ja":"プロダクト要件ガイドは、詳細なプロダクト要件文書を生成するためのツールであり、構造化された質問とフォルダ規則を含む","ko":"제품 요구 사항 가이드는 상세한 제품 요구 사항 문서를 생성하기 위한 도구로 구조화된 질문과 폴더 규칙을 포함합니다","es":"Product-requirements-guide es una habilidad que genera documentación de requisitos de producto estructurada y detallada mediante un proceso de preguntas y respuestas","fr":"Product-requirements-guide est une compétence qui génère une documentation structurée et détaillée des exigences de produit via un processus de questions et réponses","de":"Product-requirements-guide ist eine Fähigkeit, die strukturierte und detaillierte Produktanforderungsdokumentation durch einen Frage- und Antwortprozess generiert","pt":"O guia de requisitos de produto é uma ferramenta de IA que ajuda a esclarecer demandas e produzir documentos detalhados e executáveis. Ele utiliza uma abordagem de perguntas e respostas estruturadas para garantir que todos os requisitos sejam considerados.","ru":"Руководство по требованиям продукта - это инструмент ИИ, который помогает прояснить требования и производить подробные и исполняемые документы. Он использует структурированный подход вопросов и ответов для обеспечения того, чтобы все требования были учтены.","ar":"دليل متطلبات المنتج هو أداة ذكاء اصطناعي تساعد على توضيح المتطلبات وإنتاج وثائق مفصلة وقابلة للتنفيذ. يستخدم نهجًا من الأسئلة والأجوبة المنظمة لضمان أخذ جميع المتطلبات في الاعتبار."},"seo":{"title":{"en":"product-requirements-guide: Structured Product Design Set...","zh":"产品需求文档指导 Setup Guide","ja":"AIエージェントによるプロダクト要件ガイド Setup Guide","ko":"AI 도구를 사용한 제품 요구 사항 가이드 Setup Guide","es":"Guía de configuración para product-requirements-guide","fr":"Guide de mise en place pour product-requirements-guide","de":"Einrichtungsleitfaden für product-requirements-guide","pt":"Guia de Configuração de Requisitos de Produto com Ferrame...","ru":"Настройка Руководства по Требованиям Продукта с ИИ Агентами","ar":"دليل إعداد متطلبات المنتج باستخدام أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to create detailed product requirements documents with our AI agent skill, featuring interactive demand clarification and automated document gen...","zh":"使用产品需求文档指导生成详细、可执行的产品需求文档，包括结构化问答和文件夹规范","ja":"AIエージェントを使用して詳細なプロダクト要件文書を生成し、構造化された質問とフォルダ規則を含む","ko":"AI 도구를 사용하여詳細한 제품 요구 사항 문서를 생성하고 구조화된 질문과 폴더 규칙을 포함합니다","es":"Descubre cómo utilizar product-requirements-guide para generar documentación de requisitos de producto detallada y ejecutable con Herramientas de Inteligenci...","fr":"Découvrez comment utiliser product-requirements-guide pour générer une documentation détaillée et exécutable des exigences de produit avec des Outils d''Intel...","de":"Erfahren Sie, wie Sie product-requirements-guide verwenden, um detaillierte und ausführbare Produktanforderungsdokumentation mit KI-Tools zu erstellen","pt":"Aprenda a configurar o guia de requisitos de produto com ferramentas de IA para melhorar a colaboração e a clareza nos projetos de desenvolvimento","ru":"Узнайте, как настроить руководство по требованиям продукта с ИИ агентами для улучшения сотрудничества и ясности в проектах разработки","ar":"تعرف على كيفية إعداد دليل متطلبات المنتج باستخدام أدوات الذكاء الاصطناعي لتحسين التعاون ووضوح المشاريع التطويرية"},"definition":{"en":"product-requirements-guide is a skill that generates detailed, executable product requirements documents through interactive demand clarification with users.","zh":"产品需求文档指导是指使用结构化问答和文件夹规范生成详细、可执行的产品需求文档的过程","ja":"プロダクト要件ガイドとは、構造化された質問とフォルダ規則を使用して詳細なプロダクト要件文書を生成するプロセス","ko":"제품 요구 사항 가이드는 구조화된 질문과 폴더 규칙을 사용하여 상세한 제품 요구 사항 문서를 생성하는 과정입니다","es":"Product-requirements-guide es una herramienta de inteligencia artificial que ayuda a los desarrolladores a crear documentación de requisitos de producto detallada","fr":"Product-requirements-guide est un outil d''intelligence artificielle qui aide les développeurs à créer une documentation détaillée des exigences de produit","de":"Product-requirements-guide ist ein KI-Tool, das Entwicklern hilft, detaillierte Produktanforderungsdokumentation zu erstellen","pt":"O que é um guia de requisitos de produto? É uma ferramenta de IA que auxilia na criação de documentos de requisitos de produto detalhados e executáveis.","ru":"Что такое руководство по требованиям продукта? Это инструмент ИИ, который помогает в создании подробных и исполняемых документов требований продукта.","ar":"ما هو دليل متطلبات المنتج؟ هو أداة ذكاء اصطناعي تساعد في إنشاء وثائق متطلبات المنتج المفصلة والقابلة للتنفيذ."},"features":{"en":["Generates product requirements documents in Markdown format (`prd.md`)","Supports i18n documentation with separate files (`i18n.md`)","Organizes documents in a structured folder hierarchy (`product-designs/{需求名}-{YYYYMMDD}/`)","Follows a strict file naming convention for easy identification","Creates folders and files automatically if they do not exist"],"zh":["结构化问答引导用户厘清需求","生成详细、可执行的产品需求文档","文件夹规范：每个需求单独一个文件夹，命名格式为 {需求名}-{YYYYMMDD}","支持多语言，包括中文、英文等","交互式需求澄清，遇到不确定项时向开发提问"],"ja":["構造化された質問によってユーザーが要件を明確化","詳細なプロダクト要件文書を生成","フォルダ規則：各要件ごとに個別のフォルダを作成、命名形式は {要件名}-{YYYYMMDD}","多言語対応、中国語、英語など","インタラクティブな要件明確化、不確実な項目について開発者に質問"],"ko":["구조화된 질문을 통해 사용자가 요구 사항을 명확히 함","상세한 제품 요구 사항 문서를 생성함","폴더 규칙: 각 요구 사항마다 별도의 폴더를 생성하고 이름 형식은 {요구 사항 이름}-{YYYYMMDD}","다중 언어 지원, 중국어, 영어 등","대화형 요구 사항 명확화, 불확실한 항목에 대해 개발자에게 질문"],"es":["Generación de documentación de requisitos de producto en Markdown","Creación de carpetas y archivos con nombres y fechas personalizados","Soporte para i18n y traducciones","Proceso de preguntas y respuestas para clarificar requisitos","Almacenamiento de documentos en el directorio raíz del proyecto"],"fr":["Génération de documentation d''exigences de produit au format Markdown","Création de dossiers et de fichiers avec des noms et des dates personnalisés","Prise en charge de l''i18n et des traductions","Processus de questions et réponses pour clarifier les exigences","Stockage des documents dans le répertoire racine du projet"],"de":["Erstellung von Produktanforderungsdokumentation im Markdown-Format","Erstellung von Ordnern und Dateien mit benutzerdefinierten Namen und Datum","Unterstützung für i18n und Übersetzungen","Frage- und Antwortprozess zur Klärung von Anforderungen","Speicherung von Dokumenten im Stammverzeichnis des Projekts"],"pt":["Geração de documentos de requisitos de produto em formato Markdown","Organização de pastas e arquivos de acordo com um padrão pré-definido","Uso de perguntas e respostas estruturadas para esclarecer demandas","Capacidade de criar documentos de requisitos de produto personalizados","Integração com ferramentas de desenvolvimento para melhorar a colaboração"],"ru":["Генерация документов требований продукта в формате Markdown","Организация папок и файлов в соответствии с предварительно определенным стандартом","Использование структурированных вопросов и ответов для прояснения требований","Возможность создания индивидуальных документов требований продукта","Интеграция с инструментами разработки для улучшения сотрудничества"],"ar":["إنشاء وثائق متطلبات المنتج بصيغة Markdown","تنظيم المجلدات والملفات وفقًا لمعيار محدد مسبقًا","استخدام الأسئلة والأجوبة المنظمة لتوضيح المتطلبات","قدرة على إنشاء وثائق متطلبات المنتج المخصصة","التكامل مع أدوات التطوير لتحسين التعاون"]},"keywords":{"en":["how to use product-requirements-guide","product-requirements-guide setup guide","product-requirements-guide alternative","product-requirements-guide vs prd tools","product-requirements-guide install","what is product-requirements-guide","product-requirements-guide documentation","product-requirements-guide tutorial","product-requirements-guide best practices"],"zh":["产品需求文档指导","结构化问答","文件夹规范","多语言支持","交互式需求澄清","AI工具","产品经理","需求文档","项目管理"],"ja":["プロダクト要件ガイド","構造化された質問","フォルダ規則","多言語対応","インタラクティブな要件明確化","AIエージェント","プロダクトマネージャー","要件文書","プロジェクトマネジメント"],"ko":["제품 요구 사항 가이드","구조화된 질문","폴더 규칙","다중 언어 지원","대화형 요구 사항 명확화","AI 도구","제품 매니저","요구 사항 문서","프로젝트 관리"],"es":["product-requirements-guide","documentación de requisitos de producto","Herramientas de Inteligencia Artificial","generación de documentación","i18n","traducciones","desarrollo de software","gestión de proyectos"],"fr":["product-requirements-guide","documentation d''exigences de produit","Outils d''Intelligence Artificielle","génération de documentation","i18n","traductions","développement de logiciels","gestion de projets"],"de":["product-requirements-guide","Produktanforderungsdokumentation","KI-Tools","Erstellung von Dokumentation","i18n","Übersetzungen","Softwareentwicklung","Projektmanagement"],"pt":["guia de requisitos de produto","ferramentas de IA para desenvolvimento","documentos de requisitos de produto","colaboração em desenvolvimento","desenvolvimento de software","requisitos de produto","IA para desenvolvimento","ferramentas de desenvolvimento"],"ru":["руководство по требованиям продукта","инструменты ИИ для разработки","документы требований продукта","сотрудничество в разработке","разработка программного обеспечения","требования продукта","ИИ для разработки","инструменты разработки"],"ar":["دليل متطلبات المنتج","أدوات الذكاء الاصطناعي لتطوير البرمجيات","وثائق متطلبات المنتج","التعاون في التطوير","تطوير البرمجيات","متطلبات المنتج","الذكاء الاصطناعي لتطوير البرمجيات","أدوات التطوير"]}},"owner":"wyc7758775","repo":"aglie-person-manage","repoPath":"wyc7758775/aglie-person-manage","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.475Z","topics":[],"category":"community","skillMd":{"name":"product-requirements-guide","description":"以资深产品经理身份指导用户完成详细清晰的产品需求文档（PRD）、交互逻辑说明及 i18n 国际化翻译文档。PRD 含墨刀原型链接、交互逻辑表（状态/校验/边界），供前后端开发使用。适用于产品规划、需求梳理、功能设计、交互逻辑、i18n 翻译或用户提及 PRD、产品需求、产品设计稿、墨刀、国际化时。","bodyPreview":"# 产品需求文档指导\n\n## 角色定位\n\n以**资深产品经理**身份与用户协作，通过结构化问答引导用户厘清需求，产出详细、可执行的产品需求文档。\n\n## 输出位置\n\n所有生成的文档保存至项目根目录下的 **`product-designs/`** 文件夹（产品设计稿）。\n\n**文件夹规范**：每个需求单独一个文件夹，命名格式为 `{需求名}-{YYYYMMDD}`。\n\n- 路径：`{项目根目录}/product-designs/{需求名}-{YYYYMMDD}/`\n- 需求名：使用用户当前语言（如中文「项目管理增强」、英文「project-management-enhancement」）\n- 日期：创建需求时的年月日，格式 `YYYYMMDD`，如 `20260131`\n- 若文件夹不存在，先创建再写入\n\n**文件命名**（位于需求文件夹内）：\n- PRD：`prd.md`\n- i18n：`i18n.md`\n\n## 工作流程\n\n### 1. 交互式需求澄清（先问后写）\n\n**原则**：遇到不确定、有歧义或需开发决策的项，**不猜测**，而是**向开发提问**，并提供可选项，让开发通过*","body":"# 产品需求文档指导\n\n## 角色定位\n\n以**资深产品经理**身份与用户协作，通过结构化问答引导用户厘清需求，产出详细、可执行的产品需求文档。\n\n## 输出位置\n\n所有生成的文档保存至项目根目录下的 **`product-designs/`** 文件夹（产品设计稿）。\n\n**文件夹规范**：每个需求单独一个文件夹，命名格式为 `{需求名}-{YYYYMMDD}`。\n\n- 路径：`{项目根目录}/product-designs/{需求名}-{YYYYMMDD}/`\n- 需求名：使用用户当前语言（如中文「项目管理增强」、英文「project-management-enhancement」）\n- 日期：创建需求时的年月日，格式 `YYYYMMDD`，如 `20260131`\n- 若文件夹不存在，先创建再写入\n\n**文件命名**（位于需求文件夹内）：\n- PRD：`prd.md`\n- i18n：`i18n.md`\n\n## 工作流程\n\n### 1. 交互式需求澄清（先问后写）\n\n**原则**：遇到不确定、有歧义或需开发决策的项，**不猜测**，而是**向开发提问**，并提供可选项，让开发通过**选择或输入**完成全部文案。\n\n**提问格式**：每次提问时，按以下格式呈现：\n\n```\n【问题】[简短说明问题]\n\n请选择或输入：\n1. [选项 A]\n2. [选项 B]\n3. [选项 C]\n4. 其他（请直接输入你的答案）\n\n回复数字（如 1）或直接输入即可。\n```\n\n**可选项设计**：\n- 提供 2–5 个常见选项，覆盖典型场景\n- 最后一项固定为「其他（请直接输入你的答案）」，支持自定义\n- 开发可回复数字（如 `1`）快速选择，或直接输入文案\n- 若开发回复「1」或「2」，则采用对应选项的文案；若输入其他内容，则采用其输入\n\n**提问时机**（以下情况必须提问）：\n- 产品/功能背景、核心目标、范围边界不明确\n- 功能优先级、用户角色、成功标准有歧义\n- 交互逻辑、校验规则、异常处理需开发确认\n- 墨刀原型、i18n 文案等需开发提供或选择\n\n**提问节奏**：可一次提出 1–3 个相关问题，每个问题都提供可选项；待开发回复后再继续，避免一次问太多。\n\n### 2. 文档生成\n\n根据澄清结果，按 [template.md](template.md) 结构生成完整 PRD，确保：\n\n- 信息完整、逻辑清晰\n- 使用中文撰写\n- 用户故事包含「作为…我希望…以便…」格式\n- 验收标准可测试、可量化\n\n### 3. 保存与确认\n\n- 创建需求文件夹：`product-designs/{需求名}-{YYYYMMDD}/`（日期为创建当天）\n- 写入 PRD：`product-designs/{需求名}-{YYYYMMDD}/prd.md`\n- 向用户说明文件路径和文档概要\n- 询问是否需要补充或修改\n\n### 4. i18n 翻译文档（可选）\n\n当 PRD 涉及界面交互文案时，可生成配套的 i18n 国际化翻译文档，供开发使用。\n\n**触发**：PRD 中包含按钮、标签、提示、表单字段等界面文案时，主动询问或应要求生成 i18n 文档。\n\n**流程**：\n1. 从 PRD 中提取所有界面相关文案（按钮、标签、提示、占位符、错误信息等）\n2. 按 [i18n-template.md](i18n-template.md) 格式生成翻译表\n3. 保存至 `product-designs/{需求名}-{YYYYMMDD}/i18n.md`（与 PRD 同目录）\n\n**Key 规范**：`模块.自定义key`，如 `project.name`、`project.form.submit`。模块名与 PRD 功能模块对应，key 使用 camelCase。\n\n**语言**：中文（zh）、英文（en）、日文（ja），三列并排。\n\n**生成原则**：以 PRD 为背景上下文，确保翻译与产品语义一致；英文、日文需符合各语言习惯，非逐字直译。\n\n## PRD 核心结构\n\n| 章节 | 说明 | 面向 |\n|------|------|------|\n| 文档信息 | 版本、作者、更新日期 | 全员 |\n| 背景与目标 | 问题、机会、目标、成功指标 | 全员 |\n| 用户与场景 | 目标用户、使用场景、用户故事 | 全员 |\n| 功能需求 | 功能列表、优先级、详细描述 | 前后端 |\n| **交互逻辑** | 墨刀链接、交互表、校验规则 | **前端** |\n| 非功能需求 | 性能、安全、兼容性等 | 前后端 |\n| 验收标准 | 可测试的完成条件 | 全员 |\n| 范围与排期 | 本期/下期、里程碑 | 全员 |\n\n**交互逻辑与墨刀**：墨刀负责视觉与主流程，PRD 的「交互逻辑」章节补充状态变化、校验规则、异常/边界处理，供前端实现。详见 [interaction-logic-template.md](interaction-logic-template.md)。\n\n完整模板见 [template.md](template.md)。\n\n## i18n 翻译文档规范\n\n| 项目 | 说明 |\n|------|------|\n| Key 格式 | `模块.自定义key`，如 `project.name`、`auth.login.submit` |\n| 语言 | 中文、英文、日文（三列） |\n| 来源 | 从 PRD 功能描述、用户流程、验收标准中提取界面文案 |\n| 输出 | `product-designs/{需求名}-{YYYYMMDD}/i18n.md` |\n\n完整模板见 [i18n-template.md](i18n-template.md)。\n\n## 交互原则\n\n- **引导而非代劳**：通过提问帮助用户理清思路\n- **有疑必问**：不确定时不猜测，向开发提问并提供可选项\n- **选择或输入**：每次提问提供 2–5 个选项 +「其他（请直接输入）」，开发可回复数字选择或直接输入\n- **结构化输出**：PRD 使用统一模板，便于评审和落地\n- **迭代优化**：支持根据反馈补充和修订文档\n- **i18n 配套**：PRD 含界面文案时，主动提示可生成 i18n 翻译文档\n"},"lastSynced":"2026-03-08T02:09:45.092Z","agentAnalysis":{"suitability":{"en":"Perfect for Development Agents needing structured product design documentation through Q&A sessions.","zh":"非常适合需要通过问答环节获取结构化产品设计文档的开发代理","ja":"開発エージェントがQ&Aセッションを通じて構造化された製品設計文書を必要とする場合に最適","ko":"개발 에이전트가 Q&A 세션을 통해 구조화된 제품 디자인 문서를 필요로 하는 경우에 적합","es":"Perfecto para agentes de desarrollo que necesitan documentación de diseño de productos estructurada a través de sesiones de preguntas y respuestas.","fr":"Parfait pour les agents de développement ayant besoin d''une documentation de conception de produits structurée à travers des sessions de questions et réponses.","de":"Perfekt für Entwicklungsmittel, die eine strukturierte Produkt-Design-Dokumentation durch Q&A-Sitzungen benötigen.","pt":"Perfeito para Agentes de Desenvolvimento que necessitam de documentação de design de produto estruturada por meio de sessões de Perguntas e Respostas.","ru":"Идеально подходит для агентов разработки, которым необходима структурированная документация по проектированию продукта через сессии вопросов и ответов.","ar":"مثالي لعميل التطوير الذين يحتاجون إلى توثيق تصميم المنتج المنظم من خلال جلسات الأسئلة والإجابات."},"recommendation":{"en":"Empowers agents to generate detailed product requirements documents in Markdown format, utilizing a structured folder and file naming convention, and saving them in a `product-designs/` directory with files such as `prd.md` and `i18n.md`.","zh":"使代理能够生成详细的产品需求文档，以Markdown格式保存，利用结构化的文件夹和文件命名约定，并将其保存在`product-designs/`目录中，文件如`prd.md`和`i18n.md`","ja":"エージェントが詳細な製品要件文書をMarkdown形式で生成できるようにし、構造化されたフォルダとファイル命名規約を利用し、`product-designs/`ディレクトリにファイルを保存します。例：`prd.md`および`i18n.md`","ko":"에이전트가 상세한 제품 요구 사항 문서를 Markdown 형식으로 생성할 수 있도록 하며, 구조화된 폴더 및 파일 이름 규칙을 사용하여 `product-designs/` 디렉토리에 파일을 저장합니다. 예: `prd.md` 및 `i18n.md`","es":"Habilita a los agentes a generar documentos de requisitos de productos detallados en formato Markdown, utilizando una convención de nombre de carpeta y archivo estructurada, y guardándolos en un directorio `product-designs/` con archivos como `prd.md` y `i18n.md`.","fr":"Permet aux agents de générer des documents de spécifications de produits détaillés au format Markdown, en utilisant une convention de nom de dossier et de fichier structurée, et en les sauvegardant dans un répertoire `product-designs/` avec des fichiers tels que `prd.md` et `i18n.md`.","de":"Ermöglicht es den Agenten, detaillierte Produktanforderungsdokumente im Markdown-Format zu generieren, indem sie eine strukturierte Ordner- und Dateinamenskonvention verwenden und sie in einem Verzeichnis `product-designs/` mit Dateien wie `prd.md` und `i18n.md` speichern.","pt":"Permite que os agentes gerem documentos detalhados de requisitos de produto no formato Markdown, utilizando uma convenção de nomeação de pastas e arquivos estruturada, e os salvem em um diretório `product-designs/` com arquivos como `prd.md` e `i18n.md`.","ru":"Позволяет агентам создавать подробные документы требований к продукту в формате Markdown, используя структурированную конвенцию именования папок и файлов, и сохранять их в директории `product-designs/` с файлами типа `prd.md` и `i18n.md`.","ar":"تمكن الوكلاء من إنشاء مستندات متفصلة لمتطلبات المنتج بصيغة Markdown، باستخدام اتفاقية تسمية مجلدات ومستندات منضبة، وحفظها في مجلد `product-designs/` مع الملفات مثل `prd.md` و `i18n.md`."},"useCases":{"en":["Automating product design document creation through interactive Q&A sessions","Generating detailed product requirements documents with standardized naming conventions","Organizing product designs in a structured folder hierarchy"],"zh":["通过交互式Q&A环节自动创建产品设计文档","使用标准化的命名约定生成详细的产品需求文档","在结构化的文件夹层次中组织产品设计"],"ja":["対話式Q&Aセッションを通じて製品設計文書の作成を自動化","標準化された命名規約を使用して詳細な製品要件文書を生成","構造化されたフォルダ階層で製品設計を整理"],"ko":["대화형 Q&A 세션을 통해 제품 디자인 문서의 생성을 자동화","표준화된 이름 규칙을 사용하여 상세한 제품 요구 사항 문서를 생성","구조화된 폴더 계층에서 제품 디자인을 조직"],"es":["Automatización de la creación de documentos de diseño de productos a través de sesiones de preguntas y respuestas interactivas","Generación de documentos de requisitos de productos detallados con convenciones de nombre estandarizadas","Organización de diseños de productos en una jerarquía de carpetas estructurada"],"fr":["Automatisation de la création de documents de conception de produits à travers des sessions de questions et réponses interactives","Génération de documents de spécifications de produits détaillés avec des conventions de nommage standardisées","Organisation des conceptions de produits dans une hiérarchie de dossiers structurée"],"de":["Automatisierung der Erstellung von Produkt-Design-Dokumenten durch interaktive Q&A-Sitzungen","Generierung detaillierter Produktanforderungsdokumente mit standardisierten Namenskonventionen","Organisation von Produkt-Designs in einer strukturierten Ordnungshierarchie"],"pt":["Automatizar a criação de documentos de design de produto por meio de sessões interativas de Perguntas e Respostas","Gerar documentos detalhados de requisitos de produto com convenções de nomeação padronizadas","Organizar designs de produto em uma hierarquia de pastas estruturada"],"ru":["Автоматизировать создание документов по проектированию продукта через интерактивные сессии вопросов и ответов","Генерировать подробные документы требований к продукту со стандартизированными конвенциями именования","Организовывать проекты продукта в структурированной иерархии папок"],"ar":["توفير автомاتي لإنشاء مستندات تصميم المنتج من خلال جلسات تفاعلية من الأسئلة والإجابات","إنشاء مستندات متفصلة لمتطلبات المنتج باتفاقيات تسمية معيارية","تنظيم تصاميم المنتج في هرمية مجلدات منضبة"]},"limitations":{"en":["Requires file system access to save documents","Limited to generating documents in Markdown format","Dependent on user input for Q&A sessions"],"zh":["需要文件系统访问权限来保存文档","仅限生成Markdown格式的文档","依赖于用户的输入进行Q&A环节"],"ja":["文書を保存するためにファイルシステムへのアクセスが必要","Markdown形式の文書の生成のみ","Q&Aセッションのためにユーザーの入力に依存"],"ko":["문서를 저장하려면 파일 시스템에 액세스할 수 있어야 함","Markdown 형식의 문서만 생성","Q&A 세션을 위해 사용자의 입력에 의존"],"es":["Requiere acceso al sistema de archivos para guardar documentos","Limitado a la generación de documentos en formato Markdown","Dependiente de la entrada del usuario para sesiones de preguntas y respuestas"],"fr":["Nécessite un accès au système de fichiers pour enregistrer des documents","Limité à la génération de documents au format Markdown","Dépendant de la saisie de l''utilisateur pour les sessions de questions et réponses"],"de":["Benötigt Zugriff auf das Dateisystem, um Dokumente zu speichern","Begrenzt auf die Generierung von Dokumenten im Markdown-Format","Abhängig von der Benutzereingabe für Q&A-Sitzungen"],"pt":["Requer acesso ao sistema de arquivos para salvar documentos","Limitado a gerar documentos no formato Markdown","Dependente da entrada do usuário para sessões de Perguntas e Respostas"],"ru":["Требует доступа к файловой системе для сохранения документов","Ограничен генерацией документов только в формате Markdown","Зависит от ввода пользователя для сессий вопросов и ответов"],"ar":["يتطلب الوصول إلى نظام الملفات لحفظ المستندات","محدود بإنشاء مستندات بصيغة Markdown فقط","يعتمد على إدخال المستخدم لجلسات الأسئلة والإجابات"]},"version":4},"contentHash":"69d20c5b8fa97c3f5aa4a58b4a0ffe140b8a525327cc1ae5a483e0a18b376c99","qualityScore":33}');
