INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wyc7758775/aglie-person-manage/product-requirements-guide', 'product-requirements-guide', 'wyc7758775', 'aglie-person-manage', 'community', 'product-requirements-guide wyc7758775 aglie-person-manage community The product-requirements-guide skill assists developers in producing detailed product design documents through structured Q&A sessions, saving them in a `product-designs/` folder. 产品需求文档指导是用于生成详细、可执行的产品需求文档的工具，包括结构化问答和文件夹规范 プロダクト要件ガイドは、詳細なプロダクト要件文書を生成するためのツールであり、構造化された質問とフォルダ規則を含む 제품 요구 사항 가이드는 상세한 제품 요구 사항 문서를 생성하기 위한 도구로 구조화된 질문과 폴더 규칙을 포함합니다 Product-requirements-guide es una habilidad que genera documentación de requisitos de producto estructurada y detallada mediante un proceso de preguntas y respuestas Product-requirements-guide est une compétence qui génère une documentation structurée et détaillée des exigences de produit via un processus de questions et réponses Product-requirements-guide ist eine Fähigkeit, die strukturierte und detaillierte Produktanforderungsdokumentation durch einen Frage- und Antwortprozess generiert O guia de requisitos de produto é uma ferramenta de IA que ajuda a esclarecer demandas e produzir documentos detalhados e executáveis. Ele utiliza uma abordagem de perguntas e respostas estruturadas para garantir que todos os requisitos sejam considerados. Руководство по требованиям продукта - это инструмент ИИ, который помогает прояснить требования и производить подробные и исполняемые документы. Он использует структурированный подход вопросов и ответов для обеспечения того, чтобы все требования были учтены. دليل متطلبات المنتج هو أداة ذكاء اصطناعي تساعد على توضيح المتطلبات وإنتاج وثائق مفصلة وقابلة للتنفيذ. يستخدم نهجًا من الأسئلة والأجوبة المنظمة لضمان أخذ جميع المتطلبات في الاعتبار. how to use product-requirements-guide product-requirements-guide setup guide product-requirements-guide alternative product-requirements-guide vs prd tools product-requirements-guide install what is product-requirements-guide product-requirements-guide documentation product-requirements-guide tutorial product-requirements-guide best practices 产品需求文档指导 结构化问答 文件夹规范 多语言支持 交互式需求澄清 AI工具 产品经理 需求文档 项目管理 Generates product requirements documents in Markdown format (`prd.md`) Supports i18n documentation with separate files (`i18n.md`) Organizes documents in a structured folder hierarchy (`product-designs/{需求名}-{YYYYMMDD}/`) Follows a strict file naming convention for easy identification Creates folders and files automatically if they do not exist product-requirements-guide is a skill that generates detailed, executable product requirements documents through interactive demand clarification with users.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('8dazo/elix-db/vector-db-storage', 'community', '8dazo', 'elix-db', '8dazo/elix-db', 'vector-db-storage', 0, 0, 33, '2026-03-08T01:57:15.476Z', '2026-03-08T02:09:48.017Z', 'f9a6ceeb56667990440cda9259f0ea248e9869fed8d2b0ca10b1b65c5af02620', '{"id":"8dazo/elix-db/vector-db-storage","name":"vector-db-storage","description":{"en":"The vector-db-storage skill provides storage solutions for AI agents, supporting various backends like ETS, File, PostgreSQL, and Qdrant. It benefits developers working with vector databases and indexing.","zh":"向量数据库存储提供多种后端选项，包括ETS、File、PostgreSQL + pgvector和Qdrant（客户端），满足不同场景的需求","ja":"ベクトルDBストレージは、ETS、File、PostgreSQL + pgvector、Qdrant（クライアント）などの複数のバックエンドオプションを提供し、さまざまなシナリオに適応","ko":"벡터 데이터베이스 저장소는 다양한 백엔드 옵션을 제공합니다. ETS, File, PostgreSQL + pgvector 및 Qdrant(클라이언트)을 포함하여 다양한 시나리오에 적합","es":"El almacenamiento de Vector DB permite a los desarrolladores almacenar y recuperar vectores de manera eficiente. Soporta backends como ETS, File, PostgreSQL y Qdrant","fr":"Le stockage Vectoriel DB permet aux développeurs de stocker et de récupérer des vecteurs de manière efficace. Il prend en charge les backends tels que ETS, File, PostgreSQL et Qdrant","de":"Die Speicherung von Vektor-DB ermöglicht es Entwicklern, Vektoren effizient zu speichern und abzurufen. Es unterstützt Backends wie ETS, File, PostgreSQL und Qdrant","pt":"O armazenamento de banco de dados vetorial é uma solução para armazenar e indexar grandes conjuntos de dados vetoriais","ru":"Хранилище векторной базы данных - это решение для хранения и индексирования больших наборов векторных данных","ar":"مخزن قاعدة البيانات المتجه هو حل لتخزين وفهرسة مجموعات كبيرة من البيانات المتجهة"},"seo":{"title":{"en":"vector-db-storage: Storage Solutions for AI Agents | AI A...","zh":"向量数据库存储设置指南 - AIエージェント","ja":"ベクトルDBストレージベストプラクティス - AIエージェント","ko":"벡터 데이터베이스 저장소 설정 가이드 - AI 도구","es":"Guía de Configuración de Almacenamiento de Vector DB","fr":"Guide d''Installation de Stockage Vectoriel DB","de":"Einrichtungsleitfaden für Vektor-DB-Speicherung","pt":"Guia de Configuração de Armazenamento de Banco de Dados V...","ru":"Настройка Хранилища Векторной Базы Данных: Лучшие Практики","ar":"دليل إعداد مخزن قاعدة البيانات المتجه"},"description":{"en":"Explore vector-db-storage for efficient data management. Learn how to choose the right storage backend for your AI projects and optimize performance.","zh":"了解向量数据库存储的技术细节，包括ETS、File、PostgreSQL + pgvector和Qdrant（客户端）后端","ja":"ベクトルDBストレージのテクニカル詳細を学び、ETS、File、PostgreSQL + pgvector、Qdrant（クライアント）バックエンドについて","ko":"벡터 데이터베이스 저장소의 기술적 세부 정보를 알아보세요. ETS, File, PostgreSQL + pgvector 및 Qdrant(클라이언트) 백엔드","es":"Aprende a configurar el almacenamiento de Vector DB para tus proyectos de desarrollo con ETS, File, PostgreSQL y Qdrant","fr":"Découvrez comment configurer le stockage Vectoriel DB pour vos projets de développement avec ETS, File, PostgreSQL et Qdrant","de":"Erfahren Sie, wie Sie den Speicher von Vektor-DB für Ihre Entwicklungsprojekte mit ETS, File, PostgreSQL und Qdrant einrichten","pt":"Aprenda a configurar o armazenamento de banco de dados vetorial com opções como ETS, File, PostgreSQL e Qdrant","ru":"Узнайте, как настроить хранилище векторной базы данных с помощью ETS, File, PostgreSQL и Qdrant","ar":"تعرف على كيفية إعداد مخزن قاعدة البيانات المتجه مع خيارات مثل ETS و File و PostgreSQL و Qdrant"},"definition":{"en":"vector-db-storage is a skill that enables efficient storage and indexing of vector data, supporting multiple storage backends and persistence options.","zh":"向量数据库存储是一种用于存储和索引向量数据的技术，支持多种后端","ja":"ベクトルDBストレージは、ベクトルデータをストアしてインデックスするためのテクノロジーであり、複数のバックエンドをサポート","ko":"벡터 데이터베이스 저장소는 벡터 데이터를 저장하고 색인하기 위한 기술로, 여러 백엔드를 지원","es":"El almacenamiento de Vector DB es un sistema de almacenamiento de vectores que soporta varios backends para la persistencia y escalabilidad","fr":"Le stockage Vectoriel DB est un système de stockage de vecteurs qui prend en charge plusieurs backends pour la persistance et la scalabilité","de":"Die Speicherung von Vektor-DB ist ein Speichersystem für Vektoren, das mehrere Backends für die Persistenz und Skalierbarkeit unterstützt","pt":"Armazenamento de banco de dados vetorial é uma tecnologia para armazenar e recuperar dados vetoriais de forma eficiente","ru":"Хранилище векторной базы данных - это технология для хранения и извлечения векторных данных в эффективной форме","ar":"مخزن قاعدة البيانات المتجه هو تكنولوجيا لتخزين واسترجاع البيانات المتجهة بشكل فعال"},"features":{"en":["Supports ETS backend for prototype and small index use cases with low latency","Offers File backend for simple persistence without a database","Utilizes PostgreSQL with pgvector for production environments with SQL and vector support","Integrates with Qdrant client for dedicated vector engine and large-scale data management","Provides persistence options, including binary and term storage","Enables scaling for large datasets with IVFFlat and HNSW indexes"],"zh":["支持ETS后端，适用于原型和小型索引","支持File后端，提供简单的持久化","支持PostgreSQL + pgvector后端，适用于生产环境","支持Qdrant（客户端）后端，适用于大规模向量数据"],"ja":["ETSバックエンドをサポート、プロトタイプと小規模なインデックスに適","Fileバックエンドをサポート、シンプルな永続化を提供","PostgreSQL + pgvectorバックエンドをサポート、プロダクション環境に適","Qdrant（クライアント）バックエンドをサポート、大規模なベクトルデータに適"],"ko":["ETS 백엔드를 지원하여 원형 및 소규모 색인에 적합","File 백엔드를 지원하여 간단한 지속성을 제공","PostgreSQL + pgvector 백엔드를 지원하여 프로덕션 환경에 적합","Qdrant(클라이언트) 백엔드를 지원하여 대규모 벡터 데이터에 적합"],"es":["Soporte para ETS, File, PostgreSQL y Qdrant como backends","Persistencia de datos en binario o término","Escalabilidad para grandes conjuntos de datos","Compatibilidad con índices IVFFlat y HNSW","Almacenamiento de vectores en memoria o en disco"],"fr":["Prise en charge d''ETS, File, PostgreSQL et Qdrant en tant que backends","Persistance des données en binaire ou en terme","Scalabilité pour les grands ensembles de données","Compatibilité avec les index IVFFlat et HNSW","Stockage de vecteurs en mémoire ou sur disque"],"de":["Unterstützung für ETS, File, PostgreSQL und Qdrant als Backends","Persistenz von Daten in Binär- oder Term-Form","Skalierbarkeit für große Datensätze","Kompatibilität mit IVFFlat- und HNSW-Indizes","Speicherung von Vektoren im Speicher oder auf Datenträgern"],"pt":["Suporte a backends de armazenamento como ETS, File, PostgreSQL e Qdrant","Opções de persistência e escalabilidade para conjuntos de dados grandes","Índices de busca eficientes como IVFFlat e HNSW","Integração com linguagens de programação como Python e React","Suporte a cli para operações de armazenamento e recuperação de dados"],"ru":["Поддержка бэкендов хранилища, таких как ETS, File, PostgreSQL и Qdrant","Варианты персистентности и масштабируемости для больших наборов данных","Эффективные индексы поиска, такие как IVFFlat и HNSW","Интеграция с языками программирования, такими как Python и React","Поддержка CLI для операций хранения и извлечения данных"],"ar":["دعم بروتوكولات تخزين الخلفية مثل ETS و File و PostgreSQL و Qdrant","خيارات للاستمرار والتحجيم لمجموعات البيانات الكبيرة","فهرس بحث فعال مثل IVFFlat و HNSW","التكامل مع لغات البرمجة مثل Python و React","دعم CLI لعمليات تخزين واسترجاع البيانات"]},"keywords":{"en":["how to use vector-db-storage","vector-db-storage alternative","vector-db-storage setup guide","what is vector-db-storage","vector-db-storage vs Qdrant","vector-db-storage install","vector-db-storage for AI agents","vector database storage solutions","efficient vector data management"],"zh":["向量数据库存储","AIエージェント","ETS","File","PostgreSQL + pgvector","Qdrant（客户端）","向量数据存储","大规模向量数据","生产环境"],"ja":["ベクトルDBストレージ","AIエージェント","ETS","File","PostgreSQL + pgvector","Qdrant（クライアント）","ベクトルデータストレージ","大規模なベクトルデータ","プロダクション環境"],"ko":["벡터 데이터베이스 저장소","AI 도구","ETS","File","PostgreSQL + pgvector","Qdrant(클라이언트)","벡터 데이터 저장소","대규모 벡터 데이터","프로덕션 환경"],"es":["almacenamiento de vector db","stockage vectoriel db","vectores de desarrollo","ETS","File","PostgreSQL","Qdrant","índices IVFFlat","índices HNSW","persistencia de datos"],"fr":["stockage vectoriel db","vecteurs de développement","ETS","File","PostgreSQL","Qdrant","index IVFFlat","index HNSW","persistance des données"],"de":["Vektor-DB-Speicherung","Vektoren für Entwicklung","ETS","File","PostgreSQL","Qdrant","IVFFlat-Indizes","HNSW-Indizes","Datenpersistenz"],"pt":["armazenamento de banco de dados vetorial","armazenamento de dados vetoriais","indexação de dados vetoriais","ETS","File","PostgreSQL","Qdrant","índices de busca eficientes","persistência de dados","escalabilidade de dados"],"ru":["Хранилище векторной базы данных","Хранение векторных данных","Индексирование векторных данных","ETS","File","PostgreSQL","Qdrant","Эффективные индексы поиска","Персистентность данных","Масштабируемость данных"],"ar":["مخزن قاعدة البيانات المتجه","تخزين البيانات المتجهة","فهرسة البيانات المتجهة","ETS","File","PostgreSQL","Qdrant","فهرس بحث فعال","استمرار البيانات","تحجيم البيانات"]}},"owner":"8dazo","repo":"elix-db","repoPath":"8dazo/elix-db","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.476Z","topics":[],"category":"community","skillMd":{"name":"vector-db-storage","description":"Storage backends and indexing for vector databases in Elixir. Use when choosing persistence, implementing exact vs approximate k-NN, or integrating pgvector, file, or ETS for vector storage.","bodyPreview":"# Vector DB Storage and Indexing\n\n## Storage Backends\n\n| Backend | Use case | Persistence | Scale |\n|---------|----------|-------------|--------|\n| **ETS** | Prototype, small index, low latency | No | &lt; ~100k–500k vectors in memory |\n| **File** | Simple persistence, no DB | Yes (binary/term) | Same as ETS, plus disk |\n| **PostgreSQL + pgvector** | Production, SQL + vectors | Yes | Large; use IVFFlat/HNSW indexes |\n| **Qdrant (client)** | Dedicated vector engine | Yes (external) | Very large |","body":"# Vector DB Storage and Indexing\n\n## Storage Backends\n\n| Backend | Use case | Persistence | Scale |\n|---------|----------|-------------|--------|\n| **ETS** | Prototype, small index, low latency | No | &lt; ~100k–500k vectors in memory |\n| **File** | Simple persistence, no DB | Yes (binary/term) | Same as ETS, plus disk |\n| **PostgreSQL + pgvector** | Production, SQL + vectors | Yes | Large; use IVFFlat/HNSW indexes |\n| **Qdrant (client)** | Dedicated vector engine | Yes (external) | Very large |\n\n## In-Memory (ETS)\n\n- **:set** table, key = vector id.\n- Value: `{id, vector, metadata}`; vector as list or binary.\n- No persistence: load from file on GenServer init if needed (see File below).\n- **Exact k-NN**: iterate all rows, compute distance, sort, take k. O(n) per query.\n\n## File Persistence\n\n- **On shutdown**: GenServer `terminate/2` or `:gen_server.cast(pid, :persist)` → write ETS contents to file (e.g. `:erlang.term_to_binary(entries)` or custom binary format).\n- **On start**: read file, recreate ETS and insert all entries.\n- Keep dimension and metadata format in header or config so reload is consistent.\n\n## PostgreSQL + pgvector\n\nUse [pgvector](https://github.com/pgvector/pgvector-elixir) and Ecto for persistent, indexed storage.\n\n- **Schema**: table with `id`, `embedding` (pgvector type), `metadata` (jsonb/map).\n- **Index**: create HNSW or IVFFlat index on `embedding` for approximate k-NN.\n- **Queries**: use pgvector’s distance operators (`<=>`, `<->`) in raw SQL or Ecto fragments; limit k.\n\n```elixir\n# Example: nearest neighbors (cosine distance)\n# fragment(\"embedding <=> ?::vector\", ^Nx.to_flat_list(query))\n```\n\n- Handles large datasets; persistence and backups via Postgres.\n\n## Exact vs Approximate k-NN\n\n| Method | Accuracy | Speed | When |\n|--------|----------|-------|------|\n| **Exact** (scan all) | Exact | O(n) per query | Small n (e.g. &lt; 100k), correctness critical |\n| **IVFFlat** (pgvector) | Approximate | Fast | Medium/large, good recall with tuning |\n| **HNSW** (pgvector) | Approximate | Very fast | Large, high recall |\n\nFor in-memory ETS, start with exact k-NN; move to pgvector (or Qdrant) when n grows or persistence is required.\n\n## Design Checklist\n\n- [ ] Persistence requirement clear: none, file, or Postgres\n- [ ] If file: define format (term vs binary) and load/save on start/stop\n- [ ] If pgvector: add migration for vector column and chosen index (HNSW/IVFFlat)\n- [ ] Dimension and distance metric match across insert and search\n"},"lastSynced":"2026-03-08T02:09:48.017Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents requiring efficient vector database storage and indexing solutions, particularly those working with ETS, File, PostgreSQL, and Qdrant backends.","zh":"适用于需要高效的向量数据库存储和索引解决方案的AI代理，特别是那些使用ETS、File、PostgreSQL和Qdrant后端的代理。","ja":"効率的なベクトルデータベースのストレージとインデックスの解決策を必要とするAIエージェントに適しています。特に、ETS、File、PostgreSQL、Qdrantバックエンドを使用するものに適しています。","ko":"효율적인 벡터 데이터베이스 저장소 및 인덱싱 솔루션이 필요한 AI 에이전트에 적합합니다. 특히 ETS, File, PostgreSQL 및 Qdrant 백엔드를 사용하는 에이전트에 적합합니다.","es":"Ideal para agentes de IA que requieren soluciones de almacenamiento y indexación de bases de datos vectoriales eficientes, particularmente aquellos que trabajan con backends de ETS, File, PostgreSQL y Qdrant.","fr":"Idéal pour les agents IA nécessitant des solutions de stockage et d''indexation de bases de données vectorielles efficaces, en particulier ceux qui travaillent avec les backends ETS, File, PostgreSQL et Qdrant.","de":"Ideal für KI-Agents, die effiziente Vektor-Datenbank-Speicher- und Indexierungslösungen erfordern, insbesondere solche, die mit ETS-, File-, PostgreSQL- und Qdrant-Backends arbeiten.","pt":"Ideal para Agentes de IA que requerem soluções de armazenamento e indexação de bancos de dados de vetores eficientes, particularmente aqueles que trabalham com backends ETS, File, PostgreSQL e Qdrant.","ru":"Идеально для ИИ-агентов, требующих эффективных решений для хранения и индексации векторных баз данных, особенно тех, которые работают с бэкендами ETS, File, PostgreSQL и Qdrant.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى حلول تخزين قواعد البيانات المتجهة والفهرسة الكفؤة، ولا سيما تلك التي تعمل مع الخوادم الخلفية ETS و File و PostgreSQL و Qdrant."},"recommendation":{"en":"Empowers agents to store and manage large vector datasets with support for various backends, including PostgreSQL with pgvector and Qdrant, enabling efficient scaling and querying using IVFFlat and HNSW indexes.","zh":"赋予代理存储和管理大型向量数据集的能力，支持多种后端，包括PostgreSQL和pgvector、Qdrant，能够使用IVFFlat和HNSW索引实现高效的扩展和查询。","ja":"エージェントに大規模なベクトルデータセットを保存および管理する機能を提供します。PostgreSQLおよびpgvector、Qdrantを含むさまざまなバックエンドをサポートし、IVFFlatおよびHNSWインデックスを使用して効率的なスケーリングおよびクエリを可能にします。","ko":"에이전트가 대규모 벡터 데이터 세트를 저장하고 관리할 수 있는 기능을 제공하며 PostgreSQL 및 pgvector, Qdrant를 포함한 다양한 백엔드를 지원하여 IVFFlat 및 HNSW 인덱스를 사용한 효율적인 확장 및 쿼리를 가능하게 합니다.","es":"Habilita a los agentes para almacenar y gestionar grandes conjuntos de datos vectoriales con soporte para varios backends, incluyendo PostgreSQL con pgvector y Qdrant, lo que permite un escalado y una consulta eficientes mediante los índices IVFFlat y HNSW.","fr":"Permet aux agents de stocker et de gérer de grands ensembles de données vectorielles avec une prise en charge de différents backends, notamment PostgreSQL avec pgvector et Qdrant, ce qui permet un scaling et des requêtes efficaces à l''aide des index IVFFlat et HNSW.","de":"Ermöglicht es Agents, große Vektor-Datensätze zu speichern und zu verwalten, mit Unterstützung für verschiedene Backends, einschließlich PostgreSQL mit pgvector und Qdrant, wodurch ein effizientes Skalieren und Abfragen mithilfe der Indizes IVFFlat und HNSW ermöglicht wird.","pt":"Habilita agentes a armazenar e gerenciar grandes conjuntos de dados de vetores com suporte a vários backends, incluindo PostgreSQL com pgvector e Qdrant, permitindo escalabilidade eficiente e consulta usando índices IVFFlat e HNSW.","ru":"Предоставляет агентам возможность хранить и управлять большими наборами векторных данных с поддержкой различных бэкендов, включая PostgreSQL с pgvector и Qdrant, что позволяет эффективно масштабировать и выполнять запросы с использованием индексов IVFFlat и HNSW.","ar":"تمكين الوكلاء من تخزين وإدارة مجموعات كبيرة من بيانات المتجهات مع دعم للخوادم الخلفية المختلفة، بما في ذلك PostgreSQL مع pgvector و Qdrant، مما يتيح التوسع والاستعلام الفعال باستخدام فهارس IVFFlat و HNSW."},"useCases":{"en":["Indexing large vector datasets for similarity search","Storing and retrieving vector embeddings with PostgreSQL and pgvector","Scaling vector databases with Qdrant for high-performance querying"],"zh":["为相似性搜索索引大型向量数据集","使用PostgreSQL和pgvector存储和检索向量嵌入","使用Qdrant扩展向量数据库以实现高性能查询"],"ja":["類似性検索のための大規模なベクトルデータセットのインデックス作成","PostgreSQLおよびpgvectorを使用したベクトル埋め込みの保存および取得","Qdrantを使用したベクトルデータベースのスケーリングによる高性能クエリ"],"ko":["유사성 검색을 위한 대규모 벡터 데이터 세트 인덱싱","PostgreSQL 및 pgvector를 사용한 벡터 임베딩 저장 및检索","Qdrant를 사용한 벡터 데이터베이스 확장 및 고성능 쿼리"],"es":["Indexación de grandes conjuntos de datos vectoriales para búsqueda de similitud","Almacenamiento y recuperación de incrustaciones vectoriales con PostgreSQL y pgvector","Escalado de bases de datos vectoriales con Qdrant para consultas de alto rendimiento"],"fr":["Indexation de grands ensembles de données vectorielles pour la recherche de similarité","Stockage et récupération d''incrustations vectorielles avec PostgreSQL et pgvector","Scaling de bases de données vectorielles avec Qdrant pour des requêtes hautes performances"],"de":["Indexierung großer Vektor-Datensätze für Ähnlichkeitssuche","Speicherung und Abruf von Vektor-Einbettungen mit PostgreSQL und pgvector","Skalierung von Vektor-Datenbanken mit Qdrant für Hochleistungs-Abfragen"],"pt":["Indexação de grandes conjuntos de dados de vetores para busca de semelhança","Armazenamento e recuperação de incorporações de vetores com PostgreSQL e pgvector","Dimensionamento de bancos de dados de vetores com Qdrant para consultas de alto desempenho"],"ru":["Индексация больших наборов векторных данных для поиска подобия","Хранение и извлечение векторных вложений с PostgreSQL и pgvector","Масштабирование векторных баз данных с помощью Qdrant для высокопроизводительных запросов"],"ar":["فهرسة مجموعات كبيرة من بيانات المتجهات للبحث عن التشابه","تخزين واسترجاع توطين المتجهات مع PostgreSQL و pgvector","توسيع قواعد البيانات المتجهة مع Qdrant للحصول على استفسارات أداء عالية"]},"limitations":{"en":["ETS backend limited to ~100k-500k vectors in memory","File backend has same scalability limits as ETS, plus disk storage","Requires specific backend setup and configuration"],"zh":["ETS后端在内存中仅限于~100k-500k向量","File后端具有与ETS相同的可扩展性限制，并且具有磁盘存储限制","需要特定的后端设置和配置"],"ja":["ETSバックエンドはメモリ内で約100k-500k個のベクトルに限定される","FileバックエンドはETSと同等のスケーラビリティの制限に加えてディスクストレージの制限がある","特定のバックエンドの設定と構成が必要"],"ko":["ETS 백엔드는 메모리 내에서 약 100k-500k개의 벡터로 제한됨","File 백엔드는 ETS와 동일한 확장성 제한이 있으며 디스크 저장소 제한도 있음","특정 백엔드 설정 및 구성이 필요"],"es":["El backend de ETS está limitado a ~100k-500k vectores en memoria","El backend de archivo tiene los mismos límites de escalabilidad que ETS, más almacenamiento en disco","Requiere una configuración y configuración específicas del backend"],"fr":["Le backend ETS est limité à ~100k-500k vecteurs en mémoire","Le backend de fichiers a les mêmes limites de scalabilité que ETS, plus un stockage sur disque","Nécessite une configuration et une configuration spécifiques du backend"],"de":["Das ETS-Backend ist auf ~100k-500k Vektoren im Speicher beschränkt","Das Datei-Backend hat die gleichen Skalierbarkeitsgrenzen wie ETS, plus Festplattenspeicher","Benötigt eine spezifische Backend-Konfiguration und -Einrichtung"],"pt":["Backend ETS limitado a ~100k-500k vetores na memória","Backend de arquivo tem os mesmos limites de escalabilidade que o ETS, mais armazenamento em disco","Exige configuração e setup específicos do backend"],"ru":["Бэкенд ETS ограничен ~100k-500k векторами в памяти","Бэкенд файла имеет те же ограничения масштабируемости, что и ETS, плюс хранение на диске","Требует конкретной настройки и конфигурации бэкенда"],"ar":["الخادم الخلفي ETS مقيد بـ ~100k-500k متجه في الذاكرة","الخادم الخلفي للملف له نفس حدود التوسع مثل ETS، بالإضافة إلى تخزين القرص","يتطلب إعدادًا وتكوينًا محددين للخادم الخلفي"]},"version":4},"contentHash":"f9a6ceeb56667990440cda9259f0ea248e9869fed8d2b0ca10b1b65c5af02620","qualityScore":33}');
