INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('8dazo/elix-db/vector-db-storage', 'vector-db-storage', '8dazo', 'elix-db', 'community', 'vector-db-storage 8dazo elix-db community The vector-db-storage skill provides storage solutions for AI agents, supporting various backends like ETS, File, PostgreSQL, and Qdrant. It benefits developers working with vector databases and indexing. 向量数据库存储提供多种后端选项，包括ETS、File、PostgreSQL + pgvector和Qdrant（客户端），满足不同场景的需求 ベクトルDBストレージは、ETS、File、PostgreSQL + pgvector、Qdrant（クライアント）などの複数のバックエンドオプションを提供し、さまざまなシナリオに適応 벡터 데이터베이스 저장소는 다양한 백엔드 옵션을 제공합니다. ETS, File, PostgreSQL + pgvector 및 Qdrant(클라이언트)을 포함하여 다양한 시나리오에 적합 El almacenamiento de Vector DB permite a los desarrolladores almacenar y recuperar vectores de manera eficiente. Soporta backends como ETS, File, PostgreSQL y Qdrant Le stockage Vectoriel DB permet aux développeurs de stocker et de récupérer des vecteurs de manière efficace. Il prend en charge les backends tels que ETS, File, PostgreSQL et Qdrant Die Speicherung von Vektor-DB ermöglicht es Entwicklern, Vektoren effizient zu speichern und abzurufen. Es unterstützt Backends wie ETS, File, PostgreSQL und Qdrant O armazenamento de banco de dados vetorial é uma solução para armazenar e indexar grandes conjuntos de dados vetoriais Хранилище векторной базы данных - это решение для хранения и индексирования больших наборов векторных данных مخزن قاعدة البيانات المتجه هو حل لتخزين وفهرسة مجموعات كبيرة من البيانات المتجهة how to use vector-db-storage vector-db-storage alternative vector-db-storage setup guide what is vector-db-storage vector-db-storage vs Qdrant vector-db-storage install vector-db-storage for AI agents vector database storage solutions efficient vector data management 向量数据库存储 AIエージェント ETS File PostgreSQL + pgvector Qdrant（客户端） 向量数据存储 大规模向量数据 生产环境 Supports ETS backend for prototype and small index use cases with low latency Offers File backend for simple persistence without a database Utilizes PostgreSQL with pgvector for production environments with SQL and vector support Integrates with Qdrant client for dedicated vector engine and large-scale data management Provides persistence options, including binary and term storage Enables scaling for large datasets with IVFFlat and HNSW indexes vector-db-storage is a skill that enables efficient storage and indexing of vector data, supporting multiple storage backends and persistence options.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('v24kuon/django-booking/software-architecture', 'community', 'v24kuon', 'django-booking', 'v24kuon/django-booking', 'software-architecture', 0, 0, 33, '2026-03-08T01:57:15.486Z', '2026-03-08T02:10:04.091Z', 'c3628caa844f02d12218ec711073dd9dbcb8154283c8e3fb5b652430ce332c2d', '{"id":"v24kuon/django-booking/software-architecture","name":"software-architecture","description":{"en":"This skill provides guidance for quality-focused software development and architecture, benefiting developers who want to write clean and maintainable code.","zh":"本技能提供了软件架构开发的指导，遵循Clean Architecture和Domain Driven Design原则","ja":"このスキルは、Clean ArchitectureとDomain Driven Designの原則に基づくソフトウェアアーキテクチャ開発の指針を提供します","ko":"이 스킬은 Clean Architecture와 Domain Driven Design 원칙을 기반으로 한 소프트웨어 아키텍처 개발 가이드를 제공합니다","es":"Nuestra habilidad de arquitectura de software proporciona orientación para el desarrollo de software de alta calidad basado en principios de Clean Architecture y Domain Driven Design.","fr":"Notre compétence en architecture logicielle fournit des conseils pour le développement de logiciels de haute qualité basés sur les principes de Clean Architecture et de Domain Driven Design.","de":"Unsere Software-Architektur-Fähigkeit bietet Anleitung für die Entwicklung von hochwertiger Software basierend auf Clean-Architecture- und Domain-Driven-Design-Prinzipien.","pt":"Arquitetura de software de qualidade, baseada em Clean Architecture e Domain Driven Design, para desenvolvimento eficaz","ru":"Качественная архитектура программного обеспечения, основанная на Clean Architecture и Domain Driven Design, для эффективного развития ИИ Агентов","ar":"هندسة برمجيات ذكية تعتمد على التصميم النظيف والتصميم الموجه للنطاق لتحقيق برمجة فعالة"},"seo":{"title":{"en":"Software-Architecture: Clean Code Setup Guide | AI Agent ...","zh":"软件架构开发最佳实践指南 - AIエージェント","