INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('v24kuon/django-booking/software-architecture', 'software-architecture', 'v24kuon', 'django-booking', 'community', 'software-architecture v24kuon django-booking community This skill provides guidance for quality-focused software development and architecture, benefiting developers who want to write clean and maintainable code. 本技能提供了软件架构开发的指导，遵循Clean Architecture和Domain Driven Design原则 このスキルは、Clean ArchitectureとDomain Driven Designの原則に基づくソフトウェアアーキテクチャ開発の指針を提供します 이 스킬은 Clean Architecture와 Domain Driven Design 원칙을 기반으로 한 소프트웨어 아키텍처 개발 가이드를 제공합니다 Nuestra habilidad de arquitectura de software proporciona orientación para el desarrollo de software de alta calidad basado en principios de Clean Architecture y Domain Driven Design. Notre compétence en architecture logicielle fournit des conseils pour le développement de logiciels de haute qualité basés sur les principes de Clean Architecture et de Domain Driven Design. Unsere Software-Architektur-Fähigkeit bietet Anleitung für die Entwicklung von hochwertiger Software basierend auf Clean-Architecture- und Domain-Driven-Design-Prinzipien. Arquitetura de software de qualidade, baseada em Clean Architecture e Domain Driven Design, para desenvolvimento eficaz Качественная архитектура программного обеспечения, основанная на Clean Architecture и Domain Driven Design, для эффективного развития ИИ Агентов هندسة برمجيات ذكية تعتمد على التصميم النظيف والتصميم الموجه للنطاق لتحقيق برمجة فعالة how to use software-architecture software-architecture best practices clean architecture principles domain driven design tutorial software-architecture setup guide software-architecture vs monolithic architecture implementing early return pattern reusable functions in software development software-architecture install 软件架构开发 Clean Architecture Domain Driven Design 代码可读性 代码重复 软件系统设计 AIエージェント 软件开发最佳实践 Applies early return pattern for better code readability Avoids code duplication through reusable functions and modules Decomposes long components into smaller, manageable pieces Follows Clean Architecture principles for separated concerns Implements Domain Driven Design for domain-centric development Promotes modular code organization for easier maintenance Software-architecture is a set of principles and patterns for designing and building software systems, emphasizing cleanliness, reusability, and readability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('bCommonsLAB/CommonKnowledgeScout/integration-test', 'community', 'bCommonsLAB', 'CommonKnowledgeScout', 'bCommonsLAB/CommonKnowledgeScout', 'integration-test', 0, 0, 33, '2026-03-08T01:57:15.488Z', '2026-03-08T02:10:07.075Z', '4444c3288477c73a33c269c92f80ad19af46837f8b6ac97d4fbb69baa93a001d', '{"id":"bCommonsLAB/CommonKnowledgeScout/integration-test","name":"integration-test","description":{"en":"The integration-test skill performs end-to-end integration tests for the CommonKnowledgeScout project, benefiting developers who need to test directories with various file formats. It enables testing of PDF, Audio, and Markdown files, among others.","zh":"集成测试工具是一种用于执行终端到终端集成测试的AI工具，支持CommonKnowledgeScout项目","ja":"統合テストスキルは、CommonKnowledgeScoutプロジェクトのためのエンドツーエンドの統合テストを実行するAIエージェントです","ko":"통합 테스트 도구는 CommonKnowledgeScout 프로젝트를 위한 End-to-End 통합 테스트를 수행하는 AI 도구입니다","es":"El skill de prueba de integración ejecuta pruebas de extremo a extremo para CommonKnowledgeScout. Requiere pnpm dev y Secretary Service.","fr":"Le skill de test d''intégration exécute des tests de bout en bout pour CommonKnowledgeScout. Nécessite pnpm dev et Secretary Service.","de":"Der Integration-Test Skill führt End-to-End-Tests für CommonKnowledgeScout aus. Erfordert pnpm dev und Secretary Service.","pt":"O Integration-Test é um skill que executa testes de integração para o projeto CommonKnowledgeScout. Ele utiliza o pnpm dev e o Secretary Service para testar aplicações.","ru":"Integration-Test - это навык, который выполняет интеграционные тесты для проекта CommonKnowledgeScout. Он использует pnpm dev и Secretary Service для тестирования приложений.","ar":"Integration-Test هو مهارة تقوم بتنفيذ اختبارات التكامل لمشروع CommonKnowledgeScout. يستخدم pnpm dev و Secretary Service لاختبار التطبيقات."},"seo":{"title":{"en":"Integration-Test: End-to-End