INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('bCommonsLAB/CommonKnowledgeScout/integration-test', 'integration-test', 'bCommonsLAB', 'CommonKnowledgeScout', 'community', 'integration-test bCommonsLAB CommonKnowledgeScout community The integration-test skill performs end-to-end integration tests for the CommonKnowledgeScout project, benefiting developers who need to test directories with various file formats. It enables testing of PDF, Audio, and Markdown files, among others. 集成测试工具是一种用于执行终端到终端集成测试的AI工具，支持CommonKnowledgeScout项目 統合テストスキルは、CommonKnowledgeScoutプロジェクトのためのエンドツーエンドの統合テストを実行するAIエージェントです 통합 테스트 도구는 CommonKnowledgeScout 프로젝트를 위한 End-to-End 통합 테스트를 수행하는 AI 도구입니다 El skill de prueba de integración ejecuta pruebas de extremo a extremo para CommonKnowledgeScout. Requiere pnpm dev y Secretary Service. Le skill de test d''intégration exécute des tests de bout en bout pour CommonKnowledgeScout. Nécessite pnpm dev et Secretary Service. Der Integration-Test Skill führt End-to-End-Tests für CommonKnowledgeScout aus. Erfordert pnpm dev und Secretary Service. O Integration-Test é um skill que executa testes de integração para o projeto CommonKnowledgeScout. Ele utiliza o pnpm dev e o Secretary Service para testar aplicações. Integration-Test - это навык, который выполняет интеграционные тесты для проекта CommonKnowledgeScout. Он использует pnpm dev и Secretary Service для тестирования приложений. Integration-Test هو مهارة تقوم بتنفيذ اختبارات التكامل لمشروع CommonKnowledgeScout. يستخدم pnpm dev و Secretary Service لاختبار التطبيقات. how to use integration-test integration-test setup guide end-to-end testing for CommonKnowledgeScout integration-test alternative integration-test vs other testing tools integration-test install what is integration-test integration-test for AI agents CommonKnowledgeScout testing 集成测试工具 AI工具 终端到终端测试 CommonKnowledgeScout pnpm dev Secretary Service Test-Loop Runs end-to-end integration tests for the CommonKnowledgeScout project Supports testing of various file formats, including PDF, Audio, and Markdown Utilizes a dev server via `pnpm dev` command Requires Secretary Service to be reachable Enables test-loop functionality for iterative testing and analysis Integration-test is a skill that automates end-to-end testing for the CommonKnowledgeScout project, utilizing a dev server and Secretary Service to ensure thorough testing of directories and files.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('meleantonio/ChernyCode/code-style', 'community', 'meleantonio', 'ChernyCode', 'meleantonio/ChernyCode', 'code-style', 0, 0, 33, '2026-03-08T01:57:15.492Z', '2026-03-08T02:10:08.784Z', '17a2455cc63e7ec13170103276b169829cfe43e1343dd9c9502a5be3afbc60f9', '{"id":"meleantonio/ChernyCode/code-style","name":"code-style","description":{"en":"The code-style skill provides Python code formatting and naming conventions for AI agent developers, ensuring consistent and readable code. It supports Ruff formatting and type hints.","zh":"Python代码风格设置指南，介绍格式化、命名约定和类型提示的最佳实践","ja":"Pythonコードスタイル設定ガイド - フォーマット、命名規則、タイプヒントのベストプラクティス","ko":"파이썬 코드 스타일 설정 가이드 - 포맷팅, 명명 규칙, 타입 힌트의 베스트 프랙티스","es":"Configura el estilo de código para tus proyectos de Python con Ruff y sigue las mejores prácticas de formato y convenciones de nombre","fr":"Configurez le style de code pour vos projets Python avec Ruff et suivez les meilleures pratiques de formatage et de conventions de nommage","de":"Konfigurieren Sie den Code-Stil für Ihre Python-Projekte mit Ruff und folgen Sie den Best Practices für Formatierung und Namenskonventionen","pt":"O estilo de código Python é fundamental para a legibilidade e manutenção do código. Aprenda a configurar o estilo de código com Ruff e melhorar a legibilidade do seu código","ru":"Стиль кода Python имеет важное значение для читаемости и поддержки кода. Узнайте, как настроить стиль кода с помощью Ruff и улучшить читаемость вашего кода","ar":"أسلوب الكود بايثون هو أمر أساسي للقراءة والصيانة. تعلم كيفية ضبط أسلوب الكود مع Ruff وتحسين قابلية قراءة الكود الخاص بك"},"seo":{"title":{"en":"code-style: Python Formatting Best Practices | AI Agent S...","zh":"Python代码风格设置指南","ja":"Pythonコードスタイル設定ガイド - AIエージェント","ko":"파이썬 코드 스타일 설정 가이드 - AI Tools","es":"Guía de Configuración de Estilo de Código para Desarrolla...","fr":"Guide de Configuration du Style de Code pour les Développ...","de":"Einrichtungsleitfaden für Code-Stil-Tools","pt":"Guia de Configuração de Estilo de Código Python com Ferra...","ru":"Настройка стиля кода Python с помощью ИИ Агентов","ar":"دليل إعداد أسلوب الكود بايثون مع أدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to enforce consistent Python code style with Ruff formatting, snake_case naming, and type hints. Learn how to set up code-style for your AI agen...","zh":"了解Python代码风格的最佳实践，包括格式化、命名约定和类型提示，以提高代码可读性和可维护性","ja":"Pythonコードスタイルのベストプラクティスを学び、コードの可読性とメンテナンス性を向上させます - AIエージェント","ko":"파이썬 코드 스타일의 베스트 프랙티스를 학습하고 코드의 가독성과 유지보수성을 향상시키세요 - AI Tools","es":"Aprende a configurar el estilo de código para tus proyectos de Python con nuestras mejores prácticas y herramientas como Ruff","fr":"Découvrez comment configurer le style de code pour vos projets Python avec nos meilleures pratiques et outils comme Ruff","de":"Erfahren Sie, wie Sie den Code-Stil für Ihre Python-Projekte mit unseren Best Practices und Tools wie Ruff konfigurieren","pt":"Aprenda a configurar o estilo de código Python com Ruff e melhorar a legibilidade do seu código com as melhores práticas de nomeação e tipo","ru":"Узнайте, как настроить стиль кода Python с помощью Ruff и улучшить читаемость вашего кода с помощью лучших практик именования и типов","ar":"تعلم كيفية ضبط أسلوب الكود بايثون مع Ruff وتحسين قابلية قراءة الكود الخاص بك بأفضل الممارسات في التسمية والنوع"},"definition":{"en":"code-style is a set of guidelines for formatting and naming Python code, including the use of Ruff, snake_case, and type hints to ensure consistency and readability.","zh":"Python代码风格是指编写Python代码的规范和约定","ja":"Pythonコードスタイルとは、Pythonコードを書く際の規範と約束のこと","ko":"파이썬 코드 스타일은 파이썬 코드를 작성할 때의 규칙과 약속","es":"El estilo de código se refiere a las reglas y convenciones que se siguen para escribir código de manera clara y consistente","fr":"Le style de code fait référence aux règles et conventions suivies pour écrire du code de manière claire et cohérente","de":"Der Code-Stil bezieht sich auf die Regeln und Konventionen, die für das Schreiben von klarem und konsistentem Code befolgt werden","pt":"O estilo de código é um conjunto de regras e convenções para escrever código Python de forma clara e legível","ru":"Стиль кода - это набор правил и конвенций для написания читаемого и поддерживаемого кода Python","ar":"أسلوب الكود هو مجموعة من القواعد والاتفاقيات لكتابة كود بايثون بطريقة واضحة وقابلة للقراءة"},"features":{"en":["Uses Ruff for formatting with the command `ruff format .`","Enforces 4-space indentation and 120-character max line length","Supports snake_case naming for functions and variables","Utilizes type hints for function parameters and return types","Allows for nullable types using `Optional[T]` or `T | None`"],"zh":["使用Ruff进行代码格式化","采用4个空格的缩进","最大行长度为120个字符","使用下划线命名法（snake_case）","支持类型提示（Type Hints）"],"ja":["Ruffを使用したコードフォーマット","4つの空白文字によるインデント","最大行長は120文字","スネークケース（snake_case）を使用した命名","タイプヒント（Type Hints）をサポート"],"ko":["Ruff를 사용한 코드 포맷팅","4개의 공백 문자로 인덴트","최대 행 길이는 120자","스네이크 케이스（snake_case）를 사용한 명명","타입 힌트（Type Hints）를 지원"],"es":["Formato de código con Ruff","Indentación de 4 espacios","Límite de longitud de línea de 120 caracteres","Uso de comas finales en colecciones multilínea","Convenciones de nombre para funciones, variables y clases"],"fr":["Formatage de code avec Ruff","Indentation de 4 espaces","Limite de longueur de ligne de 120 caractères","Utilisation de virgules finales dans les collections multilignes","Conventions de nommage pour les fonctions, variables et classes"],"de":["Code-Formatierung mit Ruff","Einrückung von 4 Leerzeichen","Zeichenlimit von 120 Zeichen pro Zeile","Verwendung von abschließenden Kommas in mehrzeiligen Sammlungen","Namenskonventionen für Funktionen, Variablen und Klassen"],"pt":["Formatação automática com Ruff","Indentação de 4 espaços","Comprimento máximo de linha de 120 caracteres","Uso de vírgulas finais em coleções multilinhas","Convenções de nomeação de funções e variáveis em snake_case","Tipos opcionais com Optional[T] ou T | None"],"ru":["Автоматическая форматировка с помощью Ruff","Отступы размером 4 пробела","Максимальная длина строки 120 символов","Использование завершающих запятых в многострочных коллекциях","Конвенции именования функций и переменных в snake_case","Опциональные типы с Optional[T] или T | None"],"ar":["تنسيق تلقائي مع Ruff","مسافة بادئة بحجم 4 مسافات","الحد الأقصى لطول السطر 120 حرفًا","استخدام الفواصل الزائدة في المجموعات متعددة الأسطر","اتفاقيات تسمية الدوال والمتغيرات بسرعة الحية","أنواع اختيارية مع Optional[T] أو T | None"]},"keywords":{"en":["how to use code-style","code-style setup guide","python code formatting","Ruff formatting tool","code-style vs black","code-style install","python type hints","snake_case naming convention","code-style best practices"],"zh":["Python代码风格","代码格式化","命名约定","类型提示","Ruff","Python代码最佳实践"],"ja":["Pythonコードスタイル","コードフォーマット","命名規則","タイプヒント","Ruff","Pythonコードベストプラクティス","AIエージェント"],"ko":["파이썬 코드 스타일","코드 포맷팅","명명 규칙","타입 힌트","Ruff","파이썬 코드 베스트 프랙티스","AI Tools"],"es":["estilo de código python","herramientas de estilo de código","ruff formato de código","convenciones de nombre python","mejores prácticas de código","desarrollo de software","ingeniería de software"],"fr":["style de code python","outils de style de code","ruff formatage de code","conventions de nommage python","meilleures pratiques de code","développement de logiciels","ingénierie de logiciels"],"de":["code-stil python","code-stil-tools","ruff code-formatierung","namenskonventionen python","best practices code","software-entwicklung","software-ingeneering"],"pt":["estilo de código python","ruff","formatação automática","convenções de nomeação","tipos opcionais","desenvolvimento de software","legibilidade de código","manutenção de código","python coding style","ai tools para desenvolvimento"],"ru":["стиль кода python","ruff","автоматическая форматировка","конвенции именования","опциональные типы","разработка программного обеспечения","читаемость кода","поддержка кода","python кодирование","ИИ инструменты для разработки"],"ar":["أسلوب الكود بايثون","ruff","تنسيق تلقائي","اتفاقيات التسمية","أنواع اختيارية","تطوير البرمجيات","قابلية قراءة الكود","صيانة الكود","بايثون كود","أدوات الذكاء الاصطناعي لتطوير البرمجيات"]}},"owner":"meleantonio","repo":"ChernyCode","repoPath":"meleantonio/ChernyCode","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.492Z","topics":[],"category":"community","skillMd":{"name":"code-style","description":"Python code style and formatting standards using Ruff. Use when writing or reviewing Python code.","bodyPreview":"# Python Code Style\n\n## Formatting\n- Use Ruff for formatting (`ruff format .`)\n- Indentation: 4 spaces\n- Max line length: 120 characters\n- Use trailing commas in multi-line collections\n\n## Naming Conventions\n- Functions and variables: `snake_case`\n- Classes: `PascalCase`\n- Constants: `UPPER_SNAKE_CASE`\n- Private members: `_leading_underscore`\n- Module files: `snake_case.py`\n\n## Type Hints\n- Required for all function parameters and return types\n- Use `Optional[T]` or `T | None` for nullable types","body":"# Python Code Style\n\n## Formatting\n- Use Ruff for formatting (`ruff format .`)\n- Indentation: 4 spaces\n- Max line length: 120 characters\n- Use trailing commas in multi-line collections\n\n## Naming Conventions\n- Functions and variables: `snake_case`\n- Classes: `PascalCase`\n- Constants: `UPPER_SNAKE_CASE`\n- Private members: `_leading_underscore`\n- Module files: `snake_case.py`\n\n## Type Hints\n- Required for all function parameters and return types\n- Use `Optional[T]` or `T | None` for nullable types\n- Use `list[T]`, `dict[K, V]` (lowercase) for Python 3.10+\n\n## Docstrings\n- Use Google-style docstrings\n- Required for all public functions, classes, and modules\n- Include Args, Returns, and Raises sections\n\nExample:\n```python\ndef calculate_total(items: list[Item], discount: float = 0.0) -> float:\n    \"\"\"Calculate the total price of items with optional discount.\n\n    Args:\n        items: List of items to calculate total for.\n        discount: Discount percentage to apply (0.0 to 1.0).\n\n    Returns:\n        The total price after discount.\n\n    Raises:\n        ValueError: If discount is not between 0 and 1.\n    \"\"\"\n```\n\n## Imports\n- Sort with Ruff (replaces isort)\n- Group: stdlib, third-party, local\n- Use absolute imports for clarity\n- Avoid wildcard imports (`from x import *`)\n\n## Commands\n- Format: `ruff format .`\n- Lint: `ruff check .`\n- Fix: `ruff check --fix .`\n"},"lastSynced":"2026-03-08T02:10:08.784Z","agentAnalysis":{"suitability":{"en":"Ideal for Python Developer Agents requiring consistent and readable code formatting with Ruff and type hints support.","zh":"适合需要一致且可读的代码格式的Python开发者代理，支持Ruff和类型提示。","ja":"Python Developerエージェントが一貫性と読みやすさのあるコード形式を必要とする場合に適しています。Ruffと型ヒントをサポートしています。","ko":"일관성 있고 가독성이 높은 코드 형식을 필요로 하는 Python 개발자 에이전트에게 적합합니다. Ruff 및 유형 힌트를 지원합니다.","es":"Ideal para Agentes de Desarrollo de Python que requieren un formato de código consistente y legible con Ruff y soporte para type hints.","fr":"Idéal pour les Agents de Développement Python nécessitant un formatage de code cohérent et lisible avec Ruff et prise en charge des type hints.","de":"Ideal für Python-Entwicklungsagenten, die ein konsistentes und lesbares Code-Formatting mit Ruff und Type-Hints-Unterstützung benötigen.","pt":"Ideal para Agentes de Desenvolvedores Python que exigem formatação de código consistente e legível com Ruff e suporte a dicas de tipo.","ru":"Идеально подходит для агентов разработчиков Python, требующих последовательного и читаемого форматирования кода с помощью Ruff и поддержки подсказок типов.","ar":"مثالي لعميل وكلاء مطورو Python الذين يتطلبون تنسيقًا متسقًا وقراءة للشفرة باستخدام Ruff ودعم تلميحات النوع."},"recommendation":{"en":"Empowers agents to maintain uniform Python code style using Ruff formatting, enforce naming conventions like snake_case and PascalCase, and utilize type hints with Optional[T] or T | None for enhanced code readability and maintainability.","zh":"赋予代理维护统一的Python代码样式的能力，使用Ruff格式化、强制执行命名约定，如下划线分隔式和帕斯卡命名法，并利用类型提示以Optional[T]或T | None提高代码的可读性和可维护性。","ja":"エージェントがRuffのフォーマットを使用して一貫性のあるPythonコードスタイルを維持し、命名規則（例：スネークケースとパスカルケース）を強制して実施し、Optional[T]またはT | Noneを使用して型ヒントを利用し、コードの可読性と保守性を高める能力を付与します。","ko":"에이전트가 Ruff 형식을 사용하여 일관된 Python 코드 스타일을 유지하고, 명명 규칙(예: 스네이크 케이스 및 파스칼 케이스)을 강제하여 적용하며, Optional[T] 또는 T | None을 사용하여 유형 힌트를 활용하여 코드의 가독성과 유지 보수성을 향상시키는 기능을 부여합니다.","es":"Permite a los agentes mantener un estilo de código de Python uniforme utilizando el formato Ruff, hacer cumplir las convenciones de nomenclatura como snake_case y PascalCase, y utilizar type hints con Optional[T] o T | None para una mejor legibilidad y mantenibilidad del código.","fr":"Permet aux agents de maintenir un style de code Python uniforme en utilisant le formatage Ruff, de faire respecter les conventions de nommage comme snake_case et PascalCase, et d''utiliser des type hints avec Optional[T] ou T | None pour une meilleure lisibilité et maintenabilité du code.","de":"Ermächtigt Agenten, einen einheitlichen Python-Code-Stil mit Ruff-Formatierung beizubehalten, Namenskonventionen wie snake_case und PascalCase durchzusetzen und Type-Hints mit Optional[T] oder T | None für eine verbesserte Code-Lesbarkeit und Wartbarkeit zu nutzen.","pt":"Habilita os agentes a manter um estilo de código Python uniforme usando formatação Ruff, aplicar convenções de nomenclatura como snake_case e PascalCase e utilizar dicas de tipo com Optional[T] ou T | None para melhorar a legibilidade e manutenção do código.","ru":"Наделяет агентов возможностью поддерживать единый стиль кода Python, используя форматирование Ruff, обеспечивать соблюдение соглашений об именах, таких как snake_case и PascalCase, и использовать подсказки типов с Optional[T] или T | None для повышения читаемости и поддерживаемости кода.","ar":"تمكّن الوكلاء من الحفاظ على نمط kodu Python موحد باستخدام تنسيق Ruff، وفرض اتفاقيات تسمية مثل snake_case و PascalCase، واستخدام تلميحات النوع مع Optional[T] أو T | None لتحسين قراءة الشفرة وقابلية صيانتها."},"useCases":{"en":["Formatting Python code with Ruff for improved readability","Enforcing consistent naming conventions across modules","Utilizing type hints for better code documentation and error prevention"],"zh":["使用Ruff格式化Python代码以提高可读性","强制执行模块中的一致命名约定","利用类型提示进行更好的代码文档和错误预防"],"ja":["Ruffを使用してPythonコードをフォーマットし、可読性を向上させる","モジュール全体で一貫した命名規則を強制する","型ヒントを使用してより良いコードドキュメントとエラープレベンションを行う"],"ko":["Ruff를 사용하여 Python 코드를 형식화하여 가독성을 향상시키기","모듈 전체에서 일관된 명명 규칙을 강제 적용하기","유형 힌트를 사용하여 더 나은 코드 문서화 및 오류 예방을 수행하기"],"es":["Formato de código Python con Ruff para una mejor legibilidad","Hacer cumplir convenciones de nomenclatura coherentes en todos los módulos","Utilizar type hints para una mejor documentación de código y prevención de errores"],"fr":["Formatage de code Python avec Ruff pour une meilleure lisibilité","Faire respecter des conventions de nommage cohérentes à travers les modules","Utiliser des type hints pour une meilleure documentation de code et prévention d''erreurs"],"de":["Formatierung von Python-Code mit Ruff für eine verbesserte Lesbarkeit","Durchsetzen einheitlicher Namenskonventionen über alle Module hinweg","Nutzung von Type-Hints für eine verbesserte Code-Dokumentation und Fehlervermeidung"],"pt":["Formatar código Python com Ruff para melhorar a legibilidade","Aplicar convenções de nomenclatura consistentes em todo o módulo","Utilizar dicas de tipo para melhor documentação de código e prevenção de erros"],"ru":["Форматирование кода Python с помощью Ruff для улучшения читаемости","Применение последовательных соглашений об именах во всех модулях","Использование подсказок типов для лучшей документации кода и предотвращения ошибок"],"ar":["تنسيق شفرة Python باستخدام Ruff لتحسين القراءة","تطبيق اتفاقيات التسمية المتناسقة عبر الوحدات","استخدام تلميحات النوع لأفضل توثيق للشفرة ومنع الأخطاء"]},"limitations":{"en":["Requires Ruff installation and configuration","Limited to Python development environment","Adherence to specific naming conventions and formatting guidelines"],"zh":["需要Ruff的安装和配置","仅限Python开发环境","遵循特定的命名约定和格式化指南"],"ja":["Ruffのインストールと設定が必要","Python開発環境のみ","特定の命名規則とフォーマットガイドラインの遵守"],"ko":["Ruff의 설치 및 구성이 필요함","Python 개발 환경만 해당함","특정 명명 규칙 및 형식화 지침을 준수해야 함"],"es":["Requiere la instalación y configuración de Ruff","Limitado al entorno de desarrollo de Python","Adhesión a convenciones de nomenclatura y pautas de formato específicas"],"fr":["Nécessite l''installation et la configuration de Ruff","Limité à l''environnement de développement Python","Adhésion à des conventions de nommage et des lignes directrices de formatage spécifiques"],"de":["Benötigt die Installation und Konfiguration von Ruff","Begrenzt auf die Python-Entwicklungsumgebung","Einhaltung spezifischer Namenskonventionen und Formatierungsrichtlinien"],"pt":["Exige instalação e configuração do Ruff","Limitado ao ambiente de desenvolvimento Python","Adesão a convenções de nomenclatura e diretrizes de formatação específicas"],"ru":["Требует установки и настройки Ruff","Ограничен средой разработки Python","Соблюдение конкретных соглашений об именах и руководств по форматированию"],"ar":["يتطلب تثبيت وتكوين Ruff","محدود ببيئة تطوير Python","الامتثال لاتفاقيات التسمية والإرشادات التنسيقية المحددة"]},"version":4},"contentHash":"17a2455cc63e7ec13170103276b169829cfe43e1343dd9c9502a5be3afbc60f9","qualityScore":33}');
