INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('meleantonio/ChernyCode/code-style', 'code-style', 'meleantonio', 'ChernyCode', 'community', 'code-style meleantonio ChernyCode community The code-style skill provides Python code formatting and naming conventions for AI agent developers, ensuring consistent and readable code. It supports Ruff formatting and type hints. Python代码风格设置指南，介绍格式化、命名约定和类型提示的最佳实践 Pythonコードスタイル設定ガイド - フォーマット、命名規則、タイプヒントのベストプラクティス 파이썬 코드 스타일 설정 가이드 - 포맷팅, 명명 규칙, 타입 힌트의 베스트 프랙티스 Configura el estilo de código para tus proyectos de Python con Ruff y sigue las mejores prácticas de formato y convenciones de nombre Configurez le style de code pour vos projets Python avec Ruff et suivez les meilleures pratiques de formatage et de conventions de nommage Konfigurieren Sie den Code-Stil für Ihre Python-Projekte mit Ruff und folgen Sie den Best Practices für Formatierung und Namenskonventionen O estilo de código Python é fundamental para a legibilidade e manutenção do código. Aprenda a configurar o estilo de código com Ruff e melhorar a legibilidade do seu código Стиль кода Python имеет важное значение для читаемости и поддержки кода. Узнайте, как настроить стиль кода с помощью Ruff и улучшить читаемость вашего кода أسلوب الكود بايثون هو أمر أساسي للقراءة والصيانة. تعلم كيفية ضبط أسلوب الكود مع Ruff وتحسين قابلية قراءة الكود الخاص بك how to use code-style code-style setup guide python code formatting Ruff formatting tool code-style vs black code-style install python type hints snake_case naming convention code-style best practices Python代码风格 代码格式化 命名约定 类型提示 Ruff Python代码最佳实践 Uses Ruff for formatting with the command `ruff format .` Enforces 4-space indentation and 120-character max line length Supports snake_case naming for functions and variables Utilizes type hints for function parameters and return types Allows for nullable types using `Optional[T]` or `T | None` code-style is a set of guidelines for formatting and naming Python code, including the use of Ruff, snake_case, and type hints to ensure consistency and readability.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('affandar/duroxide-node/npm-publish', 'community', 'affandar', 'duroxide-node', 'affandar/duroxide-node', 'npm-publish', 0, 0, 33, '2026-03-08T01:57:15.502Z', '2026-03-08T02:10:19.081Z', 'e8fa81ccf8359b22933615e1904dfee8ef9149623219c950db603ecda83cf83a', '{"id":"affandar/duroxide-node/npm-publish","name":"npm-publish","description":{"en":"The npm-publish skill automates the publishing process for duroxide-node to npm, ensuring a clean build, passing tests, and updated changelog. It benefits developers by simplifying the release process.","zh":"npm-publish skill 提供了一套预发布检查清单，确保 duroxide-node 可以成功发布到 npm。","ja":"npm-publish スキルは、duroxide-node を npm に公開するための事前公開チェックリストを提供します","ko":"npm-publish 스킬은 duroxide-node를 npm에 배포하기 위한 배포 전 체크리스트를 제공합니다","es":"El agente npm-publish ayuda a los desarrolladores a publicar paquetes en npm, siguiendo un checklist de prepublicación y pruebas automatizadas","fr":"L''agent npm-publish aide les développeurs à publier des paquets sur npm, en suivant une checklist de prépublication et des tests automatisés","de":"Der npm-publish-Agent unterstützt Entwickler bei der Veröffentlichung von Paketen in npm, indem er eine Checklist für die Vorveröffentlichung und automatisierte Tests befolgt","pt":"O npm-publish é um skill que ajuda a publicar pacotes no npm. Ele inclui verificações de pré-publicação, como build limpo e testes.","ru":"ИИ Агенты: npm-publish - это навык, который помогает публиковать пакеты в npm. Он включает проверки перед публикацией, такие как чистая сборка и тесты.","ar":"أداة npm-publish هي مهارة تساعد في نشر الحزم في npm. تشمل عمليات التحقق قبل النشر بناء نظيف واختبارات."},"seo":{"title":{"en":"npm-publish: Automated Package Publishing Guide | AI Agen...","zh":"npm-publish Setup Guide: AIエージェント for Node.js","ja":"npm-publish ベストプラクティス: AIエージェント for JavaScript","ko":"npm-publish 구축 가이드: AI Tools for Node.js 개발","es":"Guía de configuración de npm-publish para desarrolladores","fr":"Guide de mise en place de npm-publish pour les développeurs","de":"Einrichtungsleitfaden für npm-publish für Entwickler","pt":"Guia de Configuração do npm-publish para Desenvolvedores","ru":"ИИ Агенты: Настройка npm-publish для Разработчиков","ar":"إعداد أداة npm-publish للبرمجة"},"description":{"en":"Discover how to streamline your package publishing process with npm-publish. Learn the pre-publish checklist and best practices for a seamless release","zh":"了解如何使用 npm-publish skill 将 duroxide-node 发布到 npm，包括预发布检查清单和技术要求","ja":"npm-publish スキルを使用して duroxide-node を npm に公開する方法を学びましょう。事前公開チェックリストとテクニカル要件を含みます","ko":"npm-publish 스킬을 사용하여 duroxide-node를 npm에 배포하는 방법에 대해 알아보세요. 배포 전 체크리스트와 기술 요구 사항을 포함합니다","es":"Aprende a publicar paquetes en npm con nuestra guía paso a paso, incluyendo pruebas y checklist de prepublicación","fr":"Découvrez comment publier des paquets sur npm avec notre guide étape par étape, y compris des tests et une checklist de prépublication","de":"Erfahren Sie, wie Sie Pakete in npm veröffentlichen, mit unserer Schritt-für-Schritt-Anleitung, einschließlich Tests und Checklist für die Vorveröffentlichung","pt":"Aprenda a publicar pacotes no npm com o skill npm-publish. Siga nosso guia passo a passo para uma configuração perfeita.","ru":"Узнайте, как публиковать пакеты в npm с помощью навыка npm-publish. Следуйте нашему пошаговому руководству для идеальной настройки.","ar":"تعلم كيفية نشر الحزم في npm باستخدام مهارة npm-publish. اتبع دليلنا خطوة بخطوة للحصول على إعداد مثالي."},"definition":{"en":"npm-publish is a skill that automates the publishing of packages to npm, following a pre-publish checklist that includes clean build, tests, and changelog updates","zh":"npm-publish 是一种 AI 工具，帮助开发者将 Node.js 包发布到 npm。","ja":"npm-publish は、開発者が Node.js パッケージを npm に公開するのに役立つ AI エージェントです","ko":"npm-publish는 개발자가 Node.js 패키지를 npm에 배포하는 것을 도와주는 AI 도구입니다","es":"npm-publish es una herramienta de línea de comandos que facilita la publicación de paquetes en npm","fr":"npm-publish est un outil en ligne de commande qui facilite la publication de paquets sur npm","de":"npm-publish ist ein Kommandozeilen-Tool, das die Veröffentlichung von Paketen in npm erleichtert","pt":"O que é npm-publish? É um skill que automatiza o processo de publicação de pacotes no npm.","ru":"Что такое npm-publish? Это навык, который автоматизирует процесс публикации пакетов в npm.","ar":"ما هي أداة npm-publish؟ هي مهارة تautomatiza عملية نشر الحزم في npm."},"features":{"en":["Runs cargo clippy with zero warnings for clean build","Executes napi build with release flag for optimized package","Passes 52 tests via npm run test:all with DATABASE_URL in .env","Updates CHANGELOG.md with new version entries following Keep a Changelog guidelines","Supports pre-publish checklist for verification before release","Utilizes npx napi build for platform-specific release builds"],"zh":["预发布检查清单","Clippy 和 napi 构建支持","测试用例运行","Changelog 更新","支持多平台发布","自动化发布流程"],"ja":["事前公開チェックリスト","Clippy と napi ビルドのサポート","テストケースの実行","Changelog の更新","マルチプラットフォーム公開のサポート","自動公開プロセス"],"ko":["배포 전 체크리스트","Clippy 및 napi 빌드 지원","테스트 케이스 실행","Changelog 업데이트","다중 플랫폼 배포 지원","자동 배포 프로세스"],"es":["Verificación de compilación limpia con cargo clippy","Ejecución de pruebas automatizadas con npm run test:all","Actualización de changelog con entradas para nuevas versiones","Compatibilidad con napi para construir y publicar paquetes","Soporte para plataforma y Release con npx napi build"],"fr":["Vérification de la construction propre avec cargo clippy","Exécution de tests automatisés avec npm run test:all","Mise à jour du changelog avec des entrées pour les nouvelles versions","Compatibilité avec napi pour construire et publier des paquets","Prise en charge de la plateforme et de la version avec npx napi build"],"de":["Überprüfung der sauberen Kompilierung mit cargo clippy","Ausführung von automatisierten Tests mit npm run test:all","Aktualisierung des Changelogs mit Einträgen für neue Versionen","Kompatibilität mit napi zum Erstellen und Veröffentlichen von Paketen","Unterstützung für Plattform und Release mit npx napi build"],"pt":["Verificação de build limpo com Cargo Clippy","Execução de testes com npm run test:all","Atualização do changelog com entrada para a nova versão","Suporte à plataforma napi","Build de release com npx napi build --platform --release"],"ru":["Проверка чистой сборки с Cargo Clippy","Выполнение тестов с npm run test:all","Обновление changelog с записью для новой версии","Поддержка платформы napi","Сборка релиза с npx napi build --platform --release"],"ar":["التحقق من بناء نظيف مع Cargo Clippy","تشغيل الاختبارات مع npm run test:all","تحديث سجل التغييرات مع إدخال للنسخة الجديدة","دعم منصة napi","بناء الإصدار مع npx napi build --platform --release"]},"keywords":{"en":["how to use npm-publish","npm-publish setup guide","automated package publishing","npm-publish vs manual publishing","npm-publish install","what is npm-publish","npm-publish best practices","npm-publish alternative","npm-publish tutorial"],"zh":["npm-publish","AIエージェント","Node.js 包发布","npm 包管理","JavaScript 开发","自动化发布","Clippy","napi","Changelog"],"ja":["npm-publish","AIエージェント","Node.js パッケージ公開","npm パッケージ管理","JavaScript 開発","自動公開","Clippy","napi","Changelog"],"ko":["npm-publish","AI Tools","Node.js 패키지 배포","npm 패키지 관리","JavaScript 개발","자동 배포","Clippy","napi","Changelog"],"es":["npm publish","publicar paquetes en npm","checklist de prepublicación","pruebas automatizadas","napi","cargo clippy","changelog","desarrollo de software"],"fr":["npm publish","publier des paquets sur npm","checklist de prépublication","tests automatisés","napi","cargo clippy","changelog","développement de logiciels"],"de":["npm publish","Pakete in npm veröffentlichen","Checklist für die Vorveröffentlichung","automatisierte Tests","napi","cargo clippy","Changelog","Softwareentwicklung"],"pt":["npm publish","publicar pacotes npm","configurar npm-publish","desenvolvedores npm","ferramentas de desenvolvimento npm","npm-publish para iniciantes"],"ru":["npm публикация","опубликовать пакеты в npm","настроить npm-publish","разработчики npm","инструменты разработки npm","npm-publish для начинающих"],"ar":["نشر الحزم في npm","نشر حزمة في npm","إعداد أداة npm-publish","مطورو npm","أدوات تطوير npm","أداة npm-publish للمبتدئين"]}},"owner":"affandar","repo":"duroxide-node","repoPath":"affandar/duroxide-node","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.502Z","topics":[],"category":"community","skillMd":{"name":"npm-publish","description":"Publishing duroxide-node to npm. Use when releasing a new version, building platform binaries, or publishing to the npm registry.","bodyPreview":"# Publishing duroxide-node to npm\n\n## Pre-Publish Checklist\n\nBefore publishing, verify ALL of the following:\n\n### 1. Clean Build\n\n```bash\ncd duroxide-node\n\n# Clippy — must pass with zero warnings\ncargo clippy --all-targets\n\n# Release build via napi\nnpx napi build --platform --release\n```\n\n### 2. Tests Pass\n\n```bash\n# All 52 tests must pass (requires DATABASE_URL in .env)\nnpm run test:all\n```\n\n### 3. Changelog Updated\n\n- `CHANGELOG.md` must have an entry for the new version\n- Follow [Keep a Chang","body":"# Publishing duroxide-node to npm\n\n## Pre-Publish Checklist\n\nBefore publishing, verify ALL of the following:\n\n### 1. Clean Build\n\n```bash\ncd duroxide-node\n\n# Clippy — must pass with zero warnings\ncargo clippy --all-targets\n\n# Release build via napi\nnpx napi build --platform --release\n```\n\n### 2. Tests Pass\n\n```bash\n# All 52 tests must pass (requires DATABASE_URL in .env)\nnpm run test:all\n```\n\n### 3. Changelog Updated\n\n- `CHANGELOG.md` must have an entry for the new version\n- Follow [Keep a Changelog](https://keepachangelog.com/en/1.1.0/) format\n- Include all Added/Changed/Fixed/Removed sections as applicable\n\n### 4. README Points to Changelog\n\nVerify `README.md` contains a link to `CHANGELOG.md`:\n```markdown\n> See [CHANGELOG.md](CHANGELOG.md) for release notes.\n```\n\n### 5. Version Bumped\n\nUpdate version in `package.json` and all platform `package.json` files:\n\n```bash\n# Bump version (also updates npm/npm/*/package.json)\nnpx napi version\n```\n\nOr manually update `package.json` `version` field and ensure `optionalDependencies` versions match.\n\n## Build Platform Binaries\n\nThree platforms are supported:\n\n### darwin-arm64 (macOS Apple Silicon) — native build\n```bash\nnpx napi build --platform --release\ncp duroxide.darwin-arm64.node npm/npm/darwin-arm64/\n```\n\n### darwin-x64 (macOS Intel) — native cross-compile\n```bash\nrustup target add x86_64-apple-darwin  # one-time\nnpx napi build --platform --release --target x86_64-apple-darwin\ncp duroxide.darwin-x64.node npm/npm/darwin-x64/\n```\n\n### linux-x64-gnu — Docker build\n```bash\ndocker run --rm -v \"$(pwd):/build\" -w /build --platform linux/amd64 rust:latest bash -c \"\n  curl -fsSL https://deb.nodesource.com/setup_22.x | bash - &&\n  apt-get install -y nodejs &&\n  npm install &&\n  npx napi build --platform --release --target x86_64-unknown-linux-gnu\n\"\ncp duroxide.linux-x64-gnu.node npm/npm/linux-x64-gnu/\n```\n\n### win32-x64-msvc (Windows) — Docker + cargo-xwin (optional)\nNot currently built. Can be added with `cargo-xwin` in a Linux Docker container.\n\n## Publish Order\n\nPlatform packages MUST be published before the main package (npm resolves optionalDependencies at install time).\n\n### 1. Publish platform packages\n```bash\n# Requires an npm Automation token (bypasses 2FA)\nAUTH=\"--//registry.npmjs.org/:_authToken=<TOKEN>\"\n\ncd npm/npm/darwin-arm64 && npm publish --access public $AUTH && cd -\ncd npm/npm/darwin-x64   && npm publish --access public $AUTH && cd -\ncd npm/npm/linux-x64-gnu && npm publish --access public $AUTH && cd -\n```\n\n### 2. Publish main package\n```bash\ncd duroxide-node\nnpm publish --access public $AUTH\n```\n\nThe `prepublishOnly` script runs `napi prepublish -t npm` automatically, which verifies platform binaries exist.\n\n### 3. Verify\n```bash\n# Test in a clean directory\ncd /tmp && mkdir test-duroxide && cd test-duroxide\nnpm install duroxide\nnode -e \"const d = require(''duroxide''); console.log(''loaded:'', Object.keys(d).slice(0,5))\"\nrm -rf /tmp/test-duroxide\n```\n\n## npm Authentication\n\n- Publishing requires an **Automation** token (bypasses 2FA)\n- Create at: https://www.npmjs.com/settings/<username>/tokens\n- Token type: **Automation** (not Granular, unless \"bypass 2FA\" is enabled)\n- Never commit tokens to source code\n\n## Version Cascade\n\nWhen bumping versions, update `optionalDependencies` in the main `package.json` to match:\n\n```json\n\"optionalDependencies\": {\n  \"duroxide-darwin-arm64\": \"<NEW_VERSION>\",\n  \"duroxide-darwin-x64\": \"<NEW_VERSION>\",\n  \"duroxide-linux-x64-gnu\": \"<NEW_VERSION>\",\n  \"duroxide-win32-x64-msvc\": \"<NEW_VERSION>\"\n}\n```\n\n## Summary Checklist\n\n- [ ] `cargo clippy --all-targets` — zero warnings\n- [ ] `npx napi build --platform --release` — clean build\n- [ ] `npm run test:all` — all tests pass\n- [ ] `CHANGELOG.md` — updated for new version\n- [ ] `README.md` — links to CHANGELOG.md\n- [ ] Version bumped in `package.json` + platform packages\n- [ ] Platform binaries built and copied to `npm/npm/*/`\n- [ ] Platform packages published first\n- [ ] Main package published\n- [ ] Verified with `npm install duroxide` in a clean directory\n"},"lastSynced":"2026-03-08T02:10:19.081Z","agentAnalysis":{"suitability":{"en":"Ideal for Node.js Agents needing streamlined package publishing to npm.","zh":"适用于需要将软件包发布到npm的Node.js代理，能够简化包发布过程。","ja":"npmへのパッケージ公開をストリームライン化する必要があるNode.jsエージェントに最適です。","ko":"npm에 패키지를发布할 필요가 있는 Node.js 에이전트에게 이상적이며, 패키지 게시 과정을 간소화 할 수 있습니다.","es":"Ideal para agentes de Node.js que necesitan publicación de paquetes optimizada en npm.","fr":"Idéal pour les agents Node.js nécessitant une publication de paquet optimisée sur npm.","de":"Ideal für Node.js-Agents, die eine optimierte Paketveröffentlichung auf npm benötigen.","pt":"Ideal para Agentes Node.js que necessitam de publicação de pacotes otimizada para o npm.","ru":"Идеально для агентов Node.js, требующих упрощенной публикации пакетов в npm.","ar":"مثالي لعميل Node.js الذي يحتاج إلى نشر حزمة مبسط إلى npm."},"recommendation":{"en":"Empowers agents to automate the publishing process for duroxide-node to npm, ensuring a clean build via Cargo and napi, passing tests with npm run test:all, and updated changelog in CHANGELOG.md, leveraging platforms like npm and utilizing tools such as Clippy for zero-warning builds.","zh":"赋予代理自动化 duroxide-node 到 npm 的发布过程的能力，确保通过 Cargo 和 napi 进行干净的构建，通过 npm run test：all 通过测试，并在 CHANGELOG.md 中更新更改日志，利用如 npm 的平台，并利用如 Clippy 的工具进行零警告构建。","ja":"duroxide-nodeをnpmに公開するプロセスを自動化するエージェントの能力を提供し、Cargoとnapiを使用したクリーンなビルドを保証し、npm run test：allを使用したテストをパスし、CHANGELOG.mdに更新された変更ログを提供し、npmなどのプラットフォームを利用し、Clippyなどのツールを使用したゼロ警告ビルドを実現します。","ko":"에이전트가 duroxide-node를 npm에 게시하는 프로세스를 자동화 할 수 있는 능력을 제공하여, Cargo와 napi를 사용한 깨끗한 빌드를 보장하고, npm run test：all을 사용한 테스트를 통과시키고, CHANGELOG.md에 업데이트된 변경 로그를 제공하며, npm과 같은 플랫폼을 활용하고, Clippy와 같은 도구를 사용한 제로 경고 빌드를 달성합니다.","es":"Habilita a los agentes a automatizar el proceso de publicación para duroxide-node en npm, garantizando una compilación limpia a través de Cargo y napi, pasando pruebas con npm run test:all y un registro de cambios actualizado en CHANGELOG.md, aprovechando plataformas como npm y utilizando herramientas como Clippy para compilaciones sin advertencias.","fr":"Permet aux agents d''automatiser le processus de publication pour duroxide-node sur npm, en garantissant une construction propre via Cargo et napi, en passant des tests avec npm run test:all et en mettant à jour le journal des modifications dans CHANGELOG.md, en exploitant des plates-formes comme npm et en utilisant des outils tels que Clippy pour des constructions sans avertissements.","de":"Ermöglicht es Agenten, den Veröffentlichungsprozess für duroxide-node auf npm zu automatisieren, wodurch eine saubere Erstellung über Cargo und napi gewährleistet wird, Tests mit npm run test:all bestehen und das Änderungsprotokoll in CHANGELOG.md aktualisiert wird, wobei Plattformen wie npm genutzt und Tools wie Clippy für warnungsfreie Erstellungen eingesetzt werden.","pt":"Habilita os agentes a automatizar o processo de publicação do duroxide-node para o npm, garantindo uma compilação limpa via Cargo e napi, passando nos testes com npm run test:all e atualizando o changelog em CHANGELOG.md, aproveitando plataformas como npm e utilizando ferramentas como Clippy para compilações sem avisos.","ru":"Наделяет агентов возможностью автоматизировать процесс публикации duroxide-node в npm, обеспечивая чистую сборку через Cargo и napi, проходя тесты с npm run test:all и обновляя журнал изменений в CHANGELOG.md, используя платформы như npm и инструменты như Clippy для сборок без предупреждений.","ar":"تمكن العملاء من автоматизة عملية النشر لمكتبة duroxide-node إلى npm، مما يضمن بناء نظيف من خلال Cargo و napi، وتمرير الاختبارات باستخدام npm run test:all، وتحديث سجل التغييرات في CHANGELOG.md، واستخدام منصات مثل npm وأدوات مثل Clippy للحصول على بناء بدون تحذيرات."},"useCases":{"en":["Automating package publishing to npm","Validating pre-publish checks for clean builds and passing tests","Updating changelogs for new versions"],"zh":["自动将包发布到npm","验证预发布检查以获得干净的构建和通过测试","更新更改日志以获取新版本"],"ja":["npmへのパッケージ公開を自動化する","クリーンなビルドとテストのパスを保証するためにプリパブリッシュチェックを検証する","新しいバージョン用の変更ログを更新する"],"ko":["npm에 패키지를 자동으로 게시하는 것","깨끗한 빌드와 테스트를 통과시키기 위해 사전 게시 확인을 검증하는 것","새 버전을 위한 변경 로그를 업데이트하는 것"],"es":["Automatización de la publicación de paquetes en npm","Validación de la limpieza de las compilaciones y aprobación de pruebas antes de la publicación","Actualización de los registros de cambios para nuevas versiones"],"fr":["Automatisation de la publication de paquets sur npm","Validation des contrôles préalables à la publication pour des constructions propres et des tests réussis","Mise à jour des journaux des modifications pour les nouvelles versions"],"de":["Automatisierung der Paketveröffentlichung auf npm","Validierung von Vorbereitungstests für saubere Erstellungen und bestandene Tests","Aktualisierung der Änderungsprotokolle für neue Versionen"],"pt":["Automatizar a publicação de pacotes para o npm","Validar verificações pré-publicação para compilações limpas e testes aprovados","Atualizar os registros de alterações para novas versões"],"ru":["Автоматизировать публикацию пакетов в npm","Проверять предварительные проверки публикации для чистых сборок и проходящих тестов","Обновлять журналы изменений для новых версий"],"ar":["توفير آلي لنشر الحزم إلى npm","التحقق من عمليات الفحص قبل النشر لضمان بناء نظيف وتمرير الاختبارات","تحديث سجلات التغييرات للإصدارات الجديدة"]},"limitations":{"en":["Requires npm and Cargo installation","Needs .env file with DATABASE_URL for testing","Specific to duroxide-node package"],"zh":["需要npm和Cargo的安装","需要.env文件，包含DATABASE_URL用于测试","特定于duroxide-node包"],"ja":["npmとCargoのインストールが必要",".envファイルが必要で、DATABASE_URLがテストに含まれている","duroxide-nodeパッケージに特有"],"ko":["npm과 Cargo의 설치가 필요합니다.",".env 파일이 필요하며, DATABASE_URL이 테스트에 포함되어 있습니다.","duroxide-node 패키지에 특정"],"es":["Requiere la instalación de npm y Cargo","Necesita un archivo .env con DATABASE_URL para pruebas","Específico para el paquete duroxide-node"],"fr":["Nécessite l''installation de npm et de Cargo","Nécessite un fichier .env avec DATABASE_URL pour les tests","Spécifique au paquet duroxide-node"],"de":["Benötigt die Installation von npm und Cargo","Benötigt eine Datei .env mit DATABASE_URL für Tests","Spezifisch für das Paket duroxide-node"],"pt":["Requer a instalação do npm e do Cargo","Necessita de um arquivo .env com DATABASE_URL para testes","Específico para o pacote duroxide-node"],"ru":["Требует установки npm и Cargo","Требует файла .env с DATABASE_URL для тестирования","Специфичен для пакета duroxide-node"],"ar":["يتطلب تثبيت npm و Cargo","يحتاج إلى ملف .env مع DATABASE_URL للاختبارات","محدد لحزمة duroxide-node"]},"version":4},"contentHash":"e8fa81ccf8359b22933615e1904dfee8ef9149623219c950db603ecda83cf83a","qualityScore":33}');
