INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('affandar/duroxide-node/npm-publish', 'npm-publish', 'affandar', 'duroxide-node', 'community', 'npm-publish affandar duroxide-node community The npm-publish skill automates the publishing process for duroxide-node to npm, ensuring a clean build, passing tests, and updated changelog. It benefits developers by simplifying the release process. npm-publish skill 提供了一套预发布检查清单，确保 duroxide-node 可以成功发布到 npm。 npm-publish スキルは、duroxide-node を npm に公開するための事前公開チェックリストを提供します npm-publish 스킬은 duroxide-node를 npm에 배포하기 위한 배포 전 체크리스트를 제공합니다 El agente npm-publish ayuda a los desarrolladores a publicar paquetes en npm, siguiendo un checklist de prepublicación y pruebas automatizadas L''agent npm-publish aide les développeurs à publier des paquets sur npm, en suivant une checklist de prépublication et des tests automatisés Der npm-publish-Agent unterstützt Entwickler bei der Veröffentlichung von Paketen in npm, indem er eine Checklist für die Vorveröffentlichung und automatisierte Tests befolgt O npm-publish é um skill que ajuda a publicar pacotes no npm. Ele inclui verificações de pré-publicação, como build limpo e testes. ИИ Агенты: npm-publish - это навык, который помогает публиковать пакеты в npm. Он включает проверки перед публикацией, такие как чистая сборка и тесты. أداة npm-publish هي مهارة تساعد في نشر الحزم في npm. تشمل عمليات التحقق قبل النشر بناء نظيف واختبارات. how to use npm-publish npm-publish setup guide automated package publishing npm-publish vs manual publishing npm-publish install what is npm-publish npm-publish best practices npm-publish alternative npm-publish tutorial npm-publish AIエージェント Node.js 包发布 npm 包管理 JavaScript 开发 自动化发布 Clippy napi Changelog Runs cargo clippy with zero warnings for clean build Executes napi build with release flag for optimized package Passes 52 tests via npm run test:all with DATABASE_URL in .env Updates CHANGELOG.md with new version entries following Keep a Changelog guidelines Supports pre-publish checklist for verification before release Utilizes npx napi build for platform-specific release builds npm-publish is a skill that automates the publishing of packages to npm, following a pre-publish checklist that includes clean build, tests, and changelog updates');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('technologi-service/arepaflow/og-image-generation', 'community', 'technologi-service', 'arepaflow', 'technologi-service/arepaflow', 'og-image-generation', 0, 0, 33, '2026-03-08T01:57:15.502Z', '2026-03-08T02:10:20.627Z', 'a4e1e702dc236f3689987607516916bd7438b66e78eaac936a3878c86feb9141', '{"id":"technologi-service/arepaflow/og-image-generation","name":"og-image-generation","description":{"en":"The og-image-generation skill generates dynamic social preview images using Next.js file conventions and the next/og library, benefiting developers who need server-rendered JSX images cached at build time.","zh":"OG 图像生成允许您使用 Next.js 文件约定和 next/og 库生成动态社交预览图像。服务器渲染的 JSX 图像在构建时缓存","ja":"OG 画像生成は、Next.js ファイル規約と next/og ライブラリを使用して動的なソーシャルプレビュー画像を生成します。サーバー側レンダリングの JSX 画像はビルド時にキャッシュされます","ko":"OG 이미지 생성은 Next.js 파일 규약과 next/og 라이브러리를 사용하여 동적 소셜 미리보기 이미지를 생성합니다. 서버 렌더링 JSX 이미지는 빌드 시 캐시됩니다","es":"La generación de imágenes OG permite crear vistas previas dinámicas para redes sociales con Next.js y la biblioteca next/og","fr":"La génération d''images OG permet de créer des aperçus dynamiques pour les réseaux sociaux avec Next.js et la bibliothèque next/og","de":"Die OG-Bildgenerierung ermöglicht das Erstellen von dynamischen Vorschau-Bildern für soziale Netzwerke mit Next.js und der Bibliothek next/og","pt":"Geração de imagens de previsão social dinâmicas usando Next.js e a biblioteca next/og. Imagens renderizadas pelo servidor e armazenadas em cache no momento da compilação.","ru":"Генерация динамических изображений предпросмотра социальных сетей с помощью Next.js и библиотеки next/og. Изображения, отображаемые на сервере и кэшируемые во время сборки, с ИИ Агенты","ar":"generación صور معاينة الإجتماعية ديناميكية باستخدام Next.js و مكتبة next/og. الصور المُحسّنة على الخادم وتخزينها في ذاكرة التخزين المؤقت في وقت الترجمة، مع 