INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('technologi-service/arepaflow/og-image-generation', 'og-image-generation', 'technologi-service', 'arepaflow', 'community', 'og-image-generation technologi-service arepaflow community The og-image-generation skill generates dynamic social preview images using Next.js file conventions and the next/og library, benefiting developers who need server-rendered JSX images cached at build time. OG 图像生成允许您使用 Next.js 文件约定和 next/og 库生成动态社交预览图像。服务器渲染的 JSX 图像在构建时缓存 OG 画像生成は、Next.js ファイル規約と next/og ライブラリを使用して動的なソーシャルプレビュー画像を生成します。サーバー側レンダリングの JSX 画像はビルド時にキャッシュされます OG 이미지 생성은 Next.js 파일 규약과 next/og 라이브러리를 사용하여 동적 소셜 미리보기 이미지를 생성합니다. 서버 렌더링 JSX 이미지는 빌드 시 캐시됩니다 La generación de imágenes OG permite crear vistas previas dinámicas para redes sociales con Next.js y la biblioteca next/og La génération d''images OG permet de créer des aperçus dynamiques pour les réseaux sociaux avec Next.js et la bibliothèque next/og Die OG-Bildgenerierung ermöglicht das Erstellen von dynamischen Vorschau-Bildern für soziale Netzwerke mit Next.js und der Bibliothek next/og Geração de imagens de previsão social dinâmicas usando Next.js e a biblioteca next/og. Imagens renderizadas pelo servidor e armazenadas em cache no momento da compilação. Генерация динамических изображений предпросмотра социальных сетей с помощью Next.js и библиотеки next/og. Изображения, отображаемые на сервере и кэшируемые во время сборки, с ИИ Агенты generación صور معاينة الإجتماعية ديناميكية باستخدام Next.js و مكتبة next/og. الصور المُحسّنة على الخادم وتخزينها في ذاكرة التخزين المؤقت في وقت الترجمة، مع وكلاء الذكاء الاصطناعي how to use og-image-generation og-image-generation setup guide next/og library tutorial dynamic social preview image generation og-image-generation vs static images og-image-generation install what is og-image-generation og-image-generation alternative og-image-generation best practices OG 图像生成 Next.js next/og 动态社交预览图像 服务器渲染 JSX 图像 缓存 性能优化 Generates dynamic social preview images using Next.js file conventions Utilizes the next/og library for server-rendered JSX images Caches images at build time for improved performance Supports curl requests for image generation via API Compatible with Next.js 16 and Drizzle ORM og-image-generation is a technique for generating dynamic social preview images using Next.js and the next/og library, allowing for server-rendered JSX images cached at build time.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('AI-Robot-SW/pedestrian-companion-robot/background-testing', 'community', 'AI-Robot-SW', 'pedestrian-companion-robot', 'AI-Robot-SW/pedestrian-companion-robot', 'background-testing', 0, 0, 33, '2026-03-08T01:57:15.510Z', '2026-03-08T02:10:25.244Z', 'adf6d15a1a54a7409a781e822322be7d95490c2c538e54ce134139d2211de293', '{"id":"AI-Robot-SW/pedestrian-companion-robot/background-testing","name":"background-testing","description":{"en":"The background-testing skill provides rules and patterns for writing pytest tests for Backgrounds in OM Cortex Runtime, ensuring consistent testing and hardware independence.","zh":"背景测试是OM Cortex Runtime中的一个重要组成部分，需要遵循特定的规则和结构","ja":"Background TestingはOM Cortex Runtimeの重要なコンポーネントであり、特定のルールと構造に従う必要があります","ko":"백그라운드 테스팅은 OM Cortex Runtime의 중요한 구성 요소이며 특정 규칙과 구조를 따라야 합니다","es":"Guía técnica para pruebas de fondo en AI Agent con pytest y OM Cortex Runtime","fr":"Guide technique pour les tests d''arrière-plan avec les outils d''IA et pytest","de":"Technische Anleitung für Hintergrundtests in KI-Agents mit pytest","pt":"Este guia fornece regras e padrões para escrever testes pytest para Backgrounds em OM Cortex Runtime, garantindo testes consistentes e sem hardware","ru":"Этот гид предоставляет правила и шаблоны для написания тестов pytest для Фонов в OM Cortex Runtime, гарантируя последовательные тесты и отсутствие аппаратного обеспечения","ar":"يوفر هذا الدليل قواعد وأنماط لكتابة اختبارات pytest للخلفيات في برنامج OM Cortex Runtime، مما يضمن اختبارات متسقة وبدون أجهزة"},"seo":{"title":{"en":"background-testing: Pytest Testing Guide for AI Agents","zh":"背景测试配置指南","ja":"Background Testing Setup Guide - AIエージェント","ko":"백그라운드 테스팅 설정 가이드","es":"Guía de configuración para pruebas de fondo en AI Agent","fr":"Guide de configuration pour les tests d''arrière-plan avec...","de":"Konfigurationsleitfaden für Hintergrundtests in KI-Agents","pt":"Guia de Configuração de Testes de Fundo","ru":"ИИ Агенты: Настройка Фонового Тестирования","ar":"إعداد اختبارات الخلفية للوكلاء الذكاء الاصطناعي"},"description":{"en":"Learn how to write consistent pytest tests for Backgrounds in OM Cortex Runtime. Get started with our background-testing setup guide and master testing witho...","zh":"了解背景测试的规则、结构和模式，编写高质量的pytest测试用例","ja":"AIエージェントのBackground Testingを実装するためのベストプラクティスとテストガイド","ko":"백그라운드 테스팅을 위한 규칙, 구조 및 패턴을 배우고 pytest 테스트 케이스를 작성하세요","es":"Aprende a configurar pruebas de fondo para AI Agent con pytest y OM Cortex Runtime","fr":"Découvrez comment configurer les tests d''arrière-plan pour les outils d''IA avec pytest et OM Cortex Runtime","de":"Erfahren Sie, wie Sie Hintergrundtests für KI-Agents mit pytest und OM Cortex Runtime konfigurieren","pt":"Aprenda a configurar testes de fundo para OM Cortex Runtime com pytest, incluindo regras e padrões para testes consistentes","ru":"Получите информацию о настройке фонового тестирования для OM Cortex Runtime с помощью pytest, включая правила и шаблоны для последовательных тестов","ar":"تعرف على كيفية إعداد اختبارات الخلفية لبرنامج OM Cortex Runtime باستخدام pytest، بما في ذلك القواعد والأنماط لاختبارات متسقة"},"definition":{"en":"background-testing is a set of guidelines for writing pytest tests for Backgrounds in OM Cortex Runtime, focusing on consistency and hardware independence.","zh":"背景测试是指在OM Cortex Runtime中测试Background的初始化和运行","ja":"Background Testingは、OM Cortex RuntimeにおけるBackgroundの初期化と実行をテストすること","ko":"백그라운드 테스팅은 OM Cortex Runtime에서 백그라운드의 초기화 및 실행을 테스트하는 것을 의미합니다","es":"Pruebas de fondo: proceso de verificación de la inicialización y ejecución de proveedores en AI Agent","fr":"Tests d''arrière-plan : processus de vérification de l''initialisation et de l''exécution des fournisseurs dans les outils d''IA","de":"Hintergrundtests: Prozess zur Überprüfung der Initialisierung und Ausführung von Anbietern in KI-Agents","pt":"Testes de fundo são testes automatizados para Backgrounds em OM Cortex Runtime, escritos com pytest","ru":"Фоновое тестирование - это автоматизированные тесты для Фонов в OM Cortex Runtime, написанные с помощью pytest","ar":"اختبارات الخلفية هي اختبارات آلية للخلفيات في برنامج OM Cortex Runtime، مكتوبة باستخدام pytest"},"features":{"en":["Initializes and starts Providers in `__init__`","Runs pytest tests without hardware dependency","Ensures consistent testing for Backgrounds in OM Cortex Runtime","Follows implementation rules for test assumptions","Constructs Providers in `__init__` for reliable testing"],"zh":["遵循特定的实现规则和测试假设","在__init__中初始化和启动Provider","使用pytest测试框架","模拟Provider以避免硬件依赖","确保测试的一致性和可靠性"],"ja":["特定の実装ルールとテスト仮定に従う","__init__でProviderを初期化と起動する","pytestテストフレームワークを使用する","Providerをモックしてハードウェア依存を避ける","テストの一貫性と信頼性を確保する"],"ko":["특정 구현 규칙과 테스트 가정을 따름","__init__에서 Provider를 초기화 및 시작","pytest 테스트 프레임워크 사용","Provider를 모의하여 하드웨어 종속성을 피함","테스트의 일관성 및 신뢰성을 보장"],"es":["Inicialización de proveedores en __init__","Uso de pytest para pruebas de fondo","Ejecución de pruebas sin hardware","Compatibilidad con OM Cortex Runtime","Seguimiento de reglas y patrones para pruebas de fondo"],"fr":["Initialisation des fournisseurs dans __init__","Utilisation de pytest pour les tests d''arrière-plan","Exécution des tests sans matériel","Compatibilité avec OM Cortex Runtime","Suivi des règles et des modèles pour les tests d''arrière-plan"],"de":["Initialisierung von Anbietern in __init__","Verwendung von pytest für Hintergrundtests","Ausführung von Tests ohne Hardware","Kompatibilität mit OM Cortex Runtime","Verfolgung von Regeln und Mustern für Hintergrundtests"],"pt":["Inicialização e inicialização de Providers em __init__","Testes consistentes com pytest","Mocking de Providers para testes sem hardware","Padrões para testes de Backgrounds em OM Cortex Runtime","Regras para escrita de testes pytest para Backgrounds"],"ru":["Инициализация и запуск Providers в __init__","Последовательные тесты с помощью pytest","Мокирование Providers для тестов без аппаратного обеспечения","Шаблоны для тестов Фонов в OM Cortex Runtime","Правила для написания тестов pytest для Фонов"],"ar":["ت初ياز وتشغيل المزودين في __init__","اختبارات متسقة باستخدام pytest","تمثيل المزودين لاختبارات بدون أجهزة","أنماط لاختبارات الخلفيات في برنامج OM Cortex Runtime","قواعد لكتابة اختبارات pytest للخلفيات"]},"keywords":{"en":["how to use background-testing","background-testing setup guide","pytest testing for Backgrounds","OM Cortex Runtime testing","background-testing vs unittest","background-testing install for AI Agents"],"zh":["背景测试","OM Cortex Runtime","pytest","Background测试","Provider模拟","测试一致性","AI工具","AIエージェント"],"ja":["Background Testing","OM Cortex Runtime","pytest","Backgroundテスト","Providerモック","テストの一貫性","AIエージェント","AIツール"],"ko":["백그라운드 테스팅","OM Cortex Runtime","pytest","백그라운드 테스트","Provider 모의","테스트 일관성","AI 에이전트","AI 도구"],"es":["pruebas de fondo AI Agent","pytest para pruebas de fondo","OM Cortex Runtime","inicialización de proveedores","tests de fondo sin hardware","guía de configuración para pruebas de fondo"],"fr":["tests d''arrière-plan outils d''IA","pytest pour les tests d''arrière-plan","OM Cortex Runtime","initialisation des fournisseurs","tests d''arrière-plan sans matériel","guide de configuration pour les tests d''arrière-plan"],"de":["Hintergrundtests KI-Agents","pytest für Hintergrundtests","OM Cortex Runtime","Initialisierung von Anbietern","Hintergrundtests ohne Hardware","Konfigurationsleitfaden für Hintergrundtests"],"pt":["testes de fundo","pytest","OM Cortex Runtime","Backgrounds","testes automatizados","desenvolvimento de software","teste de unidade","teste de integração"],"ru":["ИИ Агенты","фоновое тестирование","pytest","OM Cortex Runtime","Фоны","автоматизированные тесты","разработка программного обеспечения","юнит-тестирование","интеграционное тестирование"],"ar":["الوكلاء الذكاء الاصطناعي","اختبارات الخلفية","pytest","برنامج OM Cortex Runtime","الخلفيات","اختبارات آلية","تطوير البرمجيات","اختبار الوحدة","اختبار التكامل"]}},"owner":"AI-Robot-SW","repo":"pedestrian-companion-robot","repoPath":"AI-Robot-SW/pedestrian-companion-robot","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.510Z","topics":[],"category":"community","skillMd":{"name":"background-testing","description":"Rules and guidelines for writing pytest tests for Backgrounds in OM Cortex Runtime","bodyPreview":"# Background Testing Guide\n\nThis document provides rules, structure, and patterns for writing pytest tests for **Backgrounds** in OM Cortex Runtime. Use this guide when adding or reviewing Background tests so that tests are consistent, mock the Provider used inside the Background, and run without hardware.\n\n## Implementation rule (test assumption)\n\n**REQUIRED**: Every Background must **initialize and start** its Provider(s) in `__init__`, not in `run()`. That is:\n\n- In `__init__`: construct the","body":"# Background Testing Guide\n\nThis document provides rules, structure, and patterns for writing pytest tests for **Backgrounds** in OM Cortex Runtime. Use this guide when adding or reviewing Background tests so that tests are consistent, mock the Provider used inside the Background, and run without hardware.\n\n## Implementation rule (test assumption)\n\n**REQUIRED**: Every Background must **initialize and start** its Provider(s) in `__init__`, not in `run()`. That is:\n\n- In `__init__`: construct the Provider with config-derived arguments, then call `provider.start()` (or the provider’s start API, e.g. `start_stream()`).\n- Do **not** defer `start()` to `run()`.\n\nWhen writing tests, assert that `provider.start()` (or equivalent) is called **once** during Background construction (e.g. `mock_provider_instance.start.assert_called_once()` after `Background(config=config)`). Backgrounds that start the provider in `run()` are non-compliant and should be refactored.\n\n---\n\n## Quick Checklist\n\nBefore submitting Background tests, verify:\n\n- [ ] Test file: `tests/backgrounds/test_{name}_bg.py`\n- [ ] Fixtures for config (e.g. `config`, `config_default` or `config_with_*`)\n- [ ] Patch the **Provider** used inside the Background (e.g. `@patch(\"backgrounds.plugins.xxx_bg.XxxProvider\")`)\n- [ ] Tests: config init, Background init (Provider called with correct args, **`start()` called in `__init__`**), name, config access, `run()`, init failure\n- [ ] No real hardware or Provider implementation required to run\n\n---\n\n## 1. File location and naming\n\n- **Path**: `tests/backgrounds/test_{name}_bg.py`\n- **Naming**: `test_*.py`; test functions named `test_*`.\n\n**Examples**:\n- `tests/backgrounds/test_pointcloud_bg.py` → PointCloudBg\n- `tests/backgrounds/test_unitree_go2_bg.py` → UnitreeGo2Bg\n\n---\n\n## 2. Fixtures\n\nConfig fixtures matching the Background''s Config class. No `reset_singleton` is needed for the Background class itself; the Provider is mocked so the real singleton is not used.\n\n```python\n@pytest.fixture\ndef config():\n    \"\"\"Default config.\"\"\"\n    return UnitreeGo2BgConfig()\n\n\n@pytest.fixture\ndef config_with_ethernet():\n    \"\"\"Config with ethernet channel and custom timeout.\"\"\"\n    return UnitreeGo2BgConfig(unitree_ethernet=\"eth0\", timeout=10.0)\n```\n\n---\n\n## 3. Mocking the Provider\n\n**REQUIRED**: Patch the **Provider** that the Background instantiates. Patch path must be the **module where the Provider is used** (the Background module), not the Provider module.\n\n```python\n@patch(\"backgrounds.plugins.unitree_go2_bg.UnitreeGo2Provider\")\ndef test_background_initialization(mock_provider_class, config):\n    mock_provider_instance = MagicMock()\n    mock_provider_class.return_value = mock_provider_instance\n\n    background = UnitreeGo2Bg(config=config)\n\n    mock_provider_class.assert_called_once_with(channel=\"\", timeout=1.0)\n    assert background.unitree_go2_provider is mock_provider_instance\n    mock_provider_instance.start.assert_called_once()\n```\n\nThis avoids starting the real Provider (and any HW/SDK).\n\n---\n\n## 4. What to test\n\n| Area | What to verify |\n|------|----------------|\n| **Config** | Config class default and custom values (e.g. `UnitreeGo2BgConfig()`, `UnitreeGo2BgConfig(unitree_ethernet=\"eth0\", timeout=10.0)`). |\n| **Initialization** | With Provider mocked: Background constructs Provider with arguments derived from config (channel, timeout, etc.); stores the instance; **calls `provider.start()` once in `__init__`** (not in `run()`). |\n| **Config derivation** | If config has optional/whitespace fields (e.g. ethernet), assert Provider is called with stripped/defaulted values. |\n| **Name** | `background.name` equals the class name (e.g. `\"UnitreeGo2Bg\"`). |\n| **Config access** | `background.config` is the same object as the injected config; attributes match. |\n| **run()** | If `run()` only sleeps, patch `time.sleep` and assert it was called with the expected argument (e.g. `60`). |\n| **Init failure** | When Provider constructor or init raises, Background `__init__` propagates the exception (e.g. `pytest.raises(RuntimeError)`). |\n\n---\n\n## 5. Test structure\n\nPrefer one test per behavior; use `@patch` on the test function or use `with patch(...):` inside the test.\n\n```python\ndef test_config_initialization():\n    cfg = UnitreeGo2BgConfig()\n    assert cfg.unitree_ethernet is None\n    assert cfg.timeout == 1.0\n\n\n@patch(\"backgrounds.plugins.unitree_go2_bg.UnitreeGo2Provider\")\ndef test_background_initialization(mock_provider_class, config):\n    mock_provider_class.return_value = MagicMock()\n    background = UnitreeGo2Bg(config=config)\n    mock_provider_class.assert_called_once_with(channel=\"\", timeout=1.0)\n    mock_provider_class.return_value.start.assert_called_once()\n\n\n@patch(\"backgrounds.plugins.unitree_go2_bg.UnitreeGo2Provider\")\n@patch(\"backgrounds.plugins.unitree_go2_bg.time.sleep\")\ndef test_run_sleeps(mock_sleep, mock_provider_class, config):\n    mock_provider_class.return_value = MagicMock()\n    background = UnitreeGo2Bg(config=config)\n    background.run()\n    mock_sleep.assert_called_once_with(60)\n```\n\n### 5.1 `@patch` parameter order\n\nWhen stacking multiple `@patch` decorators, the **bottom** (closest to the function) decorator is applied first, and its mock is the **first** parameter:\n\n```python\n@patch(\"backgrounds.plugins.unitree_go2_bg.UnitreeGo2Provider\")  # second param\n@patch(\"backgrounds.plugins.unitree_go2_bg.time.sleep\")         # first param\ndef test_run_sleeps(mock_sleep, mock_provider_class, config):\n    ...\n```\n\n---\n\n## 6. Common patterns (pytest / mock)\n\n### 6.1 `MagicMock` return_value\n\n- `mock_provider_class.return_value = MagicMock()`: When the Background does `Provider(...)`, it gets this instance instead of a real Provider.\n\n### 6.2 Asserting calls\n\n- `mock_provider_class.assert_called_once_with(channel=\"\", timeout=1.0)`: Provider was constructed once with these arguments.\n- `mock_provider_instance.start.assert_called_once()`: `start()` was called once on the instance.\n\n### 6.3 Init failure\n\n```python\n@patch(\"backgrounds.plugins.unitree_go2_bg.UnitreeGo2Provider\")\ndef test_init_raises_on_provider_failure(mock_provider_class, config):\n    mock_provider_class.side_effect = RuntimeError(\"DDS init failed\")\n\n    with pytest.raises(RuntimeError, match=\"DDS init failed\"):\n        UnitreeGo2Bg(config=config)\n```\n\n---\n\n## 7. Running Background tests\n\n```bash\nuv run pytest tests/backgrounds/test_unitree_go2_bg.py -v\n```\n\n---\n\n## 8. Review checklist\n\n- [ ] File under `tests/backgrounds/test_*_bg.py`\n- [ ] Config fixture(s); Provider patched in Background module\n- [ ] Config initialization and Background initialization (Provider args + `start()`) tested\n- [ ] Name, config access, `run()` (e.g. sleep) and init failure tested\n- [ ] Tests pass with `uv run pytest tests/backgrounds/test_*_bg.py -v` (no HW)\n\n---\n\n## 9. Reference examples\n\n- `tests/backgrounds/test_unitree_go2_bg.py`\n- `tests/backgrounds/test_pointcloud_bg.py`\n\nImplementation guide: `.cursor/skills/background-implementation/SKILL.md`\n"},"lastSynced":"2026-03-08T02:10:25.244Z","agentAnalysis":{"suitability":{"en":"Ideal for Python Testing Agents requiring rigorous Background testing in OM Cortex Runtime","zh":"适用于需要在OM Cortex Runtime中进行严格背景测试的Python测试代理","ja":"OM Cortex Runtimeで徹底的なバックグラウンドテストを必要とするPythonテストエージェントに最適","ko":"OM Cortex Runtime에서 철저한 백그라운드 테스트가 필요한 Python 테스트 에이전트에 적합","es":"Ideal para agentes de prueba de Python que requieren pruebas de fondo rigurosas en OM Cortex Runtime","fr":"Idéal pour les agents de test Python nécessitant des tests de fond rigoureux dans OM Cortex Runtime","de":"Ideal für Python-Testagenten, die strenge Hintergrundtests in OM Cortex Runtime erfordern","pt":"Ideal para Agentes de Teste Python que exigem testes de fundo rigorosos no tempo de execução do OM Cortex","ru":"Идеально подходит для агентов тестирования Python, требующих тщательного тестирования фона в среде выполнения OM Cortex","ar":"مثالي لعميل اختبار بايثون الذي يتطلب اختبارات خلفية صارمة في وقت تشغيل OM Cortex"},"recommendation":{"en":"Empowers agents to write consistent and hardware-independent pytest tests for Backgrounds, utilizing rules and patterns to mock Providers and ensure reliable test execution, leveraging pytest and OM Cortex Runtime","zh":"赋予代理编写一致且与硬件无关的pytest测试的能力，用于背景测试，利用规则和模式模拟提供者，以确保可靠的测试执行，利用pytest和OM Cortex Runtime","ja":"バックグラウンドのテストにルールとパターンを使用してプロバイダーをモックし、テストの実行を確実に実行するために、pytestとOM Cortex Runtimeを活用して、一貫性のあるハードウェアに依存しないpytestテストを作成するエージェントを可能にします","ko":"규칙과 패턴을 사용하여 배경의 테스트에 대한 공급자를 모의하고, 테스트 실행을 신뢰할 수 있게 하기 위해 pytest와 OM Cortex Runtime를 활용하여, 일관성 있고 하드웨어에 독립적인 pytest 테스트를 작성할 수 있는 에이전트를 강화합니다","es":"Habilita a los agentes a escribir pruebas de pytest consistentes e independientes del hardware para fondos, utilizando reglas y patrones para simular Proveedores y garantizar una ejecución de pruebas confiable, aprovechando pytest y OM Cortex Runtime","fr":"Permet aux agents d''écrire des tests pytest cohérents et indépendants du matériel pour les fonds, en utilisant des règles et des modèles pour simuler les fournisseurs et assurer une exécution de test fiable, en exploitant pytest et OM Cortex Runtime","de":"Ermächtigt die Agenten, konsistente und hardwareunabhängige Pytest-Tests für Hintergründe zu schreiben, indem Regeln und Muster verwendet werden, um Anbieter zu simulieren und eine zuverlässige Testausführung zu gewährleisten, indem Pytest und OM Cortex Runtime genutzt werden","pt":"Habilita agentes a escrever testes pytest consistentes e independentes de hardware para Fundos, utilizando regras e padrões para simular Provedores e garantir a execução confiável de testes, aproveitando pytest e OM Cortex Runtime","ru":"Предоставляет агентам возможность писать последовательные и независимые от аппаратного обеспечения тесты pytest для фонов, используя правила и шаблоны для имитации Поставщиков и обеспечения надежного выполнения тестов, используя pytest и OM Cortex Runtime","ar":"تمكين الوكلاء من كتابة اختبارات pytest متسقة ومستقلة عن الأجهزة للخلفيات، باستخدام القواعد والأنماط لمحاكاة المزودين وتأمين تنفيذ اختبار موثوق، بالاستفادة من pytest و OM Cortex Runtime"},"useCases":{"en":["Automating Background test creation","Debugging hardware-independent test failures","Validating Provider initialization in Backgrounds"],"zh":["自动化背景测试创建","调试与硬件无关的测试失败","验证背景中的提供者初始化"],"ja":["バックグラウンドテストの作成の自動化","ハードウェアに依存しないテストの失敗のデバッグ","バックグラウンドでのプロバイダーの初期化の検証"],"ko":["배경 테스트 생성 자동화","하드웨어에 독립적인 테스트 실패 디버깅","배경에서 공급자 초기화 검증"],"es":["Automatización de la creación de pruebas de fondo","Depuración de fallos de pruebas independientes del hardware","Validación de la inicialización del Proveedor en fondos"],"fr":["Automatisation de la création de tests de fond","Débogage des défaillances de tests indépendants du matériel","Validation de l''initialisation du fournisseur dans les fonds"],"de":["Automatisierung der Erstellung von Hintergrundtests","Fehlerbehebung bei hardwareunabhängigen Testfehlern","Validierung der Initialisierung des Anbieters in Hintergründen"],"pt":["Automatizar a criação de testes de fundo","Depurar falhas de teste independentes de hardware","Validar a inicialização do Provedor em Fundos"],"ru":["Автоматизировать создание тестов фона","Отладить отказы тестирования, независимые от аппаратного обеспечения","Проверить инициализацию Поставщика в фонах"],"ar":["تأتمتة إنشاء اختبارات الخلفية","تصحيح أخطاء الاختبار المستقلة عن الأجهزة","التحقق من تهيئة المزود في الخلفيات"]},"limitations":{"en":["Requires OM Cortex Runtime environment","Pytest dependency","Backgrounds must initialize Providers in __init__"],"zh":["需要OM Cortex Runtime环境","pytest依赖","背景必须在__init__中初始化提供者"],"ja":["OM Cortex Runtime環境が必要","pytest依存関係","バックグラウンドは__init__でプロバイダーを初期化する必要がある"],"ko":["OM Cortex Runtime 환경 필요","pytest 종속성","배경은 __init__에서 공급자를 초기화해야 함"],"es":["Requiere entorno de OM Cortex Runtime","Dependencia de pytest","Los fondos deben inicializar los Proveedores en __init__"],"fr":["Nécessite un environnement OM Cortex Runtime","Dépendance de pytest","Les fonds doivent initialiser les fournisseurs dans __init__"],"de":["Benötigt OM Cortex Runtime-Umgebung","Pytest-Abhängigkeit","Hintergründe müssen Anbieter in __init__ initialisieren"],"pt":["Exige ambiente de tempo de execução do OM Cortex","Dependência de pytest","Os Fundos devem inicializar os Provedores em __init__"],"ru":["Требует среды выполнения OM Cortex","Зависимость от pytest","Фоны должны инициализировать Поставщиков в __init__"],"ar":["يتطلب بيئة وقت تشغيل OM Cortex","اعتماد pytest","الخلفيات يجب أن تهيئ المزودين في __init__"]},"version":4},"contentHash":"adf6d15a1a54a7409a781e822322be7d95490c2c538e54ce134139d2211de293","qualityScore":33}');
