INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('psychicDree/PirateTileClash/unity-netcode-patterns', 'unity-netcode-patterns', 'psychicDree', 'PirateTileClash', 'community', 'unity-netcode-patterns psychicDree PirateTileClash community The unity-netcode-patterns skill enables developers to set up Distributed Authority topology and configure NetworkBehaviour for network management. It benefits Unity developers working on multiplayer games and applications. Unity Netcode Patterns 提供了分布式权威设置和网络行为的解决方案，实现高效的网络编程 Unity Netcode パターンは、分散型の権限設定とネットワーク動作を実現するためのソリューションを提供します 유니티 네트워크 코드 패턴은 분산 권한 설정과 네트워크 동작을 구현하기 위한 솔루션을 제공합니다 Los patrones de Unity Netcode permiten una autoridad distribuida y gestión de escenas en red. Aprende a configurarlos Les modèles Unity Netcode permettent une autorité distribuée et une gestion de scènes en réseau. Découvrez comment les configurer Die Muster von Unity Netcode ermöglichen eine verteilte Autorität und Netzwerk-Szenenverwaltung. Erfahren Sie, wie Sie sie einrichten Os padrões de Unity Netcode permitem desenvolver jogos multiplayer com autoridade distribuída e gerenciamento de cena Шаблоны Unity Netcode позволяют разрабатывать многопользовательские игры с распределенной властью и управлением сцен نماذج يونيتي نيتكود تمكن من تطوير ألعاب متعددة اللاعبين مع السلطة الموزعة وإدارة المشاهد how to use unity-netcode-patterns unity-netcode-patterns setup guide unity-netcode-patterns vs Mirror unity-netcode-patterns install what is unity-netcode-patterns unity-netcode-patterns alternative unity netcode patterns tutorial unity netcode patterns example unity netcode patterns documentation Unity Netcode Patterns 分布式权威设置 NetworkManager 网络行为 Unity 网络编程 C# 网络编程 Configures NetworkManager for Distributed Authority topology Sets up player prefab spawning for networked games Manages scene transitions for seamless network experience Implements NetworkBehaviour basics, including OnNetworkSpawn and OnNetworkDespawn Initializes grid management on session owner using IsServer check Uses C# scripting for custom NetworkBehaviour implementation unity-netcode-patterns is a set of techniques for configuring NetworkManager and NetworkBehaviour in Unity, enabling distributed authority and networked gameplay.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('karstenheld3/SharePoint-GPT-Middleware/session-management', 'community', 'karstenheld3', 'SharePoint-GPT-Middleware', 'karstenheld3/SharePoint-GPT-Middleware', 'session-management', 0, 0, 33, '2026-03-08T01:57:15.520Z', '2026-03-08T02:10:43.321Z', '73387388bec9e306f36c89a346e41657678b04b9870afac5bc5760499294726b', '{"id":"karstenheld3/SharePoint-GPT-Middleware/session-management","name":"session-management","description":{"en":"The session-management skill is designed for developers to crawl SharePoint site content into OpenAI Vector Stores using an Azure Web App in Python. It benefits developers working with Azure and OpenAI integrations.","zh":"会话管理是Azure Web App在Python中爬取SharePoint站点内容到OpenAI Vector Stores的关键技术","ja":"セッション管理は、Azure Web AppのPythonでSharePointサイトのコンテンツをOpenAI Vector Storesにクロールするための重要な技術です","ko":"세션 관리는 Azure Web App의 Python에서 SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링하는 핵심 기술입니다","es":"La gestión de sesiones en Azure Web App con Python permite administrar el contenido de sitios de SharePoint en OpenAI Vector Stores de manera eficiente","fr":"La gestion de sessions dans Azure Web App avec Python permet de gérer le contenu des sites SharePoint dans OpenAI Vector Stores de manière efficace","de":"Die Sitzungsverwaltung in Azure Web App mit Python ermöglicht die effiziente Verwaltung von Inhalten von SharePoint-Sites in OpenAI Vector Stores","pt":"O gerenciamento de sessão é uma habilidade que permite crawlar conteúdo de sites SharePoint para armazenamento de vetores OpenAI em um aplicativo web Azure em Python.","ru":"Управление сессиями - это навык, который позволяет ползать содержимое сайтов SharePoint в хранилище векторов OpenAI в веб-приложении Azure на Python.","ar":"إدارة الجلسة هي مهارة تتيح تصفح محتوى مواقع SharePoint إلى مخزن متجهات OpenAI في تطبيق ويب Azure باستخدام Python."},"seo":{"title":{"en":"Session-Management: Setup Guide for Azure Web App and Ope...","zh":"AIエージェント会话管理Setup Guide","ja":"AIエージェントのセッション管理ベストプラクティス","ko":"AI 에이전트 세션 관리 구축 가이드","es":"Guía de configuración de gestión de sesiones para Azure W...","fr":"Guide de configuration de la gestion de sessions pour Azu...","de":"Konfigurationsleitfaden für Sitzungsverwaltung in Azure W...","pt":"Guia de Configuração de Gerenciamento de Sessão com Azure...","ru":"Руководство по настройке управления сессиями с Azure и Op...","ar":"دليل إعداد إدارة الجلسة مع Azure و OpenAI"},"description":{"en":"Discover how to track EDIRD phases and manage sessions with Azure Web App and OpenAI Vector Stores. Learn to implement session-management and optimize your w...","zh":"了解Azure Web App在Python中如何爬取SharePoint站点内容到OpenAI Vector Stores，实现会话管理","ja":"Azure Web AppのPythonでSharePointサイトのコンテンツをOpenAI Vector Storesにクロールするセッション管理について","ko":"Azure Web App의 Python에서 SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링하여 세션 관리를 구현하는 방법","es":"Aprende a administrar sesiones en Azure Web App con Python y OpenAI Vector Stores para mejorar la eficiencia de tu aplicación","fr":"Découvrez comment gérer les sessions dans Azure Web App avec Python et OpenAI Vector Stores pour améliorer l''efficacité de votre application","de":"Erfahren Sie, wie Sie Sitzungen in Azure Web App mit Python und OpenAI Vector Stores verwalten, um die Effizienz Ihrer Anwendung zu verbessern","pt":"Aprenda a gerenciar sessões em um aplicativo web Azure em Python, crawlando conteúdo de sites SharePoint para armazenamento de vetores OpenAI","ru":"Узнайте, как управлять сессиями в веб-приложении Azure на Python, ползая содержимое сайтов SharePoint в хранилище векторов OpenAI","ar":"تعلم كيفية إدارة الجلسات في تطبيق ويب Azure باستخدام Python، وتصفح محتوى مواقع SharePoint إلى مخزن متجهات OpenAI"},"definition":{"en":"session-management is a technical process for tracking EDIRD phases and managing sessions, utilizing Azure Web App and OpenAI Vector Stores.","zh":"会话管理是指管理Azure Web App会话的技术，包括跟踪EDIRD阶段和管理会话文件","ja":"セッション管理とは、Azure Web Appのセッションを管理する技術であり、EDIRDステージの追跡とセッションファイルの管理が含まれます","ko":"세션 관리는 Azure Web App의 세션을 관리하는 기술로, EDIRD 단계의 추적과 세션 파일의 관리를 포함합니다","es":"La gestión de sesiones es una funcionalidad que permite administrar el estado de una aplicación en Azure Web App","fr":"La gestion de sessions est une fonctionnalité qui permet de gérer l''état d''une application dans Azure Web App","de":"Die Sitzungsverwaltung ist eine Funktion, die die Verwaltung des Zustands einer Anwendung in Azure Web App ermöglicht","pt":"O que é gerenciamento de sessão? É uma habilidade que gerencia a fase de crawlagem de conteúdo de sites SharePoint para armazenamento de vetores OpenAI.","ru":"Что такое управление сессиями? Это навык, который управляет фазой ползания содержимого сайтов SharePoint в хранилище векторов OpenAI.","ar":"ما هي إدارة الجلسة؟ هي مهارة تدير مرحلة تصفح محتوى مواقع SharePoint إلى مخزن متجهات OpenAI."},"features":{"en":["Tracks EDIRD phases using NOTES.md and PROGRESS.md files","Utilizes Azure Web App in Python for crawling SharePoint site content","Integrates with OpenAI Vector Stores for efficient data storage","Supports phase tracking with 5 phases and status updates in PROGRESS.md","Requires specific files including NOTES.md, PROBLEMS.md, and PROGRESS.md"],"zh":["支持Azure Web App在Python中爬取SharePoint站点内容","实现OpenAI Vector Stores的内容存储","跟踪EDIRD阶段","管理会话文件","支持NOTES.md、PROBLEMS.md、PROGRESS.md文件"],"ja":["Azure Web AppのPythonでSharePointサイトのコンテンツをクロールする機能","OpenAI Vector Storesへのコンテンツストア機能","EDIRDステージの追跡","セッションファイルの管理","NOTES.md、PROBLEMS.md、PROGRESS.mdファイルのサポート"],"ko":["Azure Web App의 Python에서 SharePoint 사이트의 콘텐츠를 크롤링하는 기능","OpenAI Vector Stores에 콘텐츠를 저장하는 기능","EDIRD 단계의 추적","세션 파일의 관리","NOTES.md, PROBLEMS.md, PROGRESS.md 파일의 지원"],"es":["Administración de sesiones en Azure Web App con Python","Integración con OpenAI Vector Stores para almacenar contenido de sitios de SharePoint","Seguimiento de fases de EDIRD","Gestión de carpetas de sesiones con ubicación personalizable","Requisitos de archivos específicos como NOTES.md, PROBLEMS.md y PROGRESS.md"],"fr":["Gestion de sessions dans Azure Web App avec Python","Intégration avec OpenAI Vector Stores pour stocker le contenu des sites SharePoint","Suivi des phases EDIRD","Gestion des dossiers de sessions avec emplacement personnalisable","Exigences de fichiers spécifiques tels que NOTES.md, PROBLEMS.md et PROGRESS.md"],"de":["Sitzungsverwaltung in Azure Web App mit Python","Integration mit OpenAI Vector Stores zum Speichern von Inhalten von SharePoint-Sites","Verfolgung von EDIRD-Phasen","Verwaltung von Sitzungsordnern mit anpassbarer Speicherort","Erfordernis von spezifischen Dateien wie NOTES.md, PROBLEMS.md und PROGRESS.md"],"pt":["Crawlagem de conteúdo de sites SharePoint","Armazenamento de vetores OpenAI","Gerenciamento de fases de crawlagem","Suporte a aplicativos web Azure em Python","Integração com NOTES.md e PROGRESS.md"],"ru":["Ползание содержимого сайтов SharePoint","Хранилище векторов OpenAI","Управление фазами ползания","Поддержка веб-приложений Azure на Python","Интеграция с NOTES.md и PROGRESS.md"],"ar":["تصفح محتوى مواقع SharePoint","مخزن متجهات OpenAI","إدارة مراحل التصفح","دعم تطبيقات الويب Azure باستخدام Python","التكامل مع NOTES.md و PROGRESS.md"]},"keywords":{"en":["how to use session-management","session-management setup guide","what is session-management","session-management alternative","session-management vs Azure API","session-management install","Azure Web App session management","OpenAI Vector Stores integration","EDIRD phase tracking"],"zh":["AIエージェント会话管理","Azure Web App会话管理","Python会话管理","SharePoint站点爬取","OpenAI Vector Stores","EDIRD阶段跟踪","会话文件管理"],"ja":["AIエージェントのセッション管理","Azure Web Appのセッション管理","Pythonのセッション管理","SharePointサイトのクロール","OpenAI Vector Stores","EDIRDステージの追跡","セッションファイルの管理"],"ko":["AI 에이전트 세션 관리","Azure Web App의 세션 관리","Python의 세션 관리","SharePoint 사이트의 크롤링","OpenAI Vector Stores","EDIRD 단계의 추적","세션 파일의 관리"],"es":["gestión de sesiones","Azure Web App","Python","OpenAI Vector Stores","SharePoint","EDIRD","administración de aplicaciones","desarrollo de aplicaciones","integración de tecnologías"],"fr":["gestion de sessions","Azure Web App","Python","OpenAI Vector Stores","SharePoint","EDIRD","administration d''applications","développement d''applications","intégration de technologies"],"de":["Sitzungsverwaltung","Azure Web App","Python","OpenAI Vector Stores","SharePoint","EDIRD","Anwendungsverwaltung","Anwendungsentwicklung","Technologieintegration"],"pt":["gerenciamento de sessão","crawlagem de conteúdo","armazenamento de vetores OpenAI","aplicativos web Azure em Python","SharePoint","OpenAI","NOTES.md","PROGRESS.md"],"ru":["управление сессиями","ползание содержимого","хранилище векторов OpenAI","веб-приложения Azure на Python","SharePoint","OpenAI","NOTES.md","PROGRESS.md"],"ar":["إدارة الجلسة","تصفح المحتوى","مخزن متجهات OpenAI","تطبيقات الويب Azure باستخدام Python","SharePoint","OpenAI","NOTES.md","PROGRESS.md"]}},"owner":"karstenheld3","repo":"SharePoint-GPT-Middleware","repoPath":"karstenheld3/SharePoint-GPT-Middleware","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.520Z","topics":[],"category":"community","skillMd":{"name":"session-management","description":"Apply when initializing, saving, resuming, or closing a work session","bodyPreview":"# Session Management Guide\n\n## Phase Tracking\n\nSessions track EDIRD phases:\n- NOTES.md: \"Current Phase\" section with phase, last verb, gate status\n- PROGRESS.md: \"Phase Plan\" section with 5 phases and status\n\n## MUST-NOT-FORGET\n\n- Session folder location: `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n- Default: `[DEFAULT_SESSIONS_FOLDER]` = `[WORKSPACE_FOLDER]` (override in `!NOTES.md`)\n- Required files: NOTES.md, PROBLEMS.md, PROGRESS.md\n- Lifecycle: Init → Work → Save → Resu","body":"# Session Management Guide\n\n## Phase Tracking\n\nSessions track EDIRD phases:\n- NOTES.md: \"Current Phase\" section with phase, last verb, gate status\n- PROGRESS.md: \"Phase Plan\" section with 5 phases and status\n\n## MUST-NOT-FORGET\n\n- Session folder location: `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n- Default: `[DEFAULT_SESSIONS_FOLDER]` = `[WORKSPACE_FOLDER]` (override in `!NOTES.md`)\n- Required files: NOTES.md, PROBLEMS.md, PROGRESS.md\n- Lifecycle: Init → Work → Save → Resume → Finalize → Archive\n- Sync session PROBLEMS.md to project on /session-finalize\n- Phase tracking: NOTES.md has current phase, PROGRESS.md has full phase plan\n- **STOP after session init**: After creating session files, STOP and wait for user review. Do NOT implement session goal until explicitly requested. User must review and refine goals before work begins.\n\n## Session Lifecycle\n\n1. **Init** (`/session-new`): Create session folder with tracking files\n2. **Work**: Create specs, plans, implement, track progress\n3. **Save** (`/session-save`): Document findings, commit changes\n4. **Resume** (`/session-load`): Re-read session documents, continue work\n5. **Finalize** (`/session-finalize`): Sync findings to project files, prepare for archive\n\n## Session Folder Location\n\n**Base:** `[DEFAULT_SESSIONS_FOLDER]` (default: `[WORKSPACE_FOLDER]`, can be overridden in `!NOTES.md`)\n\n**Format:** `[DEFAULT_SESSIONS_FOLDER]/_YYYY-MM-DD_[SessionTopicCamelCase]/`\n\n**Example:** `_PrivateSessions/_2026-01-12_FixAuthenticationBug/`\n\n## Required Session Files\n\nUse templates from this skill folder:\n\n- **NOTES.md** (`NOTES_TEMPLATE.md`): Key information, agent instructions, working patterns, large initial prompts (>120 tokens)\n- **PROBLEMS.md** (`PROBLEMS_TEMPLATE.md`): All problems to be addressed - initial prompts, questions, feature requests, bugs, strange behavior, investigation topics. Each problem gets a unique ID and tracks status (Open/Resolved/Deferred)\n- **PROGRESS.md** (`PROGRESS_TEMPLATE.md`): Task execution tracking - to-do list, done items, tried-but-not-used approaches\n\n**Key distinction:**\n- **NOTES.md** = Context and reference information (static knowledge)\n- **PROBLEMS.md** = All topics requiring attention (dynamic problem list with IDs)\n- **PROGRESS.md** = Task execution status (what''s being worked on)\n\n## Assumed Workflow\n\n```\n1. INIT: User initializes session (`/session-new`)\n   └── Session folder, NOTES.md, PROBLEMS.md, PROGRESS.md created\n\n2. PREPARE (one of):\n   A) User prepares work manually\n      └── Creates INFO / SPEC / IMPL documents, tracks progress\n   B) User explains problem, agent assists\n      └── Updates Problems, Progress, Notes → researches → creates documents\n\n3. WORK: User or agent implements\n   └── Makes decisions, creates tests, implements, verifies\n   └── Progress and findings tracked continuously\n\n4. SAVE: User saves session for later (`/session-save`)\n   └── Everything updated and committed\n\n5. RESUME: User resumes session (`/session-load`)\n   └── Agent primes from session files, executes workflows in Notes\n   └── Continue with steps 2-3\n\n6. FINALIZE: User finalizes session (`/session-finalize`)\n   └── Everything updated, committed, synced to project/workspace\n\n7. ARCHIVE: User archives session\n   └── Session folder moved to _Archive/\n```\n\n## ID System\n\nSee `[AGENT_FOLDER]/rules/devsystem-ids.md` rule (always-on) for complete ID system.\n\n**Quick Reference:**\n- Document: `[TOPIC]-[DOC][NN]` (IN, SP, IP, TP)\n  - Example: `CRWL-SP01`, `AUTH-IP01`\n- Tracking: `[TOPIC]-[TYPE]-[NNN]` (BG = Bug, FT = Feature, PR = Problem, FX = Fix, TK = Task)\n  - Example: `SAP-BG-001`, `UI-PR-003`, `GLOB-TK-015`\n- Topic Registry: Maintained in project NOTES.md\n\n## Session Init Template\n\n### NOTES.md\n```markdown\n# Session Notes\n\n## Session Info\n- **Started**: [DATE]\n- **Goal**: [Brief description]\n\n## Key Decisions\n\n## Important Findings\n\n## Workflows to Run on Resume\n```\n\n### PROBLEMS.md\n```markdown\n# Session Problems\n\n## Open\n\n## Resolved\n\n## Deferred\n```\n\n### PROGRESS.md\n```markdown\n# Session Progress\n\n## To Do\n\n## In Progress\n\n## Done\n\n## Tried But Not Used\n```\n"},"lastSynced":"2026-03-08T02:10:43.321Z","agentAnalysis":{"suitability":{"en":"Perfect for Azure-focused AI Agents needing advanced session management and OpenAI Vector Store integration capabilities.","zh":"非常适合需要高级会话管理和 OpenAI Vector Store 集成能力的 Azure 专注 AI 代理。","ja":"Azure に焦点を当てた AI エージェントが高度なセッション管理と OpenAI Vector Store の統合機能を必要とする場合に最適です。","ko":"Azure에 중점을 둔 AI 에이전트가 고급 세션 관리 및 OpenAI Vector Store 통합 기능을 필요로 할 때 완벽합니다.","es":"Perfecto para agentes de inteligencia artificial enfocados en Azure que necesitan capacidades de administración de sesiones avanzadas e integración con OpenAI Vector Store.","fr":"Parfait pour les agents d''intelligence artificielle axés sur Azure nécessitant une gestion de session avancée et des capacités d''intégration avec OpenAI Vector Store.","de":"Perfekt für Azure-fokussierte KI-Agents, die erweiterte Sitzungsverwaltung und OpenAI Vector Store-Integration benötigen.","pt":"Perfeito para Agentes de IA focados em Azure que necessitam de gerenciamento de sessão avançado e capacidades de integração com OpenAI Vector Store.","ru":"Идеально подходит для агентов ИИ, ориентированных на Azure, которым требуются продвинутые возможности управления сессиями и интеграции с OpenAI Vector Store.","ar":"مثالي لعميل الذكاء الاصطناعي المتمركز على Azure الذي يحتاج إلى إدارة جلسة متقدمة وقدرات دمج OpenAI Vector Store."},"recommendation":{"en":"Empowers agents to track EDIRD phases, manage session folders, and integrate with Azure Web Apps using Python, providing seamless content crawling into OpenAI Vector Stores via protocols like Azure''s API framework and file formats such as Markdown for NOTES.md, PROBLEMS.md, and PROGRESS.md.","zh":"赋予代理跟踪 EDIRD 阶段、管理会话文件夹、使用 Python 与 Azure Web Apps 集成的能力，并通过协议（如 Azure 的 API 框架）和文件格式（如 Markdown 的 NOTES.md、PROBLEMS.md 和 PROGRESS.md）将内容无缝地爬取到 OpenAI Vector Stores 中。","ja":"EDIRD フェーズの追跡、セッション フォルダの管理、Python を使用した Azure Web Apps との統合、および Azure の API フレームワークなどのプロトコルと Markdown の NOTES.md、PROBLEMS.md、PROGRESS.md などのファイル形式を介した OpenAI Vector Stores へのコンテンツのシームレスなクロールを可能にします。","ko":"EDIRD 단계를 추적하고, 세션 폴더를 관리하고, Python을 사용하여 Azure Web Apps와 통합하며, Azure의 API 프레임워크와 Markdown의 NOTES.md, PROBLEMS.md, PROGRESS.md와 같은 파일 형식을 통해 OpenAI Vector Stores로 콘텐츠를 무중단으로 크롤링할 수 있는 기능을 에이전트에 부여합니다.","es":"Permite a los agentes realizar un seguimiento de las fases de EDIRD, administrar carpetas de sesiones e integrarse con Azure Web Apps mediante Python, proporcionando un acceso sin problemas a los contenidos de OpenAI Vector Stores a través de protocolos como el marco de API de Azure y formatos de archivo como Markdown para NOTES.md, PROBLEMS.md y PROGRESS.md.","fr":"Permet aux agents de suivre les phases EDIRD, de gérer les dossiers de session et de s''intégrer à Azure Web Apps à l''aide de Python, fournissant un accès transparent aux contenus de OpenAI Vector Stores via des protocoles tels que le framework API d''Azure et des formats de fichiers tels que Markdown pour NOTES.md, PROBLEMS.md et PROGRESS.md.","de":"Ermöglicht es den Agents, EDIRD-Phasen zu verfolgen, Sitzungsordner zu verwalten und sich über Python in Azure Web Apps zu integrieren, wodurch ein nahtloser Zugriff auf die Inhalte von OpenAI Vector Stores über Protokolle wie Azure API-Framework und Dateiformate wie Markdown für NOTES.md, PROBLEMS.md und PROGRESS.md ermöglicht wird.","pt":"Habilita os agentes a rastrear fases EDIRD, gerenciar pastas de sessão e integrar com Azure Web Apps usando Python, fornecendo crawl de conteúdo sem interrupção para OpenAI Vector Stores via protocolos como a estrutura de API do Azure e formatos de arquivo como Markdown para NOTES.md, PROBLEMS.md e PROGRESS.md.","ru":"Наделяет агентов возможностью отслеживать фазы EDIRD, управлять папками сессий и интегрироваться с Azure Web Apps с помощью Python, обеспечивая бесперебойный поиск контента в OpenAI Vector Stores через протоколы, такие как фреймворк API Azure и форматы файлов, такие как Markdown для NOTES.md, PROBLEMS.md и PROGRESS.md.","ar":"تمكين العميل من تتبع مراحل EDIRD وإدارة مجلدات الجلسة والدمج مع تطبيقات الويب في Azure باستخدام Python، وتوفير زحف المحتوى دون انقطاع إلى OpenAI Vector Stores عبر بروتوكولات مثل إطار API Azure وتنسيقات الملفات مثل Markdown لـ NOTES.md و PROBLEMS.md و PROGRESS.md."},"useCases":{"en":["Automating SharePoint site content crawling into OpenAI Vector Stores","Managing session lifecycles through Init, Work, Save, and Resume phases","Tracking phase progress and gate status in PROGRESS.md files"],"zh":["自动将 SharePoint 站点内容爬取到 OpenAI Vector Stores","通过 Init、Work、Save 和 Resume 阶段管理会话生命周期","在 PROGRESS.md 文件中跟踪阶段进度和门状态"],"ja":["SharePoint サイトのコンテンツを OpenAI Vector Stores に自動でクロールする","Init、Work、Save、Resume フェーズを通じてセッションのライフサイクルを管理する","PROGRESS.md ファイルでフェーズの進捗とゲートの状態を追跡する"],"ko":["SharePoint 사이트 콘텐츠를 OpenAI Vector Stores로 자동 크롤링","Init, Work, Save, Resume 단계를 통해 세션 라이프사이클 관리","PROGRESS.md 파일에서 단계 진행과 게이트 상태 추적"],"es":["Automatización del contenido del sitio de SharePoint en OpenAI Vector Stores","Administración del ciclo de vida de la sesión a través de las fases de Inicio, Trabajo, Guardado y Reanudación","Seguimiento del progreso de la fase y el estado de la puerta en archivos PROGRESS.md"],"fr":["Automatisation du contenu du site SharePoint dans OpenAI Vector Stores","Gestion du cycle de vie de la session via les phases d''initialisation, de travail, d''enregistrement et de reprise","Suivi de la progression de phase et du statut de la porte dans les fichiers PROGRESS.md"],"de":["Automatisierung des SharePoint-Site-Inhalts in OpenAI Vector Stores","Verwaltung des Sitzungslebenszyklus durch die Phasen Initialisierung, Arbeit, Speichern und Wiederaufnahme","Verfolgung des Phasenfortschritts und des Torstatus in PROGRESS.md-Dateien"],"pt":["Automatizar o crawl de conteúdo do site do SharePoint para OpenAI Vector Stores","Gerenciar ciclos de vida de sessão por meio das fases Init, Work, Save e Resume","Rastrear o progresso da fase e o status do portão em arquivos PROGRESS.md"],"ru":["Автоматизировать поиск контента на сайте SharePoint в OpenAI Vector Stores","Управлять жизненным циклом сессий через фазы Init, Work, Save и Resume","Отслеживать прогресс фазы и статус шлюза в файлах PROGRESS.md"],"ar":["توفير تلقائي لزحف المحتوى لمواقع SharePoint إلى OpenAI Vector Stores","إدارة دورة حياة الجلسة من خلال مراحل الإنشاء والعمل والحفظ والإعادة","تتبع تقدم المرحلة وحالة البوابة في ملفات PROGRESS.md"]},"limitations":{"en":["Requires Azure Web App setup","Needs Python environment for execution","Dependent on OpenAI Vector Stores integration"],"zh":["需要 Azure Web App 设置","需要 Python 环境来执行","依赖于 OpenAI Vector Stores 的集成"],"ja":["Azure Web Apps の設定が必要","Python 環境が実行に必要","OpenAI Vector Stores の統合に依存する"],"ko":["Azure Web App 설정이 필요","Python 환경이 실행에 필요","OpenAI Vector Stores 통합에 의존"],"es":["Requiere configuración de Azure Web App","Necesita entorno de Python para la ejecución","Dependiente de la integración con OpenAI Vector Stores"],"fr":["Nécessite une configuration d''Azure Web App","Nécessite un environnement Python pour l''exécution","Dépend de l''intégration avec OpenAI Vector Stores"],"de":["Benötigt Azure Web App-Setup","Benötigt Python-Umgebung für die Ausführung","Abhängig von der Integration mit OpenAI Vector Stores"],"pt":["Requer configuração do Azure Web App","Necessita de ambiente Python para execução","Dependente da integração com OpenAI Vector Stores"],"ru":["Требует настройки Azure Web App","Требует среды Python для выполнения","Зависит от интеграции с OpenAI Vector Stores"],"ar":["يتطلب إعداد تطبيق الويب في Azure","يحتاج إلى بيئة Python للتشغيل","يعتمد على دمج OpenAI Vector Stores"]},"version":4},"contentHash":"73387388bec9e306f36c89a346e41657678b04b9870afac5bc5760499294726b","qualityScore":33}');
