INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('karstenheld3/SharePoint-GPT-Middleware/session-management', 'session-management', 'karstenheld3', 'SharePoint-GPT-Middleware', 'community', 'session-management karstenheld3 SharePoint-GPT-Middleware community The session-management skill is designed for developers to crawl SharePoint site content into OpenAI Vector Stores using an Azure Web App in Python. It benefits developers working with Azure and OpenAI integrations. 会话管理是Azure Web App在Python中爬取SharePoint站点内容到OpenAI Vector Stores的关键技术 セッション管理は、Azure Web AppのPythonでSharePointサイトのコンテンツをOpenAI Vector Storesにクロールするための重要な技術です 세션 관리는 Azure Web App의 Python에서 SharePoint 사이트의 콘텐츠를 OpenAI Vector Stores에 크롤링하는 핵심 기술입니다 La gestión de sesiones en Azure Web App con Python permite administrar el contenido de sitios de SharePoint en OpenAI Vector Stores de manera eficiente La gestion de sessions dans Azure Web App avec Python permet de gérer le contenu des sites SharePoint dans OpenAI Vector Stores de manière efficace Die Sitzungsverwaltung in Azure Web App mit Python ermöglicht die effiziente Verwaltung von Inhalten von SharePoint-Sites in OpenAI Vector Stores O gerenciamento de sessão é uma habilidade que permite crawlar conteúdo de sites SharePoint para armazenamento de vetores OpenAI em um aplicativo web Azure em Python. Управление сессиями - это навык, который позволяет ползать содержимое сайтов SharePoint в хранилище векторов OpenAI в веб-приложении Azure на Python. إدارة الجلسة هي مهارة تتيح تصفح محتوى مواقع SharePoint إلى مخزن متجهات OpenAI في تطبيق ويب Azure باستخدام Python. how to use session-management session-management setup guide what is session-management session-management alternative session-management vs Azure API session-management install Azure Web App session management OpenAI Vector Stores integration EDIRD phase tracking AIエージェント会话管理 Azure Web App会话管理 Python会话管理 SharePoint站点爬取 OpenAI Vector Stores EDIRD阶段跟踪 会话文件管理 Tracks EDIRD phases using NOTES.md and PROGRESS.md files Utilizes Azure Web App in Python for crawling SharePoint site content Integrates with OpenAI Vector Stores for efficient data storage Supports phase tracking with 5 phases and status updates in PROGRESS.md Requires specific files including NOTES.md, PROBLEMS.md, and PROGRESS.md session-management is a technical process for tracking EDIRD phases and managing sessions, utilizing Azure Web App and OpenAI Vector Stores.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ryolambert/kiro-wiz/kiro-directory-layout', 'community', 'ryolambert', 'kiro-wiz', 'ryolambert/kiro-wiz', 'kiro-directory-layout', 0, 0, 33, '2026-03-08T01:57:15.545Z', '2026-03-08T02:11:20.161Z', '6d4ead0787f4277e4a102cfe7b6f24e749d3b1fca70f90ca2203d04fd9e00caa', '{"id":"ryolambert/kiro-wiz/kiro-directory-layout","name":"kiro-directory-layout","description":{"en":"The Kiro Directory Layout skill provides a structured configuration for AI agents, benefiting developers with organized global and local settings. It enables efficient management of agent configs, settings, and prompts.","zh":"Kiro 目录布局提供了一个结构化的配置文件和数据存储系统，用于 AI 代理开发","ja":"Kiro ディレクトリレイアウトは、AIエージェント開発用の構造化された設定ファイルとデータストレージシステムを提供する","ko":"Kiro 디렉토리 레이아웃은 AI 도구 개발을 위한 구조화된 설정 파일과 데이터 저장 시스템을 제공합니다","es":"kiro-directory-layout es un componente clave para la configuración de agentes de inteligencia artificial, que permite la organización de archivos y configuraciones","fr":"kiro-directory-layout est un composant essentiel pour la configuration des outils d''intelligence artificielle, permettant l''organisation de fichiers et de configurations","de":"kiro-directory-layout ist ein wichtiger Bestandteil für die Konfiguration von KI-Agenten, der die Organisation von Dateien und Konfigurationen ermöglicht","pt":"O Kiro Directory Layout é um recurso fundamental para desenvolvedores que trabalham com ferramentas de IA. Ele fornece uma estrutura para organizar configurações globais e locais.","ru":"Макет каталогов Kiro является важной функцией для разработчиков, работающих с ИИ агентами. Он предоставляет структуру для организации глобальных и локальных конфигураций.","ar":"تخطيط دليل Kiro هو ميزة أساسية للمطورين الذين يعملون مع أدوات الذكاء الاصطناعي. ي 제공 هيكلاً لتنظيم الإعدادات العالمية والمحلية."},"seo":{"title":{"en":"Kiro Directory Layout: Configuration Setup Guide | AI Age...","zh":"Kiro 目录布局设置指南","ja":"Kiro ディレクトリレイアウトのベストプラクティス - AIエージェント","ko":"Kiro 디렉토리 레이아웃 설정 가이드 - AI 도구","es":"Guía de Configuración de kiro-directory-layout para Agent...","fr":"Guide de Configuration de kiro-directory-layout pour Outi...","de":"Einrichtungsleitfaden für kiro-directory-layout in KI-Age...","pt":"Guia de Configuração do Kiro Directory Layout para Ferram...","ru":"Настройка Макета Каталогов Kiro для ИИ Агентов","ar":"دليل إعداد تخطيط دليل Kiro للوكلاء الذكية"},"description":{"en":"Discover how to navigate and configure the Kiro Directory Layout for optimal AI agent performance. Learn more and get started today!","zh":"了解 Kiro 目录布局的结构和配置，优化您的 AI 代理开发体验","ja":"Kiro ディレクトリレイアウトについて詳しく知り、AIエージェント開発を最適化する","ko":"Kiro 디렉토리 레이아웃의 구조와 설정을 학습하여 AI 도구 개발을 개선하세요","es":"Aprende a configurar kiro-directory-layout para tus proyectos de inteligencia artificial con nuestra guía paso a paso","fr":"Découvrez comment configurer kiro-directory-layout pour vos projets d''intelligence artificielle avec notre guide étape par étape","de":"Erfahren Sie, wie Sie kiro-directory-layout für Ihre KI-Projekte konfigurieren können, mit unserer Schritt-für-Schritt-Anleitung","pt":"Aprenda a configurar o layout de diretório do Kiro para otimizar o desempenho das suas ferramentas de IA e melhorar a produtividade do desenvolvedor.","ru":"Узнайте, как настроить макет каталогов Kiro, чтобы оптимизировать работу ИИ агентов и повысить производительность разработчика.","ar":"تعرف على كيفية ضبط تخطيط دليل Kiro لتحسين أداء أدوات الذكاء الاصطناعي وزيادة إنتاجية المطور."},"definition":{"en":"Kiro Directory Layout is a configuration setup for AI agents, organizing global and local settings within a structured directory hierarchy.","zh":"Kiro 目录布局是一种用于 AI 代理的配置文件和数据存储结构","ja":"Kiro ディレクトリレイアウトは、AIエージェント用の設定ファイルとデータストレージ構造の一種である","ko":"Kiro 디렉토리 레이아웃은 AI 도구를 위한 설정 파일과 데이터 저장 구조입니다","es":"kiro-directory-layout es un esquema de organización de directorios para agentes de inteligencia artificial","fr":"kiro-directory-layout est un schéma d''organisation de répertoires pour les outils d''intelligence artificielle","de":"kiro-directory-layout ist ein Verzeichnisschema für KI-Agenten","pt":"O Kiro Directory Layout é uma estrutura de organização para configurações de ferramentas de IA.","ru":"Макет каталогов Kiro — это структура организации для конфигураций ИИ агентов.","ar":"تخطيط دليل Kiro هو هيكل لتنظيم إعدادات أدوات الذكاء الاصطناعي."},"features":{"en":["Stores global agent configs in JSON format within the ~/.kiro/agents directory","Supports local agent config overrides in the .kiro/agents directory","Manages global settings via the cli.json file in the ~/.kiro/settings directory","Utilizes SQLite for saved conversation storage in the ~/.kiro/sessions directory","Allows custom tool projects within the ~/.kiro/tools directory"],"zh":["支持全局和局部配置文件","具有 agents、settings、prompts 和 sessions 目录","支持 SQLite 数据存储","具有 CLI 和 MCP 服务器配置","支持自定义工具项目"],"ja":["グローバルとローカルの設定ファイルをサポート","agents、settings、prompts、sessions ディレクトリを含む","SQLite データストレージをサポート","CLI と MCP サーバーの設定を含む","カスタムツールプロジェクトをサポート"],"ko":["전역 및 지역 설정 파일 지원","에이전트, 설정, 프롬프트 및 세션 디렉토리 포함","SQLite 데이터 저장 지원","CLI 및 MCP 서버 구성 포함","사용자 정의 도구 프로젝트 지원"],"es":["Soporte para configuraciones de agentes globales y locales","Organización de archivos en directorios como agents/, settings/ y prompts/","Compatibilidad con SQLite para sesiones guardadas","Configuración de servidores MCP globales","Soporte para proyectos de herramientas personalizadas"],"fr":["Prise en charge des configurations d''agents globales et locales","Organisation de fichiers dans des répertoires tels que agents/, settings/ et prompts/","Compatibilité avec SQLite pour les sessions enregistrées","Configuration des serveurs MCP globaux","Prise en charge des projets d''outils personnalisés"],"de":["Unterstützung für globale und lokale Agentenkonfigurationen","Organisation von Dateien in Verzeichnissen wie agents/, settings/ und prompts/","Kompatibilität mit SQLite für gespeicherte Sitzungen","Konfiguration globaler MCP-Server","Unterstützung für benutzerdefinierte Werkzeugprojekte"],"pt":["Suporte a configurações globais e locais","Organização de agentes em pastas separadas","Armazenamento de configurações em arquivos JSON","Integração com servidor MCP","Suporte a projetos de ferramentas personalizadas"],"ru":["Поддержка глобальных и локальных конфигураций","Организация агентов в отдельных папках","Хранение конфигураций в файлах JSON","Интеграция с сервером MCP","Поддержка пользовательских проектов инструментов"],"ar":["دعم الإعدادات العالمية والمحلية","تنظيم الوكلاء في مجلدات منفصلة","تخزين الإعدادات في ملفات JSON","التكامل مع خادم MCP","دعم مشاريع الأدوات المخصصة"]},"keywords":{"en":["how to use kiro-directory-layout","kiro-directory-layout setup guide","kiro-directory-layout configuration","ai agent directory structure","json config files for ai agents","sqlite database for conversations","custom tool projects for ai agents","kiro-directory-layout alternative","kiro-directory-layout vs competitor"],"zh":["Kiro 目录布局","AI 代理开发","配置文件","数据存储","SQLite","CLI","MCP 服务器","自定义工具"],"ja":["Kiro ディレクトリレイアウト","AIエージェント開発","設定ファイル","データストレージ","SQLite","CLI","MCP サーバー","カスタムツール"],"ko":["Kiro 디렉토리 레이아웃","AI 도구 개발","설정 파일","데이터 저장","SQLite","CLI","MCP 서버","사용자 정의 도구"],"es":["kiro-directory-layout","agentes de inteligencia artificial","configuración de agentes","organización de directorios","SQLite","servidores MCP","proyectos de herramientas personalizadas"],"fr":["kiro-directory-layout","outils d''intelligence artificielle","configuration d''agents","organisation de répertoires","SQLite","serveurs MCP","projets d''outils personnalisés"],"de":["kiro-directory-layout","KI-Agenten","Agentenkonfiguration","Verzeichnisschema","SQLite","MCP-Server","benutzerdefinierte Werkzeugprojekte"],"pt":["Kiro Directory Layout","ferramentas de IA","configuração de diretório","desenvolvimento de software","otimização de desempenho","produtividade do desenvolvedor","organização de código","armazenamento de configurações"],"ru":["Макет каталогов Kiro","ИИ агенты","настройка каталогов","разработка программного обеспечения","оптимизация производительности","производительность разработчика","организация кода","хранение конфигураций"],"ar":["تخطيط دليل Kiro","أدوات الذكاء الاصطناعي","إعداد دليل","تطوير البرمجيات","تحسين الأداء","إنتاجية المطور","تنظيم الكود","تخزين الإعدادات"]}},"owner":"ryolambert","repo":"kiro-wiz","repoPath":"ryolambert/kiro-wiz","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.545Z","topics":[],"category":"community","skillMd":{"name":"kiro-directory-layout","description":"Reference for the .kiro directory structure and file locations. Use when setting up or organizing Kiro projects.","bodyPreview":"# Kiro Directory Layout\n\n## Global (~/.kiro/)\n```\n~/.kiro/\n├── agents/              # Global agent configs (.json)\n├── settings/\n│   └── cli.json         # Global settings\n├── prompts/             # Global prompt templates\n├── sessions/            # Saved conversations (SQLite)\n├── mcp.json             # Global MCP server config\n└── tools/               # Custom tool projects\n```\n\n## Workspace (.kiro/)\n```\n.kiro/\n├── agents/              # Local agent configs (.json) — override global\n├── settin","body":"# Kiro Directory Layout\n\n## Global (~/.kiro/)\n```\n~/.kiro/\n├── agents/              # Global agent configs (.json)\n├── settings/\n│   └── cli.json         # Global settings\n├── prompts/             # Global prompt templates\n├── sessions/            # Saved conversations (SQLite)\n├── mcp.json             # Global MCP server config\n└── tools/               # Custom tool projects\n```\n\n## Workspace (.kiro/)\n```\n.kiro/\n├── agents/              # Local agent configs (.json) — override global\n├── settings/\n│   └── cli.json         # Workspace settings — override global\n├── steering/            # Steering docs (.md, inclusion: always)\n├── hooks/               # Hook scripts\n├── prompts/             # Local prompt templates\n├── skills/              # Skill resources\n│   └── <name>/\n│       └── SKILL.md     # Requires YAML frontmatter (name, description)\n├── tools/               # Custom tool projects\n├── specs/               # Specification documents\n└── mcp.json             # Workspace MCP config\n```\n\n## Precedence\n- Workspace settings override global settings\n- Local agents override global agents with same name\n- Workspace MCP servers merge with global\n- Steering docs are always included in context\n\n## Key File Formats\n- Agents: JSON (.json)\n- Steering: Markdown with YAML frontmatter\n- Skills: Markdown with YAML frontmatter (name + description required)\n- Settings: JSON (cli.json)\n- MCP: JSON (mcp.json or in agent mcpServers field)\n- Prompts: Markdown or text, referenced via file:// URI\n- Hooks: Shell scripts, referenced in agent hooks config\n"},"lastSynced":"2026-03-08T02:11:20.161Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing structured configuration management with JSON files and SQLite databases.","zh":"适用于需要使用JSON文件和SQLite数据库进行结构化配置管理的AI代理。","ja":"JSONファイルとSQLiteデータベースを使用した構造化された設定管理が必要なAIエージェントに適しています。","ko":"JSON 파일과 SQLite 데이터베이스를 사용하여 구조화된 구성 관리가 필요한 AI 에이전트에 적합합니다.","es":"Perfecto para Agentes de IA que necesitan una gestión de configuración estructurada con archivos JSON y bases de datos SQLite.","fr":"Parfait pour les agents IA nécessitant une gestion de configuration structurée avec des fichiers JSON et des bases de données SQLite.","de":"Perfekt für KI-Agents, die eine strukturierte Konfigurationsverwaltung mit JSON-Dateien und SQLite-Datenbanken benötigen.","pt":"Perfeito para Agentes de IA que necessitam de gerenciamento de configuração estruturado com arquivos JSON e bancos de dados SQLite.","ru":"Идеально для ИИ-агентов, которым необходим структурированный менеджмент конфигурации с файлами JSON и базами данных SQLite.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى إدارة تكوين منظم مع ملفات JSON وقواعد بيانات SQLite."},"recommendation":{"en":"Empowers agents to manage global and local settings efficiently using a standardized directory layout, including configuration files like cli.json and mcp.json, and leveraging SQLite for conversation history in sessions/","zh":"赋予代理高效地管理全局和本地设置的能力，使用标准化的目录布局，包括cli.json和mcp.json等配置文件，并利用SQLite管理会话中的对话历史。","ja":"グローバル設定とローカル設定を効率的に管理できるようにエージェントに権限を与え、標準化されたディレクトリレイアウトを使用し、cli.jsonやmcp.jsonなどの設定ファイルとセッション内の会話履歴を管理するためにSQLiteを利用します。","ko":"표준화된 디렉토리 레이아웃을 사용하여 글로벌 및 로컬 설정을 효율적으로 관리할 수 있는 능력을 에이전트에게 부여하며, cli.json 및 mcp.json과 같은 구성 파일 및 SQLite를 사용하여 세션 내의 대화 기록을 관리합니다.","es":"Habilita a los agentes a gestionar los ajustes globales y locales de manera eficiente utilizando un diseño de directorio estandarizado, incluyendo archivos de configuración como cli.json y mcp.json, y aprovechando SQLite para el historial de conversación en sesiones/","fr":"Permet aux agents de gérer les paramètres globaux et locaux de manière efficace en utilisant une disposition de répertoire standardisée, y compris des fichiers de configuration tels que cli.json et mcp.json, et en exploitant SQLite pour l''historique de conversation dans les sessions/","de":"Ermöglich es den Agents, globale und lokale Einstellungen effizient zu verwalten, indem sie ein standardisiertes Verzeichnislayout verwenden, einschließlich Konfigurationsdateien wie cli.json und mcp.json, und SQLite für die Konversationshistorie in Sitzungen nutzen/","pt":"Habilita os agentes a gerenciar configurações globais e locais de forma eficiente usando um layout de diretório padronizado, incluindo arquivos de configuração como cli.json e mcp.json, e aproveitando o SQLite para histórico de conversas em sessões/","ru":"Наделяет агентов возможностью эффективного менеджмента глобальных и локальных настроек с использованием стандартизированного расположения директорий, включая файлы конфигурации типа cli.json и mcp.json, и использует SQLite для истории разговоров в сессиях/","ar":"يمنح الوكلاء القدرة على إدارة الإعدادات العالمية والمحلية بفعالية باستخدام تخطيط دليل معياري ، بما في ذلك ملفات التكوين مثل cli.json و mcp.json ، واستخدام SQLite لتاريخ المحادثات في الجلسات /"},"useCases":{"en":["Automating agent configuration with global and local settings override","Generating and managing prompt templates in prompts/","Debugging conversation flows using saved sessions in sessions/"],"zh":["使用全局和本地设置覆盖自动化代理配置","在prompts/中生成和管理提示模板","使用sessions/中的保存会话调试对话流"],"ja":["グローバル設定とローカル設定のオーバーライドを使用したエージェントの自動化設定","prompts/内のプロンプトテンプレートの生成と管理","セッション内の会話履歴を保存して会話フローをデバッグする"],"ko":["글로벌 및 로컬 설정 오버라이드를 사용하여 에이전트 구성 자동화","prompts/ 내에서 프롬프트 템플릿 생성 및 관리","세션 내의 대화 기록을 저장하여 대화 흐름을 디버깅"],"es":["Automatizar la configuración del agente con anulación de ajustes globales y locales","Generar y gestionar plantillas de prompts en prompts/","Depurar flujos de conversación utilizando sesiones guardadas en sessions/"],"fr":["Automatiser la configuration de l''agent avec une substitution de paramètres globaux et locaux","Générer et gérer des modèles de prompts dans prompts/","Déboguer les flux de conversation en utilisant des sessions enregistrées dans sessions/"],"de":["Automatisieren der Agentenkonfiguration mit globalen und lokalen Einstellungsüberschreibung","Erzeugen und Verwalten von Prompt-Vorlagen in prompts/","Fehlersuche bei Konversationsflüssen mithilfe gespeicherter Sitzungen in sessions/"],"pt":["Automatizar a configuração do agente com substituição de configurações globais e locais","Gerar e gerenciar modelos de prompts em prompts/","Depurar fluxos de conversa usando sessões salvas em sessions/"],"ru":["Автоматизировать конфигурацию агента с заменой глобальных и локальных настроек","Генерировать и управлять шаблонами приглашений в prompts/","Отлаживать потоки разговора с использованием сохраненных сессий в sessions/"],"ar":["توفير تلقائي لتكوين الوكيل مع استبدال الإعدادات العالمية والمحلية","generar و إدارة قوالب الدعوات في prompts/","تصحيح أخطاء تدفق المحادثة باستخدام الجلسات المحفوظة في sessions/"]},"limitations":{"en":["Requires filesystem access for directory and file management","Dependent on JSON file format for configuration","SQLite database required for conversation history management"],"zh":["需要文件系统访问权限以进行目录和文件管理","依赖于JSON文件格式进行配置","需要SQLite数据库进行对话历史管理"],"ja":["ディレクトリとファイルの管理のためにファイルシステムへのアクセスが必要","設定のためにJSONファイル形式に依存している","会話履歴の管理のためにSQLiteデータベースが必要"],"ko":["디렉토리 및 파일 관리를 위한 파일 시스템 액세스 필요","구성의 경우 JSON 파일 형식에 의존","대화 기록 관리를 위한 SQLite 데이터베이스 필요"],"es":["Requiere acceso al sistema de archivos para la gestión de directorios y archivos","Dependiente del formato de archivo JSON para la configuración","Se requiere una base de datos SQLite para la gestión del historial de conversación"],"fr":["Nécessite un accès au système de fichiers pour la gestion des répertoires et des fichiers","Dépendant du format de fichier JSON pour la configuration","Une base de données SQLite est requise pour la gestion de l''historique de conversation"],"de":["Benötigt Dateisystemzugriff für die Verwaltung von Verzeichnissen und Dateien","Abhängig vom JSON-Dateiformat für die Konfiguration","Eine SQLite-Datenbank ist erforderlich für die Verwaltung der Konversationshistorie"],"pt":["Requer acesso ao sistema de arquivos para gerenciamento de diretórios e arquivos","Dependente do formato de arquivo JSON para configuração","Banco de dados SQLite necessário para gerenciamento de histórico de conversas"],"ru":["Требует доступа к файловой системе для менеджмента директорий и файлов","Зависит от формата файла JSON для конфигурации","Требуется база данных SQLite для менеджмента истории разговоров"],"ar":["يتطلب الوصول إلى نظام الملفات لإدارة الدلائل والملفات","يعتمد على تنسيق ملف JSON للتكوين","مطلوب قاعدة بيانات SQLite لإدارة تاريخ المحادثات"]},"version":4},"contentHash":"6d4ead0787f4277e4a102cfe7b6f24e749d3b1fca70f90ca2203d04fd9e00caa","qualityScore":33}');
