INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ryolambert/kiro-wiz/kiro-directory-layout', 'kiro-directory-layout', 'ryolambert', 'kiro-wiz', 'community', 'kiro-directory-layout ryolambert kiro-wiz community The Kiro Directory Layout skill provides a structured configuration for AI agents, benefiting developers with organized global and local settings. It enables efficient management of agent configs, settings, and prompts. Kiro 目录布局提供了一个结构化的配置文件和数据存储系统，用于 AI 代理开发 Kiro ディレクトリレイアウトは、AIエージェント開発用の構造化された設定ファイルとデータストレージシステムを提供する Kiro 디렉토리 레이아웃은 AI 도구 개발을 위한 구조화된 설정 파일과 데이터 저장 시스템을 제공합니다 kiro-directory-layout es un componente clave para la configuración de agentes de inteligencia artificial, que permite la organización de archivos y configuraciones kiro-directory-layout est un composant essentiel pour la configuration des outils d''intelligence artificielle, permettant l''organisation de fichiers et de configurations kiro-directory-layout ist ein wichtiger Bestandteil für die Konfiguration von KI-Agenten, der die Organisation von Dateien und Konfigurationen ermöglicht O Kiro Directory Layout é um recurso fundamental para desenvolvedores que trabalham com ferramentas de IA. Ele fornece uma estrutura para organizar configurações globais e locais. Макет каталогов Kiro является важной функцией для разработчиков, работающих с ИИ агентами. Он предоставляет структуру для организации глобальных и локальных конфигураций. تخطيط دليل Kiro هو ميزة أساسية للمطورين الذين يعملون مع أدوات الذكاء الاصطناعي. ي 제공 هيكلاً لتنظيم الإعدادات العالمية والمحلية. how to use kiro-directory-layout kiro-directory-layout setup guide kiro-directory-layout configuration ai agent directory structure json config files for ai agents sqlite database for conversations custom tool projects for ai agents kiro-directory-layout alternative kiro-directory-layout vs competitor Kiro 目录布局 AI 代理开发 配置文件 数据存储 SQLite CLI MCP 服务器 自定义工具 Stores global agent configs in JSON format within the ~/.kiro/agents directory Supports local agent config overrides in the .kiro/agents directory Manages global settings via the cli.json file in the ~/.kiro/settings directory Utilizes SQLite for saved conversation storage in the ~/.kiro/sessions directory Allows custom tool projects within the ~/.kiro/tools directory Kiro Directory Layout is a configuration setup for AI agents, organizing global and local settings within a structured directory hierarchy.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('xiaobei930/cc-best/architecture', 'community', 'xiaobei930', 'cc-best', 'xiaobei930/cc-best', 'architecture', 0, 0, 33, '2026-03-08T01:57:15.550Z', '2026-03-08T02:11:26.297Z', 'a2ae4f728585fbb0fdf0760b94aa4e524c0ec56ac13db0bb30fb8bdb318d49d3', '{"id":"xiaobei930/cc-best/architecture","name":"architecture","description":{"en":"The architecture skill provides a comprehensive guide for autonomous workflow, including ADR records, design checklists, and scalability assessments, benefiting developers and project managers.","zh":"架构设计技能提供ADR记录、设计检查清单和自动化工作流的完整指南","ja":"AIエージェントのアーキテクチャ設計スキルは、ADRレコード、設計チェックリスト、自動化ワークフローの総合ガイドを提供します","ko":"아키텍처 설계 스킬은 ADR 기록, 설계 검사 목록 및 자동화 워크플로우에 대한 완전한 가이드를 제공합니다","es":"Nuestra guía de arquitectura proporciona una visión general completa de las mejores prácticas para diseñar sistemas escalables","fr":"Notre guide d''architecture offre une vue d''ensemble complète des meilleures pratiques pour concevoir des systèmes évolutifs","de":"Unsere Architektur-Anleitung bietet eine umfassende Übersicht über die besten Praktiken für das Entwerfen von skalierbaren Systemen","pt":"Desenvolva habilidades de arquitetura de software com nossa guia de melhores práticas, incluindo ADR, design de verificação e avaliação de escalabilidade","ru":"Разработайте навыки программной архитектуры с нашим руководством по лучшим практикам, включая ADR, контрольный список дизайна и оценку масштабируемости","ar":"طور من مهاراتك في هندسة البرمجيات مع دليلنا لأفضل الممارسات، بما في ذلك سجلات ADR، قائمة التحقق من التصميم وتقييم القابلية للتحجيم"},"seo":{"title":{"en":"Architecture: Autonomous Workflow Setup Guide | AI Agent ...","zh":"架构设计技能：ADR 记录和自动化工作流设置指南","ja":"AIエージェントのアーキテクチャ設計スキル：ADRレコードと自動化ワークフローの設定ガイド","ko":"아키텍처 설계 스킬: ADR 기록 및 자동화 워크플로우 설정 가이드","es":"Guía de Arquitectura: Mejores Prácticas para Desarrolladores","fr":"Guide d''Architecture: Bonnes Pratiques pour les Développeurs","de":"Architektur-Setup Guide: Best Practices für Entwickler","pt":"Guia de Arquitetura: Melhores Práticas para Desenvolvedores","ru":"Руководство по Архитектуре: Лучшие Практики для Разработч...","ar":"دليل الهندسة المعمارية: أفضل الممارسات للعاملين في مجال ا..."},"description":{"en":"Unlock efficient development workflows with architecture skill, featuring 40 commands, 17 skills, and auto-learning pipeline. Get started now!","zh":"了解架构设计技能的技术细节，包括ADR记录、设计检查清单和自动化工作流","ja":"AIエージェントのアーキテクチャ設計スキルの技術的詳細を学び、ADRレコード、設計チェックリスト、自動化ワークフローを実現する","ko":"아키텍처 설계 스킬의 기술적 세부 사항을 배우고, ADR 기록, 설계 검사 목록 및 자동화 워크플로우를 구현하세요","es":"Aprende a diseñar arquitecturas escalables con nuestra guía de mejores prácticas, incluyendo ADR y patrones de diseño","fr":"Découvrez comment concevoir des architectures évolutives avec notre guide de bonnes pratiques, y compris ADR et modèles de conception","de":"Erfahren Sie, wie Sie skalierbare Architekturen entwerfen, mit unserer Anleitung zu Best Practices, einschließlich ADR und Entwurfsmustern","pt":"Aprenda a projetar arquiteturas de software escaláveis e eficientes com nossa guia de melhores práticas para desenvolvedores","ru":"Узнайте, как проектировать масштабируемые и эффективные программные архитектуры с нашим руководством по лучшим практикам для разработчиков и ИИ Агентов","ar":"تعلم كيفية تصميم هندسة برمجية قابلة للتحجيم وفعالة مع دليلنا لأفضل الممارسات للعاملين في مجال التطوير وأدوات الذكاء الاصطناعي"},"definition":{"en":"Architecture is a skill that provides a complete development team workflow, including technical design, task decomposition, and decision-making frameworks.","zh":"架构设计技能是指用于创建和管理软件系统架构的技术和方法","ja":"アーキテクチャ設計スキルとは、ソフトウェアシステムのアーキテクチャを作成して管理するための技術と方法です","ko":"아키텍처 설계 스킬은 소프트웨어 시스템의 아키텍처를 생성하고 관리하기 위한 기술과 방법입니다","es":"La arquitectura se refiere al diseño y la estructura de un sistema o aplicación, incluyendo la planificación y la implementación","fr":"L''architecture fait référence à la conception et à la structure d''un système ou d''une application, y compris la planification et la mise en œuvre","de":"Die Architektur bezieht sich auf die Gestaltung und Struktur eines Systems oder einer Anwendung, einschließlich der Planung und Implementierung","pt":"Arquitetura de software é a prática de projetar e estruturar sistemas de software escaláveis e eficientes","ru":"Программная архитектура - это практика проектирования и структурирования масштабируемых и эффективных программных систем","ar":"هندسة البرمجيات هي ممارسة تصميم وهيكلة أنظمة البرمجيات القابلة للتحجيم والفعالة"},"features":{"en":["Generates ADR records using markdown templates","Supports lead methodology with technical design and task decomposition","Includes PM methodology for requirements analysis and decision frameworks","Provides design checklists for scalability assessments and architecture patterns","Features an auto-learning pipeline for continuous improvement","Utilizes 40 commands and 17 skills for comprehensive workflow management"],"zh":["ADR 记录模板","设计检查清单","自动化工作流","Lead 角色方法论","PM 角色方法论"],"ja":["ADRレコードテンプレート","設計チェックリスト","自動化ワークフロー","Lead役割方法論","PM役割方法論"],"ko":["ADR 기록 템플릿","설계 검사 목록","자동화 워크플로우","Lead 역할 방법론","PM 역할 방법론"],"es":["ADR (Architecture Decision Records) para documentar decisiones de diseño","Patrones de diseño para sistemas escalables","Metodologías de liderazgo y gestión de proyectos","Evaluación de la escalabilidad y la flexibilidad","Integración con herramientas de desarrollo como CLI y React"],"fr":["ADR (enregistrements de décisions d''architecture) pour documenter les décisions de conception","Modèles de conception pour les systèmes évolutifs","Méthodologies de leadership et de gestion de projets","Évaluation de l''évolutivité et de la flexibilité","Intégration avec des outils de développement tels que CLI et React"],"de":["ADR (Architektur-Entscheidungsprotokolle) zur Dokumentation von Designentscheidungen","Entwurfsmuster für skalierbare Systeme","Führungsmethoden und Projektmanagement","Bewertung der Skalierbarkeit und Flexibilität","Integration mit Entwicklungstools wie CLI und React"],"pt":["ADR (Arquitetura de Decisão de Registro) para documentar decisões de arquitetura","Design de verificação para garantir a qualidade do código","Avaliação de escalabilidade para sistemas de software","Metodologia de liderança para equipes de desenvolvimento","Metodologia de gerenciamento de projetos para desenvolvedores"],"ru":["ADR (Архитектура Решения Записи) для документирования решений по архитектуре","Контрольный список дизайна для обеспечения качества кода","Оценка масштабируемости для программных систем","Методология лидерства для команд разработчиков","Методология управления проектами для разработчиков и ИИ Агентов"],"ar":["سجلات ADR لتسجيل قرارات الهندسة المعمارية","قائمة التحقق من التصميم لضمان جودة الكود","تقييم القابلية للتحجيم لأنظمة البرمجيات","منهجية القيادة لفريق التطوير","منهجية إدارة المشاريع للعاملين في مجال التطوير وأدوات الذكاء الاصطناعي"]},"keywords":{"en":["how to use architecture in development","what is architecture in software development","architecture alternative to traditional workflows","architecture vs waterfall methodology","architecture setup guide for AI agents","architecture install for autonomous workflows","best practices for architecture implementation","architecture skill for developers and project managers"],"zh":["架构设计技能","ADR 记录","设计检查清单","自动化工作流","Lead 角色方法论","PM 角色方法论","软件系统架构","技术设计","任务分解"],"ja":["AIエージェントのアーキテクチャ設計スキル","ADRレコード","設計チェックリスト","自動化ワークフロー","Lead役割方法論","PM役割方法論","ソフトウェアシステムのアーキテクチャ","技術設計","タスク分解"],"ko":["아키텍처 설계 스킬","ADR 기록","설계 검사 목록","자동화 워크플로우","Lead 역할 방법론","PM 역할 방법론","소프트웨어 시스템의 아키텍처","기술 설계","작업 분해"],"es":["arquitectura de software","diseño de sistemas","ADR","patrones de diseño","metodologías de liderazgo","gestión de proyectos","escalabilidad","flexibilidad","herramientas de desarrollo","CLI","React"],"fr":["architecture logicielle","conception de systèmes","ADR","modèles de conception","méthodologies de leadership","gestion de projets","évolutivité","flexibilité","outils de développement","CLI","React"],"de":["Software-Architektur","Systemdesign","ADR","Entwurfsmuster","Führungsmethoden","Projektmanagement","Skalierbarkeit","Flexibilität","Entwicklungstools","CLI","React"],"pt":["arquitetura de software","desenvolvimento de software","ADR","design de verificação","avaliação de escalabilidade","metodologia de liderança","metodologia de gerenciamento de projetos","guias de desenvolvimento","melhores práticas de desenvolvimento"],"ru":["программная архитектура","разработка программного обеспечения","ADR","контрольный список дизайна","оценка масштабируемости","методология лидерства","методология управления проектами","руководства по разработке","лучшие практики разработки","ИИ Агенты"],"ar":["هندسة البرمجيات","تطوير البرمجيات","سجلات ADR","قائمة التحقق من التصميم","تقييم القابلية للتحجيم","منهجية القيادة","منهجية إدارة المشاريع","دلائل التطوير","أفضل الممارسات للتطوير","أدوات الذكاء الاصطناعي"]}},"owner":"xiaobei930","repo":"cc-best","repoPath":"xiaobei930/cc-best","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.550Z","topics":[],"category":"community","skillMd":{"name":"architecture","description":"Architecture design skill: ADR records, system design checklists, scalability assessment, architecture patterns. Use for complex system design and architecture decisions.","bodyPreview":"# 架构设计技能\n\n本技能提供架构设计的完整指南，包括 ADR 记录、设计检查清单、可扩展性评估、架构模式速查等最佳实践。\n\n## 子文件\n\n- [lead-methodology.md](lead-methodology.md) - Lead 角色方法论（技术设计、任务分解）\n- [pm-methodology.md](pm-methodology.md) - PM 角色方法论（需求分析、决策框架）\n\n## 架构决策记录 (ADR)\n\n对于重要的架构决策，创建 ADR 记录：\n\n### ADR 模板 (`docs/decisions/ADR-XXX.md`)\n\n```markdown\n# ADR-XXX: [决策标题]\n\n## 状态\n\nProposed | Accepted | Deprecated | Superseded by ADR-YYY\n\n## 上下文\n\n[描述导致这个决策的背景、问题或需求]\n\n## 决策\n\n[明确说明做出的决策]\n\n## 理由\n\n[解释为什么选择这个方案]\n\n## 备选方案\n\n### 方案 A: [名称]\n\n- 优点: ...\n- 缺点: ...\n\n##","body":"# 架构设计技能\n\n本技能提供架构设计的完整指南，包括 ADR 记录、设计检查清单、可扩展性评估、架构模式速查等最佳实践。\n\n## 子文件\n\n- [lead-methodology.md](lead-methodology.md) - Lead 角色方法论（技术设计、任务分解）\n- [pm-methodology.md](pm-methodology.md) - PM 角色方法论（需求分析、决策框架）\n\n## 架构决策记录 (ADR)\n\n对于重要的架构决策，创建 ADR 记录：\n\n### ADR 模板 (`docs/decisions/ADR-XXX.md`)\n\n```markdown\n# ADR-XXX: [决策标题]\n\n## 状态\n\nProposed | Accepted | Deprecated | Superseded by ADR-YYY\n\n## 上下文\n\n[描述导致这个决策的背景、问题或需求]\n\n## 决策\n\n[明确说明做出的决策]\n\n## 理由\n\n[解释为什么选择这个方案]\n\n## 备选方案\n\n### 方案 A: [名称]\n\n- 优点: ...\n- 缺点: ...\n\n### 方案 B: [名称]\n\n- 优点: ...\n- 缺点: ...\n\n## 后果\n\n### 正面\n\n- [好处1]\n- [好处2]\n\n### 负面\n\n- [代价1]\n- [代价2]\n\n### 风险\n\n- [风险1] → 缓解: [措施]\n\n## 相关决策\n\n- ADR-XXX: [相关决策]\n\n## 日期\n\nYYYY-MM-DD\n```\n\n### 何时创建 ADR\n\n| 场景                           | 是否需要 ADR  |\n| ------------------------------ | ------------- |\n| 选择主要技术栈（框架、数据库） | ✅ 必须       |\n| 定义核心架构模式               | ✅ 必须       |\n| 引入新的外部依赖               | ⚠️ 视影响范围 |\n| API 设计重大变更               | ✅ 必须       |\n| 简单的实现细节                 | ❌ 不需要     |\n\n---\n\n## 系统设计检查清单\n\n设计方案前，检查以下维度：\n\n### 功能性需求\n\n- [ ] 用户故事是否清晰完整\n- [ ] API 契约是否定义明确\n- [ ] 数据模型是否满足需求\n- [ ] 边界条件是否考虑\n\n### 非功能性需求\n\n- [ ] **性能**: 响应时间目标？吞吐量要求？\n- [ ] **可扩展性**: 预期用户量？数据增长？\n- [ ] **可用性**: 可接受的停机时间？\n- [ ] **安全性**: 认证授权？数据保护？\n\n### 技术设计\n\n- [ ] 架构图是否清晰\n- [ ] 组件职责是否明确\n- [ ] 数据流是否完整\n- [ ] 错误处理策略是否定义\n- [ ] 测试策略是否规划\n\n### 运维考虑\n\n- [ ] 部署策略是否明确\n- [ ] 监控告警是否规划\n- [ ] 日志策略是否定义\n- [ ] 回滚方案是否准备\n\n---\n\n## 可扩展性评估\n\n### 扩展阶段规划\n\n| 阶段   | 用户量   | 架构要求                   |\n| ------ | -------- | -------------------------- |\n| MVP    | <1K      | 单体应用足够               |\n| 成长期 | 1K-10K   | 优化数据库查询，添加缓存   |\n| 扩展期 | 10K-100K | 服务拆分，读写分离         |\n| 规模化 | >100K    | 微服务，分布式缓存，多区域 |\n\n### 常见瓶颈与解决方案\n\n| 瓶颈         | 解决方案                     |\n| ------------ | ---------------------------- |\n| 数据库读取慢 | 索引优化 → 读写分离 → 缓存层 |\n| API 响应慢   | 异步处理 → 消息队列 → CDN    |\n| 内存不足     | 分页加载 → 流式处理 → 扩容   |\n| 并发冲突     | 乐观锁 → 分布式锁 → 事件溯源 |\n\n---\n\n## 架构模式速查\n\n### 后端模式\n\n| 模式       | 适用场景         | 复杂度 |\n| ---------- | ---------------- | ------ |\n| 分层架构   | 大多数 CRUD 应用 | 低     |\n| 六边形架构 | 需要高可测试性   | 中     |\n| CQRS       | 读写负载差异大   | 高     |\n| 事件溯源   | 需要完整审计轨迹 | 高     |\n| 微服务     | 团队多、规模大   | 高     |\n\n### 前端模式\n\n| 模式              | 适用场景       |\n| ----------------- | -------------- |\n| 组件组合          | 构建复杂 UI    |\n| 状态提升          | 组件间共享状态 |\n| Context + Reducer | 全局状态管理   |\n| 自定义 Hooks      | 复用有状态逻辑 |\n| 渲染属性          | 灵活的组件复用 |\n\n### 数据访问模式\n\n| 模式          | 说明               |\n| ------------- | ------------------ |\n| Repository    | 抽象数据访问层     |\n| Unit of Work  | 事务管理           |\n| DAO           | 数据访问对象       |\n| Active Record | 模型直接操作数据库 |\n\n---\n\n## 架构评审清单\n\n在提交设计方案前：\n\n- [ ] 是否遵循现有架构模式\n- [ ] 是否考虑了向后兼容性\n- [ ] 是否有明确的错误处理策略\n- [ ] 是否考虑了监控和可观测性\n- [ ] 是否有性能基准和目标\n- [ ] 是否考虑了安全性\n- [ ] 是否有回滚方案\n\n## 与 /cc-best:lead 角色的配合\n\n```\n/cc-best:lead 技术设计\n    ↓\n  需要架构决策？\n    ├─ 是 → 创建 ADR 记录\n    └─ 否 → 继续设计\n    ↓\n  设计检查清单\n    ↓\n  任务分解\n    ↓\n  /cc-best:dev 开始实现\n```\n\n> **记住**: 架构决策要记录理由——ADR 不是文档负担，而是未来自己和团队的决策参考。\n"},"lastSynced":"2026-03-08T02:11:26.297Z","agentAnalysis":{"suitability":{"en":"Perfect for Technical Agents needing comprehensive architecture design guidance, including ADR records and scalability assessments.","zh":"非常适合需要全面架构设计指导的技术代理，包括ADR记录和可扩展性评估。","ja":"技術エージェントが包括的なアーキテクチャ設計ガイダンスを必要とする場合、ADRレコードやスケーラビリティ評価を含む場合に最適です。","ko":"전체적인 아키텍처 설계 가이드가 필요한 기술 에이전트에게 적합하며, ADR 기록 및 확장성 평가를 포함합니다.","es":"Perfecto para Agentes Técnicos que necesitan orientación de diseño de arquitectura integral, incluyendo registros ADR y evaluaciones de escalabilidad.","fr":"Parfait pour les agents techniques ayant besoin d''une orientation de conception d''architecture complète, y compris des enregistrements ADR et des évaluations de scalabilité.","de":"Perfekt für technische Agenten, die umfassende Architektur-Design-Anleitungen benötigen, einschließlich ADR-Aufzeichnungen und Skalierbarkeitsbewertungen.","pt":"Perfeito para Agentes Técnicos que necessitam de orientação de design de arquitetura abrangente, incluindo registros ADR e avaliações de escalabilidade.","ru":"Идеально подходит для технических агентов, которым требуется комплексное руководство по проектированию архитектуры, включая записи ADR и оценки масштабируемости.","ar":"مثالي لوكيلات تقنية تحتاج إلى إرشادات تصميم هيكلية شاملة، بما في ذلك سجلات ADR وتقييمات قابلية التوسع."},"recommendation":{"en":"Empowers agents to create well-structured architecture designs using ADR templates, design checklists, and scalability evaluations, while leveraging best practices and decision-making frameworks like Lead and PM methodologies.","zh":"赋予代理创建结构良好的架构设计的能力，使用ADR模板、设计清单和可扩展性评估，同时利用最佳实践和决策框架，如Lead和PM方法论。","ja":"ADRテンプレート、設計チェックリスト、スケーラビリティ評価を使用して、エージェントが整理されたアーキテクチャ設計を作成できるようにし、LeadやPMメソドロジーなどのベストプラクティスや意思決定フレームワークを活用します。","ko":"에이전트가 구조적으로 잘 정리된 아키텍처 설계를 생성할 수 있도록 하며, ADR 템플릿, 설계 체크리스트 및 확장성 평가를 사용하고, 리드 및 PM 메소드론과 같은 모범 사례 및 의사 결정 프레임워크를 활용합니다.","es":"Habilita a los agentes a crear diseños de arquitectura bien estructurados utilizando plantillas ADR, listas de verificación de diseño y evaluaciones de escalabilidad, mientras aprovecha las mejores prácticas y marcos de toma de decisiones como las metodologías Lead y PM.","fr":"Permet aux agents de créer des conceptions d''architecture bien structurées en utilisant des modèles ADR, des listes de vérification de conception et des évaluations de scalabilité, tout en exploitant les meilleures pratiques et les cadres de prise de décision tels que les méthodologies Lead et PM.","de":"Ermächtigt Agenten, gut strukturierte Architektur-Designs zu erstellen, indem sie ADR-Vorlagen, Design-Checklisten und Skalierbarkeitsbewertungen verwenden, während sie die besten Praktiken und Entscheidungsfindungs-Frameworks wie Lead- und PM-Methoden nutzen.","pt":"Habilita os agentes a criar projetos de arquitetura bem estruturados usando modelos ADR, listas de verificação de design e avaliações de escalabilidade, aproveitando as melhores práticas e estruturas de tomada de decisão, como metodologias Lead e PM.","ru":"Наделяет агентов возможностью создавать хорошо структурированные архитектурные проекты с использованием шаблонов ADR, контрольных списков дизайна и оценок масштабируемости, используя при этом лучшие практики и рамки принятия решений, такие как методологии Lead и PM.","ar":"تمكين الوكالات من إنشاء تصاميم هيكلية متجانسة باستخدام قوالب ADR وقوائم مراجعة التصميم وتقييمات قابلية التوسع، مع الاستفادة من أفضل الممارسات وأطر اتخاذ القرار، مثل منهجيات Lead و PM."},"useCases":{"en":["Generating ADR records for critical architecture decisions","Creating design checklists for scalability assessments","Evaluating architecture patterns for optimal workflow"],"zh":["为关键架构决策生成ADR记录","为可扩展性评估创建设计清单","评估架构模式以实现最佳工作流"],"ja":["重要なアーキテクチャの決定に対するADRレコードの生成","スケーラビリティ評価のための設計チェックリストの作成","最適なワークフローを実現するためのアーキテクチャパターンの評価"],"ko":["중요한 아키텍처 결정에 대한 ADR 기록 생성","확장성 평가를 위한 설계 체크리스트 생성","최적의 워크플ロー 달성을 위한 아키텍처 패턴 평가"],"es":["Generación de registros ADR para decisiones de arquitectura críticas","Creación de listas de verificación de diseño para evaluaciones de escalabilidad","Evaluación de patrones de arquitectura para flujos de trabajo óptimos"],"fr":["Génération d''enregistrements ADR pour des décisions d''architecture critiques","Création de listes de vérification de conception pour des évaluations de scalabilité","Évaluation de modèles d''architecture pour des flux de travail optimaux"],"de":["Erstellung von ADR-Aufzeichnungen für kritische Architektur-Entscheidungen","Erstellung von Design-Checklisten für Skalierbarkeitsbewertungen","Bewertung von Architekturmuster für optimale Workflows"],"pt":["Geração de registros ADR para decisões arquiteturais críticas","Criação de listas de verificação de design para avaliações de escalabilidade","Avaliação de padrões de arquitetura para fluxo de trabalho ótimo"],"ru":["Генерация записей ADR для критических архитектурных решений","Создание контрольных списков дизайна для оценок масштабируемости","Оценка шаблонов архитектуры для оптимального рабочего процесса"],"ar":["Generating سجلات ADR لقرارات هيكلية حرجة","إنشاء قوائم مراجعة التصميم لتقييمات قابلية التوسع","تقييم أنماط الهيكلية من أجل تدفق عمل مثالي"]},"limitations":{"en":["Requires knowledge of architecture design principles","Limited to software development projects"],"zh":["需要架构设计原则的知识","仅限于软件开发项目"],"ja":["アーキテクチャ設計原則の知識が必要","ソフトウェア開発プロジェクトに限定される"],"ko":["아키텍처 설계 원칙에 대한 지식 필요","소프트웨어 개발 프로젝트에만 제한됨"],"es":["Requiere conocimiento de los principios de diseño de arquitectura","Limitado a proyectos de desarrollo de software"],"fr":["Nécessite une connaissance des principes de conception d''architecture","Limité aux projets de développement de logiciels"],"de":["Benötigt Kenntnisse der Architektur-Design-Prinzipien","Begrenzt auf Software-Entwicklungsprojekte"],"pt":["Exige conhecimento de princípios de design de arquitetura","Limitado a projetos de desenvolvimento de software"],"ru":["Требует знания принципов проектирования архитектуры","Ограничен проектами разработки программного обеспечения"],"ar":["يتطلب معرفة بمبادئ تصميم الهيكلية","محدود بمشاريع تطوير البرمجيات"]},"version":4},"contentHash":"a2ae4f728585fbb0fdf0760b94aa4e524c0ec56ac13db0bb30fb8bdb318d49d3","qualityScore":33}');
