INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('xiaobei930/cc-best/architecture', 'architecture', 'xiaobei930', 'cc-best', 'community', 'architecture xiaobei930 cc-best community The architecture skill provides a comprehensive guide for autonomous workflow, including ADR records, design checklists, and scalability assessments, benefiting developers and project managers. 架构设计技能提供ADR记录、设计检查清单和自动化工作流的完整指南 AIエージェントのアーキテクチャ設計スキルは、ADRレコード、設計チェックリスト、自動化ワークフローの総合ガイドを提供します 아키텍처 설계 스킬은 ADR 기록, 설계 검사 목록 및 자동화 워크플로우에 대한 완전한 가이드를 제공합니다 Nuestra guía de arquitectura proporciona una visión general completa de las mejores prácticas para diseñar sistemas escalables Notre guide d''architecture offre une vue d''ensemble complète des meilleures pratiques pour concevoir des systèmes évolutifs Unsere Architektur-Anleitung bietet eine umfassende Übersicht über die besten Praktiken für das Entwerfen von skalierbaren Systemen Desenvolva habilidades de arquitetura de software com nossa guia de melhores práticas, incluindo ADR, design de verificação e avaliação de escalabilidade Разработайте навыки программной архитектуры с нашим руководством по лучшим практикам, включая ADR, контрольный список дизайна и оценку масштабируемости طور من مهاراتك في هندسة البرمجيات مع دليلنا لأفضل الممارسات، بما في ذلك سجلات ADR، قائمة التحقق من التصميم وتقييم القابلية للتحجيم how to use architecture in development what is architecture in software development architecture alternative to traditional workflows architecture vs waterfall methodology architecture setup guide for AI agents architecture install for autonomous workflows best practices for architecture implementation architecture skill for developers and project managers 架构设计技能 ADR 记录 设计检查清单 自动化工作流 Lead 角色方法论 PM 角色方法论 软件系统架构 技术设计 任务分解 Generates ADR records using markdown templates Supports lead methodology with technical design and task decomposition Includes PM methodology for requirements analysis and decision frameworks Provides design checklists for scalability assessments and architecture patterns Features an auto-learning pipeline for continuous improvement Utilizes 40 commands and 17 skills for comprehensive workflow management Architecture is a skill that provides a complete development team workflow, including technical design, task decomposition, and decision-making frameworks.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('mgaldino/agents-workflow/review-paper', 'community', 'mgaldino', 'agents-workflow', 'mgaldino/agents-workflow', 'review-paper', 0, 0, 33, '2026-03-08T01:57:15.552Z', '2026-03-08T02:11:31.916Z', '33e0b1bfd543b6aecbcac0555a7a0bd13efd54087270c17b137ca05bbb602b46', '{"id":"mgaldino/agents-workflow/review-paper","name":"review-paper","description":{"en":"The review-paper skill enables editors to review manuscripts efficiently by executing dual independent agent reviews in parallel, leveraging the Task tool for streamlined evaluation.","zh":"review-paper 技术是用于论文评审的工具，通过 Task 工具创建两个独立的评审者","ja":"review-paper は、AIエージェントを使用して論文をレビューするためのツールです","ko":"review-paper 는 독립적인 에이전트를 사용하여 논문을 리뷰하는 개발자용 도구입니다","es":"La revisión de artículos con agentes de IA permite la ejecución de herramientas de revisión en paralelo. Esta función utiliza la herramienta Task para crear agentes independientes.","fr":"La révision d''articles avec des agents d''IA permet l''exécution d''outils de révision en parallèle. Cette fonction utilise l''outil Task pour créer des agents indépendants.","de":"Die Überprüfung von Artikeln mit KI-Agents ermöglicht die Ausführung von Überprüfungstools in Parallelverarbeitung. Diese Funktion verwendet das Tool Task, um unabhängige Agenten zu erstellen.","pt":"O review-paper é uma ferramenta de revisão de manuscritos para Ciência Política que utiliza a ferramenta Task para criar agentes independentes","ru":"ИИ Агент review-paper - это инструмент для рецензирования статей по политологии, который использует инструмент Task для создания независимых агентов","ar":"أداة استعراض الورقة البحثية هي أداة مراجعة المخطوطات للعلوم السياسية التي تستخدم أداة Task لإنشاء وكلاء مستقلين"},"seo":{"title":{"en":"review-paper: Expert Manuscript Review Setup Guide | AI A...","zh":"review-paper 技术指南：双重评审流程","ja":"review-paper セットアップガイド：AIエージェントを使用した論文レビュー","ko":"review-paper 개발자 가이드: 독립적인 에이전트 기반의 논문 리뷰","es":"Guía de Configuración de Revisión de Artículos con Agente...","fr":"Guide de Configuration de la Révision d''Articles avec des...","de":"Konfigurationsleitfaden für die Überprüfung von Artikeln ...","pt":"Guia de Configuração do review-paper: Ferramenta de Revis...","ru":"Настройка ИИ Агента review-paper: Инструмент для рецензир...","ar":"دليل إعداد أداة استعراض الورقة البحثية: أداة مراجعة المخط..."},"description":{"en":"Unlock efficient manuscript review with review-paper! Learn how to execute dual independent agent reviews in parallel and streamline your editorial process","zh":"了解 review-paper 技术的详细信息，包括双重评审流程和 Task 工具的使用","ja":"review-paper の機能と AIエージェントを使用した論文レビューの方法を紹介します","ko":"review-paper 에 대한 기술 정보와 독립적인 에이전트를 사용한 논문 리뷰 방법을 제공합니다","es":"Aprende a configurar la revisión de artículos con agentes de IA. Descubre las mejores prácticas y los pasos para ejecutar herramientas de revisión en paralelo.","fr":"Découvrez comment configurer la révision d''articles avec des agents d''IA. Apprenez les meilleures pratiques et les étapes pour exécuter des outils de révisio...","de":"Erfahren Sie, wie Sie die Überprüfung von Artikeln mit KI-Agents konfigurieren. Entdecken Sie die besten Praktiken und die Schritte zur Ausführung von Überpr...","pt":"Aprenda a configurar o review-paper, uma ferramenta de revisão de manuscritos para Ciência Política, e descubra como melhorar o processo de revisão","ru":"Узнайте, как настроить ИИ Агент review-paper, инструмент для рецензирования статей по политологии, и улучшите процесс рецензирования","ar":"تعرف على كيفية إعداد أداة استعراض الورقة البحثية، أداة مراجعة المخطوطات للعلوم السياسية، وتعلم كيف تحسن عملية المراجعة"},"definition":{"en":"review-paper is a specialized AI agent skill designed for editors to review and evaluate manuscripts using a dual-agent approach","zh":"review-paper 是一种论文评审工具，使用 Task 工具创建两个独立的评审者","ja":"review-paper は、AIエージェントを使用して論文をレビューするためのツールです","ko":"review-paper 는 논문을 리뷰하기 위한 독립적인 에이전트를 생성하는 개발자용 도구입니다","es":"La revisión de artículos con agentes de IA es una función que permite la ejecución de herramientas de revisión en paralelo utilizando la herramienta Task.","fr":"La révision d''articles avec des agents d''IA est une fonction qui permet l''exécution d''outils de révision en parallèle en utilisant l''outil Task.","de":"Die Überprüfung von Artikeln mit KI-Agents ist eine Funktion, die die Ausführung von Überprüfungstools in Parallelverarbeitung unter Verwendung des Tools Task ermöglicht.","pt":"O review-paper é uma ferramenta de revisão de manuscritos que ajuda a melhorar a qualidade das publicações científicas","ru":"ИИ Агент review-paper - это инструмент для рецензирования статей, который помогает улучшить качество научных публикаций","ar":"أداة استعراض الورقة البحثية هي أداة مراجعة المخطوطات التي تساعد على تحسين جودة المنشورات العلمية"},"features":{"en":["Executes dual independent agent reviews in parallel using the Task tool","Utilizes a two-step process for comprehensive manuscript evaluation","Leverages the Task DUAS tool for efficient agent creation and execution","Supports parallel execution of multiple tool calls within a single message","Enables editors to review manuscripts for top journals such as APSR, AJPS, JOP, and IO"],"zh":["双重评审流程","Task 工具的使用","两个独立的评审者","并行执行评审任务","支持论文评审的技术"],"ja":["AIエージェントを使用した論文レビュー","Task ツールの使用","二つの独立したエージェント","並列実行のレビュータスク","論文レビューをサポートする技術"],"ko":["독립적인 에이전트 기반의 논문 리뷰","Task 도구의 사용","두 개의 독립적인 에이전트","병렬적으로 실행되는 리뷰 태스크","논문 리뷰를 지원하는 기술"],"es":["Ejecución de herramientas de revisión en paralelo","Uso de la herramienta Task para crear agentes independientes","Compatibilidad con la creación de dos agentes independientes","Ejecución de herramientas de revisión en la misma mensaje","Uso de la función de revisión de manuscritos","Integración con la herramienta DUAS"],"fr":["Exécution d''outils de révision en parallèle","Utilisation de l''outil Task pour créer des agents indépendants","Compatibilité avec la création de deux agents indépendants","Exécution d''outils de révision dans le même message","Utilisation de la fonction de révision de manuscrits","Intégration avec l''outil DUAS"],"de":["Ausführung von Überprüfungstools in Parallelverarbeitung","Verwendung des Tools Task zur Erstellung unabhängiger Agenten","Kompatibilität mit der Erstellung von zwei unabhängigen Agenten","Ausführung von Überprüfungstools in der gleichen Nachricht","Verwendung der Funktion zur Überprüfung von Manuskripten","Integration mit dem Tool DUAS"],"pt":["Criação de agentes independentes utilizando a ferramenta Task","Revisão de manuscritos para Ciência Política","Utilização de dois agentes em paralelo para melhorar a eficiência","Compatibilidade com os principais jornais de Ciência Política","Fácil integração com a ferramenta Task"],"ru":["Создание независимых агентов с помощью инструмента Task","Рецензирование статей по политологии","Использование двух агентов в параллели для повышения эффективности","Совместимость с ведущими журналами по политологии","Легкая интеграция с инструментом Task"],"ar":["إنشاء وكلاء مستقلين باستخدام أداة Task","مراجعة المخطوطات للعلوم السياسية","استخدام两个 وكلاء في متوازي لتحسين الكفاءة","التوافق مع الدوريات العلمية الرائدة للعلوم السياسية","التكامل السهل مع أداة Task"]},"keywords":{"en":["how to use review-paper","review-paper setup guide","review-paper alternative","review-paper vs manuscript review tools","review-paper install","what is review-paper","review-paper for AI agents","manuscript review with review-paper","review-paper for editors"],"zh":["review-paper","论文评审","Task 工具","AI 评审","双重评审流程","论文评审技术"],"ja":["review-paper","論文レビュー","AIエージェント","Task ツール","二つの独立したエージェント","論文レビューの技術"],"ko":["review-paper","논문 리뷰","독립적인 에이전트","Task 도구","병렬적으로 실행되는 리뷰 태스크","논문 리뷰를 지원하는 기술"],"es":["revisión de artículos con agentes de IA","configuración de revisión de artículos","herramientas de revisión en paralelo","agentes de IA para revisión de artículos","revisión de manuscritos con herramientas de IA","integración con herramientas de revisión","desarrollo de herramientas de revisión","IA para revisión de artículos","revisión de artículos con KI","herramientas de revisión de artículos"],"fr":["révision d''articles avec des agents d''IA","configuration de la révision d''articles","outils de révision en parallèle","agents d''IA pour la révision d''articles","révision de manuscrits avec des outils d''IA","intégration avec des outils de révision","développement d''outils de révision","IA pour la révision d''articles","révision d''articles avec des agents d''IA","outils de révision d''articles"],"de":["Überprüfung von Artikeln mit KI-Agents","Konfiguration der Überprüfung von Artikeln","Überprüfungstools in Parallelverarbeitung","KI-Agents für die Überprüfung von Artikeln","Überprüfung von Manuskripten mit Überprüfungstools","Integration mit Überprüfungstools","Entwicklung von Überprüfungstools","KI für die Überprüfung von Artikeln","Überprüfung von Artikeln mit KI","Überprüfungstools für Artikel"],"pt":["review-paper","ferramenta de revisão de manuscritos","Ciência Política","Task","agentes independentes","revisão de artigos","publicações científicas","jornais de Ciência Política"],"ru":["ИИ Агент review-paper","инструмент для рецензирования статей","политология","Task","независимые агенты","рецензирование статей","научные публикации","журналы по политологии"],"ar":["أداة استعراض الورقة البحثية","أداة مراجعة المخطوطات","العلوم السياسية","Task","وكلاء مستقلين","مراجعة المخطوطات","المنشورات العلمية","الدوريات العلمية للعلوم السياسية"]}},"owner":"mgaldino","repo":"agents-workflow","repoPath":"mgaldino/agents-workflow","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.552Z","topics":[],"category":"community","skillMd":{"name":"review-paper","description":"Revisão de manuscrito estilo referee de top journal (dois pareceristas)","bodyPreview":"# Revisão de Manuscrito (Dois Pareceristas)\n\nVocê é o editor de um top journal em Ciência Política (APSR, AJPS, JOP, IO). **Não edite nenhum arquivo.**\n\n## INSTRUÇÃO OBRIGATÓRIA\n\nVocê DEVE executar os seguintes passos nesta ordem exata:\n\n1. Leia o manuscrito completo para entender o conteúdo.\n2. Use a ferramenta Task DUAS vezes para criar dois agentes independentes. Lance ambos em paralelo (na mesma mensagem, dois tool calls). Os prompts completos para cada agente estão abaixo.\n3. Após receber o","body":"# Revisão de Manuscrito (Dois Pareceristas)\n\nVocê é o editor de um top journal em Ciência Política (APSR, AJPS, JOP, IO). **Não edite nenhum arquivo.**\n\n## INSTRUÇÃO OBRIGATÓRIA\n\nVocê DEVE executar os seguintes passos nesta ordem exata:\n\n1. Leia o manuscrito completo para entender o conteúdo.\n2. Use a ferramenta Task DUAS vezes para criar dois agentes independentes. Lance ambos em paralelo (na mesma mensagem, dois tool calls). Os prompts completos para cada agente estão abaixo.\n3. Após receber os dois pareceres, você (o editor) escreve a Carta Editorial consolidada.\n\nNÃO faça a revisão você mesmo. NÃO produza um único parecer unificado. Você DEVE usar a ferramenta Task para criar dois agentes separados. Isso é obrigatório.\n\n---\n\n## Task 1: Parecerista 1\n\nUse a ferramenta Task com estes parâmetros:\n- description: \"Parecerista 1 — Teoria\"\n- subagent_type: general-purpose\n- prompt: (copie o bloco abaixo, substituindo CAMINHO_DO_ARQUIVO pelo caminho real)\n\n```\nVocê é o Parecerista 1 de um top journal em Ciência Política. Sua especialidade é teoria, contribuição substantiva e posicionamento na literatura. Você é um senior scholar da área que conhece a literatura de cabo a rabo. Sua pergunta guia é: \"por que eu deveria me importar com esse paper?\"\n\nLeia o manuscrito em CAMINHO_DO_ARQUIVO. Produza um parecer cobrindo as dimensões abaixo. NÃO edite nenhum arquivo — apenas retorne o parecer como texto.\n\nSuas dimensões de avaliação:\n\n1. Contribuição\n- A pergunta de pesquisa é clara e relevante?\n- Qual é a contribuição marginal sobre a literatura existente?\n- O paper resolve um puzzle ou preenche um gap real?\n- A contribuição é teórica, empírica, metodológica, ou combinação?\n\n2. Framing teórico (AVALIAR COM RIGOR)\n- Pergunta teórica vs empírica: A pergunta é formulada no nível da teoria (fenômeno geral) ou no nível do caso (evento específico)? Exemplo ruim: \"Qual o efeito das enchentes do RS sobre reeleição?\" Exemplo bom: \"Qual o efeito de desastres naturais sobre responsabilização eleitoral de incumbentes?\"\n- Mecanismo explícito: O \"por quê\" está articulado? Há um mecanismo causal claro ligando X a Y, não apenas uma correlação esperada?\n- Scope conditions: O paper explicita quando o argumento se aplica e quando não? Quais são os moderadores?\n- Caso como teste, não como pergunta: O caso empírico é apresentado como instância de um fenômeno mais geral, ou a pergunta é sobre o caso em si?\n- Generalização teórica: O paper articula o que aprendemos além do caso específico?\n\n3. Argumento e mecanismo (ângulo teórico)\n- O mecanismo causal é teoricamente plausível?\n- As hipóteses derivam logicamente do argumento?\n- Explicações alternativas são consideradas e descartadas teoricamente?\n- O framework teórico é parcimonioso?\n- A seleção de caso é adequada para testar a teoria?\n\n4. Apresentação (ângulo narrativo)\n- A escrita é clara e persuasiva?\n- A estrutura narrativa faz sentido (puzzle → teoria → evidência → implicações)?\n- A introdução vende o paper? O leitor entende a contribuição em 2 páginas?\n- As conclusões articulam implicações teóricas mais amplas?\n- O paper tem tamanho adequado (sem padding)?\n\n5. Referências substantivas\n- O paper engaja com a literatura certa?\n- Faltam referências-chave na área substantiva?\n- Há debates que o paper ignora mas deveria engajar?\n\nFormato OBRIGATÓRIO do seu parecer:\n\n# Parecer — Parecerista 1 (Teoria & Substância)\n\n## Recomendação: [Rejeitar / R&R major / R&R minor / Aceitar]\n\n## Resumo do paper\n[2-3 frases]\n\n## Avaliação geral\n[Parágrafo sintético — pontos fortes e fracos principais do ponto de vista teórico/substantivo]\n\n## Comentários maiores\n1. [Numerados, com explicação e sugestão construtiva]\n\n## Comentários menores\n1. [Pontos menores]\n\n## Referências sugeridas\n- [Papers substantivos que o autor deveria engajar]\n\nTom: rigoroso mas construtivo. Cada crítica com sugestão de melhoria. Reconheça o que está bem feito.\n```\n\n---\n\n## Task 2: Parecerista 2\n\nUse a ferramenta Task com estes parâmetros:\n- description: \"Parecerista 2 — Método\"\n- subagent_type: general-purpose\n- prompt: (copie o bloco abaixo, substituindo CAMINHO_DO_ARQUIVO pelo caminho real)\n\n```\nVocê é o Parecerista 2 de um top journal em Ciência Política. Sua especialidade é econometria aplicada, estratégias de identificação e inferência causal. Você é um metodólogo rigoroso. Sua pergunta guia é: \"como você sabe que é causal?\"\n\nLeia o manuscrito em CAMINHO_DO_ARQUIVO. Produza um parecer cobrindo as dimensões abaixo. NÃO edite nenhum arquivo — apenas retorne o parecer como texto.\n\nSuas dimensões de avaliação:\n\n1. Estratégia de identificação\n- O design de pesquisa é adequado para a pergunta causal?\n- A estratégia de identificação é convincente? Quais são os pressupostos e são plausíveis?\n- Há problemas de endogeneidade, viés de seleção, ou causalidade reversa?\n- O paper usa o melhor método disponível para o problema, ou há alternativa superior?\n- Se é DiD: parallel trends é testável e testado? Se é IV: exclusion restriction é plausível? Se é RDD: bandwidth sensitivity? Se é matching: overlap e balance?\n\n2. Dados e mensuração\n- Os dados são apropriados para testar as hipóteses?\n- A mensuração das variáveis-chave é válida?\n- Há problemas de missing data, attrition, ou measurement error?\n- Unidade de análise está correta?\n- Período temporal faz sentido para a pergunta?\n\n3. Especificação e inferência\n- A especificação econométrica está correta?\n- Erros-padrão são adequados ao design (cluster, robust, HC)?\n- Variáveis de controle fazem sentido teórico (não são bad controls / colliders)?\n- Functional form é adequada?\n- Há múltiplas comparações sem correção?\n\n4. Robustez e resultados\n- Os resultados sustentam as conclusões?\n- A magnitude dos efeitos é discutida (não apenas significância estatística)?\n- Heterogeneidade é explorada?\n- Resultados nulos são tratados honestamente?\n- Testes de robustez são suficientes? Considere sugerir:\n  - Especificações alternativas\n  - Amostras alternativas\n  - Placebo tests\n  - Diferentes medidas do outcome/tratamento\n  - Permutation / randomization inference\n\n5. Argumento e mecanismo (ângulo empírico)\n- O mecanismo causal é testado ou apenas assumido?\n- Há evidência sobre o canal (mediation analysis, mecanismos observáveis)?\n- O paper distingue entre o efeito total e o mecanismo?\n\n6. Apresentação (ângulo técnico)\n- Tabelas são claras, com notas sobre erros-padrão e significância?\n- Figuras são informativas (coefficient plots, event studies, binscatters)?\n- Estatísticas descritivas são suficientes para entender os dados?\n- Apêndice online tem os detalhes técnicos necessários?\n\n7. Referências metodológicas\n- O paper cita a literatura metodológica relevante?\n- Há avanços recentes em métodos que o paper deveria usar?\n\nFormato OBRIGATÓRIO do seu parecer:\n\n# Parecer — Parecerista 2 (Método & Inferência)\n\n## Recomendação: [Rejeitar / R&R major / R&R minor / Aceitar]\n\n## Resumo do paper\n[2-3 frases]\n\n## Avaliação geral\n[Parágrafo sintético — pontos fortes e fracos principais do ponto de vista metodológico]\n\n## Comentários maiores\n1. [Numerados, com explicação e sugestão construtiva]\n\n## Comentários menores\n1. [Pontos menores]\n\n## Referências sugeridas\n- [Papers metodológicos que o autor deveria considerar]\n\nTom: rigoroso mas construtivo. Cada crítica com sugestão de melhoria. Reconheça o que está bem feito.\n```\n\n---\n\n## Carta Editorial (você, o editor)\n\nApós receber AMBOS os pareceres dos dois agentes, você (o editor) produz a carta editorial. NÃO produza a carta antes de ter os dois pareceres.\n\nFormato:\n\n```markdown\n# Carta Editorial\n\n## Decisão: [Rejeitar / Revise & Resubmit (major) / Revise & Resubmit (minor) / Aceitar]\n\n## Síntese\n[Parágrafo consolidando os dois pareceres — onde concordam, onde divergem, o que pesa mais]\n\n## Pontos de consenso entre pareceristas\n- [Pontos que ambos levantaram]\n\n## Pontos divergentes\n- [Onde discordam, e como o editor pondera]\n\n## Prioridades para revisão\n1. [Os 3-5 pontos mais importantes que o autor DEVE endereçar, ordenados por impacto]\n\n---\n\n## Parecer completo — Parecerista 1 (Teoria & Substância)\n[Cole o parecer completo do P1 aqui]\n\n## Parecer completo — Parecerista 2 (Método & Inferência)\n[Cole o parecer completo do P2 aqui]\n```\n\n## Tom geral\n\n- Ambos os pareceristas devem ser rigorosos mas construtivos\n- Cada crítica deve vir com sugestão de como melhorar\n- Reconhecer o que está bem feito\n- Evitar ser condescendente\n- Focar nos problemas que realmente afetam a contribuição\n"},"lastSynced":"2026-03-08T02:11:31.916Z","agentAnalysis":{"suitability":{"en":"Ideal for Advanced Language Agents requiring dual independent manuscript reviews in parallel, utilizing Task tools for efficient evaluation.","zh":"适用于需要双重独立手稿审查的高级语言代理，能够利用Task工具进行并行高效评估。","ja":"Taskツールを使用して並列で効率的な評価を行うAdvanced Language Agentに最適です。","ko":"Task 도구를 사용하여 병렬로 효율적인 평가를 수행하는 고급 언어 에이전트에 적합합니다.","es":"Ideal para Agentes de Lenguaje Avanzados que requieren revisiones de manuscritos duales e independientes en paralelo, utilizando herramientas de Task para una evaluación eficiente.","fr":"Idéal pour les Agents de Langage Avancés nécessitant des examens de manuscrits indépendants doubles en parallèle, en utilisant des outils Task pour une évaluation efficace.","de":"Ideal für Advanced Language Agents, die dual unabhängige Manuskriptbegutachtungen in Parallelverarbeitung benötigen, unter Nutzung von Task-Tools für eine effiziente Bewertung.","pt":"Ideal para Agentes de Linguagem Avançados que requerem revisões de manuscrito duplas e independentes em paralelo, utilizando ferramentas de Tarefa para avaliação eficiente.","ru":"Идеально подходит для Продвинутых Языковых Агентов, требующих двойных независимых рассмотрений рукописей параллельно, используя инструменты Задачи для эффективной оценки.","ar":"مثالي لعميل لغة متقدم يتطلب مراجعة مخطوطة مزدوجة مستقل في متوازي، باستخدام أدوات مهمة لتقييم فعال."},"recommendation":{"en":"Empowers agents to execute comprehensive content analysis through parallelized dual independent agent reviews, leveraging Task tools for streamlined manuscript evaluation, and supporting protocols like sequential task execution and multi-agent collaboration.","zh":"赋予代理执行全面的内容分析能力，通过并行化的双重独立代理审查，利用Task工具简化手稿评估，并支持诸如顺序任务执行和多代理协作等协议。","ja":"エージェントに包括的なコンテンツ分析を実行させることができます。Taskツールを使用して並列で効率的な評価を行い、シーケンシャルタスクの実行やマルチエージェントのコラボレーションなどのプロトコルをサポートします。","ko":"에이전트가 포괄적인 콘텐츠 분석을 수행하도록 하는데, Task 도구를 사용하여 효율적인 평가를 수행하고, 순차적 작업 실행 및多エージェント 협업 등의 프로토콜을 지원합니다.","es":"Habilita a los agentes a ejecutar un análisis de contenido integral a través de revisiones de agentes duales independientes en paralelo, aprovechando las herramientas de Task para una evaluación de manuscritos optimizada y apoyando protocolos como la ejecución de tareas secuenciales y la colaboración entre múltiples agentes.","fr":"Permet aux agents d''exécuter une analyse de contenu approfondie via des examens d''agents indépendants doubles en parallèle, en exploitant les outils Task pour une évaluation de manuscrits rationalisée et en soutenant des protocoles tels que l''exécution de tâches séquentielles et la collaboration entre plusieurs agents.","de":"Ermächtigt Agenten, eine umfassende Inhaltsanalyse durch parallelisierte, unabhängige Doppelagentenbewertungen durchzuführen, indem Task-Tools für eine optimierte Manuskriptbewertung genutzt werden und Protokolle wie sequenzielle Aufgabenausführung und Zusammenarbeit zwischen mehreren Agenten unterstützt werden.","pt":"Habilita agentes a executar análise de conteúdo abrangente por meio de revisões de agentes duplos e independentes paralelos, aproveitando ferramentas de Tarefa para avaliação de manuscrito otimizada e apoiando protocolos como execução de tarefas sequenciais e colaboração multiagente.","ru":"Наделяет агентов возможностью выполнять всесторонний анализ контента посредством параллелизированных двойных независимых рассмотрений агентов, используя инструменты Задачи для оптимизированной оценки рукописей и поддержки протоколов, таких как последовательная выполнение задач и многоагентное сотрудничество.","ar":"يتمكن العملاء من تنفيذ تحليل محتوى شاملة من خلال استعراض عميل مزدوج مستقل متوازي، مستفيداً من أدوات مهمة لتقييم مخطوطة متدفق ومدعوم ببروتوكولات مثل تنفيذ مهمة متسلسلة وتعاون متعدد العملاء."},"useCases":{"en":["Conducting dual independent reviews of manuscripts in parallel","Streamlining evaluation processes with Task tools","Enhancing editorial efficiency in top journals like APSR, AJPS, JOP, IO"],"zh":["并行进行双重独立的手稿审查","使用Task工具简化评估流程","提高顶级期刊如APSR、AJPS、JOP、IO的编辑效率"],"ja":["並列で独立した原稿のレビューを実施する","Taskツールを使用して評価プロセスを合理化する","トップジャーナル such as APSR、AJPS、JOP、IOの編集効率を向上させる"],"ko":["병렬로 독립적인 원고의 리뷰를 수행하는こと","Task 도구를 사용하여 평가 프로세스를 간소화하는 것","최상위 저널 such as APSR、AJPS、JOP、IO의 편집 효율성을 향상시키는 것"],"es":["Realizar revisiones duales independientes de manuscritos en paralelo","Optimizar los procesos de evaluación con herramientas de Task","Mejorar la eficiencia editorial en las principales revistas como APSR, AJPS, JOP, IO"],"fr":["Réalisant des examens indépendants doubles de manuscrits en parallèle","Rationaliser les processus d''évaluation avec des outils Task","Améliorer l''efficacité éditoriale dans les principales revues comme APSR, AJPS, JOP, IO"],"de":["Durchführen von dual unabhängigen Manuskriptbegutachtungen in Parallelverarbeitung","Optimieren der Bewertungsprozesse mit Task-Tools","Verbesserung der redaktionellen Effizienz in führenden Zeitschriften wie APSR, AJPS, JOP, IO"],"pt":["Realizar revisões de manuscrito duplas e independentes em paralelo","Otimizar processos de avaliação com ferramentas de Tarefa","Aumentar a eficiência editorial em principais jornais como APSR, AJPS, JOP, IO"],"ru":["Проведение двойных независимых рассмотрений рукописей параллельно","Оптимизация процессов оценки с помощью инструментов Задачи","Повышение редакторской эффективности в ведущих журналах, таких как APSR, AJPS, JOP, IO"],"ar":["إجراء استعراض مخطوطة مزدوج مستقل في متوازي","تسهيل عمليات التقييم بأدوات مهمة","تعزيز الكفاءة التحريرية في مجلات رائدة مثل APSR و AJPS و JOP و IO"]},"limitations":{"en":["Requires access to manuscript content","Limited to dual independent agent reviews","No file editing capabilities"],"zh":["需要访问手稿内容","仅限双重独立代理审查","没有文件编辑功能"],"ja":["原稿の内容にアクセスする必要がある","独立したエージェントのレビューは2つまで","ファイル編集機能がない"],"ko":["원고 내용에 액세스해야 함","독립 에이전트 리뷰는 2개로 제한됨","파일 편집 기능 없음"],"es":["Requiere acceso al contenido del manuscrito","Limitado a revisiones de agentes duales independientes","No tiene capacidades de edición de archivos"],"fr":["Nécessite un accès au contenu du manuscrit","Limité aux examens d''agents indépendants doubles","N''a pas de capacités d''édition de fichiers"],"de":["Benötigt Zugriff auf den Manuskriptinhalt","Begrenzt auf unabhängige Doppelagentenbewertungen","Hat keine Dateibearbeitungsfunktionen"],"pt":["Requer acesso ao conteúdo do manuscrito","Limitado a revisões de agente duplo e independente","Nenhuma capacidade de edição de arquivos"],"ru":["Требует доступа к содержанию рукописи","Ограничен двойными независимыми рассмотрениями агентов","Нет возможности редактирования файлов"],"ar":["يتطلب الوصول إلى محتوى المخطوطة","محدود بالاستعراض المزدوج المستقل للعميل","لا يوجد إمكانية لتحرير الملفات"]},"version":4},"contentHash":"33e0b1bfd543b6aecbcac0555a7a0bd13efd54087270c17b137ca05bbb602b46","qualityScore":33}');
