INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('mgaldino/agents-workflow/review-paper', 'review-paper', 'mgaldino', 'agents-workflow', 'community', 'review-paper mgaldino agents-workflow community The review-paper skill enables editors to review manuscripts efficiently by executing dual independent agent reviews in parallel, leveraging the Task tool for streamlined evaluation. review-paper 技术是用于论文评审的工具，通过 Task 工具创建两个独立的评审者 review-paper は、AIエージェントを使用して論文をレビューするためのツールです review-paper 는 독립적인 에이전트를 사용하여 논문을 리뷰하는 개발자용 도구입니다 La revisión de artículos con agentes de IA permite la ejecución de herramientas de revisión en paralelo. Esta función utiliza la herramienta Task para crear agentes independientes. La révision d''articles avec des agents d''IA permet l''exécution d''outils de révision en parallèle. Cette fonction utilise l''outil Task pour créer des agents indépendants. Die Überprüfung von Artikeln mit KI-Agents ermöglicht die Ausführung von Überprüfungstools in Parallelverarbeitung. Diese Funktion verwendet das Tool Task, um unabhängige Agenten zu erstellen. O review-paper é uma ferramenta de revisão de manuscritos para Ciência Política que utiliza a ferramenta Task para criar agentes independentes ИИ Агент review-paper - это инструмент для рецензирования статей по политологии, который использует инструмент Task для создания независимых агентов أداة استعراض الورقة البحثية هي أداة مراجعة المخطوطات للعلوم السياسية التي تستخدم أداة Task لإنشاء وكلاء مستقلين how to use review-paper review-paper setup guide review-paper alternative review-paper vs manuscript review tools review-paper install what is review-paper review-paper for AI agents manuscript review with review-paper review-paper for editors review-paper 论文评审 Task 工具 AI 评审 双重评审流程 论文评审技术 Executes dual independent agent reviews in parallel using the Task tool Utilizes a two-step process for comprehensive manuscript evaluation Leverages the Task DUAS tool for efficient agent creation and execution Supports parallel execution of multiple tool calls within a single message Enables editors to review manuscripts for top journals such as APSR, AJPS, JOP, and IO review-paper is a specialized AI agent skill designed for editors to review and evaluate manuscripts using a dual-agent approach');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('jeongbeenson19/research_notes/create-paper-note', 'community', 'jeongbeenson19', 'research_notes', 'jeongbeenson19/research_notes', 'create-paper-note', 0, 0, 33, '2026-03-08T01:57:15.571Z', '2026-03-08T02:11:45.992Z', '52e4601edae2eb0d0001713a1e7355345182ec0fd6a277d1064690f0782fd92a', '{"id":"jeongbeenson19/research_notes/create-paper-note","name":"create-paper-note","description":{"en":"The create-paper-note skill automates the creation of new paper summary notes in a specified directory, using a template and Google web search to find paper details. This skill benefits researchers and academics.","zh":"create-paper-note技能自动创建论文摘要笔记，基于60_Library/Research/MNS/MNS(Workflow).md模板","ja":"create-paper-noteスキルは、60_Library/Research/MNS/MNS(Workflow).mdテンプレートに基づいて論文のサマリー ノートを作成します","ko":"create-paper-note 스킬은 60_Library/Research/MNS/MNS(Workflow).md 템플릿을 기반으로 논문 요약 노트를 자동 생성합니다","es":"El skill create-paper-note automatiza la creación de resúmenes de papel en un directorio específico, utilizando una plantilla predefinida.","fr":"Le skill create-paper-note automatise la création de résumés de papier dans un répertoire spécifique, en utilisant un modèle prédéfini.","de":"Das Skill create-paper-note automatisiert die Erstellung von Papier-Zusammenfassungen in einem bestimmten Verzeichnis, unter Verwendung einer vordefinierten Vorlage.","pt":"O agente de notas de papel cria resumos de artigos automaticamente com base em um modelo. Ele pesquisa detalhes do artigo usando a ferramenta de pesquisa da web do Google.","ru":"ИИ Агент создает записи о статьях автоматически на основе шаблона. Он использует инструмент поиска Google для tìmания деталей статьи.","ar":"وسيط ملاحظات الورق يُنشئ ملخصات للمقالات تلقائيًا باستخدام نموذج محدد. يستخدم أداة بحث الويب من جوجل لإيجاد تفاصيل المقال"},"seo":{"title":{"en":"create-paper-note: Automated Paper Summary Note Creation ...","zh":"创建论文笔记设置指南 - AI工具","ja":"論文ノート作成セットアップガイド - AIエージェント","ko":"논문 노트 생성 설정 가이드 - AI 에이전트","es":"Guía de configuración para crear notas de papel con AI Agent","fr":"Guide de création de notes de papier avec l''outil AI","de":"Einrichtungsleitfaden für die Erstellung von Papier-Notiz...","pt":"Guia de Configuração do Agente de Notas de Papel","ru":"ИИ Агент: Создание Записи о Статье - Руководство","ar":"دليل إعداد وسيط ملاحظات الورق"},"description":{"en":"Discover how to automate paper note creation with create-paper-note. Learn how to setup and use this AI agent skill to streamline your research workflow","zh":"使用create-paper-note技能自动创建论文摘要笔记，基于模板和谷歌搜索结果","ja":"create-paper-noteスキルを使用して論文のサマリー ノートを作成します。テンプレートとGoogle検索結果に基づいています","ko":"create-paper-note 스킬을 사용하여 논문 요약 노트를 자동 생성합니다. 템플릿과 구글 검색 결과를 기반으로 합니다","es":"Aprende a crear notas de papel de manera automática con nuestra guía de configuración para el skill create-paper-note","fr":"Découvrez comment créer des notes de papier de manière automatisée avec notre guide de configuration pour le skill create-paper-note","de":"Erfahren Sie, wie Sie Papier-Notizen automatisch erstellen können, mit unserer Einrichtungsanleitung für das Skill create-paper-note","pt":"Aprenda a configurar o agente de notas de papel para automatizar a criação de resumos de artigos em seu diretório de pesquisa","ru":"Настройте ИИ Агент для автоматизации создания записей о статьях в вашем исследовательском каталоге","ar":"تعلم كيفية إعداد وسيط ملاحظات الورق لتوفير وقتك في إنشاء ملخصات للمقالات في دليلك البحثي"},"definition":{"en":"create-paper-note is a skill that automates the creation of paper summary notes based on a template and Google web search results","zh":"create-paper-note是一种AI工具，用于自动创建论文摘要笔记","ja":"create-paper-noteは、論文のサマリー ノートを作成するAIエージェントです","ko":"create-paper-note는 논문 요약 노트를 자동 생성하는 AI 에이전트입니다","es":"El skill create-paper-note es una herramienta de AI que crea notas de papel automáticamente, basadas en una plantilla predefinida.","fr":"Le skill create-paper-note est un outil d''IA qui crée des notes de papier de manière automatisée, en utilisant un modèle prédéfini.","de":"Das Skill create-paper-note ist ein KI-Tool, das Papier-Notizen automatisch erstellt, basierend auf einer vordefinierten Vorlage.","pt":"O que é um agente de notas de papel? É uma ferramenta de automação que cria resumos de artigos em um diretório de pesquisa.","ru":"Что такое ИИ Агент? Это инструмент автоматизации, который создает записи о статьях в исследовательском каталоге.","ar":"ما هو وسيط ملاحظات الورق؟ هو أداة تلقائية لإنشاء ملخصات للمقالات في دليل البحث"},"features":{"en":["Automates paper note creation in the 60_Library/Research/MNS/04_Papers/ directory","Uses a template found in 60_Library/Research/MNS/MNS(Workflow).md","Utilizes the google_web_search tool to find paper details","Supports searching for paper titles, venues, years, and public URLs on arXiv","Generates notes based on user-provided paper titles"],"zh":["基于60_Library/Research/MNS/MNS(Workflow).md模板创建论文摘要笔记","使用google_web_search工具查找论文标题、发表地点、年份和公共URL","支持多种语言和地域","自动创建论文摘要笔记","基于模板和搜索结果生成笔记"],"ja":["60_Library/Research/MNS/MNS(Workflow).mdテンプレートに基づいて論文のサマリー ノートを作成","google_web_searchツールを使用して論文のタイトル、発表場所、年、公開URLを検索","複数の言語と地域をサポート","自動的に論文のサマリー ノートを作成","テンプレートと検索結果に基づいてノートを生成"],"ko":["60_Library/Research/MNS/MNS(Workflow).md 템플릿을 기반으로 논문 요약 노트를 자동 생성","google_web_search 도구를 사용하여 논문 제목, 발표 장소, 연도, 공개 URL을 검색","다중 언어와 지역을 지원","자동으로 논문 요약 노트를 생성","템플릿과 검색 결과를 기반으로 노트를 생성"],"es":["Uso de la herramienta google_web_search para encontrar detalles del papel","Creación de notas de papel en un directorio específico","Utilización de una plantilla predefinida para la creación de notas","Compatibilidad con búsquedas en arXiv","Automatización del proceso de creación de notas"],"fr":["Utilisation de l''outil google_web_search pour trouver les détails du papier","Création de notes de papier dans un répertoire spécifique","Utilisation d''un modèle prédéfini pour la création de notes","Compatibilité avec les recherches sur arXiv","Automatisation du processus de création de notes"],"de":["Verwendung der google_web_search-Tools, um Papierdetails zu finden","Erstellung von Papier-Notizen in einem bestimmten Verzeichnis","Verwendung einer vordefinierten Vorlage für die Erstellung von Notizen","Kompatibilität mit arXiv-Suchen","Automatisierung des Erstellungsprozesses von Notizen"],"pt":["Criação automática de resumos de artigos","Pesquisa de detalhes do artigo usando a ferramenta de pesquisa da web do Google","Uso de um modelo de resumo pré-definido","Organização de resumos em um diretório de pesquisa","Compatibilidade com a ferramenta de pesquisa da web do Google","Integração com o diretório de pesquisa para armazenar resumos"],"ru":["Автоматическое создание записей о статьях","Поиск деталей статьи с помощью инструмента поиска Google","Использование предварительно определенного шаблона записи","Организация записей в исследовательском каталоге","Совместимость с инструментом поиска Google","Интеграция с исследовательским каталогом для хранения записей"],"ar":["إنشاء ملخصات للمقالات تلقائيًا","البحث عن تفاصيل المقال باستخدام أداة بحث الويب من جوجل","استخدام نموذج محدد مسبقًا لملخص المقال","تنظيم الملخصات في دليل البحث","التعاون مع أداة بحث الويب من جوجل","التكامل مع دليل البحث لتخزين الملخصات"]},"keywords":{"en":["how to use create-paper-note","create-paper-note setup guide","automated paper note creation","create-paper-note alternative","create-paper-note vs paper management tools","what is create-paper-note","create-paper-note install","paper note creation workflow"],"zh":["create-paper-note","AI工具","论文摘要笔记","谷歌搜索","自动创建","论文笔记模板","研究笔记","论文组织"],"ja":["create-paper-note","AIエージェント","論文のサマリー ノート","Google検索","自動作成","論文ノートテンプレート","研究ノート","論文整理"],"ko":["create-paper-note","AI 에이전트","논문 요약 노트","구글 검색","자동 생성","논문 노트 템플릿","연구 노트","논문 조직"],"es":["create-paper-note","herramientas de AI","notas de papel","automatización de tareas","google_web_search","arXiv","plantillas predefinidas","directorios específicos"],"fr":["create-paper-note","outils d''IA","notes de papier","automatisation de tâches","google_web_search","arXiv","modèles prédéfinis","répertoires spécifiques"],"de":["create-paper-note","KI-Tools","Papier-Notizen","Automatisierung von Aufgaben","google_web_search","arXiv","vordefinierte Vorlagen","bestimmte Verzeichnisse"],"pt":["agente de notas de papel","criação automática de resumos","pesquisa de artigos","ferramenta de pesquisa da web do Google","modelo de resumo","diretório de pesquisa","automatização de tarefas","produtividade acadêmica","ferramentas de pesquisa"],"ru":["ИИ Агент","создание записей о статьях","поиск статей","инструмент поиска Google","шаблон записи","исследовательский каталог","автоматизация задач","академическая производительность","инструменты поиска"],"ar":["وسيط ملاحظات الورق","إنشاء ملخصات للمقالات","البحث عن المقالات","أداة بحث الويب من جوجل","نموذج ملخص المقال","دليل البحث","توفير الوقت","الإنتاجية الأكاديمية","أدوات البحث"]}},"owner":"jeongbeenson19","repo":"research_notes","repoPath":"jeongbeenson19/research_notes","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.571Z","topics":[],"category":"community","skillMd":{"name":"create-paper-note","description":"MNS(Workflow).md에 정의된 템플릿에 따라, 논문 제목을 입력받아 60_Library/Research/MNS/04_Papers 디렉토리에 요약 노트를 생성합니다.","bodyPreview":"# Paper Note Creation Skill\n\nThis skill automates the creation of a new paper summary note in the `60_Library/Research/MNS/04_Papers/` directory, based on the template found in `60_Library/Research/MNS/MNS(Workflow).md`.\n\n## Workflow\n\n1.  **Get Paper Title**: The user will provide a paper title.\n2.  **Find Paper Details**: Use the `google_web_search` tool to find the paper''s official title, venue, year, and a public URL (prefer arXiv).\n    - **Query**: Use a query like `\"[paper_title]\" paper arx","body":"# Paper Note Creation Skill\n\nThis skill automates the creation of a new paper summary note in the `60_Library/Research/MNS/04_Papers/` directory, based on the template found in `60_Library/Research/MNS/MNS(Workflow).md`.\n\n## Workflow\n\n1.  **Get Paper Title**: The user will provide a paper title.\n2.  **Find Paper Details**: Use the `google_web_search` tool to find the paper''s official title, venue, year, and a public URL (prefer arXiv).\n    - **Query**: Use a query like `\"[paper_title]\" paper arxiv`.\n3.  **Construct File Content**: Use the paper details to fill out the template below. The \"Extract\" and \"Takeaway\" sections should be left as placeholders for the user to fill in, as they require in-depth analysis.\n4.  **Determine Filename**: The filename should be the paper''s official title.\n5.  **Create File**: Use the `write_file` tool to create the new markdown file in the `40_Papers/` directory.\n\n## Note Template\n\nUse the following markdown template for the file content.\n\n```markdown\n## Paper\n- Title: {{title}}\n- Venue/Year: {{venue_year}}\n- Link: {{url}}\n- 역할(문제정의/방법/평가/반박):\n\n## Extract\n- Task:\n- Unobserved interval:\n- Memory unit:\n- State:\n- Update rule:\n- Reactivation:\n- Fusion:\n- Assumptions:\n- Evaluation:\n- Failure modes:\n\n## Takeaway\n- 내 설계에 적용(1줄):\n- D1/D2/D3에 미치는 영향:\n```"},"lastSynced":"2026-03-08T02:11:45.992Z","agentAnalysis":{"suitability":{"en":"Ideal for Research Agents needing automated paper summary note creation with Google web search integration.","zh":"适用于需要自动创建论文摘要笔记并集成Google网页搜索的研究代理。","ja":"Google Web検索の統合による自動化された論文の要約ノートの作成が必要な研究エージェントに最適です。","ko":"구글 웹 검색 통합을 통해 자동으로 논문 요약 노트를 생성해야 하는 연구 에이전트에 적합합니다.","es":"Ideal para Agentes de Investigación que necesitan la creación automática de notas de resumen de artículos con integración de búsqueda web de Google.","fr":"Idéal pour les agents de recherche ayant besoin de la création automatisée de notes de résumé d''articles avec intégration de recherche web Google.","de":"Ideal für Forschungsagenten, die die automatisierte Erstellung von Artikelzusammenfassungsnotizen mit Google-Websuche-Integration benötigen.","pt":"Ideal para Agentes de Pesquisa que necessitam de criação automática de notas de resumo de artigos com integração de pesquisa na web do Google.","ru":"Идеально для Исследовательских Агентов, которым необходима автоматизированная создание заметок к статьям с интеграцией поиска в Интернете Google.","ar":"مثالي للوكلاء البحثيين الذين يحتاجون إلى إنشاء تلقائي لمذكرات ملخص الأوراق مع دمج البحث على شبكة الإنترنت من جوجل."},"recommendation":{"en":"Empowers agents to generate paper summary notes in Markdown format using a template, leveraging google_web_search for details like title, venue, year, and public URLs from arXiv, enhancing research efficiency with automated note organization in specified directories.","zh":"使代理能够使用模板以Markdown格式生成论文摘要笔记，利用google_web_search获取标题、场地、年份和arXiv的公开URL等详细信息，从而提高研究效率并自动组织指定目录中的笔记。","ja":"エージェントがテンプレートを使用してMarkdown形式で論文の要約ノートを生成できるようにし、google_web_searchを利用してタイトル、会場、年、arXivの公開URLなどの詳細を取得し、研究効率を高め、指定されたディレクトリのノートを自動で整理します。","ko":"에이전트가 템플릿을 사용하여 마크다운 형식으로 논문 요약 노트를 생성할 수 있도록 하며, google_web_search를 활용하여 제목, 장소, 연도 및 arXiv의 공개 URL 등의 세부 정보를 얻어 연구 효율성을 높이고 지정된 디렉토리의 노트를 자동으로 조직합니다.","es":"Permite a los agentes generar notas de resumen de artículos en formato Markdown utilizando una plantilla, aprovechando google_web_search para detalles como título, lugar, año y URLs públicas de arXiv, mejorando la eficiencia de la investigación con la organización automática de notas en directorios especificados.","fr":"Permet aux agents de générer des notes de résumé d''articles au format Markdown en utilisant un modèle, en exploitant google_web_search pour des détails tels que le titre, le lieu, l''année et les URL publiques d''arXiv, améliorant l''efficacité de la recherche avec l''organisation automatisée de notes dans des répertoires spécifiés.","de":"Ermöglicht es Agenten, Artikelzusammenfassungsnotizen im Markdown-Format mithilfe einer Vorlage zu generieren, indem google_web_search für Details wie Titel, Ort, Jahr und öffentliche URLs von arXiv genutzt wird, wodurch die Forschungseffizienz durch die automatische Notenorganisation in bestimmten Verzeichnissen verbessert wird.","pt":"Habilita os agentes a gerar notas de resumo de artigos em formato Markdown usando um modelo, aproveitando google_web_search para detalhes como título, local, ano e URLs públicas do arXiv, melhorando a eficiência da pesquisa com organização automática de notas em diretórios especificados.","ru":"Наделяет агентов возможностью генерировать заметки к статьям в формате Markdown с использованием шаблона, используя google_web_search для деталей, таких как название, место, год и публичные URL-адреса из arXiv, повышая эффективность исследования за счет автоматизированной организации заметок в указанных директориях.","ar":"تمكين الوكلاء من إنشاء مذكرات ملخص الأوراق في تنسيق Markdown باستخدام قالب، واستخدام google_web_search للتفاصيل مثل العنوان والمكان والسنة والرابط التشعبي العام من arXiv، وتحسين كفاءة البحث من خلال تنظيم المذكرات تلقائيًا في الدلائل المحددة."},"useCases":{"en":["Automating paper note creation for research libraries","Generating summaries with venue and year details","Organizing research papers with public URLs from arXiv"],"zh":["为研究图书馆自动创建论文笔记","使用场地和年份详细信息生成摘要","使用arXiv的公开URL组织研究论文"],"ja":["研究ライブラリの論文ノートの自動作成","会場と年などの詳細を使用して要約を生成する","arXivの公開URLを使用して研究論文を整理する"],"ko":["연구 도서관을 위한 논문 노트 자동 생성","장소 및 연도 세부 정보로 요약 생성","arXiv의 공개 URL로 연구 논문을 조직화"],"es":["Automatización de la creación de notas de artículos para bibliotecas de investigación","Generación de resúmenes con detalles de lugar y año","Organización de artículos de investigación con URLs públicas de arXiv"],"fr":["Automatisation de la création de notes d''articles pour les bibliothèques de recherche","Génération de résumés avec des détails de lieu et d''année","Organisation d''articles de recherche avec des URL publiques d''arXiv"],"de":["Automatisierung der Erstellung von Artikelnotizen für Forschungsbibliotheken","Erstellung von Zusammenfassungen mit Angaben zu Ort und Jahr","Organisation von Forschungsartikeln mit öffentlichen URLs von arXiv"],"pt":["Automatizar a criação de notas de artigos para bibliotecas de pesquisa","Gerar resumos com detalhes de local e ano","Organizar artigos de pesquisa com URLs públicas do arXiv"],"ru":["Автоматизировать создание заметок к статьям для исследовательских библиотек","Генерировать резюме с деталями о месте и годе","Организовать исследовательские статьи с публичными URL-адресами из arXiv"],"ar":["توفير إنشاء تلقائي لمذكرات الأوراق البحثية لمكتبات البحث","توليد ملخصات بالتفاصيل المكان والسنة","تنظيم الأوراق البحثية بالرابط التشعبي العام من arXiv"]},"limitations":{"en":["Requires Google web search functionality","Limited to Markdown template format","Dependent on accurate paper title input for search"],"zh":["需要Google网页搜索功能","仅限Markdown模板格式","依赖于准确的论文标题输入以进行搜索"],"ja":["Google Web検索機能が必要","Markdownテンプレート形式のみ","検索のために正確な論文タイトルの入力に依存"],"ko":["구글 웹 검색 기능이 필요","마크다운 템플릿 형식만 해당","검색을 위해 정확한 논문 제목 입력에 의존"],"es":["Requiere la funcionalidad de búsqueda web de Google","Limitado al formato de plantilla Markdown","Dependiente de la entrada precisa del título del artículo para la búsqueda"],"fr":["Nécessite la fonctionnalité de recherche web Google","Limité au format de modèle Markdown","Dépendant de la saisie précise du titre de l''article pour la recherche"],"de":["Benötigt die Funktionalität der Google-Websuche","Begrenzt auf das Markdown-Vorlagenformat","Abhängig von der genauen Eingabe des Artikeltitels für die Suche"],"pt":["Exige funcionalidade de pesquisa na web do Google","Limitado ao formato de modelo Markdown","Dependente da entrada precisa do título do artigo para a pesquisa"],"ru":["Требует функциональности поиска в Интернете Google","Ограничен форматом шаблона Markdown","Зависит от точного ввода названия статьи для поиска"],"ar":["يتطلب خاصية البحث على شبكة الإنترنت من جوجل","محدود بتنسيق القالب Markdown","يعتمد على إدخال دقيق للعنوان البحث للبحث"]},"version":4},"contentHash":"52e4601edae2eb0d0001713a1e7355345182ec0fd6a277d1064690f0782fd92a","qualityScore":33}');
