INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('jeongbeenson19/research_notes/create-paper-note', 'create-paper-note', 'jeongbeenson19', 'research_notes', 'community', 'create-paper-note jeongbeenson19 research_notes community The create-paper-note skill automates the creation of new paper summary notes in a specified directory, using a template and Google web search to find paper details. This skill benefits researchers and academics. create-paper-note技能自动创建论文摘要笔记，基于60_Library/Research/MNS/MNS(Workflow).md模板 create-paper-noteスキルは、60_Library/Research/MNS/MNS(Workflow).mdテンプレートに基づいて論文のサマリー ノートを作成します create-paper-note 스킬은 60_Library/Research/MNS/MNS(Workflow).md 템플릿을 기반으로 논문 요약 노트를 자동 생성합니다 El skill create-paper-note automatiza la creación de resúmenes de papel en un directorio específico, utilizando una plantilla predefinida. Le skill create-paper-note automatise la création de résumés de papier dans un répertoire spécifique, en utilisant un modèle prédéfini. Das Skill create-paper-note automatisiert die Erstellung von Papier-Zusammenfassungen in einem bestimmten Verzeichnis, unter Verwendung einer vordefinierten Vorlage. O agente de notas de papel cria resumos de artigos automaticamente com base em um modelo. Ele pesquisa detalhes do artigo usando a ferramenta de pesquisa da web do Google. ИИ Агент создает записи о статьях автоматически на основе шаблона. Он использует инструмент поиска Google для tìmания деталей статьи. وسيط ملاحظات الورق يُنشئ ملخصات للمقالات تلقائيًا باستخدام نموذج محدد. يستخدم أداة بحث الويب من جوجل لإيجاد تفاصيل المقال how to use create-paper-note create-paper-note setup guide automated paper note creation create-paper-note alternative create-paper-note vs paper management tools what is create-paper-note create-paper-note install paper note creation workflow create-paper-note AI工具 论文摘要笔记 谷歌搜索 自动创建 论文笔记模板 研究笔记 论文组织 Automates paper note creation in the 60_Library/Research/MNS/04_Papers/ directory Uses a template found in 60_Library/Research/MNS/MNS(Workflow).md Utilizes the google_web_search tool to find paper details Supports searching for paper titles, venues, years, and public URLs on arXiv Generates notes based on user-provided paper titles create-paper-note is a skill that automates the creation of paper summary notes based on a template and Google web search results');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('RoleModel/rolemodel-skills/theming-context', 'community', 'RoleModel', 'rolemodel-skills', 'RoleModel/rolemodel-skills', 'theming-context', 0, 0, 33, '2026-03-08T01:57:15.578Z', '2026-03-08T02:11:50.403Z', '05220c59a8f6a0da45cadcc1a43105bf3674ee5720da9c381f81a01e36822aa4', '{"id":"RoleModel/rolemodel-skills/theming-context","name":"theming-context","description":{"en":"The theming-context skill allows developers to customize applications with custom theme files, overriding existing tokens. It benefits developers working with RoleModel Software.","zh":"theming-context 是一个用于自定义应用程序的技术，允许开发者使用自定义主题文件覆盖现有 tokens","ja":"theming-context は、カスタムテーマファイルを使用して既存のトークンをオーバーライドすることで、アプリケーションのカスタマイズを実現する技術です","ko":"theming-context 는 사용자 정의 테마 파일을 사용하여 기존 토큰을 재정의하여 애플리케이션을 사용자 정의하는 기술입니다","es":"Theming-context es una colección de habilidades para personalizar aplicaciones. Permite override tokens y crear temas personalizados con CSS.","fr":"Theming-context est un ensemble de compétences pour personnaliser des applications. Il permet de override des tokens et de créer des thèmes personnalisés avec CSS.","de":"Theming-context ist eine Sammlung von Fähigkeiten zur Anpassung von Anwendungen. Es ermöglicht das Override von Token und die Erstellung von benutzerdefinierten Themen mit CSS.","pt":"O Theming-Context é uma coleção de habilidades de agente que permitem personalizar aplicativos com tokens personalizados e CSS de override","ru":"Theming-Context - это коллекция навыков агентов, позволяющая настраивать приложения с помощью пользовательских токенов и CSS-перехвата","ar":"السياق Theming-Context هو مجموعة من مهارات الوكيل التي تسمح بتخصيص التطبيقات باستخدام الرموز المميزة المخصصة و CSS الالتفاف"},"seo":{"title":{"en":"theming-context: Custom Theme Setup Guide | AI Agent Skill","zh":"theming-context 定制主题设置指南","ja":"theming-context カスタムテーマ設定ベストプラクティス","ko":"theming-context 사용자 정의 테마 설정 가이드","es":"Guía de configuración de theming-context para Agentes de IA","fr":"Guide de mise en place de theming-context pour les Outils...","de":"Einrichtungsleitfaden für theming-context in KI-Agents","pt":"Guia de Configuração do Theming-Context para Desenvolvedores","ru":"ИИ Агенты: Настройка Theming-Context для Разработчиков","ar":"دليل إعداد السياق Theming-Context لملحقي البرمجيات"},"description":{"en":"Discover how to override existing tokens with custom theme files in theming-context. Learn to import custom CSS and redefine luminos, colors, and fonts.","zh":"了解 theming-context 技术，如何使用自定义主题文件覆盖现有 tokens，包括颜色、半径、字体等","ja":"theming-context 技術を使用して、カスタムテーマファイルで既存のトークンをオーバーライドする方法を学びます","ko":"theming-context 기술을 사용하여 사용자 정의 테마 파일로 기존 토큰을 재정의하는 방법에 대해 알아보세요","es":"Aprende a personalizar aplicaciones con theming-context, una colección de habilidades para Agentes de IA. Descubre cómo override tokens y crear temas persona...","fr":"Découvrez comment personnaliser des applications avec theming-context, un ensemble de compétences pour les Outils d''IA. Apprenez à override des tokens et à c...","de":"Erfahren Sie, wie Sie Anwendungen mit theming-context anpassen, einer Sammlung von Fähigkeiten für KI-Agents. Erlearnen Sie, wie Sie Token override und eigen...","pt":"Aprenda a personalizar aplicativos com o Theming-Context, incluindo tokens personalizados e CSS de override","ru":"Откройте для себя возможности настройки приложений с помощью Theming-Context, включая пользовательские токены и CSS-перехват","ar":"تعلم كيفية تخصيص التطبيقات باستخدام السياق Theming-Context ، بما في ذلك الرموز المميزة المخصصة و CSS الالتفاف"},"definition":{"en":"theming-context is a collection of agent skills for customizing applications with override tokens, including colors, radius, fonts, and luminos.","zh":"theming-context 是一种用于自定义应用程序外观的技术","ja":"theming-context は、アプリケーションの外観をカスタマイズする技術です","ko":"theming-context 는 애플리케이션의外観을 사용자 정의하는 기술입니다","es":"Theming-context es una colección de habilidades para Agentes de IA que permite personalizar aplicaciones mediante la creación de temas personalizados.","fr":"Theming-context est un ensemble de compétences pour les Outils d''IA qui permet de personnaliser des applications via la création de thèmes personnalisés.","de":"Theming-context ist eine Sammlung von Fähigkeiten für KI-Agents, die die Anpassung von Anwendungen durch die Erstellung von benutzerdefinierten Themen ermöglicht.","pt":"O que é Theming-Context? É uma habilidade de agente que permite personalizar aplicativos com tokens personalizados","ru":"Что такое Theming-Context? Это навык агента, позволяющий настраивать приложения с помощью пользовательских токенов","ar":"ما هو السياق Theming-Context؟ إنه مهارة وكلاء يمكنها تخصيص التطبيقات باستخدام الرموز المميزة المخصصة"},"features":{"en":["Imports custom theme CSS files using @import","Overrides existing tokens, including colors and fonts","Redefines luminos for customized application appearance","Ensures custom theme precedence with ordered imports","Supports customization of radius and other visual elements"],"zh":["使用自定义主题文件覆盖现有 tokens","支持颜色、半径、字体等 tokens 的自定义","可以重新定义 luminos","支持使用 CSS 实现自定义主题","可以使用 @import 语句导入自定义主题文件"],"ja":["カスタムテーマファイルを使用して既存のトークンをオーバーライド","色、半径、フォントなどトークンのカスタマイズをサポート","luminos の再定義をサポート","CSS を使用してカスタムテーマを実現","@import 文を使用してカスタムテーマファイルをインポート"],"ko":["사용자 정의 테마 파일을 사용하여 기존 토큰을 재정의","색상, 반경, 글꼴 등 토큰의 사용자 정의를 지원","luminos 의 재정의를 지원","CSS 를 사용하여 사용자 정의 테마를 구현","@import 문을 사용하여 사용자 정의 테마 파일을 임포트"],"es":["Override de tokens con CSS","Creación de temas personalizados","Personalización de colores, radios y fuentes","Compatibilidad con Optics","Importación de archivos CSS personalizados","Rediseño de la luminosidad"],"fr":["Override de tokens avec CSS","Création de thèmes personnalisés","Personnalisation des couleurs, des radios et des polices","Compatibilité avec Optics","Importation de fichiers CSS personnalisés","Redéfinition de la luminosité"],"de":["Token-Override mit CSS","Erstellung von benutzerdefinierten Themen","Anpassung von Farben, Radien und Schriftarten","Kompatibilität mit Optics","Import von benutzerdefinierten CSS-Dateien","Neudefinierung der Helligkeit"],"pt":["Importação de arquivos CSS personalizados","Sobrescrita de tokens existentes","Definição de cores, raio e fontes personalizados","Redefinição de luminosidade"],"ru":["Импорт пользовательских файлов CSS","Перехват существующих токенов","Определение пользовательских цветов, радиуса и шрифтов","Переопределение светимости"],"ar":["استيراد ملفات CSS المخصصة","الالتفاف بالرموز المميزة الحالية","تحديد الألوان و النصف قطر و الخطوط المخصصة","إعادة تعريف اللمعان"]},"keywords":{"en":["how to use theming-context","theming-context setup guide","custom theme css import","theming-context vs rolemodel software","theming-context install","what is theming-context","theming-context alternative","override existing tokens","custom luminos definition"],"zh":["theming-context","AIエージェント","自定义主题","tokens","CSS","应用程序定制","色彩定制","字体定制"],"ja":["theming-context","AIエージェント","カスタムテーマ","トークン","CSS","アプリケーションのカスタマイズ","色のカスタマイズ","フォントのカスタマイズ"],"ko":["theming-context","AI 에이전트","사용자 정의 테마","토큰","CSS","애플리케이션 사용자 정의","색상 사용자 정의","글꼴 사용자 정의"],"es":["theming-context","Agentes de IA","personalización de aplicaciones","CSS","Optics","tokens","temas personalizados","desarrollo de software","tecnologías de IA"],"fr":["theming-context","Outils d''IA","personnalisation d''applications","CSS","Optics","tokens","thèmes personnalisés","développement de logiciels","technologies d''IA"],"de":["theming-context","KI-Agents","Anpassung von Anwendungen","CSS","Optics","Token","benutzerdefinierte Themen","Softwareentwicklung","KI-Technologien"],"pt":["Theming-Context","personalização de aplicativos","tokens personalizados","CSS de override","desenvolvimento de software"," RoleModel Software"],"ru":["Theming-Context","настройка приложений","пользовательские токены","CSS-перехват","разработка программного обеспечения","ИИ Агенты"],"ar":["السياق Theming-Context","تخصيص التطبيقات","الرموز المميزة المخصصة","CSS الالتفاف","تطوير البرمجيات","وكلاء الذكاء الاصطناعي"]}},"owner":"RoleModel","repo":"rolemodel-skills","repoPath":"RoleModel/rolemodel-skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.578Z","topics":[],"category":"community","skillMd":{"name":"theming-context","description":"Using Optics for implementing design system guidelines, theming, and color scales.","bodyPreview":"# Theming\nTo customize the application, a custom theme files that serve as overrides to the existing tokens can be provided. An example implementation of the main project CSS file would look like:\n```css\n@import ''@rolemodel/optics'';\n\n@import ''stylesheets/theme/my_app_theme'';\n```\nNote how the custom theme is imported after the main Optics styles, ensuring that any token overrides take precedence.\n\nA custom theme can change any tokens, including colors, radius, fonts, and even redefine the luminos","body":"# Theming\nTo customize the application, a custom theme files that serve as overrides to the existing tokens can be provided. An example implementation of the main project CSS file would look like:\n```css\n@import ''@rolemodel/optics'';\n\n@import ''stylesheets/theme/my_app_theme'';\n```\nNote how the custom theme is imported after the main Optics styles, ensuring that any token overrides take precedence.\n\nA custom theme can change any tokens, including colors, radius, fonts, and even redefine the luminosity and semantic scales.\n\n```css\n@import url(''https://fonts.googleapis.com/css2?family=Coming+Soon&display=swap'');\n@import url(''https://fonts.googleapis.com/css2?family=Grandstander:ital,wght@0,100;0,200;0,300;0,400;0,500;0,600;0,700;0,800;0,900;1,100;1,200;1,300;1,400;1,500;1,600;1,700;1,800;1,900&display=swap'');\n\n:root {\n  /* Colors */\n  --op-color-primary-h: my-new-value;\n  --op-color-primary-s: my-new-value;\n  --op-color-primary-l: my-new-value;\n\n  /* Color Scale */\n  --op-color-primary-plus-two: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 64%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 32%)\n  );\n\n  /* Fonts */\n  --op-font-family: ''Coming Soon'', sans-serif;\n}\n\n@media (prefers-color-scheme: dark) {\n  :root:not([data-theme-mode=''light'']) {\n    --op-font-family: ''Grandstander'', sans-serif;\n  }\n}\n\n:root[data-theme-mode=''dark''] {\n  --op-font-family: ''Grandstander'', sans-serif;\n}\n```\n\n### Color Scale Overriding\nIf  you need to override the provided color scales, you should redefine all the variants of that color to ensure consistency across the application. For example, if you are overriding the primary color, you should redefine all its variants like so:\n\n```css\n:root {\n  --op-color-primary-h: 164;\n  --op-color-primary-s: 100%;\n  --op-color-primary-l: 50%;\n\n  /* Main Scale */\n  --op-color-primary-plus-two: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 64%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 32%)\n  );\n  --op-color-primary-plus-one: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 45%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 35%)\n  );\n\n  /* On Scale */\n  --op-color-primary-on-plus-two: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 16%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 80%)\n  );\n  --op-color-primary-on-plus-two-alt: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 6%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 92%)\n  );\n  --op-color-primary-on-plus-one: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 100%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 80%)\n  );\n  --op-color-primary-on-plus-one-alt: light-dark(\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 95%),\n    hsl(var(--op-color-primary-h) var(--op-color-primary-s) 98%)\n  );\n}\n```\n\n## For More Information\nFor more details on theming and token overrides, refer to the Optics documentation using the links below\n- [Optics Repo](https://github.com/RoleModel/optics/)\n\n### Documentation Resources\nFor detailed component usage, refer to:\n- **Component API**: https://docs.optics.rolemodel.design/?path=/docs/components-button--docs\n- **Token Reference**: https://docs.optics.rolemodel.design/?path=/docs/overview-tokens--docs\n- **Color System**: https://docs.optics.rolemodel.design/?path=/docs/tokens-color-color-scale--docs\n\n### When You Need More Information\nIf the user asks about specific components or advanced features not covered in this skill:\n1. Use `web_fetch` or another method to retrieve the relevant documentation page\n2. Extract the specific information needed\n3. Apply it to the user''s request\n\nExample: For button variants, check https://docs.optics.rolemodel.design/?path=/docs/components-button--docs\n"},"lastSynced":"2026-03-08T02:11:50.403Z","agentAnalysis":{"suitability":{"en":"Perfect for Frontend Agents needing customizable UI theme management with CSS overrides.","zh":"非常适合需要自定义 UI 主题管理且支持 CSS 覆盖的前端代理。","ja":"フロントエンドエージェントがカスタマイズ可能な UI テーマ管理を必要とする場合に最適です。CSS のオーバーライドも対応しています。","ko":"사용자 정의 가능한 UI 테마 관리와 CSS 오버라이드가 필요한 프론트엔드 에이전트에 적합합니다.","es":"Perfecto para Agentes Frontend que necesitan gestión de temas de interfaz de usuario personalizables con anulaciones de CSS.","fr":"Parfait pour les agents Frontend qui ont besoin d''une gestion de thème d''interface utilisateur personnalisable avec des substitutions CSS.","de":"Perfekt für Frontend-Agents, die eine anpassbare UI-Themenverwaltung mit CSS-Überschreibungen benötigen.","pt":"Perfeito para Agentes Frontend que necessitam de gerenciamento de temas de UI personalizáveis com substituições de CSS.","ru":"Идеально для Фронтенд-агентов, которым необходима настраиваемая система управления темами UI с заменой CSS.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يحتاج إلى إدارة тем واجهة المستخدم القابلة للتعديل مع إيقاف خدمات CSS."},"recommendation":{"en":"Empowers agents to override existing tokens with custom theme files, utilizing CSS imports and variables to redefine colors, radius, fonts, and luminosity, all while integrating with RoleModel Software and Optics styles.","zh":"赋予代理人使用自定义主题文件覆盖现有令牌的能力，利用 CSS 导入和变量重新定义颜色、半径、字体和亮度，同时集成 RoleModel Software 和 Optics 样式。","ja":"エージェントに既存のトークンをカスタムテーマファイルでオーバーライドする能力を与え、CSS インポートと変数を使用して色、半径、フォント、明るさを再定義します。また、RoleModel Software と Optics スタイルも統合します。","ko":"에이전트에게 기존 토큰을 사용자 정의 테마 파일로 오버라이드할 수 있는 능력을 부여하여 CSS 가져오기와 변수를 사용하여 색상, 반지름, 글꼴 및 밝기를 재정의하고 RoleModel Software 및 Optics 스타일을 통합합니다.","es":"Habilita a los agentes a anular los tokens existentes con archivos de tema personalizados, utilizando importaciones de CSS y variables para redefinir colores, radios, fuentes y luminosidad, todo mientras se integra con RoleModel Software y estilos Optics.","fr":"Habilite les agents à remplacer les jetons existants par des fichiers de thème personnalisés, en utilisant des imports CSS et des variables pour rédéfinir les couleurs, les rayons, les polices et la luminosité, le tout en s''intégrant avec RoleModel Software et les styles Optics.","de":"Ermächtigt Agenten, bestehende Token mit benutzerdefinierten Theme-Dateien zu überschreiben, indem CSS-Importe und Variablen verwendet werden, um Farben, Radien, Schriftarten und Helligkeit neu zu definieren, all dies während der Integration mit RoleModel Software und Optics-Stilen.","pt":"Permite que os agentes substituam tokens existentes por arquivos de tema personalizados, utilizando imports de CSS e variáveis para redefinir cores, raio, fontes e luminosidade, tudo enquanto se integra com o software RoleModel e estilos Optics.","ru":"Наделяет агентов возможностью переопределить существующие токены пользовательскими файлами тем, используя импорт CSS и переменные для переопределения цветов, радиуса, шрифтов и яркости, все это при интеграции с программным обеспечением RoleModel и стилями Optics.","ar":"تمكن الوكلاء من إيقاف خدمات الرموز المتوفرة مع ملفات مخصصة للسمة، باستخدام استيراد CSS والمتغيرات لإعادة تعريف الألوان والنصف قطر والأحرف واللمعان، كل ذلك أثناء التكامل مع برنامج RoleModel وأساليب Optics."},"useCases":{"en":["Customizing application UI with bespoke themes","Overriding default tokens for brand consistency","Creating reusable theme files for multiple applications"],"zh":["使用自定义主题自定义应用程序 UI","覆盖默认令牌以保持品牌一致性","为多个应用程序创建可重用的主题文件"],"ja":["カスタムテーマを使用してアプリケーション UI をカスタマイズする","デフォルトトークンをオーバーライドしてブランド一致性を保持する","複数のアプリケーション用の再利用可能なテーマファイルを作成する"],"ko":["사용자 정의 테마를 사용하여 애플리케이션 UI를 사용자 정의하는 것","기본 토큰을 오버라이드하여 브랜드 일관성을 유지하는 것","다중 애플리케이션을 위한 재사용 가능한 테마 파일을 생성하는 것"],"es":["Personalizar la interfaz de usuario de la aplicación con temas personalizados","Anular los tokens predeterminados para la coherencia de la marca","Crear archivos de tema reutilizables para varias aplicaciones"],"fr":["Personnaliser l''interface utilisateur de l''application avec des thèmes sur mesure","Remplacer les jetons par défaut pour la cohérence de la marque","Créer des fichiers de thème réutilisables pour plusieurs applications"],"de":["Anpassen der Benutzeroberfläche der Anwendung mit maßgeschneiderten Themen","Überschreiben der Standard-Token für Markenkonsequenz","Erstellen von wiederverwendbaren Theme-Dateien für mehrere Anwendungen"],"pt":["Personalizar a interface do aplicativo com temas personalizados","Substituir tokens padrão para consistência da marca","Criar arquivos de tema reutilizáveis para vários aplicativos"],"ru":["Настройка интерфейса приложения с помощью индивидуальных тем","Переопределение токенов по умолчанию для соответствия бренду","Создание повторно используемых файлов тем для нескольких приложений"],"ar":["تخصيص واجهة التطبيق باستخدام السمات المخصصة","إيقاف خدمات الرموز الافتراضية للاتساق مع العلامة التجارية","إنشاء ملفات سمة قابلة لإعادة الاستخدام لمتعدد التطبيقات"]},"limitations":{"en":["Requires RoleModel Software and Optics styles integration","Limited to CSS-based theme customization"],"zh":["需要 RoleModel Software 和 Optics 样式集成","仅限 CSS 基础主题自定义"],"ja":["RoleModel Software と Optics スタイルの統合が必要","CSS ベースのテーマカスタマイズのみ対応"],"ko":["RoleModel Software 및 Optics 스타일 통합이 필요","CSS 기반 테마 사용자 정의만 해당"],"es":["Requiere integración con RoleModel Software y estilos Optics","Limitado a la personalización de temas basada en CSS"],"fr":["Nécessite une intégration avec RoleModel Software et les styles Optics","Limité à la personnalisation de thème basée sur CSS"],"de":["Erfordert Integration mit RoleModel Software und Optics-Stilen","Begrenzt auf CSS-basierte Themenanpassung"],"pt":["Requer integração com software RoleModel e estilos Optics","Limitado à personalização de temas baseada em CSS"],"ru":["Требует интеграции с программным обеспечением RoleModel и стилями Optics","Ограничен настраиваемостью тем на основе CSS"],"ar":["يتطلب تكاملًا مع برنامج RoleModel وأساليب Optics","محدود بالتخصيص القائم على CSS لسمة"]},"version":4},"contentHash":"05220c59a8f6a0da45cadcc1a43105bf3674ee5720da9c381f81a01e36822aa4","qualityScore":33}');
