INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('RoleModel/rolemodel-skills/theming-context', 'theming-context', 'RoleModel', 'rolemodel-skills', 'community', 'theming-context RoleModel rolemodel-skills community The theming-context skill allows developers to customize applications with custom theme files, overriding existing tokens. It benefits developers working with RoleModel Software. theming-context 是一个用于自定义应用程序的技术，允许开发者使用自定义主题文件覆盖现有 tokens theming-context は、カスタムテーマファイルを使用して既存のトークンをオーバーライドすることで、アプリケーションのカスタマイズを実現する技術です theming-context 는 사용자 정의 테마 파일을 사용하여 기존 토큰을 재정의하여 애플리케이션을 사용자 정의하는 기술입니다 Theming-context es una colección de habilidades para personalizar aplicaciones. Permite override tokens y crear temas personalizados con CSS. Theming-context est un ensemble de compétences pour personnaliser des applications. Il permet de override des tokens et de créer des thèmes personnalisés avec CSS. Theming-context ist eine Sammlung von Fähigkeiten zur Anpassung von Anwendungen. Es ermöglicht das Override von Token und die Erstellung von benutzerdefinierten Themen mit CSS. O Theming-Context é uma coleção de habilidades de agente que permitem personalizar aplicativos com tokens personalizados e CSS de override Theming-Context - это коллекция навыков агентов, позволяющая настраивать приложения с помощью пользовательских токенов и CSS-перехвата السياق Theming-Context هو مجموعة من مهارات الوكيل التي تسمح بتخصيص التطبيقات باستخدام الرموز المميزة المخصصة و CSS الالتفاف how to use theming-context theming-context setup guide custom theme css import theming-context vs rolemodel software theming-context install what is theming-context theming-context alternative override existing tokens custom luminos definition theming-context AIエージェント 自定义主题 tokens CSS 应用程序定制 色彩定制 字体定制 Imports custom theme CSS files using @import Overrides existing tokens, including colors and fonts Redefines luminos for customized application appearance Ensures custom theme precedence with ordered imports Supports customization of radius and other visual elements theming-context is a collection of agent skills for customizing applications with override tokens, including colors, radius, fonts, and luminos.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('zxj719/ai_wolf_game/add-api', 'community', 'zxj719', 'ai_wolf_game', 'zxj719/ai_wolf_game', 'add-api', 0, 0, 33, '2026-03-08T01:57:15.582Z', '2026-03-08T02:11:53.325Z', 'a924e2d75ec94db1e19f2ec5192da0d4ba604db15f0de32b76588d4c2a5c7ebc', '{"id":"zxj719/ai_wolf_game/add-api","name":"add-api","description":{"en":"The add-api skill enables developers to add new APIs to their application, handling authentication and errors consistently. It benefits developers working with backend and frontend services.","zh":"本文介绍如何在后端和前端添加新的API接口，保持错误处理和鉴权的一致性","ja":"この記事では、後端とフロントエンドで新しいAPIエンドポイントを追加し、エラーハンドリングと認証を一致させる方法について説明します","ko":"본 문서에서는 후엔드와 프론텐드에서 새로운 API 엔드 포인트를 추가하고 오류 처리 및 인증을 일치시키는 방법에 대해 설명합니다","es":"El skill add-api permite a los desarrolladores agregar fácilmente una nueva API en el backend y frontend, manteniendo la consistencia en el manejo de errores y la autenticación","fr":"Le skill add-api permet aux développeurs d''ajouter facilement une nouvelle API en backend et frontend, en maintenant la cohérence dans la gestion des erreurs et l''authentification","de":"Das add-api-Skill ermöglicht es Entwicklern, eine neue API im Backend und Frontend leicht hinzuzufügen und dabei die Konsistenz bei der Fehlerbehandlung und Authentifizierung zu gewährleisten","pt":"O add-api permite adicionar novas APIs ao seu projeto, com recursos de autenticação e tratamento de erros","ru":"Add-api позволяет добавлять новые API в свой проект, с функциями аутентификации и обработки ошибок","ar":"يسمح add-api بإضافة واجهات برمجة تطبيقات جديدة إلى مشروعك، مع ميزات المصادقة ومعالجة الأخطاء"},"seo":{"title":{"en":"add-api: API Setup Guide for AI Agents","zh":"添加 API 接口设置指南","ja":"API エンドポイント追加のベストプラクティス","ko":"API 추가 설정 가이드","es":"Configuración de API con add-api: Guía de Implementación","fr":"Mise en place d''une API avec add-api: Meilleures Pratiques","de":"Einrichtung von APIs mit add-api: Leitfaden für Entwickler","pt":"Guia de Configuração do add-api: Adicionando APIs com Aut...","ru":"Настройка add-api: Руководство по добавлению API с аутент...","ar":"دليل إضافة add-api: إضافة واجهات برمجة التطبيقات مع المصادقة"},"description":{"en":"Discover how to implement add-api for seamless API integration. Learn to set up handlers, routes, and services with our expert guide.","zh":"了解如何在后端和前端添加新的API接口，保持错误处理和鉴权的一致性","ja":"後端とフロントエンドで新しいAPIエンドポイントを追加する方法を学び、エラーハンドリングと認証を一致させる","ko":"后端와 전면에서 새로운 API 엔드 포인트를 추가하고 오류 처리 및 인증을 일치시키는 방법을 알아보세요","es":"Aprende a agregar una nueva API con add-api y mejora tu experiencia de desarrollo con nuestra guía paso a paso","fr":"Découvrez comment mettre en place une nouvelle API avec add-api et améliorez votre expérience de développement avec notre guide étape par étape","de":"Erfahren Sie, wie Sie eine neue API mit add-api hinzufügen und Ihre Entwicklungserfahrung mit unserem Schritt-für-Schritt-Leitfaden verbessern","pt":"Aprenda a adicionar uma nova API ao seu projeto com o add-api, incluindo autenticação e tratamento de erros","ru":"Узнайте, как добавить новый API в свой проект с помощью add-api, включая аутентификацию и обработку ошибок","ar":"تعرف على كيفية إضافة واجهة برمجة تطبيقات جديدة إلى مشروعك مع add-api، بما في ذلك المصادقة ومعالجة الأخطاء"},"definition":{"en":"add-api is a skill that allows developers to create and integrate new APIs into their application, ensuring uniform error handling and authentication.","zh":"添加API接口是一种在后端和前端增加新的API端点的技术，用于保持错误处理和鉴权的一致性","ja":"APIエンドポイントの追加は、後端とフロントエンドで新しいAPIエンドポイントを追加し、エラーハンドリングと認証を一致させる技術です","ko":"API 엔드 포인트 추가는 후엔드와 프론텐드에서 새로운 API 엔드 포인트를 추가하고 오류 처리 및 인증을 일치시키는 기술입니다","es":"add-api es un skill que facilita la integración de nuevas APIs en aplicaciones web, mejorando la eficiencia y la escalabilidad","fr":"add-api est un skill qui facilite l''intégration de nouvelles API dans les applications web, améliorant l''efficacité et la scalabilité","de":"add-api ist ein Skill, der die Integration neuer APIs in Webanwendungen erleichtert und damit die Effizienz und Skalierbarkeit verbessert","pt":"O add-api é uma habilidade que permite adicionar novas APIs ao seu projeto","ru":"Add-api - это навык, который позволяет добавлять новые API в свой проект","ar":"add-api هو مهارة يسمح بإضافة واجهات برمجة تطبيقات جديدة إلى مشروعك"},"features":{"en":["Generates API handlers using JavaScript","Utilizes authMiddleware for login validation","Supports JSON response and error handling","Creates routes for API endpoints in workers/auth/index.js","Encapsulates API calls in src/services/authService.js"],"zh":["后端处理函数的新增和修改","后端路由的配置和管理","前端封装和API调用","错误处理和鉴权的一致性","使用jsonResponse和errorResponse返回数据"],"ja":["後端処理関数の追加と修正","後端ルーティングの設定と管理","フロントエンドの封装とAPI呼び出し","エラーハンドリングと認証の一致性","jsonResponseとerrorResponseを使用したデータの返却"],"ko":["후엔드 처리 함수의 추가와 수정","후엔드 라우팅의 설정과 관리","프론텐드의封装과 API 호출","오류 처리와 인증의 일치성","jsonResponse와 errorResponse를 사용한 데이터 반환"],"es":["Implementación de APIs en el backend con workers/auth/handlers.js","Uso de authMiddleware para la autenticación","Respuestas JSON y de error personalizadas","Integración con el frontend mediante src/services/authService.js","Mantenimiento de la consistencia en el manejo de errores y la autenticación"],"fr":["Mise en place d''API en backend avec workers/auth/handlers.js","Utilisation d''authMiddleware pour l''authentification","Réponses JSON et d''erreur personnalisées","Intégration avec le frontend via src/services/authService.js","Maintenance de la cohérence dans la gestion des erreurs et l''authentification"],"de":["Implementierung von APIs im Backend mit workers/auth/handlers.js","Verwendung von authMiddleware für die Authentifizierung","Angepasste JSON- und Fehlerantworten","Integration mit dem Frontend über src/services/authService.js","Beibehaltung der Konsistenz bei der Fehlerbehandlung und Authentifizierung"],"pt":["Adiciona novas APIs ao projeto","Inclui autenticação com middleware","Tratamento de erros unificado","Utiliza jsonResponse e errorResponse","Integração com serviços de autenticação existentes"],"ru":["Добавляет новые API в проект","Включает аутентификацию с middleware","Объединяет обработку ошибок","Использует jsonResponse и errorResponse","Интегрируется с существующими службами аутентификации"],"ar":["يضيف واجهات برمجة تطبيقات جديدة إلى المشروع","يشمل المصادقة مع middleware","معالجة الأخطاء الموحد","يستخدم jsonResponse و errorResponse","يتكامل مع خدمات المصادقة الحالية"]},"keywords":{"en":["how to use add-api","add-api setup guide","add-api vs other API tools","add-api alternative","add-api install","what is add-api","add-api for AI agents","add-api API integration","add-api backend development"],"zh":["添加API接口","后端开发","前端开发","错误处理","鉴权","API设计","后端路由","前端封装"],"ja":["APIエンドポイントの追加","後端開発","フロントエンド開発","エラーハンドリング","認証","API設計","後端ルーティング","フロントエンドの封装"],"ko":["API 엔드 포인트 추가","후엔드 개발","프론텐드 개발","오류 처리","인증","API 설계","후엔드 라우팅","프론텐드의封装"],"es":["add-api","integración de APIs","desarrollo web","autenticación","manejo de errores","workers/auth/handlers.js","src/services/authService.js","Herramientas de desarrollo de AI","Agentes de IA para desarrolladores"],"fr":["add-api","intégration d''API","développement web","authentification","gestion des erreurs","workers/auth/handlers.js","src/services/authService.js","Outils de développement d''IA","Agents d''IA pour les développeurs"],"de":["add-api","API-Integration","Webentwicklung","Authentifizierung","Fehlerbehandlung","workers/auth/handlers.js","src/services/authService.js","Entwicklungstools für KI","KI-Agents für Entwickler"],"pt":["add-api","adicionar api","autenticação api","tratamento de erros api","desenvolvimento de api","api com autenticação","add-api tutorial","add-api guia"],"ru":["add-api","добавить api","аутентификация api","обработка ошибок api","разработка api","api с аутентификацией","add-api руководство","add-api урок"],"ar":["add-api","إضافة واجهة برمجة تطبيقات","مصادقة واجهة برمجة التطبيقات","معالجة أخطاء واجهة برمجة التطبيقات","تطوير واجهة برمجة التطبيقات","واجهة برمجة التطبيقات مع المصادقة","دليل add-api","إضافة add-api"]}},"owner":"zxj719","repo":"ai_wolf_game","repoPath":"zxj719/ai_wolf_game","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.582Z","topics":[],"category":"community","skillMd":{"name":"add-api","description":"新增 Cloudflare Workers API 端点，并在前端封装调用。","bodyPreview":"目标：在后端 `workers/auth/*` 新增一个 API，并在前端 `src/services/authService.js` 增加调用封装，保持错误处理与鉴权一致。\n\n## 步骤\n\n1. 后端处理函数：`workers/auth/handlers.js`\n   - 新增 `export async function handleXxx(request, env) { ... }`\n   - 复用 `authMiddleware` 做登录校验\n   - 统一用 `jsonResponse` / `errorResponse` 返回\n\n2. 后端路由：`workers/auth/index.js`\n   - import 新增的 handler\n   - 在路由表里添加对应 URL 与 HTTP method\n\n3. 前端封装：`src/services/authService.js`\n   - 新增一个方法调用该 API（复用现有 token/header 逻辑）\n\n## 参考模板\n\n```js\n// workers/auth/handlers.js\nexport async","body":"目标：在后端 `workers/auth/*` 新增一个 API，并在前端 `src/services/authService.js` 增加调用封装，保持错误处理与鉴权一致。\n\n## 步骤\n\n1. 后端处理函数：`workers/auth/handlers.js`\n   - 新增 `export async function handleXxx(request, env) { ... }`\n   - 复用 `authMiddleware` 做登录校验\n   - 统一用 `jsonResponse` / `errorResponse` 返回\n\n2. 后端路由：`workers/auth/index.js`\n   - import 新增的 handler\n   - 在路由表里添加对应 URL 与 HTTP method\n\n3. 前端封装：`src/services/authService.js`\n   - 新增一个方法调用该 API（复用现有 token/header 逻辑）\n\n## 参考模板\n\n```js\n// workers/auth/handlers.js\nexport async function handleNewFeature(request, env) {\n  try {\n    const { user, error } = await authMiddleware(request, env);\n    if (error) return errorResponse(error, 401, env, request);\n\n    // business logic...\n\n    return jsonResponse({ success: true, data: result }, 200, env, request);\n  } catch (err) {\n    return errorResponse(''Failed: '' + err.message, 500, env, request);\n  }\n}\n```\n\n"},"lastSynced":"2026-03-08T02:11:53.325Z","agentAnalysis":{"suitability":{"en":"Ideal for Full-Stack Agents seeking to expand API capabilities with consistent authentication and error handling.","zh":"适合于全栈代理寻求扩展API功能，具有统一的身份验证和错误处理的代理。","ja":"フルスタックエージェントがAPIの機能を拡張し、認証とエラーハンドリングを一貫して行う場合に最適です。","ko":"전체 스택 에이전트가 API 기능을 확장하고 일관된 인증 및 오류 처리를 수행하기에 적합합니다.","es":"Ideal para Agentes Full-Stack que buscan ampliar las capacidades de la API con autenticación y manejo de errores consistentes.","fr":"Idéal pour les agents Full-Stack qui cherchent à étendre les capacités de l''API avec une authentification et une gestion des erreurs cohérentes.","de":"Ideal für Full-Stack-Agents, die die API-Fähigkeiten mit konsistenter Authentifizierung und Fehlerbehandlung erweitern möchten.","pt":"Ideal para agentes Full-Stack que buscam expandir as capacidades da API com autenticação consistente e tratamento de erros.","ru":"Идеально для полнофункциональных агентов, стремящихся расширить возможности API с помощью последовательной аутентификации и обработки ошибок.","ar":"مثالي لعميل متكامل يبحث عن توسيع قدرات واجهة البرمجة التطبيقية مع مصادقة متسقةและมعالجة للأخطاء."},"recommendation":{"en":"Empowers agents to seamlessly integrate new APIs into their application, utilizing authentication middleware and standardized JSON response formats, while maintaining consistent error handling and authorization protocols through libraries like jsonResponse and errorResponse.","zh":"赋予代理无缝地将新API集成到其应用程序中，利用身份验证中间件和标准化的JSON响应格式，同时通过像jsonResponse和errorResponse这样的库保持一致的错误处理和授权协议。","ja":"エージェントが新しいAPIをアプリケーションにシームレスに統合できるようにすることで、認証ミドルウェアと標準化されたJSONレスポンス形式を利用し、jsonResponseやerrorResponseなどのライブラリを介して一貫したエラーハンドリングと認可プロトコルを維持します。","ko":"에이전트가 새로운 API를 애플리케이션에 무縫으로 통합할 수 있도록 하여, 인증 미들웨어와 표준화된 JSON 응답 형식을 활용하고, jsonResponse 및 errorResponse와 같은 라이브러리를 통해 일관된 오류 처리 및 인증 프로토콜을 유지합니다.","es":"Permite a los agentes integrar nuevas API en su aplicación de forma transparente, utilizando middleware de autenticación y formatos de respuesta JSON estandarizados, manteniendo al mismo tiempo un manejo de errores y protocolos de autorización consistentes a través de bibliotecas como jsonResponse y errorResponse.","fr":"Permet aux agents d''intégrer de nouvelles API dans leur application de manière transparente, en utilisant un middleware d''authentification et des formats de réponse JSON standardisés, tout en maintenant une gestion des erreurs et des protocoles d''autorisation cohérents via des bibliothèques comme jsonResponse et errorResponse.","de":"Ermächtigt die Agenten, neue API nahtlos in ihre Anwendung zu integrieren, indem sie Authentifizierungsmiddleware und standardisierte JSON-Antwortformate verwenden, während sie gleichzeitig eine konsistente Fehlerbehandlung und Autorisierungsprotokolle durch Bibliotheken wie jsonResponse und errorResponse aufrechterhalten.","pt":"Permite que os agentes integrem novas APIs em seu aplicativo de forma transparente, utilizando middleware de autenticação e formatos de resposta JSON padronizados, mantendo assim tratamento de erros e protocolos de autorização consistentes por meio de bibliotecas como jsonResponse e errorResponse.","ru":"Позволяет агентам бесшовно интегрировать новые API в их приложение, используя middleware аутентификации и стандартизированные форматы ответа JSON, сохраняя при этом последовательную обработку ошибок и протоколы авторизации через библиотеки seperti jsonResponse и errorResponse.","ar":"تمكن العميل من دمج واجهات برمجة تطبيقات جديدة في التطبيق بسهولة، باستخدام وسيط المصادقة وأشكال استجابة JSON المعيارية، مع الحفاظ على معالجة الأخطاء والبروتوكولات الموثوقة من خلال مكتبات مثل jsonResponse و errorResponse."},"useCases":{"en":["Adding custom authentication endpoints","Implementing API routes for data services","Extending backend functionality with new API handlers"],"zh":["添加自定义身份验证端点","实现API路由以提供数据服务","使用新的API处理程序扩展后端功能"],"ja":["カスタム認証エンドポイントを追加する","データサービス用のAPIルートを実装する","新しいAPIハンドラーを使用してバックエンド機能を拡張する"],"ko":["사용자 지정 인증 엔드포인트 추가","데이터 서비스를 위한 API 루트 구현","새로운 API 핸들러를 사용하여 백엔드 기능 확장"],"es":["Agregar puntos de conexión de autenticación personalizados","Implementar rutas de API para servicios de datos","Ampliar la funcionalidad del backend con nuevos controladores de API"],"fr":["Ajouter des points de terminaison d''authentification personnalisés","Mettre en œuvre des routes d''API pour les services de données","Étendre la fonctionnalité du backend avec de nouveaux gestionnaires d''API"],"de":["Hinzufügen von benutzerdefinierten Authentifizierungs-Endpunkten","Implementierung von API-Routen für Datendienste","Erweiterung der Backend-Funktionalität mit neuen API-Handlern"],"pt":["Adicionar pontos de extremidade de autenticação personalizados","Implementar rotas de API para serviços de dados","Ampliar a funcionalidade do backend com novos manipuladores de API"],"ru":["Добавление пользовательских конечных точек аутентификации","Реализация маршрутов API для сервисов данных","Расширение функциональности бэкэнда с помощью новых обработчиков API"],"ar":["إضافة نقاط نهاية مصادقة مخصصة","تنفيذ مسارات واجهة برمجة التطبيقات لخدمات البيانات","توسيع وظائف الخلفية مع معالجات واجهة برمجة التطبيقات الجديدة"]},"limitations":{"en":["Requires existing backend infrastructure","Dependent on authMiddleware for authentication","Limited to JSON response formats"],"zh":["需要现有的后端基础设施","依赖于authMiddleware进行身份验证","仅限于JSON响应格式"],"ja":["既存のバックエンドインフラストラクチャが必要","認証にはauthMiddlewareに依存する","JSONレスポンス形式のみに限定される"],"ko":["既存의 백엔드 인프라스트럭처가 필요","인증에는 authMiddleware에 의존","JSON 응답 형식만으로 제한"],"es":["Requiere una infraestructura de backend existente","Depende de authMiddleware para la autenticación","Limitado a formatos de respuesta JSON"],"fr":["Nécessite une infrastructure de backend existante","Dépend de authMiddleware pour l''authentification","Limité aux formats de réponse JSON"],"de":["Benötigt eine bestehende Backend-Infrastruktur","Hängt von authMiddleware für die Authentifizierung ab","Begrenzt auf JSON-Antwortformate"],"pt":["Exige infraestrutura de backend existente","Dependente do authMiddleware para autenticação","Limitado a formatos de resposta JSON"],"ru":["Требует существующей инфраструктуры бэкэнда","Зависит от authMiddleware для аутентификации","Ограничен форматами ответа JSON"],"ar":["يتطلب بنية خلفية موجودة","يعتمد على authMiddleware للمصادقة","محدود أشكال استجابة JSON"]},"version":4},"contentHash":"a924e2d75ec94db1e19f2ec5192da0d4ba604db15f0de32b76588d4c2a5c7ebc","qualityScore":33}');
