INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zxj719/ai_wolf_game/add-api', 'add-api', 'zxj719', 'ai_wolf_game', 'community', 'add-api zxj719 ai_wolf_game community The add-api skill enables developers to add new APIs to their application, handling authentication and errors consistently. It benefits developers working with backend and frontend services. 本文介绍如何在后端和前端添加新的API接口，保持错误处理和鉴权的一致性 この記事では、後端とフロントエンドで新しいAPIエンドポイントを追加し、エラーハンドリングと認証を一致させる方法について説明します 본 문서에서는 후엔드와 프론텐드에서 새로운 API 엔드 포인트를 추가하고 오류 처리 및 인증을 일치시키는 방법에 대해 설명합니다 El skill add-api permite a los desarrolladores agregar fácilmente una nueva API en el backend y frontend, manteniendo la consistencia en el manejo de errores y la autenticación Le skill add-api permet aux développeurs d''ajouter facilement une nouvelle API en backend et frontend, en maintenant la cohérence dans la gestion des erreurs et l''authentification Das add-api-Skill ermöglicht es Entwicklern, eine neue API im Backend und Frontend leicht hinzuzufügen und dabei die Konsistenz bei der Fehlerbehandlung und Authentifizierung zu gewährleisten O add-api permite adicionar novas APIs ao seu projeto, com recursos de autenticação e tratamento de erros Add-api позволяет добавлять новые API в свой проект, с функциями аутентификации и обработки ошибок يسمح add-api بإضافة واجهات برمجة تطبيقات جديدة إلى مشروعك، مع ميزات المصادقة ومعالجة الأخطاء how to use add-api add-api setup guide add-api vs other API tools add-api alternative add-api install what is add-api add-api for AI agents add-api API integration add-api backend development 添加API接口 后端开发 前端开发 错误处理 鉴权 API设计 后端路由 前端封装 Generates API handlers using JavaScript Utilizes authMiddleware for login validation Supports JSON response and error handling Creates routes for API endpoints in workers/auth/index.js Encapsulates API calls in src/services/authService.js add-api is a skill that allows developers to create and integrate new APIs into their application, ensuring uniform error handling and authentication.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rob9206/DynoAI_3/dynoai-domain-expert', 'community', 'rob9206', 'DynoAI_3', 'rob9206/DynoAI_3', 'dynoai-domain-expert', 0, 0, 33, '2026-03-08T01:57:15.590Z', '2026-03-08T02:12:01.242Z', '6d3b30d0df190617d0073d4ba0617fd4bca52c543a4ea99262127860d89d4a07', '{"id":"rob9206/DynoAI_3/dynoai-domain-expert","name":"dynoai-domain-expert","description":{"en":"The dynoai-domain-expert skill provides deterministic dyno tuning for Harley-Davidson motorcycles, benefiting developers and motorcycle enthusiasts. It utilizes a monorepo architecture with REST API, frontend, core library, and desktop GUI components.","zh":"dynoai-domain-expert是一个用于哈雷戴维森V-twin发动机的确定性dyno调优的monorepo","ja":"dynoai-domain-expertはハーレーダビッドソンのV-twinエンジンのための決定性dynoチューニングのmonorepoです","ko":"dynoai-domain-expert는 하ーレ이戴비슨 V-twin 엔진을 위한 결정적 dyno 튜닝 모노레포입니다","es":"DynoAI Domain Expert es una herramienta de ajuste de motores V-twin que utiliza tecnologías como Flask, React y Python para ofrecer una plataforma de ajuste determinista","fr":"DynoAI Domain Expert est un outil de réglage de moteurs V-twin qui utilise des technologies comme Flask, React et Python pour offrir une plateforme de réglage déterministe","de":"DynoAI Domain Expert ist ein Tool für die Einstellung von V-twin-Motoren, das Technologien wie Flask, React und Python nutzt, um eine deterministische Einstellplattform zu bieten","pt":"O DynoAI Domain Expert é uma plataforma de tuning de motores que utiliza React, Python e Flask para desenvolver soluções personalizadas.","ru":"DynoAI Domain Expert - это платформа для настройки двигателей, которая использует React, Python и Flask для разработки индивидуальных решений.","ar":"DynoAI Domain Expert هو منصة ضبط محركات تستخدم React و Python و Flask لتطوير حلول مخصصة."},"seo":{"title":{"en":"dynoai-domain-expert: Expert Guidance for Harley-Davidson...",